package com.osrscopilot;

import com.osrscopilot.pipeline.EntityResolver;
import com.osrscopilot.pipeline.GameCapture;
import com.osrscopilot.pipeline.ItemDescriptor;
import com.osrscopilot.pipeline.Ownership;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Skill;

/**
 * Entity-aware answer styling: quest names colored by the player's
 * progress, item names by where the player holds them, monsters and pages
 * linked plainly. Every name links to its OSRS Wiki page. Deterministic;
 * the model plays no part.
 */
final class AnswerDecorator
{
	private static final String WIKI_BASE = "https://oldschool.runescape.wiki/w/";

	/** Names shorter than this are too likely to collide with prose. */
	private static final int MIN_NAME_LENGTH = 4;

	private static final class Rule
	{
		final String lowerName;
		final String title;
		final String color;
		/** Pre-resolved icon file URL (skill and quest icons, written to
		 * disk at startup); null = none or item-sprite icon. */
		final String iconUrl;
	/** Item ID whose inventory sprite decorates the name; -1 = none. */
		final int iconItemId;
		final int iconW;
		final int iconH;
		/** Skill names are everyday words ("attack the demon", "a ranged
		 * switch"); only their capitalized form denotes the skill. */
		final boolean capitalizedOnly;
		/** Ownership annotation ("×5,006 banked") rendered after the first
		 * mention of the name only; null = none. */
		final String badge;
		/** Single-word untradeable item: yields to any longer chosen name
		 * containing the word ("the totem" beside "Dark totem pieces"
		 * means the dark totem, not the Legends' Quest item). */
		final boolean yielding;

		Rule(String lowerName, String title, String color, String iconUrl,
			int iconItemId, int iconW, int iconH, boolean capitalizedOnly, String badge,
			boolean yielding)
		{
			this.lowerName = lowerName;
			this.title = title;
			this.color = color;
			this.iconUrl = iconUrl;
			this.iconItemId = iconItemId;
			this.iconW = iconW;
			this.iconH = iconH;
			this.capitalizedOnly = capitalizedOnly;
			this.badge = badge;
			this.yielding = yielding;
		}
	}

	private final List<Rule> rules;
	private final IconStore icons;

	private AnswerDecorator(List<Rule> rules, IconStore icons)
	{
		// Longest name first, so "Diamond bolts" wins over "Diamond".
		rules.sort((a, b) -> b.lowerName.length() - a.lowerName.length());
		this.rules = rules;
		this.icons = icons;
	}

	/** Inventory sprites are 36x31-ish; near-square icons stay square. */
	private static final int ICON_SQUARE = 14;
	private static final int ITEM_ICON_W = 16;

	/** Every skill the client knows, from the same enum IconStore draws
	 * icons from, so a new skill arrives in both places at once. OVERALL
	 * is the deprecated pseudo-skill with no icon or page. */
	private static final List<String> SKILLS = java.util.Arrays.stream(Skill.values())
		.filter(s -> !"OVERALL".equals(s.name()))
		.map(Skill::getName)
		.collect(java.util.stream.Collectors.toList());

	/** Assemble the name vocabularies in precedence order: a name known
	 * several ways keeps its richest meaning (quest state over item over
	 * plain page link). */
	static AnswerDecorator build(GameCapture cap, EntityResolver.Resolution entities,
		List<String> monsterNames, List<ItemDescriptor> items, IconStore icons)
	{
		Theme theme = Theme.active();
		Map<String, Rule> byName = new LinkedHashMap<>();
		if (cap != null && cap.questStates != null)
		{
			String questIcon = icons != null ? icons.questIconUrl() : null;
			for (Map.Entry<String, String> e : cap.questStates.entrySet())
			{
				String color = "FINISHED".equals(e.getValue()) ? theme.questDoneHex
					: "IN_PROGRESS".equals(e.getValue()) ? theme.questProgressHex
					: theme.questNotStartedHex;
				add(byName, e.getKey(), e.getKey(), color,
					questIcon, -1, ICON_SQUARE, ICON_SQUARE, false, null, false);
			}
		}
		Map<String, Rule> owned = cap != null
			? ownedRules(cap, theme, safeBaseNames(items)) : Map.of();
		owned.forEach(byName::putIfAbsent);
		for (String skill : SKILLS)
		{
			add(byName, skill, skill, theme.plainLinkHex,
				icons != null ? icons.skillIconUrl(skill) : null,
				-1, ICON_SQUARE, ICON_SQUARE, true, null, false);
		}
		if (entities != null)
		{
			for (List<String> kind : List.of(entities.monsters, entities.pages, entities.quests))
			{
				for (String name : kind)
				{
					add(byName, name, name, theme.plainLinkHex, null, -1, 0, 0, false, null, false);
				}
			}
		}
		for (String name : monsterNames)
		{
			add(byName, name, name, theme.plainLinkHex, null, -1, 0, 0, false, null, false);
		}
		// Versioned names ("Fire cape (l)") match by name but link to
		// their shared page; items without an ID render iconless. A name
		// covered by an owned variant takes that variant's styling: prose
		// says "Slayer helmet (i)", the player's copy is black, and the
		// prompt already told the model the variant counts as owned.
		Map<String, List<Rule>> ownedByWord = indexByWord(owned);
		for (ItemDescriptor it : items)
		{
			Rule cover = coveringOwned(ownedByWord, Ownership.baseName(it.name));
			if (cover != null)
			{
				add(byName, it.name, it.page, cover.color, null, cover.iconItemId,
					ITEM_ICON_W, ICON_SQUARE, false, cover.badge, false);
			}
			else
			{
				add(byName, it.name, it.page, theme.itemUnownedHex,
					null, it.id != null ? it.id : -1, ITEM_ICON_W, ICON_SQUARE, false, null,
					!it.tradeable && it.name.indexOf(' ') < 0);
			}
		}
		return new AnswerDecorator(new ArrayList<>(byName.values()), icons);
	}

	/** Owned rules under every word of their name, so the covering rule
	 * for a catalogue name is found without scanning all owned items. */
	private static Map<String, List<Rule>> indexByWord(Map<String, Rule> owned)
	{
		Map<String, List<Rule>> byWord = new LinkedHashMap<>();
		for (Rule rule : owned.values())
		{
			for (String word : rule.lowerName.split(" "))
			{
				byWord.computeIfAbsent(word, k -> new ArrayList<>()).add(rule);
			}
		}
		return byWord;
	}

	/** The owned rule covering a canonical name, or null. A whole-word
	 * containment means the canonical's last word is a word of the owned
	 * name, so only that index bucket needs the full test. */
	private static Rule coveringOwned(Map<String, List<Rule>> ownedByWord, String canonical)
	{
		String lower = canonical.toLowerCase(Locale.ROOT);
		String lastWord = lower.substring(lower.lastIndexOf(' ') + 1);
		for (Rule rule : ownedByWord.getOrDefault(lastWord, List.of()))
		{
			if (Ownership.covers(rule.lowerName, lower))
			{
				return rule;
			}
		}
		return null;
	}

	/** Lowercased base names of every catalogued item. Owned rules obey
	 * the same prose-safety policy as catalogue rules: a name the snapshot
	 * excluded ("Coins") must not decorate just because copies are owned. */
	private static Set<String> safeBaseNames(List<ItemDescriptor> items)
	{
		Set<String> safe = new HashSet<>(items.size() * 2);
		for (ItemDescriptor it : items)
		{
			safe.add(Ownership.baseName(it.name).toLowerCase(Locale.ROOT));
		}
		return safe;
	}

	/** Aggregate every owned copy of an item across containers (dose and
	 * charge variants collapse to one base name), then emit a single rule
	 * per base name whose badge states quantity and place: "×5,006
	 * banked", "equipped", "×20 carried, ×5,006 banked". */
	private static Map<String, Rule> ownedRules(GameCapture cap, Theme theme,
		Set<String> safeNames)
	{
		Map<String, long[]> counts = new LinkedHashMap<>(); // {carried, equipped, banked}
		Map<String, Integer> iconId = new LinkedHashMap<>();
		accumulate(counts, iconId, cap.inventory, 0);
		accumulate(counts, iconId, cap.equipment, 1);
		accumulate(counts, iconId, cap.bank, 2);
		Map<String, Rule> rules = new LinkedHashMap<>();
		for (Map.Entry<String, long[]> e : counts.entrySet())
		{
			String lower = e.getKey().toLowerCase(Locale.ROOT);
			if (e.getKey().length() < MIN_NAME_LENGTH || !safeNames.contains(lower))
			{
				continue;
			}
			long[] c = e.getValue();
			boolean carried = c[0] > 0 || c[1] > 0;
			List<String> parts = new ArrayList<>();
			if (c[1] > 0)
			{
				parts.add(c[1] > 1 ? String.format("×%,d equipped", c[1]) : "equipped");
			}
			if (c[0] > 0)
			{
				parts.add(String.format("×%,d carried", c[0]));
			}
			if (c[2] > 0)
			{
				parts.add(String.format("×%,d banked", c[2]));
			}
			Integer id = iconId.get(e.getKey());
			rules.putIfAbsent(lower, new Rule(lower, e.getKey(),
				carried ? theme.itemCarriedHex : theme.itemBankedHex,
				null, id != null ? id : -1, ITEM_ICON_W, ICON_SQUARE, false,
				String.join(", ", parts), false));
		}
		return rules;
	}

	private static void accumulate(Map<String, long[]> counts, Map<String, Integer> iconId,
		List<Map<String, Object>> container, int slot)
	{
		if (container == null)
		{
			return;
		}
		for (Map<String, Object> item : container)
		{
			String name = String.valueOf(item.get("name"));
			// The icon keeps the exact owned variant's ID.
			String base = Ownership.baseName(name);
			Object q = item.get("quantity");
			long qty = q instanceof Number ? ((Number) q).longValue() : 1;
			counts.computeIfAbsent(base, k -> new long[3])[slot] += qty;
			Object id = item.get("id");
			if (id instanceof Number)
			{
				iconId.putIfAbsent(base, ((Number) id).intValue());
			}
		}
	}

	private static void add(Map<String, Rule> byName, String name, String title,
		String color, String iconUrl, int iconItemId, int iconW, int iconH,
		boolean capitalizedOnly, String badge, boolean yielding)
	{
		if (name == null || name.length() < MIN_NAME_LENGTH)
		{
			return;
		}
		byName.putIfAbsent(name.toLowerCase(Locale.ROOT),
			new Rule(name.toLowerCase(Locale.ROOT), title, color,
				iconUrl, iconItemId, iconW, iconH, capitalizedOnly, badge, yielding));
	}

	/**
	 * Rewrite known names in rendered answer HTML into colored wiki links.
	 * Operates on text between tags only; matches are whole-word,
	 * case-insensitive, and tolerate a plural "s".
	 */
	String decorate(String html)
	{
		String lower = html.toLowerCase(Locale.ROOT);
		boolean[] offLimits = tagRanges(html);
		List<int[]> chosen = new ArrayList<>();
		for (int r = 0; r < rules.size(); r++)
		{
			String needle = rules.get(r).lowerName;
			int from = 0;
			int i;
			while ((i = lower.indexOf(needle, from)) >= 0)
			{
				from = i + 1;
				int end = Ownership.wordMatchEnd(lower, i, needle.length());
				if (end < 0 || anyMarked(offLimits, i, end))
				{
					continue;
				}
				if (rules.get(r).capitalizedOnly && !Character.isUpperCase(html.charAt(i)))
				{
					continue;
				}
				if (fragmentOfLargerName(html, end) || tailOfLargerName(html, i))
				{
					continue;
				}
				if (rules.get(r).yielding && chosenLongerNameContains(needle, chosen))
				{
					continue;
				}
				for (int k = i; k < end; k++)
				{
					offLimits[k] = true;
				}
				chosen.add(new int[]{i, end, r});
			}
		}
		if (chosen.isEmpty())
		{
			return html;
		}
		chosen.sort((a, b) -> a[0] - b[0]);
		StringBuilder out = new StringBuilder(html.length() + chosen.size() * 64);
		String badgeHex = Theme.active().metaHex;
		Set<Integer> badged = new HashSet<>();
		int pos = 0;
		for (int[] m : chosen)
		{
			Rule rule = rules.get(m[2]);
			out.append(html, pos, m[0])
				.append("<a href='").append(wikiUrl(rule.title)).append("'>");
			// Item sprites render here, lazily, for matched names only.
			String iconUrl = rule.iconUrl != null ? rule.iconUrl
				: rule.iconItemId >= 0 && icons != null
				? icons.itemIconUrl(rule.iconItemId) : null;
			if (iconUrl != null)
			{
				// border=0 kills the browser-style link border on images.
				out.append("<img src='").append(iconUrl)
					.append("' width='").append(rule.iconW)
					.append("' height='").append(rule.iconH)
					.append("' border='0'>&nbsp;");
			}
			out.append("<font color='").append(rule.color).append("'>")
				.append(html, m[0], m[1])
				.append("</font></a>");
			// Ownership badge on the first mention only.
			if (rule.badge != null && badged.add(m[2]))
			{
				out.append(" <font size='2' color='").append(badgeHex)
					.append("'>[").append(rule.badge).append("]</font>");
			}
			pos = m[1];
		}
		out.append(html, pos, html.length());
		return out.toString();
	}

	/** True when an already-chosen match's name contains the word. Rules
	 * match longest-first, so every longer name mentioned anywhere in the
	 * answer is already in chosen when a yielding rule runs. */
	private boolean chosenLongerNameContains(String needle, List<int[]> chosen)
	{
		for (int[] m : chosen)
		{
			String longer = rules.get(m[2]).lowerName;
			if (longer.length() > needle.length() && Ownership.mentionsWord(longer, needle))
			{
				return true;
			}
		}
		return false;
	}

	/** True in every position that sits inside an HTML tag. */
	private static boolean[] tagRanges(String html)
	{
		boolean[] blocked = new boolean[html.length()];
		boolean in = false;
		for (int i = 0; i < html.length(); i++)
		{
			char c = html.charAt(i);
			if (c == '<')
			{
				in = true;
			}
			blocked[i] = in;
			if (c == '>')
			{
				in = false;
			}
		}
		return blocked;
	}

	/**
	 * Continuation of a title-case phrase: whitespace, optional lowercase
	 * connectors, then a capitalized word. Anything else (punctuation, tags,
	 * ordinary lowercase prose) ends the phrase.
	 */
	private static final Pattern PROPER_NOUN_CONTINUES =
		Pattern.compile("\\s+(?:(?:of|the|de)\\s+)*\\p{Lu}");

	/** True when the matched name is only a fragment of a longer proper
	 * noun ("Bank" in "Bank of Gielinor"); linking the fragment would
	 * mislabel it. */
	private static boolean fragmentOfLargerName(String html, int end)
	{
		Matcher m = PROPER_NOUN_CONTINUES.matcher(html);
		m.region(end, html.length());
		return m.lookingAt();
	}

	/**
	 * A capitalized word, optional lowercase connectors, then whitespace,
	 * ending exactly where the match starts.
	 */
	private static final Pattern PROPER_NOUN_PRECEDES =
		Pattern.compile("(?<!\\p{L})\\p{Lu}[\\p{L}'-]*(?:\\s+(?:of|the|de))*\\s+\\z");

	/** The match is the tail of a longer title-case phrase ("demons" in
	 * "Greater demons"); linking it would mislabel the fragment. A
	 * preceding capital only counts mid-sentence: sentence openers are
	 * capitalized no matter what ("The demons" must not suppress the
	 * link). */
	private static boolean tailOfLargerName(String html, int start)
	{
		Matcher m = PROPER_NOUN_PRECEDES.matcher(html);
		// A bounded region keeps the scan O(1) per candidate match.
		m.region(Math.max(0, start - 48), start);
		m.useTransparentBounds(true);
		if (!m.find())
		{
			return false;
		}
		int i = m.start();
		while (i > 0 && Character.isWhitespace(html.charAt(i - 1)))
		{
			i--;
		}
		if (i == 0)
		{
			return false;
		}
		char before = html.charAt(i - 1);
		return Character.isLetterOrDigit(before) || before == ',';
	}

	private static boolean anyMarked(boolean[] marked, int start, int end)
	{
		for (int i = start; i < end; i++)
		{
			if (marked[i])
			{
				return true;
			}
		}
		return false;
	}

	static String wikiUrl(String title)
	{
		return WIKI_BASE + URLEncoder.encode(title, StandardCharsets.UTF_8).replace("+", "_");
	}
}

package com.osrscopilot;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;

/**
 * Applies bank changes that happen while the bank is closed: deposit-box
 * deposits and the Grand Exchange's collect-to-bank. Client thread only.
 * Deltas are credit-only and conservative: an ambiguous collect clears the
 * tracking instead of guessing -- a missed credit self-heals at the next
 * bank open, an invented one is a wrong ownership answer until then.
 */
@Slf4j
class BankMutations
{
	private static final String COLLECT_TO_BANK = "Collect to bank";

	private final BankStore bankStore;
	private final ItemManager itemManager;
	private final GeSlots geSlots = new GeSlots();

	/** Inventory/equipment as last seen while the deposit box is open;
	 * null while it is closed. */
	private Map<Integer, Integer> inventorySeen;
	private Map<Integer, Integer> equipmentSeen;

	BankMutations(BankStore bankStore, ItemManager itemManager)
	{
		this.bankStore = bankStore;
		this.itemManager = itemManager;
	}

	// --- deposit box ---

	void depositBoxOpened(ItemContainer inventory, ItemContainer equipment)
	{
		inventorySeen = multiset(inventory);
		equipmentSeen = multiset(equipment);
	}

	void depositBoxClosed()
	{
		inventorySeen = null;
		equipmentSeen = null;
	}

	/** Inventory or equipment changed. While the deposit box is open, any
	 * decrease against the last-seen state is a deposit. */
	void containerChanged(int containerId, ItemContainer container)
	{
		if (inventorySeen == null)
		{
			return;
		}
		Map<Integer, Integer> now = multiset(container);
		Map<Integer, Integer> before;
		if (containerId == InventoryID.INV)
		{
			before = inventorySeen;
			inventorySeen = now;
		}
		else if (containerId == InventoryID.WORN)
		{
			before = equipmentSeen;
			equipmentSeen = now;
		}
		else
		{
			return;
		}
		for (Map.Entry<Integer, Integer> gone : decreases(before, now).entrySet())
		{
			credit(gone.getKey(), gone.getValue());
		}
	}

	// --- grand exchange ---

	void offerChanged(int slot, GrandExchangeOfferState state, int itemId,
		int quantitySold, int totalQuantity)
	{
		geSlots.offerChanged(slot, state, itemId, quantitySold, totalQuantity);
	}

	/** Every menu click passes through here. "Collect to bank" credits the
	 * tracked collectables; any other collect variant (to inventory,
	 * per-slot, collection box) or a bank visit clears them instead of
	 * guessing where the items landed. */
	void menuClicked(String option)
	{
		if (option == null)
		{
			return;
		}
		if (COLLECT_TO_BANK.equalsIgnoreCase(option))
		{
			for (int[] pair : geSlots.drain())
			{
				credit(pair[0], pair[1]);
			}
		}
		else if (option.regionMatches(true, 0, "Collect", 0, 7) || "Bank".equals(option))
		{
			geSlots.clear();
		}
	}

	// --- shared ---

	/** Noted deposits must land on the unnoted bank stack, hence the
	 * canonicalize. Runs on the client thread (item composition lookup). */
	private void credit(int itemId, int quantity)
	{
		try
		{
			int canonical = itemManager.canonicalize(itemId);
			bankStore.credit(canonical,
				itemManager.getItemComposition(canonical).getName(), quantity);
		}
		catch (Exception e)
		{
			log.debug("bank credit failed for item {}", itemId, e);
		}
	}

	private static Map<Integer, Integer> multiset(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() != -1)
			{
				counts.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	/** Per item id, how much less of it `after` holds than `before`. */
	static Map<Integer, Integer> decreases(Map<Integer, Integer> before,
		Map<Integer, Integer> after)
	{
		Map<Integer, Integer> out = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> was : before.entrySet())
		{
			int drop = was.getValue() - after.getOrDefault(was.getKey(), 0);
			if (drop > 0)
			{
				out.put(was.getKey(), drop);
			}
		}
		return out;
	}

	/**
	 * Prediction-vs-actual summary for the drift audit at an authoritative
	 * bank capture, or null when the prediction matched (or there was
	 * nothing predicted).
	 */
	static String drift(List<Map<String, Object>> predicted, List<Map<String, Object>> actual)
	{
		if (predicted == null || actual == null)
		{
			return null;
		}
		Map<Integer, Long> want = quantitiesById(predicted);
		Map<Integer, Long> got = quantitiesById(actual);
		List<String> lines = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : got.entrySet())
		{
			long off = e.getValue() - want.getOrDefault(e.getKey(), 0L);
			if (off != 0)
			{
				lines.add("item " + e.getKey() + " " + (off > 0 ? "+" : "") + off);
			}
		}
		for (Map.Entry<Integer, Long> e : want.entrySet())
		{
			if (!got.containsKey(e.getKey()))
			{
				lines.add("item " + e.getKey() + " -" + e.getValue());
			}
		}
		if (lines.isEmpty())
		{
			return null;
		}
		String head = String.join(", ", lines.subList(0, Math.min(10, lines.size())));
		return lines.size() + " stacks off prediction: " + head
			+ (lines.size() > 10 ? ", ..." : "");
	}

	private static Map<Integer, Long> quantitiesById(List<Map<String, Object>> items)
	{
		Map<Integer, Long> out = new HashMap<>();
		for (Map<String, Object> item : items)
		{
			Object id = item.get("id");
			Object qty = item.get("quantity");
			if (id instanceof Number && qty instanceof Number)
			{
				out.merge(((Number) id).intValue(), ((Number) qty).longValue(), Long::sum);
			}
		}
		return out;
	}

	/** Per GE slot, the offer's item and how much sits uncollected. Buy
	 * fills accrue from quantitySold deltas; a cancelled sell's remainder
	 * becomes collectable. Coins are not tracked. */
	static class GeSlots
	{
		private static final int SLOTS = 8;

		private final int[] item = new int[SLOTS];
		private final int[] uncollected = new int[SLOTS];
		private final int[] sold = new int[SLOTS];

		void offerChanged(int slot, GrandExchangeOfferState state, int itemId,
			int quantitySold, int totalQuantity)
		{
			if (slot < 0 || slot >= SLOTS)
			{
				return;
			}
			switch (state)
			{
				case EMPTY:
					item[slot] = 0;
					uncollected[slot] = 0;
					sold[slot] = 0;
					return;
				case BUYING:
				case BOUGHT:
				case CANCELLED_BUY:
					if (itemId != item[slot] || quantitySold < sold[slot])
					{
						// a new offer reusing the slot
						item[slot] = itemId;
						uncollected[slot] = 0;
						sold[slot] = 0;
					}
					uncollected[slot] += quantitySold - sold[slot];
					sold[slot] = quantitySold;
					return;
				case SELLING:
				case SOLD:
					// the sold portion collects as coins, not items
					item[slot] = itemId;
					sold[slot] = quantitySold;
					uncollected[slot] = 0;
					return;
				case CANCELLED_SELL:
					item[slot] = itemId;
					sold[slot] = quantitySold;
					uncollected[slot] = Math.max(0, totalQuantity - quantitySold);
					return;
				default:
			}
		}

		/** The uncollected {itemId, quantity} pairs, cleared by this call. */
		List<int[]> drain()
		{
			List<int[]> out = new ArrayList<>();
			for (int slot = 0; slot < SLOTS; slot++)
			{
				if (item[slot] > 0 && uncollected[slot] > 0)
				{
					out.add(new int[]{item[slot], uncollected[slot]});
				}
				uncollected[slot] = 0;
			}
			return out;
		}

		void clear()
		{
			for (int slot = 0; slot < SLOTS; slot++)
			{
				uncollected[slot] = 0;
			}
		}
	}
}

package com.osrscopilot;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executor;
import lombok.extern.slf4j.Slf4j;

/**
 * The player's last-seen bank, kept per account: the bank container is not
 * readable after it closes, so the last open is cached in memory and
 * persisted to disk. The account hash keys everything: a second account on
 * the same machine must never inherit the first one's bank.
 *
 * Mutators run on the client thread; disk writes go to the executor. The
 * synchronized blocks make the writer observe contents and accountHash as
 * a consistent pair.
 */
@Slf4j
class BankStore
{
	private final File dataDir;
	private final Gson gson;
	private final Executor ioExecutor;

	private List<Map<String, Object>> contents;
	/** Which account the in-memory/persisted bank belongs to.
	 * -1 = no account seen yet this session. */
	private long accountHash = -1;

	BankStore(File dataDir, Gson gson, Executor ioExecutor)
	{
		this.dataDir = dataDir;
		this.gson = gson;
		this.ioExecutor = ioExecutor;
	}

	/** Runs on the client thread. On the first tick of a session and on
	 * any account switch, drop the previous account's bank and load this
	 * one's persisted copy. */
	void sync(long hash)
	{
		if (hash == -1 || hash == accountHash)
		{
			return;
		}
		synchronized (this)
		{
			accountHash = hash;
			contents = null;
		}
		load(hash);
	}

	/** A fresh bank capture from an open bank container: cache and persist. */
	void update(List<Map<String, Object>> items)
	{
		synchronized (this)
		{
			contents = items;
		}
		persist();
	}

	/** Applies an out-of-band deposit (deposit box, GE collect-to-bank).
	 * Copy-on-write: the pipeline reads the contents list off-thread, so
	 * the reference is swapped, never mutated. No-op without a snapshot. */
	void credit(int itemId, String name, int quantity)
	{
		if (contents == null || accountHash == -1 || quantity <= 0)
		{
			return;
		}
		List<Map<String, Object>> next = new ArrayList<>(contents.size() + 1);
		boolean merged = false;
		for (Map<String, Object> entry : contents)
		{
			Object id = entry.get("id");
			if (!merged && id instanceof Number && ((Number) id).intValue() == itemId)
			{
				Object have = entry.get("quantity");
				Map<String, Object> updated = new LinkedHashMap<>(entry);
				updated.put("quantity",
					(have instanceof Number ? ((Number) have).longValue() : 0L) + quantity);
				next.add(updated);
				merged = true;
			}
			else
			{
				next.add(entry);
			}
		}
		if (!merged)
		{
			Map<String, Object> entry = new LinkedHashMap<>();
			entry.put("id", itemId);
			entry.put("name", name);
			entry.put("quantity", quantity);
			next.add(entry);
		}
		synchronized (this)
		{
			contents = next;
		}
		persist();
	}

	List<Map<String, Object>> contents()
	{
		return contents;
	}

	private File bankFile(long accountHash)
	{
		return new File(dataDir, "bank-" + Long.toUnsignedString(accountHash) + ".json");
	}

	private void persist()
	{
		if (contents == null || accountHash == -1)
		{
			return;
		}
		ioExecutor.execute(() ->
		{
			List<Map<String, Object>> snapshot;
			long hash;
			synchronized (this)
			{
				snapshot = contents;
				hash = accountHash;
			}
			if (snapshot == null || hash == -1)
			{
				return;
			}
			try
			{
				Files.write(bankFile(hash).toPath(),
					gson.toJson(snapshot).getBytes(StandardCharsets.UTF_8));
			}
			catch (IOException e)
			{
				log.warn("Bank persist failed", e);
			}
		});
	}

	private void load(long accountHash)
	{
		File f = bankFile(accountHash);
		if (!f.exists())
		{
			return;
		}
		try (BufferedReader r = Files.newBufferedReader(f.toPath(), StandardCharsets.UTF_8))
		{
			List<Map<String, Object>> loaded = gson.fromJson(r,
				new TypeToken<List<Map<String, Object>>>() { }.getType());
			synchronized (this)
			{
				contents = loaded;
			}
			log.info("Loaded persisted bank ({} items)",
				loaded != null ? loaded.size() : 0);
		}
		catch (Exception e)
		{
			log.warn("Bank load failed", e);
		}
	}
}

package com.osrscopilot;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("osrscopilot")
public interface CopilotConfig extends Config
{
	@ConfigSection(
		name = "LLM endpoint",
		description = "Any OpenAI-compatible chat completions API.",
		position = 0
	)
	String endpointSection = "endpoint";

	@ConfigSection(
		name = "Sampling",
		description = "Model sampling settings",
		position = 1
	)
	String samplingSection = "sampling";

	@ConfigSection(
		name = "Context & privacy",
		description = "What game state is sent with your questions",
		position = 2
	)
	String contextSection = "context";

	@ConfigSection(
		name = "Appearance",
		description = "How the chat panel looks",
		position = 3
	)
	String appearanceSection = "appearance";

	@ConfigSection(
		name = "Developer",
		description = "Diagnostics; leave off for normal use",
		position = 4,
		closedByDefault = true
	)
	String devSection = "developer";

	// ------------------------------------------------------------------
	// Endpoint
	// ------------------------------------------------------------------

	// The third-party-server disclosure is the Plugin Hub install warning;
	// nothing is sent to an LLM until the user configures an endpoint here.
	@ConfigItem(
		keyName = "provider",
		name = "Provider",
		description = "OpenRouter, or any custom OpenAI-compatible endpoint",
		section = endpointSection,
		position = 0
	)
	default LlmProvider provider()
	{
		return LlmProvider.OPENROUTER;
	}

	@ConfigItem(
		keyName = "apiKey",
		name = "API key",
		description = "Bearer token for the endpoint (leave empty if not required)",
		section = endpointSection,
		position = 1,
		secret = true
	)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(
		keyName = "model",
		name = "Model",
		description = "Model name as the endpoint expects it, e.g. deepseek/deepseek-chat on OpenRouter",
		section = endpointSection,
		position = 2
	)
	default String model()
	{
		return "";
	}

	@ConfigItem(
		keyName = "apiBaseUrl",
		name = "Custom base URL",
		description = "OpenAI-compatible base URL, used only when Provider is Custom, "
			+ "e.g. http://localhost:11434/v1",
		section = endpointSection,
		position = 3
	)
	default String apiBaseUrl()
	{
		return "";
	}

	// ------------------------------------------------------------------
	// Sampling
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "temperature",
		name = "Temperature",
		description = "Sampling temperature (0.0-2.0). Lower = more factual",
		section = samplingSection,
		position = 0
	)
	default double temperature()
	{
		return 0.2;
	}

	@ConfigItem(
		keyName = "maxTokens",
		name = "Max tokens",
		description = "Per-response token cap sent to the endpoint. Reasoning models "
			+ "spend their thinking from this budget too; if answers come back "
			+ "empty with a token-limit error, raise this.",
		section = samplingSection,
		position = 1
	)
	@Range(min = 256, max = 32768)
	default int maxTokens()
	{
		return 8192;
	}

	@ConfigItem(
		keyName = "maxToolTurns",
		name = "Max tool turns",
		description = "How many rounds of tool calls the model may make before being forced to answer",
		section = samplingSection,
		position = 2
	)
	// The heaviest questions (budget + ownership) take three research turns.
	@Range(min = 1, max = 8)
	default int maxToolTurns()
	{
		return 4;
	}

	// ------------------------------------------------------------------
	// Context & privacy
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "sendBank",
		name = "Send bank contents",
		description = "Include your bank in questions so answers know what you own",
		section = contextSection,
		position = 0
	)
	default boolean sendBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sendRecentEvents",
		name = "Send recent events",
		description = "Include recent drops, kills, and game messages as question context",
		section = contextSection,
		position = 1
	)
	default boolean sendRecentEvents()
	{
		return true;
	}

	// ------------------------------------------------------------------
	// Appearance
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "theme",
		name = "Theme",
		description = "Visual style of the chat panel: game-native dark, modern neutral, or parchment",
		section = appearanceSection,
		position = 0
	)
	default PanelTheme theme()
	{
		return PanelTheme.GAME_NATIVE;
	}

	@ConfigItem(
		keyName = "fontSize",
		name = "Text size",
		description = "Base size of chat message text, in pixels",
		section = appearanceSection,
		position = 1
	)
	@Range(min = 11, max = 24)
	default int fontSize()
	{
		return 13;
	}

	@ConfigItem(
		keyName = "simpleMode",
		name = "Simple answers",
		description = "Short plain-text replies without headings, tables, or lists. "
			+ "Also togglable from the chat panel.",
		section = appearanceSection,
		position = 2
	)
	default boolean simpleMode()
	{
		return false;
	}

	// ------------------------------------------------------------------
	// Developer
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "logEvents",
		name = "Log events to disk",
		description = "Append gameplay events to a JSONL log (diagnostics)",
		section = devSection,
		position = 0
	)
	default boolean logEvents()
	{
		return false;
	}

	@ConfigItem(
		keyName = "logMenuClicks",
		name = "Log menu clicks",
		description = "Include every menu click in the event log (noisy)",
		section = devSection,
		position = 1
	)
	default boolean logMenuClicks()
	{
		return false;
	}
}

package com.osrscopilot;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Insets;
import java.awt.event.ActionListener;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JEditorPane;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPasswordField;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.event.HyperlinkEvent;
import javax.swing.event.HyperlinkListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * Sidebar chat panel. Pure view: collects questions, renders answers from a
 * {@link TranscriptModel}. All methods must be called on the Swing EDT.
 * Cards are custom-painted (Swing's HTML renderer is stuck in HTML 3.2);
 * HTML is used only for text flow inside a card.
 */
class CopilotPanel extends PluginPanel
{
	private static final int RENDER_THROTTLE_MS = 100;

	private final Theme theme = Theme.active();

	private final TranscriptModel model = new TranscriptModel();
	/** The card currently displaying each block; rebuilt on structural
	 * changes, patched in place while streaming. */
	private final Map<TranscriptModel.Block, MessageCard> cards = new HashMap<>();

	private final JPanel messageList = new ScrollableStack();
	private final JScrollPane scroll;
	private final JTextField input;
	private final JButton send;
	private final JButton clear;
	private final JButton popOut;
	private final FlatToggle simple;
	private final JLabel status = SwingUtil.smoothLabel(" ");
	private final Timer renderTimer;
	private final Timer pulseTimer;
	private int pulse;

	private final HyperlinkListener linkOpener = e -> {
		if (e.getEventType() == HyperlinkEvent.EventType.ACTIVATED)
		{
			LinkBrowser.browse(e.getDescription());
		}
	};

	private Consumer<String> askHandler;
	private Runnable clearHandler;
	private Consumer<Boolean> simpleModeHandler;
	private SetupHandler setupHandler;
	private final SetupCard setupCard;
	private final FlatButton setupLink;
	private final JPanel setupLinkRow;
	private boolean setupOpen;
	private boolean setupConfigured;
	private boolean busy;
	private String statusBase = " ";

	// Pop-out support: the chat UI sits on `content`, which lives either in
	// this sidebar panel or in a free-floating resizable frame.
	private final JPanel content = new JPanel(new BorderLayout(0, 8));
	private final PopOutManager popOutManager;

	/** Base pixel size for message text; everything HTML scales from it. */
	private final int bodyFontPx;

	CopilotPanel(int bodyFontPx)
	{
		super(false);
		this.bodyFontPx = bodyFontPx;
		setLayout(new BorderLayout());
		setBackground(theme.chromeBg);

		input = new RoundedField(theme);
		send = new FlatButton("Ask", theme, true);
		clear = new FlatButton("New chat", theme, false);
		popOut = new FlatButton("Pop out", theme, false);
		simple = new FlatToggle("Simple", theme);
		simple.setToolTipText("Short plain-text answers");
		setupCard = new SetupCard();
		setupLink = new FlatButton(" ", theme, false);
		setupLink.setToolTipText("Show or hide the LLM connection settings");
		setupLink.addActionListener(e -> setSetupOpen(!setupOpen));
		setupLinkRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 8));
		setupLinkRow.setOpaque(false);
		setupLinkRow.add(setupLink);
		styleSetupLink();
		popOutManager = new PopOutManager(this, content, popOut, input, theme);

		messageList.setBackground(theme.surface);
		messageList.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		scroll = new JScrollPane(messageList);
		scroll.setPreferredSize(new Dimension(0, 420));
		scroll.setBorder(null);
		scroll.getViewport().setBackground(theme.surface);
		scroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		SwingUtil.styleScrollBar(scroll.getVerticalScrollBar(), theme);

		input.setToolTipText("Ask about gear, quests, drops, prices, training...");

		status.setFont(theme.statusFont != null ? theme.statusFont.deriveFont(16f)
			: status.getFont().deriveFont(Font.ITALIC, 12f));
		status.setForeground(theme.statusFg);
		status.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));

		JPanel inputRow = new JPanel(new BorderLayout(6, 0));
		inputRow.setOpaque(false);
		inputRow.add(input, BorderLayout.CENTER);
		inputRow.add(send, BorderLayout.EAST);

		JPanel statusRow = new JPanel(new BorderLayout(6, 0));
		statusRow.setOpaque(false);
		statusRow.add(status, BorderLayout.CENTER);
		statusRow.add(simple, BorderLayout.EAST);

		JPanel south = new JPanel(new BorderLayout(0, 4));
		south.setOpaque(false);
		south.add(inputRow, BorderLayout.CENTER);
		south.add(statusRow, BorderLayout.SOUTH);

		JLabel wordmark = SwingUtil.smoothLabel("COPILOT");
		wordmark.setForeground(theme.accent);
		wordmark.setFont(theme.chromeFont != null ? theme.chromeFont.deriveFont(16f)
			: wordmark.getFont().deriveFont(Font.BOLD, 12f));
		wordmark.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 0));

		JPanel northButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		northButtons.setOpaque(false);
		northButtons.add(popOut);
		northButtons.add(clear);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		clear.setToolTipText("Start a new conversation (clears context)");
		popOut.setToolTipText("Open the chat in its own resizable window");
		north.add(wordmark, BorderLayout.WEST);
		north.add(northButtons, BorderLayout.EAST);

		// The whole chat UI lives on one movable panel so the pop-out can
		// carry it into a resizable window.
		content.setBackground(theme.chromeBg);
		content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		content.add(north, BorderLayout.NORTH);
		content.add(scroll, BorderLayout.CENTER);
		content.add(south, BorderLayout.SOUTH);
		add(content, BorderLayout.CENTER);

		popOut.addActionListener(e -> popOutManager.toggle());

		renderTimer = new Timer(RENDER_THROTTLE_MS, e -> render());
		renderTimer.setRepeats(false);
		// Animates the status ellipsis while the model works.
		pulseTimer = new Timer(400, e -> {
			pulse++;
			refreshStatus();
		});

		ActionListener submit = e -> fireAsk();
		input.addActionListener(submit);
		send.addActionListener(submit);
		clear.addActionListener(e -> fireClear());
		// The click handler fires only on clicks, so programmatic state sync
		// via setSimpleMode never echoes back into the handler.
		simple.setToggleHandler(on -> {
			if (simpleModeHandler != null)
			{
				simpleModeHandler.accept(on);
			}
		});

		rebuild();
	}

	/** Plugin shutdown: a floating chat window must not outlive the plugin. */
	void closePopOut()
	{
		popOutManager.close();
	}

	/** Replay one completed exchange into a fresh panel (theme and font-size
	 * changes rebuild the panel). The answer re-renders as decorated HTML
	 * and meta line when available, markdown otherwise. */
	void seedExchange(String question, String answer, String decoratedHtml, String meta)
	{
		model.seedExchange(question, answer, decoratedHtml, meta);
		rebuild();
	}

	void setAskHandler(Consumer<String> handler)
	{
		askHandler = handler;
	}

	void setClearHandler(Runnable handler)
	{
		clearHandler = handler;
	}

	/** Called when the player clicks the Simple toggle. */
	void setSimpleModeHandler(Consumer<Boolean> handler)
	{
		simpleModeHandler = handler;
	}

	/** Everything the setup form edits, mirroring the config entries. */
	static final class SetupValues
	{
		final LlmProvider provider;
		final String apiKey;
		final String model;
		final String customUrl;
		final double temperature;
		final int maxTokens;
		final int toolTurns;

		SetupValues(LlmProvider provider, String apiKey, String model, String customUrl,
			double temperature, int maxTokens, int toolTurns)
		{
			this.provider = provider;
			this.apiKey = apiKey;
			this.model = model;
			this.customUrl = customUrl;
			this.temperature = temperature;
			this.maxTokens = maxTokens;
			this.toolTurns = toolTurns;
		}
	}

	/** Both methods are called on the EDT with the form's current values.
	 * Test fires one tiny completion against those values without saving
	 * them; onDone must run on the EDT and receives null on success, else
	 * a display error message. */
	interface SetupHandler
	{
		void save(SetupValues values);

		void test(SetupValues values, Consumer<String> onDone);
	}

	void setSetupHandler(SetupHandler handler)
	{
		setupHandler = handler;
	}

	/** Sync the setup form to the config values without firing the handler. */
	void setSetupState(SetupValues values)
	{
		setupCard.setState(values);
		setupConfigured = values.model != null && !values.model.trim().isEmpty();
		styleSetupLink();
	}

	/** Expand or collapse the setup form (dev tool + tests). */
	void setSetupOpen(boolean open)
	{
		setupOpen = open;
		rebuild();
	}

	/** Sync the toggle to the config value without firing the handler. */
	void setSimpleMode(boolean on)
	{
		simple.setSelected(on);
	}

	private void fireAsk()
	{
		String question = input.getText().trim();
		if (question.isEmpty() || busy || askHandler == null)
		{
			return;
		}
		model.beginQuestion(question);
		rebuild();
		input.setText("");
		setBusy(true);
		askHandler.accept(question);
	}

	private void fireClear()
	{
		if (busy)
		{
			return;
		}
		model.clear();
		rebuild();
		setStatusBase(" ");
		status.setToolTipText(null);
		status.setForeground(theme.statusFg);
		if (clearHandler != null)
		{
			clearHandler.run();
		}
	}

	/** A fragment of the streamed answer arrived. */
	void appendDelta(String text)
	{
		if (model.appendDelta(text))
		{
			rebuild();
		}
		scheduleRender();
	}

	/** Streamed text turned out not to be the answer (tool-call preamble);
	 * the model keeps it as a dim working note. */
	void discardPartial()
	{
		if (model.discardPartial())
		{
			scheduleRender();
		}
	}

	/** A pipeline progress note ("Looking up: ..."): shown dim inside the
	 * answer card and echoed to the status line. */
	void showWorking(String note)
	{
		if (model.addWorkingNote(note))
		{
			rebuild();
		}
		setStatusBase(note);
		scheduleRender();
	}

	void showAnswerDone(String answer, String decoratedHtml, double seconds,
		boolean bankSeen, String meta)
	{
		TranscriptModel.Block done = model.completeAnswer(answer, decoratedHtml, meta);
		if (cards.get(done) == null)
		{
			rebuild();
		}
		else
		{
			syncCard(done);
		}
		setBusy(false);
		if (bankSeen)
		{
			setStatusBase(String.format("answered in %.1fs", seconds));
			status.setToolTipText(null);
		}
		else
		{
			// Without bank contents the copilot can't tell "you don't own it"
			// from "I can't see it", so gear answers stay hypothetical.
			setStatusBase("answered - open your bank once for gear answers");
			status.setToolTipText("<html><body style='width:280px'>Bank contents are "
				+ "read when the bank is opened, then persist across sessions.</body></html>");
		}
	}

	/** Roll the conversation back to before this question and put the
	 * question text back in the input box so the player can resubmit. */
	void showError(String message)
	{
		String question = model.rollback();
		rebuild();
		if (question != null)
		{
			input.setText(question);
		}
		setBusy(false);
		setStatusBase("Error - press Enter to retry (hover for details)");
		status.setToolTipText("<html><body style='width:280px'>" + SwingUtil.escapeHtml(message)
			+ "</body></html>");
		status.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
	}

	private void setBusy(boolean b)
	{
		busy = b;
		input.setEnabled(!b);
		send.setEnabled(!b);
		clear.setEnabled(!b);
		if (b)
		{
			setStatusBase("Thinking");
			status.setForeground(theme.statusFg);
			status.setToolTipText(null);
			pulseTimer.start();
		}
		else
		{
			pulseTimer.stop();
			refreshStatus();
		}
	}

	private void setStatusBase(String text)
	{
		statusBase = text;
		refreshStatus();
	}

	private void refreshStatus()
	{
		status.setText(busy && !statusBase.trim().isEmpty()
			? statusBase + ".".repeat(1 + pulse % 3) : statusBase);
	}

	// ------------------------------------------------------------------
	// Rendering
	// ------------------------------------------------------------------

	/** Coalesces bursts of streaming deltas into ~10 renders/second. */
	private void scheduleRender()
	{
		if (!renderTimer.isRunning())
		{
			renderTimer.start();
		}
	}

	/** Streaming refresh: only the live block's card re-renders. */
	private void render()
	{
		if (model.answerBlock() != null)
		{
			syncCard(model.answerBlock());
		}
	}

	/** Rebuild the card stack from the model. Structural changes only
	 * (new turn, rollback, clear); streaming goes through syncCard. */
	private void rebuild()
	{
		messageList.removeAll();
		cards.clear();
		if (model.isEmpty())
		{
			messageList.add(welcomePane());
			messageList.add(setupLinkRow);
			if (setupOpen)
			{
				messageList.add(setupCard);
			}
		}
		for (TranscriptModel.Block block : model.blocks())
		{
			MessageCard card = new MessageCard(theme, block.isUser(), linkOpener, bodyFontPx);
			cards.put(block, card);
			syncCard(block);
			messageList.add(card);
		}
		messageList.revalidate();
		messageList.repaint();
		scrollToBottom();
	}

	private void syncCard(TranscriptModel.Block block)
	{
		MessageCard card = cards.get(block);
		if (card == null)
		{
			return;
		}
		// Secondary text stays at HTML size 3: size 2 maps to ~10px in
		// Swing's renderer, which is unreadable.
		StringBuilder html = new StringBuilder();
		if (block.isUser() && theme.userAsChatLine)
		{
			html.append("<font color='").append(theme.userPrefixHex)
				.append("'><b>You:</b></font> ");
		}
		for (String note : block.working)
		{
			html.append("<font size='3' color='").append(theme.noteHex).append("'><i>")
				.append(SwingUtil.escapeHtml(note)).append("</i></font><br>");
		}
		html.append(block.decoratedHtml != null ? block.decoratedHtml
			: MarkdownHtml.toHtml(block.text.toString()));
		if (model.isStreaming(block))
		{
			// Streaming: a caret keeps the block visibly alive.
			html.append("<font color='").append(theme.caretHex)
				.append("'><b>&#9612;</b></font>");
		}
		if (block.meta != null && !block.meta.isEmpty())
		{
			// Meta arrives as HTML from answerMeta (its only producer), which
			// escapes the dynamic parts itself: fact titles carry source links.
			html.append("<br><font size='3' color='").append(theme.metaHex).append("'>")
				.append(block.meta).append("</font>");
		}
		card.setBodyHtml(html.toString());
		scrollToBottom();
	}

	private void scrollToBottom()
	{
		SwingUtilities.invokeLater(() -> {
			JScrollBar bar = scroll.getVerticalScrollBar();
			bar.setValue(bar.getMaximum());
		});
	}

