	/** Flat themed button with a hover state and hand cursor. */
	private static final class FlatButton extends JButton
	{
		private final Color bg;
		private final Color bgHover;
		private final Color bgDisabled;
		private final int arc;
		private boolean hover;

		FlatButton(String text, Theme theme, boolean primary)
		{
			super(text);
			this.bg = primary ? theme.primaryBg : theme.buttonBg;
			this.bgHover = primary ? theme.primaryHover : theme.buttonHover;
			// Disabled buttons recede to the secondary surface; a primary
			// fill under gray text is illegible.
			this.bgDisabled = theme.buttonBg;
			this.arc = theme.arc;
			setForeground(primary ? theme.primaryFg : theme.buttonFg);
			setFocusPainted(false);
			setContentAreaFilled(false);
			setBorderPainted(false);
			setOpaque(false);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			setBorder(BorderFactory.createEmptyBorder(5, 12, 5, 12));
			if (theme.chromeFont != null)
			{
				setFont(theme.chromeFont.deriveFont(16f));
			}
			else if (primary)
			{
				setFont(getFont().deriveFont(Font.BOLD));
			}
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					hover = true;
					repaint();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = false;
					repaint();
				}
			});
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			SwingUtil.paintRounded(g, this, arc,
				!isEnabled() ? bgDisabled : hover ? bgHover : bg, null, null);
			SwingUtil.smooth(g);
			super.paintComponent(g);
		}
	}

	/** The Simple-mode control: clickable status text ("Simple: off/on").
	 * Deliberately a JLabel, not a JToggleButton: the client's Substance
	 * LAF paints button text from its own scheme and ignores
	 * setForeground. */
	private static final class FlatToggle extends JLabel
	{
		private final Theme theme;
		private final String label;
		/** Off state: the status color at reduced opacity. */
		private final Color offFg;
		private boolean selected;
		private boolean hover;
		private Consumer<Boolean> toggleHandler;

		FlatToggle(String label, Theme theme)
		{
			this.theme = theme;
			this.label = label;
			this.offFg = new Color(theme.statusFg.getRed(), theme.statusFg.getGreen(),
				theme.statusFg.getBlue(), 155);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			// Top inset drops the text to sit on the status line's baseline.
			setBorder(BorderFactory.createEmptyBorder(3, 6, 0, 2));
			// Matches the status label's font so the row reads as one line.
			setFont(theme.statusFont != null ? theme.statusFont.deriveFont(16f)
				: getFont().deriveFont(12f));
			refresh();
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					// A label hears every button; only a left click toggles.
					if (!SwingUtilities.isLeftMouseButton(e))
					{
						return;
					}
					selected = !selected;
					refresh();
					if (toggleHandler != null)
					{
						toggleHandler.accept(selected);
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					hover = true;
					refresh();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = false;
					refresh();
				}
			});
		}

		/** Fires on clicks only, never on programmatic setSelected. */
		void setToggleHandler(Consumer<Boolean> handler)
		{
			toggleHandler = handler;
		}

		void setSelected(boolean on)
		{
			selected = on;
			refresh();
		}

		private void refresh()
		{
			setText(label + ": " + (selected ? "on" : "off"));
			setForeground(hover ? theme.buttonFg
				: selected ? theme.statusFg : offFg);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			SwingUtil.smooth(g);
			super.paintComponent(g);
		}
	}

	/** Themed text field; the border brightens on focus. */
	private static final class RoundedField extends JTextField
	{
		private final Theme theme;

		RoundedField(Theme theme)
		{
			this.theme = theme;
			setOpaque(false);
			setBackground(theme.inputBg);
			setForeground(theme.inputText);
			setCaretColor(theme.inputText);
			setBorder(BorderFactory.createEmptyBorder(6, 10, 6, 10));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			SwingUtil.paintRounded(g, this, theme.arc, theme.inputBg,
				hasFocus() ? theme.inputFocusEdge : theme.inputEdge, null);
			SwingUtil.smooth(g);
			super.paintComponent(g);
		}
	}
}

