/**
 * OSRS Copilot: ask questions in the side panel, answered by an LLM with
 * your live game state and facts fetched from the OSRS Wiki / Grand
 * Exchange. The user configures only their LLM endpoint, key, model, and
 * sampling.
 */
@Slf4j
@PluginDescriptor(
	name = "OSRS Copilot",
	description = "Bring your own LLM! Supports OpenRouter or any OpenAI-compatible endpoint.",
	tags = {"ai", "copilot", "assistant", "llm"}
)
public class CopilotPlugin extends Plugin
{
	private static final File DATA_DIR = new File(RuneLite.RUNELITE_DIR, "osrs-copilot");
	private static final File CACHE_DIR = new File(DATA_DIR, "cache");

	/** The nexus Teleport Menu interface, calibrated in-game 2026-08-30;
	 * its first text is "Portal Nexus". */
	private static final int NEXUS_MENU_GROUP = 17;

	@Inject
	private Client client;

	@Inject
	private CopilotConfig config;

	@Inject
	private Gson gson;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private SkillIconManager skillIconManager;

	/** RuneLite's shared background thread: right for small tasks like the
	 * bank persist writes, which must stay off the client thread. */
	@Inject
	private ScheduledExecutorService sharedExecutor;

	/** Dedicated pipeline worker: RuneLite's injected executor is one
	 * shared thread for every plugin, and a multi-minute LLM stream would
	 * stall it. A private single thread also serializes questions and
	 * dies with the plugin. */
	private ExecutorService pipelineExecutor;

	private CopilotPipeline pipeline;
	private CopilotPanel panel;
	private NavigationButton navButton;
	private IconStore iconStore;
	private BufferedImage navIcon;

	// Question flow must hop threads: Swing EDT (submit) -> client thread
	// (capture; Quest.getState runs scripts, so never from a script callback)
	// -> executor (pipeline; network + LLM) -> Swing EDT (render).
	private volatile String pendingQuestion;
	private String pendingSnapshotLabel;
	private BankStore bankStore;
	private BankMutations bankMutations;
	private HouseStore houseStore;
	/** Facilities seen in the current scene; cleared on every scene load,
	 * committed to the store only while the player stands in the POH. */
	private final Set<String> houseSeen = new LinkedHashSet<>();
	private boolean housePendingCommit;
	private boolean pendingNexusScrape;
	/** Arms the drift audit for the next bank capture; set at startup and
	 * whenever the bank interface closes, cleared once the visit's first
	 * capture has been audited. */
	private boolean bankDriftAuditArmed = true;
	private EventRecorder events;
	private GameStateReader reader;

	/** One completed turn: the pipeline exchange (LLM history) plus what the
	 * turn rendered. Panel rebuilds (theme/font-size changes) replay the
	 * rendered form verbatim, so decoration and meta survive them. */
	private static final class Turn
	{
		final CopilotPipeline.Exchange exchange;
		final String decoratedHtml;
		final String meta;

		Turn(CopilotPipeline.Exchange exchange, String decoratedHtml, String meta)
		{
			this.exchange = exchange;
			this.decoratedHtml = decoratedHtml;
			this.meta = meta;
		}
	}

	// Conversation session: completed exchanges only (errors never enter).
	// Touched from the EDT and the executor, hence the synchronization.
	private final List<Turn> conversation = new ArrayList<>();

	@Override
	protected void startUp() throws Exception
	{
		DATA_DIR.mkdirs();
		bankStore = new BankStore(DATA_DIR, gson, sharedExecutor);
		bankMutations = new BankMutations(bankStore, itemManager);
		houseStore = new HouseStore(DATA_DIR, gson, sharedExecutor);
		events = new EventRecorder(client, gson, config, DATA_DIR);
		reader = new GameStateReader(client, configManager, config, bankStore, houseStore, events);

		pipelineExecutor = Executors.newSingleThreadExecutor(r -> {
			Thread t = new Thread(r, "osrs-copilot-pipeline");
			t.setDaemon(true);
			return t;
		});
		pipeline = new CopilotPipeline(okHttpClient, gson, CACHE_DIR);
		// Warming only fetches static vocabulary from the plugin's GitHub;
		// nothing reaches an LLM until the user configures an endpoint.
		pipelineExecutor.execute(pipeline::warmCaches);
		iconStore = new IconStore(new File(CACHE_DIR, "icons"),
			itemManager, spriteManager, skillIconManager);

		Theme.setActive(Theme.byName(config.theme().key));
		navIcon = ImageUtil.loadImageResource(CopilotPlugin.class, "nav-icon.png");
		panel = createPanel();
		navButton = createNavButton(panel);
		clientToolbar.addNavigation(navButton);

		if (config.logEvents())
		{
			events.openLog();
		}
		log.info("OSRS Copilot started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::closePopOut);
		}
		if (events != null)
		{
			events.closeLog();
		}
		if (pipelineExecutor != null)
		{
			// Drops queued work; an in-flight HTTP read runs out its
			// timeout on the dying daemon thread.
			pipelineExecutor.shutdownNow();
			pipelineExecutor = null;
		}
		// The plugin instance outlives disable, so everything sizable must
		// be released: the pipeline's vocabulary sets and page cache, the
		// panel's rendered conversation, and the capture state.
		pipeline = null;
		panel = null;
		iconStore = null;
		navIcon = null;
		bankStore = null;
		bankMutations = null;
		houseStore = null;
		houseSeen.clear();
		events = null;
		reader = null;
		pendingQuestion = null;
		pendingSnapshotLabel = null;
		synchronized (conversation)
		{
			conversation.clear();
		}
	}

	@Provides
	CopilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CopilotConfig.class);
	}

	private CopilotPanel createPanel()
	{
		CopilotPanel p = new CopilotPanel(config.fontSize());
		p.setAskHandler(this::askQuestion);
		p.setClearHandler(() -> {
			synchronized (conversation)
			{
				conversation.clear();
			}
		});
		// The config entry is the single source of truth for simple mode;
		// the chat toggle is just a shortcut to it.
		p.setSimpleMode(config.simpleMode());
		p.setSimpleModeHandler(on ->
			configManager.setConfiguration("osrscopilot", "simpleMode", on));
		// Same deal for the setup form: it reads and writes the config
		// entries the settings panel edits.
		p.setSetupState(setupValues());
		p.setSetupHandler(new CopilotPanel.SetupHandler()
		{
			@Override
			public void save(CopilotPanel.SetupValues v)
			{
				configManager.setConfiguration("osrscopilot", "provider", v.provider);
				configManager.setConfiguration("osrscopilot", "apiKey", v.apiKey);
				configManager.setConfiguration("osrscopilot", "model", v.model);
				if (v.provider == LlmProvider.CUSTOM)
				{
					configManager.setConfiguration("osrscopilot", "apiBaseUrl", v.customUrl);
				}
				configManager.setConfiguration("osrscopilot", "temperature", v.temperature);
				configManager.setConfiguration("osrscopilot", "maxTokens", v.maxTokens);
				configManager.setConfiguration("osrscopilot", "maxToolTurns", v.toolTurns);
			}

			@Override
			public void test(CopilotPanel.SetupValues v, java.util.function.Consumer<String> onDone)
			{
				String baseUrl = v.provider.baseUrl != null ? v.provider.baseUrl : v.customUrl;
				Llm.Settings settings = new Llm.Settings(baseUrl, v.apiKey, v.model,
					v.temperature, v.maxTokens);
				pipelineExecutor.execute(() -> {
					String error = null;
					try
					{
						pipeline.testEndpoint(settings);
					}
					catch (Exception e)
					{
						log.debug("endpoint test failed", e);
						error = friendlyError(e);
					}
					String err = error;
					SwingUtilities.invokeLater(() -> onDone.accept(err));
				});
			}
		});
		return p;
	}

	private CopilotPanel.SetupValues setupValues()
	{
		return new CopilotPanel.SetupValues(config.provider(), config.apiKey(),
			config.model(), config.apiBaseUrl(), config.temperature(),
			config.maxTokens(), config.maxToolTurns());
	}

	private NavigationButton createNavButton(CopilotPanel forPanel)
	{
		return NavigationButton.builder()
			.tooltip("OSRS Copilot")
			.icon(navIcon)
			.priority(7)
			.panel(forPanel)
			.build();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"osrscopilot".equals(event.getGroup()))
		{
			return;
		}
		if ("theme".equals(event.getKey()) || "fontSize".equals(event.getKey()))
		{
			// Both rebuild the panel and replay the conversation into it.
			SwingUtilities.invokeLater(this::applyTheme);
		}
		if ("simpleMode".equals(event.getKey()) && panel != null)
		{
			// Changed from the RuneLite config panel: mirror it on the toggle.
			SwingUtilities.invokeLater(() -> panel.setSimpleMode(config.simpleMode()));
		}
		String key = event.getKey();
		if (("provider".equals(key) || "apiKey".equals(key) || "model".equals(key)
			|| "apiBaseUrl".equals(key) || "temperature".equals(key)
			|| "maxTokens".equals(key) || "maxToolTurns".equals(key)) && panel != null)
		{
			// Mirror config-panel edits into the setup form.
			SwingUtilities.invokeLater(() -> panel.setSetupState(setupValues()));
		}
	}

	/** A theme is baked into every component at construction, so switching
	 * builds a fresh panel and replays the conversation into it exactly as
	 * rendered. */
	private void applyTheme()
	{
		if (panel == null)
		{
			return;
		}
		Theme.setActive(Theme.byName(config.theme().key));
		panel.closePopOut();
		clientToolbar.removeNavigation(navButton);
		panel = createPanel();
		synchronized (conversation)
		{
			for (Turn turn : conversation)
			{
				panel.seedExchange(turn.exchange.question, turn.exchange.answer,
					turn.decoratedHtml, turn.meta);
			}
		}
		navButton = createNavButton(panel);
		clientToolbar.addNavigation(navButton);
	}

	// ------------------------------------------------------------------
	// Ask flow
	// ------------------------------------------------------------------

	/** Called from the Swing EDT when the player submits a question. */
	private void askQuestion(String question)
	{
		Llm.Settings settings = llmSettings();
		if (!settings.isConfigured())
		{
			panel.showError("Set up your LLM first: click New chat and fill in the form, "
				+ "or use the plugin settings (wrench icon -> OSRS Copilot).");
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			panel.showError("Log in first - the copilot needs your game state.");
			return;
		}
		pendingQuestion = question;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		bankStore.sync(client.getAccountHash());

		if (pendingSnapshotLabel != null)
		{
			String label = pendingSnapshotLabel;
			pendingSnapshotLabel = null;
			File f = dumpSnapshot(label);
			String msg = f != null
				? "Copilot: snapshot written to " + f.getName()
				: "Copilot: snapshot FAILED, see client log";
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
		}
		houseStore.sync(client.getAccountHash());
		if (housePendingCommit && inPoh())
		{
			housePendingCommit = false;
			List<String> facilities = new ArrayList<>(houseSeen);
			facilities.sort(String::compareTo);
			houseStore.updateFacilities(facilities);
		}
		if (pendingNexusScrape)
		{
			pendingNexusScrape = false;
			List<String> destinations =
				HouseStore.parseNexusMenu(widgetGroupTexts(NEXUS_MENU_GROUP));
			if (destinations != null)
			{
				houseStore.updateNexus(destinations);
			}
		}

		if (pendingQuestion != null)
		{
			String question = pendingQuestion;
			pendingQuestion = null;
			GameCapture capture = reader.buildCapture();
			Llm.Settings settings = llmSettings();
			int maxTurns = config.maxToolTurns();
			boolean simpleMode = config.simpleMode();
			pipelineExecutor.execute(() ->
				runPipeline(question, capture, settings, maxTurns, simpleMode));
		}
	}

	/** Runs on the executor: wiki prefetch + LLM calls, streamed to the panel. */
	private void runPipeline(String question, GameCapture capture, Llm.Settings settings,
		int maxTurns, boolean simpleMode)
	{
		// Locals, not fields: shutDown nulls the fields, and this method may
		// still be finishing an HTTP read on the dying daemon thread.
		CopilotPipeline pipeline = this.pipeline;
		CopilotPanel panel = this.panel;
		IconStore iconStore = this.iconStore;
		if (pipeline == null || panel == null)
		{
			return;
		}
		StreamListener listener = new StreamListener()
		{
			@Override
			public void onDelta(String text)
			{
				SwingUtilities.invokeLater(() -> panel.appendDelta(text));
			}

			@Override
			public void onTurnDiscarded()
			{
				SwingUtilities.invokeLater(panel::discardPartial);
			}

			@Override
			public void onStatus(String status)
			{
				SwingUtilities.invokeLater(() -> panel.showWorking(status));
			}
		};

		List<CopilotPipeline.Exchange> history = new ArrayList<>();
		synchronized (conversation)
		{
			for (Turn turn : conversation)
			{
				history.add(turn.exchange);
			}
		}

		try
		{
			CopilotPipeline.Result result =
				pipeline.answer(question, history, capture, settings, maxTurns,
					simpleMode, listener);
			log.debug("answered in {}ms, {} fact blocks, {} tool calls, {} context chars",
				result.millis, result.factBlocks, result.toolLog.size(), result.contextChars);
			String meta = answerMeta(result, gson);
			// Decoration runs on the worker (it may fetch the GE
			// catalogue); a failure costs only the styling.
			String decorated = null;
			try
			{
				decorated = AnswerDecorator
					.build(capture, result.route != null ? result.route.entities : null,
						pipeline.knownMonsterNames(), pipeline.knownItems(), iconStore)
					.decorate(MarkdownHtml.toHtml(result.answer));
			}
			catch (Exception e)
			{
				log.warn("answer decoration failed", e);
			}
			String decoratedHtml = decorated;
			synchronized (conversation)
			{
				conversation.add(new Turn(
					new CopilotPipeline.Exchange(question, result.answer, result.subject),
					decoratedHtml, meta));
			}
			SwingUtilities.invokeLater(() ->
				panel.showAnswerDone(result.answer, decoratedHtml, result.millis / 1000.0,
					capture.bank != null, meta));
		}
		catch (Exception e)
		{
			log.warn("Copilot pipeline failed", e);
			SwingUtilities.invokeLater(() -> panel.showError(friendlyError(e)));
		}
	}

	/** One dim HTML line under each answer disclosing what the model was
	 * given. Wiki pages link their edit history: the contributors hold the
	 * copyright (CC BY-NC-SA). Underlines are explicit because the shared
	 * stylesheet suppresses them for entity links. */
	static String answerMeta(CopilotPipeline.Result result, Gson gson)
	{
		StringBuilder sb = new StringBuilder();
		if (result.factTitles.isEmpty())
		{
			sb.append("no facts retrieved");
		}
		else
		{
			sb.append("facts: ");
			for (int i = 0; i < result.factTitles.size(); i++)
			{
				String title = result.factTitles.get(i);
				String page = CopilotPipeline.factSourcePage(title);
				String display = SwingUtil.escapeHtml(CopilotPipeline.factDisplayTitle(title));
				sb.append(i > 0 ? "; " : "")
					.append(page == null ? display : historyLink(page, display));
			}
		}
		if (result.toolLog != null && !result.toolLog.isEmpty())
		{
			sb.append(" | tools: ");
			for (int i = 0; i < result.toolLog.size(); i++)
			{
				sb.append(i > 0 ? ", " : "").append(toolHtml(gson, result.toolLog.get(i)));
			}
		}
		if (result.usage != null)
		{
			sb.append(" | tokens ").append(result.usage.promptTokens).append(" in / ")
				.append(result.usage.completionTokens).append(" out");
		}
		if (!result.suspectNames.isEmpty())
		{
			sb.append(" | unverified names: ")
				.append(SwingUtil.escapeHtml(String.join(", ", result.suspectNames)));
		}
		return sb.toString();
	}

	private static String historyLink(String page, String escapedText)
	{
		return "<a href='" + AnswerDecorator.wikiUrl(page) + "?action=history'><u>"
			+ escapedText + "</u></a>";
	}

	/** One tool-log entry ("name({json})") as footer HTML. Single-argument
	 * calls display just the value; page-backed tools (wiki_page,
	 * item_stats) link the page like a fact. Anything unexpected falls back
	 * to the raw entry. */
	private static String toolHtml(Gson gson, String entry)
	{
		int paren = entry.indexOf('(');
		if (paren > 0 && entry.endsWith(")"))
		{
			String name = entry.substring(0, paren);
			try
			{
				JsonObject args = gson.fromJson(
					entry.substring(paren + 1, entry.length() - 1), JsonObject.class);
				if (args.size() == 1)
				{
					JsonElement only = args.entrySet().iterator().next().getValue();
					if (only.isJsonPrimitive() && only.getAsJsonPrimitive().isString())
					{
						String value = only.getAsString();
						String display = SwingUtil.escapeHtml(name + "(" + value + ")");
						return "wiki_page".equals(name) || "item_stats".equals(name)
							? historyLink(value, display) : display;
					}
				}
			}
			catch (RuntimeException e)
			{
				log.debug("unparseable tool log entry: {}", entry);
			}
		}
		return SwingUtil.escapeHtml(entry);
	}

	private Llm.Settings llmSettings()
	{
		LlmProvider provider = config.provider();
		String baseUrl = provider.baseUrl != null ? provider.baseUrl : config.apiBaseUrl();
		return new Llm.Settings(baseUrl, config.apiKey(), config.model(),
			config.temperature(), config.maxTokens());
	}

	/** Maps failures by kind -- HTTP status class or transport error -- with
	 * the server's own message as the detail. No per-endpoint cases. */
	private static String friendlyError(Exception e)
	{
		if (e instanceof EmptyAnswerException)
		{
			return "The model didn't produce an answer: " + e.getMessage()
				+ ". Press Enter to resubmit.";
		}
		if (e instanceof HttpException)
		{
			HttpException he = (HttpException) e;
			String detail = he.serverMessage.isEmpty() ? he.getMessage() : he.serverMessage;
			if (he.code == 401 || he.code == 403)
			{
				return "Rejected (" + he.code + ") - check the API key in settings. " + detail;
			}
			if (he.code == 404)
			{
				return "Not found (404) - check the API base URL and model name. " + detail;
			}
			if (he.code == 429 || he.code >= 500)
			{
				return "Endpoint unavailable (" + he.code + ") - resubmit in a moment. " + detail;
			}
			// Code 0: a mid-stream failure that carried no HTTP status.
			if (he.code == 0)
			{
				return "Model provider error - resubmit in a moment. " + detail;
			}
			return "HTTP " + he.code + ": " + detail;
		}
		if (e instanceof IOException)
		{
			return "Network error: " + e.getMessage();
		}
		return "Unexpected error: " + e;
	}

	// ------------------------------------------------------------------
	// Event capture
	// ------------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		events.log("gameState", Map.of("state", event.getGameState().name()));
		if (event.getGameState() == GameState.LOADING)
		{
			houseSeen.clear();
		}
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			pipeline.onLogin();
		}
	}

	// House facilities exist only as scene objects while the player stands
	// inside the POH (RuneLite's bundled POH plugin reads them the same
	// way). Spawns collect scene-wide; the POH check happens at commit.
	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		collectHouseFacility(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		collectHouseFacility(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		collectHouseFacility(event.getDecorativeObject());
	}

	private void collectHouseFacility(TileObject obj)
	{
		ObjectComposition comp = resolvedComposition(obj);
		if (comp == null)
		{
			return;
		}
		String facility = HouseStore.describe(comp.getName(), comp.getActions());
		if (facility != null && houseSeen.add(facility))
		{
			housePendingCommit = true;
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		// Dev aid: ::probe dumps a full snapshot usable by the offline eval
		// runner. Deferred to the next tick (scripts are not reentrant).
		if ("probe".equalsIgnoreCase(event.getCommand()))
		{
			pendingSnapshotLabel = "manual";
		}
		// Dev aid: ::place prints what the prompt's location line will say
		// for the current position.
		if ("place".equalsIgnoreCase(event.getCommand()))
		{
			WorldPoint wp = GameStateReader.playerLocation(client);
			String msg;
			if (wp == null)
			{
				msg = "Copilot place: no player location";
			}
			else
			{
				String name = Areas.resolve(wp);
				if (name == null)
				{
					name = wp.getX() >= 6400
						? "(unresolved; prompt says: sailing at sea on a boat)"
						: wp.getY() >= 6400
						? "(unresolved; prompt says: underground area)"
						: "(unresolved; prompt omits place)";
				}
				msg = "Copilot place: (" + wp.getX() + ", " + wp.getY() + ", "
					+ wp.getPlane() + ") region " + wp.getRegionID() + " -> " + name;
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
		}
		// Dev aid: ::house dumps impostor-resolved scene objects and open
		// widget texts, for calibrating the POH facility whitelist.
		if ("house".equalsIgnoreCase(event.getCommand()))
		{
			File f = dumpHouseCalibration();
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", f != null
				? "Copilot: house dump written to " + f.getName()
				: "Copilot: house dump FAILED, see client log", null);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		events.log("stat", Map.of(
			"skill", event.getSkill().name(),
			"xp", event.getXp(),
			"level", event.getLevel(),
			"boosted", event.getBoostedLevel()));
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			// The drift audit runs only on the visit's first capture:
			// later captures fire per withdrawal/deposit, and diffing
			// those merely echoes each interaction.
			List<Map<String, Object>> fresh = reader.itemList(event.getItemContainer());
			if (bankDriftAuditArmed)
			{
				bankDriftAuditArmed = false;
				String drift = BankMutations.drift(bankStore.contents(), fresh);
				if (drift != null)
				{
					log.debug("Bank snapshot drift at capture: {}", drift);
				}
			}
			bankStore.update(fresh);
		}
		bankMutations.containerChanged(id, event.getItemContainer());
		if (events.logOpen())
		{
			Map<String, Object> data = new LinkedHashMap<>();
			data.put("containerId", id);
			data.put("itemCount", event.getItemContainer().count());
			events.log("itemContainer", data);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// Game messages are useful question context; player chat is not.
		// The disk log applies the same filter: other players' chat must
		// never land in a file.
		if (event.getType() == ChatMessageType.GAMEMESSAGE
			|| event.getType() == ChatMessageType.SPAM)
		{
			events.buffer("chat", Map.of("message", event.getMessage()));
			events.log("chat", Map.of(
				"chatType", event.getType().name(),
				"message", event.getMessage()));
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == null)
		{
			return;
		}
		Map<String, Object> data = Map.of(
			"actor", String.valueOf(event.getActor().getName()),
			"isLocalPlayer", event.getActor() == client.getLocalPlayer());
		events.log("death", data);
		events.buffer("death", data);
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		List<Map<String, Object>> items = new ArrayList<>();
		for (ItemStack stack : event.getItems())
		{
			items.add(Map.of(
				"id", stack.getId(),
				"name", reader.itemName(stack.getId()),
				"quantity", stack.getQuantity()));
		}
		Map<String, Object> data = Map.of(
			"npc", String.valueOf(event.getNpc().getName()),
			"items", items);
		events.log("npcLoot", data);
		events.buffer("npcLoot", data);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		bankMutations.menuClicked(event.getMenuOption());
		if (!config.logMenuClicks())
		{
			return;
		}
		events.log("click", Map.of(
			"option", String.valueOf(event.getMenuOption()),
			"target", String.valueOf(event.getMenuTarget())));
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANK_DEPOSITBOX)
		{
			bankMutations.depositBoxOpened(
				client.getItemContainer(InventoryID.INV),
				client.getItemContainer(InventoryID.WORN));
		}
		// The nexus Teleport Menu lists only the destinations actually
		// added; read it a tick after load, once its texts are populated.
		if (event.getGroupId() == NEXUS_MENU_GROUP && inPoh())
		{
			pendingNexusScrape = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANK_DEPOSITBOX)
		{
			bankMutations.depositBoxClosed();
		}
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankDriftAuditArmed = true;
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		// The client fires an all-slots-EMPTY storm during login; those are
		// not real offer changes and must not wipe tracked collectables.
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		GrandExchangeOffer offer = event.getOffer();
		bankMutations.offerChanged(event.getSlot(), offer.getState(),
			offer.getItemId(), offer.getQuantitySold(), offer.getTotalQuantity());
	}

	// ------------------------------------------------------------------
	// Snapshot dump (dev aid for the offline eval runner)
	// ------------------------------------------------------------------

	private File dumpSnapshot(String label)
	{
		try
		{
			GameCapture cap = reader.buildCapture();
			File out = new File(DATA_DIR, "snapshot-" + label + "-" + System.currentTimeMillis() + ".json");
			Files.write(out.toPath(), gson.newBuilder().setPrettyPrinting().create()
				.toJson(cap).getBytes(StandardCharsets.UTF_8));
			log.info("Snapshot written: {}", out.getAbsolutePath());
			return out;
		}
		catch (Exception e)
		{
			log.error("Snapshot failed", e);
			return null;
		}
	}

	/** One calibration file: every distinct scene object (impostor-resolved,
	 * so varbit-built house furniture reports what is actually built) and
	 * the texts of every open widget group. Run inside the POH, then again
	 * with the nexus Teleport Menu open to identify its group ID. */
	private File dumpHouseCalibration()
	{
		try
		{
			StringBuilder sb = new StringBuilder();
			WorldPoint wp = GameStateReader.playerLocation(client);
			sb.append("location: ").append(wp).append(" -> ")
				.append(wp != null ? Areas.resolve(wp) : null).append('\n');

			sb.append("\n-- scene objects (deduped by resolved id) --\n");
			Map<Integer, String> seen = new TreeMap<>();
			for (Tile[][] plane : client.getScene().getTiles())
			{
				for (Tile[] row : plane)
				{
					for (Tile tile : row)
					{
						if (tile == null)
						{
							continue;
						}
						describeObjects(seen, tile.getGameObjects());
						describeObjects(seen, tile.getWallObject(),
							tile.getDecorativeObject(), tile.getGroundObject());
					}
				}
			}
			seen.values().forEach(line -> sb.append(line).append('\n'));

			sb.append("\n-- open widget groups with text --\n");
			Map<Integer, List<String>> byGroup = new TreeMap<>();
			for (Widget root : client.getWidgetRoots())
			{
				collectWidgetTexts(root, byGroup, 0);
			}
			byGroup.forEach((group, texts) ->
				sb.append("group ").append(group).append(": ").append(texts).append('\n'));

			File out = new File(DATA_DIR, "house-calibration-" + System.currentTimeMillis() + ".txt");
			Files.write(out.toPath(), sb.toString().getBytes(StandardCharsets.UTF_8));
			log.info("House calibration written: {}", out.getAbsolutePath());
			return out;
		}
		catch (Exception e)
		{
			log.error("House calibration failed", e);
			return null;
		}
	}

	/** The object's composition with any impostor resolved: POH facility
	 * objects are varbit-multiloc, the base id is an empty shell. */
	private ObjectComposition resolvedComposition(TileObject obj)
	{
		ObjectComposition comp = client.getObjectDefinition(obj.getId());
		if (comp != null && comp.getImpostorIds() != null)
		{
			comp = comp.getImpostor();
		}
		return comp == null || "null".equals(comp.getName()) ? null : comp;
	}

	private void describeObjects(Map<Integer, String> out, TileObject... objects)
	{
		for (TileObject obj : objects)
		{
			if (obj == null)
			{
				continue;
			}
			ObjectComposition comp = resolvedComposition(obj);
			if (comp == null)
			{
				continue;
			}
			out.putIfAbsent(comp.getId(), String.format("id=%d base=%d name=%s ops=%s",
				comp.getId(), obj.getId(), comp.getName(), Arrays.toString(comp.getActions())));
		}
	}

	private boolean inPoh()
	{
		WorldPoint wp = GameStateReader.playerLocation(client);
		return wp != null && "Player Owned House".equals(Areas.resolve(wp));
	}

	private List<String> widgetGroupTexts(int group)
	{
		Map<Integer, List<String>> byGroup = new TreeMap<>();
		for (Widget root : client.getWidgetRoots())
		{
			collectWidgetTexts(root, byGroup, 0);
		}
		return byGroup.getOrDefault(group, List.of());
	}

	private void collectWidgetTexts(Widget widget, Map<Integer, List<String>> byGroup, int depth)
	{
		if (widget == null || depth > 12)
		{
			return;
		}
		String text = widget.getText();
		if (text != null && !text.isEmpty())
		{
			List<String> texts = byGroup.computeIfAbsent(widget.getId() >>> 16,
				k -> new ArrayList<>());
			if (texts.size() < 60)
			{
				texts.add(text);
			}
		}
		for (Widget[] children : new Widget[][]{widget.getStaticChildren(),
			widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				collectWidgetTexts(child, byGroup, depth + 1);
			}
		}
	}

}

package com.osrscopilot;

import com.google.gson.Gson;
import java.io.BufferedWriter;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

/**
 * Recent gameplay events, in two forms with two audiences: a bounded
 * in-memory buffer that accompanies questions as context ("what's this
 * drop?"), and an opt-in JSONL disk log for development diagnostics.
 * Both are filtered at the call sites to event types that are the player's
 * own data -- never other players' chat.
 */
@Slf4j
class EventRecorder
{
	private static final int EVENT_BUFFER_SIZE = 100;
	private static final int EVENTS_SENT_WITH_QUESTION = 30;
	/** How long dev event logs are kept before pruning. */
	private static final long EVENT_LOG_RETENTION_MS = 14L * 24 * 60 * 60 * 1000;

	private final Client client;
	private final Gson gson;
	private final CopilotConfig config;
	private final File dataDir;

	// Client thread only.
	private final Deque<Map<String, Object>> recentEvents = new ArrayDeque<>();
	private BufferedWriter eventLog;

	EventRecorder(Client client, Gson gson, CopilotConfig config, File dataDir)
	{
		this.client = client;
		this.gson = gson;
		this.config = config;
		this.dataDir = dataDir;
	}

	/** Runs on the client thread. Only event types useful as question context. */
	void buffer(String type, Map<String, Object> data)
	{
		Map<String, Object> entry = new LinkedHashMap<>();
		entry.put("tsMs", System.currentTimeMillis());
		entry.put("type", type);
		entry.putAll(data);
		recentEvents.addLast(entry);
		while (recentEvents.size() > EVENT_BUFFER_SIZE)
		{
			recentEvents.removeFirst();
		}
	}

	/** Runs on the client thread: the newest buffered events, timestamps
	 * rewritten as minutes-ago for the model. */
	List<Map<String, Object>> recent()
	{
		List<Map<String, Object>> out = new ArrayList<>();
		long now = System.currentTimeMillis();
		int skip = Math.max(0, recentEvents.size() - EVENTS_SENT_WITH_QUESTION);
		int i = 0;
		for (Map<String, Object> e : recentEvents)
		{
			if (i++ < skip)
			{
				continue;
			}
			Map<String, Object> entry = new LinkedHashMap<>(e);
			Object ts = entry.remove("tsMs");
			if (ts instanceof Long)
			{
				entry.put("minutes_ago", Math.round((now - (Long) ts) / 6000.0) / 10.0);
			}
			out.add(entry);
		}
		return out;
	}

	void openLog() throws IOException
	{
		// One file per session, never read back: prune old ones or they
		// accumulate forever.
		File[] old = dataDir.listFiles((d, name) ->
			name.startsWith("events-") && name.endsWith(".jsonl"));
		if (old != null)
		{
			long cutoff = System.currentTimeMillis() - EVENT_LOG_RETENTION_MS;
			for (File f : old)
			{
				if (f.lastModified() < cutoff)
				{
					f.delete();
				}
			}
		}
		File logFile = new File(dataDir, "events-" + System.currentTimeMillis() + ".jsonl");
		eventLog = Files.newBufferedWriter(logFile.toPath(), StandardCharsets.UTF_8,
			StandardOpenOption.CREATE, StandardOpenOption.APPEND);
	}

	void closeLog() throws IOException
	{
		if (eventLog != null)
		{
			eventLog.close();
			eventLog = null;
		}
	}

	void log(String type, Map<String, Object> data)
	{
		if (eventLog == null || !config.logEvents())
		{
			return;
		}
		try
		{
			Map<String, Object> line = new LinkedHashMap<>();
			line.put("ts", Instant.now().toString());
			line.put("tick", client.getTickCount());
			line.put("type", type);
			line.putAll(data);
			eventLog.write(gson.toJson(line));
			eventLog.newLine();
			// Flush per write so a client crash cannot lose captured events.
			eventLog.flush();
		}
		catch (IOException e)
		{
			log.warn("Event log write failed", e);
		}
	}

	boolean logOpen()
	{
		return eventLog != null;
	}
}

package com.osrscopilot;

import com.osrscopilot.pipeline.GameCapture;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;

/**
 * Reads the game client into a GameCapture snapshot. Everything here runs
 * on the client thread (Quest.getState runs scripts); the pipeline then
 * works entirely off-thread against the immutable capture.
 */
class GameStateReader
{
	// The config the built-in Slayer plugin writes its task to. String
	// literals keep this off that plugin's classes.
	private static final String SLAYER_GROUP = "slayer";
	private static final String SLAYER_TASK_NAME = "taskName";
	private static final String SLAYER_TASK_LOCATION = "taskLocation";

	private final Client client;
	private final ConfigManager configManager;
	private final CopilotConfig config;
	private final BankStore bankStore;
	private final HouseStore houseStore;
	private final EventRecorder events;

	GameStateReader(Client client, ConfigManager configManager, CopilotConfig config,
		BankStore bankStore, HouseStore houseStore, EventRecorder events)
	{
		this.client = client;
		this.configManager = configManager;
		this.config = config;
		this.bankStore = bankStore;
		this.houseStore = houseStore;
		this.events = events;
	}

	/** The player's position in overworld coordinates. Instances (POH,
	 * raids) place the player in scratch map space; translate back to the
	 * template tile the chunk was copied from, which is what the area
	 * table indexes. */
	static WorldPoint playerLocation(Client client)
	{
		Player p = client.getLocalPlayer();
		if (p == null)
		{
			return null;
		}
		LocalPoint lp = p.getLocalLocation();
		if (lp != null && client.getTopLevelWorldView().isInstance())
		{
			return WorldPoint.fromLocalInstance(client, lp);
		}
		return p.getWorldLocation();
	}

	GameCapture buildCapture()
	{
		GameCapture cap = new GameCapture();
		Player p = client.getLocalPlayer();
		if (p != null)
		{
			cap.playerName = p.getName();
			cap.combatLevel = p.getCombatLevel();
			WorldPoint wp = playerLocation(client);
			if (wp != null)
			{
				cap.location = Map.of("x", wp.getX(), "y", wp.getY(),
					"plane", wp.getPlane(), "regionId", wp.getRegionID());
			}
		}
		cap.accountType = client.getVarbitValue(VarbitID.IRONMAN);

		Map<String, Integer> skills = new LinkedHashMap<>();
		Map<String, Integer> skillXp = new LinkedHashMap<>();
		Map<String, Integer> boosts = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			String name = skill.getName();
			int real = client.getRealSkillLevel(skill);
			int boosted = client.getBoostedSkillLevel(skill);
			skills.put(name, real);
			skillXp.put(name, client.getSkillExperience(skill));
			if (boosted != real)
			{
				boosts.put(name, boosted - real);
			}
		}
		cap.skills = skills;
		cap.skillXp = skillXp;
		cap.boostsOrDrains = boosts;

		Map<String, String> questStates = new LinkedHashMap<>();
		for (Quest q : Quest.values())
		{
			QuestState state = q.getState(client);
			questStates.put(q.getName(), state.name());
		}
		cap.questStates = questStates;
		cap.diaries = diaryCompletion();
		cap.slayerTask = slayerTask();
		cap.unlocks = unlocks();

		cap.inventory = itemList(client.getItemContainer(InventoryID.INV));
		cap.equipment = itemList(client.getItemContainer(InventoryID.WORN));
		if (config.sendBank())
		{
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			cap.bank = bank != null ? itemList(bank) : bankStore.contents();
		}
		if (config.sendRecentEvents())
		{
			cap.recentEvents = events.recent();
		}
		cap.house = houseStore.forCapture();
		return cap;
	}

	/**
	 * Per-tier achievement diary completion via varbits. Per-task varbits
	 * exist but need a curated ID map; tiers cover most question needs.
	 */
	private Map<String, Object> diaryCompletion()
	{
		Map<String, int[]> areas = new LinkedHashMap<>();
		areas.put("Ardougne", new int[]{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE});
		areas.put("Desert", new int[]{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE});
		areas.put("Falador", new int[]{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE});
		areas.put("Fremennik", new int[]{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE});
		areas.put("Kandarin", new int[]{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE});
		// Karamja predates the diary varbit convention: its easy/medium/hard
		// completion lives in ATJUN_*_DONE; only elite follows the pattern.
		areas.put("Karamja", new int[]{VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE, VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE});
		areas.put("Kourend & Kebos", new int[]{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE});
		areas.put("Lumbridge & Draynor", new int[]{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE});
		areas.put("Morytania", new int[]{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE});
		areas.put("Varrock", new int[]{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE});
		areas.put("Western Provinces", new int[]{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE});
		areas.put("Wilderness", new int[]{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE});

		String[] tiers = {"easy", "medium", "hard", "elite"};
		Map<String, Object> out = new LinkedHashMap<>();
		for (Map.Entry<String, int[]> area : areas.entrySet())
		{
			List<String> done = new ArrayList<>();
			for (int i = 0; i < 4; i++)
			{
				if (client.getVarbitValue(area.getValue()[i]) == 1)
				{
					done.add(tiers[i]);
				}
			}
			out.put(area.getKey(), done);
		}
		return out;
	}

	/** Spellbook and prayer-scroll unlocks from varbits; a consumed scroll
	 * shows as "0 owned" in item search, so unlocks must be stated here.
	 * Piety/Chivalry are deliberately absent: their gate (Knight Waves)
	 * has no reliably readable varbit. */
	private Map<String, Object> unlocks()
	{
		Map<String, Object> out = new LinkedHashMap<>();
		String[] books = {"standard", "ancient magicks", "lunar", "arceuus"};
		int book = client.getVarbitValue(VarbitID.SPELLBOOK);
		out.put("active_spellbook", book >= 0 && book < books.length
			? books[book] : "unknown");
		out.put("rigour_unlocked",
			client.getVarbitValue(VarbitID.PRAYER_RIGOUR_UNLOCKED) == 1);
		out.put("augury_unlocked",
			client.getVarbitValue(VarbitID.PRAYER_AUGURY_UNLOCKED) == 1);
		out.put("preserve_unlocked",
			client.getVarbitValue(VarbitID.PRAYER_PRESERVE_UNLOCKED) == 1);
		return out;
	}

	/** The active Slayer task. The remaining count (a varp) is exact; the
	 * creature name comes from the built-in Slayer plugin's config, so
	 * with that plugin off only the count is reported. */
	private Map<String, Object> slayerTask()
	{
		// The count is the source of truth for "is there a task": the stored
		// creature name outlives the task it was recorded for.
		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (remaining <= 0)
		{
			return null;
		}
		Map<String, Object> task = new LinkedHashMap<>();
		String creature = configManager.getRSProfileConfiguration(SLAYER_GROUP, SLAYER_TASK_NAME);
		if (creature != null && !creature.isEmpty())
		{
			task.put("creature", creature);
		}
		task.put("remaining", remaining);
		String location = configManager.getRSProfileConfiguration(SLAYER_GROUP, SLAYER_TASK_LOCATION);
		if (location != null && !location.isEmpty())
		{
			task.put("location", location);
		}
		return task;
	}

	List<Map<String, Object>> itemList(ItemContainer container)
	{
		List<Map<String, Object>> items = new ArrayList<>();
		if (container == null)
		{
			return items;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() == -1)
			{
				continue;
			}
			ItemComposition def = itemDefinition(item.getId());
			// A bank placeholder is a distinct item sharing the real
			// item's name, delivered with quantity 1; recording it would
			// claim a banked copy of every item ever withdrawn.
			if (def == null || def.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			items.add(Map.of(
				"id", item.getId(),
				"name", def.getName(),
				"quantity", item.getQuantity()));
		}
		return items;
	}

	String itemName(int id)
	{
		ItemComposition def = itemDefinition(id);
		return def != null ? def.getName() : "unknown";
	}

	private ItemComposition itemDefinition(int id)
	{
		try
		{
			return client.getItemDefinition(id);
		}
		catch (Exception e)
		{
			return null;
		}
	}
}

package com.osrscopilot;

import com.google.gson.Gson;
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.Executor;
import lombok.extern.slf4j.Slf4j;

/**
 * The player's POH facilities, kept per account: the house only exists as
 * scene objects while the player stands inside it, so each visit's scan is
 * persisted for use everywhere else. Same threading contract as BankStore:
 * mutators run on the client thread, disk writes go to the executor.
 */
@Slf4j
class HouseStore
{
	/** Wall-mounted teleport items; everything else mounted is decor. */
	private static final Set<String> MOUNTED_TELEPORTS = Set.of(
		"amulet of glory", "digsite pendant", "xeric's talisman", "mythical cape");

	private final File dataDir;
	private final Gson gson;
	private final Executor ioExecutor;

	private Data data;
	private long accountHash = -1;

	private static final class Data
	{
		List<String> facilities;
		List<String> nexus;
		long capturedAt;
	}

	HouseStore(File dataDir, Gson gson, Executor ioExecutor)
	{
		this.dataDir = dataDir;
		this.gson = gson;
		this.ioExecutor = ioExecutor;
	}

	/** Runs on the client thread. On the first tick of a session and on
	 * any account switch, drop the previous account's house and load this
	 * one's persisted copy. */
	void sync(long hash)
	{
		if (hash == -1 || hash == accountHash)
		{
			return;
		}
		synchronized (this)
		{
			accountHash = hash;
			data = null;
		}
		load(hash);
	}

	/** A fresh facility scan from inside the house: replace and persist.
	 * The nexus destination list survives -- it comes from its own menu. */
	void updateFacilities(List<String> facilities)
	{
		synchronized (this)
		{
			Data next = new Data();
			next.facilities = facilities;
			next.nexus = data != null ? data.nexus : null;
			next.capturedAt = System.currentTimeMillis();
			data = next;
		}
		persist();
	}

	/** Destinations parsed from the nexus Teleport Menu. */
	void updateNexus(List<String> destinations)
	{
		synchronized (this)
		{
			Data next = new Data();
			next.facilities = data != null ? data.facilities : null;
			next.nexus = destinations;
			next.capturedAt = data != null ? data.capturedAt : System.currentTimeMillis();
			data = next;
		}
		persist();
	}

	/** The facility list for a capture, nexus destinations folded into its
	 * entry; null when the player's house has never been scanned. */
	List<String> forCapture()
	{
		Data d = data;
		if (d == null || d.facilities == null || d.facilities.isEmpty())
		{
			return null;
		}
		List<String> out = new ArrayList<>(d.facilities.size());
		for (String facility : d.facilities)
		{
			out.add("Portal Nexus".equals(facility) && d.nexus != null && !d.nexus.isEmpty()
				? "Portal Nexus: " + String.join(", ", d.nexus)
				: facility);
		}
		return out;
	}

	/**
	 * The facility a scene object represents, or null for furniture. Names
	 * and ops are impostor-resolved, so they reflect what is actually
	 * built. Calibrated against a real house dump 2026-08-30.
	 */
	static String describe(String name, String[] ops)
	{
		List<String> opList = new ArrayList<>();
		if (ops != null)
		{
			for (String op : ops)
			{
				if (op != null)
				{
					opList.add(op);
				}
			}
		}
		if ("Portal Nexus".equals(name))
		{
			return name;
		}
		// Portal Chamber portals are named by destination ("Kourend
		// Portal"); the bare house exit is just "Portal". Diary-upgraded
		// duals list both destinations as ops before a Toggle.
		if (name.endsWith(" Portal"))
		{
			int toggle = opList.indexOf("Toggle");
			return toggle >= 2
				? name + " (" + opList.get(0) + " or " + opList.get(1) + ")"
				: name;
		}
		String lower = name.toLowerCase(Locale.ROOT);
		if (opList.contains("Drink") && lower.contains("pool"))
		{
			return name;
		}
		if (opList.contains("Pray") && lower.contains("altar"))
		{
			return name;
		}
		// Spellbook altars (Occult, Ancient, Lunar, Dark).
		if (opList.contains("Venerate"))
		{
			return name;
		}
		if (lower.contains("jewellery box") || lower.contains("fairy ring")
			|| lower.contains("spirit tree") || "obelisk".equals(lower)
			|| MOUNTED_TELEPORTS.contains(lower))
		{
			return name;
		}
		return null;
	}

	/**
	 * Destinations from the nexus Teleport Menu's texts, or null when the
	 * texts are some other interface. Entries render as
	 * "&lt;col=ffffff&gt;1&lt;/col&gt; :  Arceuus Library"; the
	 * Configuration screen shares the title but lists its catalogue
	 * without the " : " separator, so it parses to nothing.
	 */
	static List<String> parseNexusMenu(List<String> texts)
	{
		if (texts.isEmpty() || !"Portal Nexus".equals(texts.get(0)))
		{
			return null;
		}
		List<String> out = new ArrayList<>();
		for (String text : texts)
		{
			String plain = text.replaceAll("<[^>]*>", "");
			int sep = plain.indexOf(" : ");
			if (sep > 0)
			{
				out.add(plain.substring(sep + 3).trim());
			}
		}
		return out;
	}

	private File houseFile(long accountHash)
	{
		return new File(dataDir, "house-" + Long.toUnsignedString(accountHash) + ".json");
	}

	private void persist()
	{
		ioExecutor.execute(() ->
		{
			Data snapshot;
			long hash;
			synchronized (this)
			{
				snapshot = data;
				hash = accountHash;
			}
			if (snapshot == null || hash == -1)
			{
				return;
			}
			try
			{
				Files.write(houseFile(hash).toPath(),
					gson.toJson(snapshot).getBytes(StandardCharsets.UTF_8));
			}
			catch (IOException e)
			{
				log.warn("House persist failed", e);
			}
		});
	}

	private void load(long accountHash)
	{
		File f = houseFile(accountHash);
		if (!f.exists())
		{
			return;
		}
		try (BufferedReader r = Files.newBufferedReader(f.toPath(), StandardCharsets.UTF_8))
		{
			Data loaded = gson.fromJson(r, Data.class);
			synchronized (this)
			{
				data = loaded;
			}
		}
		catch (Exception e)
		{
			log.warn("House load failed", e);
		}
	}
}

package com.osrscopilot;

import java.awt.image.BufferedImage;
import java.io.File;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Real game icons for decorated answers, rendered from the client's own
 * caches; nothing is fetched over the network. Icons persist as PNGs
 * because the Swing HTML renderer references images by URL. Fail-soft:
 * any miss returns null and the caller renders without an icon.
 */
@Slf4j
final class IconStore
{
	/** Bound on a decorate-time wait for the client to draw a sprite; a
	 * wedged client thread must not stall an answer. */
	private static final long ITEM_RENDER_TIMEOUT_MS = 2000;

	private final File dir;
	private final ItemManager itemManager;
	/** Resolved file URLs for this session, so repeat mentions cost only
	 * a map hit. */
	private final Map<String, String> resolved = new ConcurrentHashMap<>();

	/**
	 * Managers may be null outside the client (UI previews, tests): the
	 * store then serves only icons already on disk.
	 */
	IconStore(File dir, ItemManager itemManager, SpriteManager spriteManager,
		SkillIconManager skillIconManager)
	{
		this.dir = dir;
		this.itemManager = itemManager;
		dir.mkdirs();

		if (skillIconManager != null)
		{
			for (Skill skill : Skill.values())
			{
				// The deprecated OVERALL pseudo-skill has no icon. Matched
				// by name so its removal from the enum cannot break this.
				if ("OVERALL".equals(skill.name()))
				{
					continue;
				}
				writeOnce(skillFile(skill.getName()),
					() -> skillIconManager.getSkillImage(skill, true));
			}
		}
		if (spriteManager != null)
		{
			// Sprite readiness depends on client startup; async with a
			// write-once callback instead of assuming the cache is loaded.
			spriteManager.getSpriteAsync(SpriteID.AchievementDiaryIcons.BLUE_QUESTS, 0,
				img -> writeOnce(questFile(), () -> img));
		}
	}

	/** File URL for an item's inventory sprite, rendering it from the game
	 * cache on first use. Null if unavailable; never throws. */
	String itemIconUrl(int itemId)
	{
		File f = new File(dir, "item-" + itemId + ".png");
		if (!resolved.containsKey(f.getName()) && !f.exists() && !renderItem(itemId, f))
		{
			return null;
		}
		return existingUrl(f);
	}

	/** File URL for a skill's icon; written at construction. */
	String skillIconUrl(String skillName)
	{
		return existingUrl(skillFile(skillName));
	}

	/** File URL for the quest point icon; written at construction. */
	String questIconUrl()
	{
		return existingUrl(questFile());
	}

	private String existingUrl(File f)
	{
		String cached = resolved.get(f.getName());
		if (cached != null)
		{
			return cached;
		}
		if (!f.exists())
		{
			return null;
		}
		String url = f.toURI().toString();
		resolved.put(f.getName(), url);
		return url;
	}

	/** Render one item sprite to disk. AsyncBufferedImage paints on the
	 * client thread while decoration runs on the pipeline worker, so a
	 * bounded wait here is safe. */
	private boolean renderItem(int itemId, File f)
	{
		if (itemManager == null)
		{
			return false;
		}
		try
		{
			AsyncBufferedImage img = itemManager.getImage(itemId);
			CountDownLatch drawn = new CountDownLatch(1);
			img.onLoaded(drawn::countDown);
			if (!drawn.await(ITEM_RENDER_TIMEOUT_MS, TimeUnit.MILLISECONDS))
			{
				log.debug("item sprite {} not drawn within {}ms", itemId, ITEM_RENDER_TIMEOUT_MS);
				return false;
			}
			// Copy: AsyncBufferedImage repaints itself on its own schedule.
			BufferedImage copy = new BufferedImage(img.getWidth(), img.getHeight(),
				BufferedImage.TYPE_INT_ARGB);
			copy.getGraphics().drawImage(img, 0, 0, null);
			return writePng(copy, f);
		}
		catch (InterruptedException e)
		{
			return false;
		}
		catch (Exception e)
		{
			log.debug("item sprite {} render failed", itemId, e);
			return false;
		}
	}

	private void writeOnce(File f, Supplier<BufferedImage> source)
	{
		if (f.exists())
		{
			return;
		}
		try
		{
			BufferedImage img = source.get();
			if (img != null)
			{
				writePng(img, f);
			}
		}
		catch (Exception e)
		{
			log.debug("icon write failed for {}", f.getName(), e);
		}
	}

	private boolean writePng(BufferedImage img, File f)
	{
		try
		{
			return ImageIO.write(img, "png", f);
		}
		catch (Exception e)
		{
			log.debug("icon write failed for {}", f.getName(), e);
			return false;
		}
	}

	private File skillFile(String skillName)
	{
		return new File(dir, "skill-" + skillName.toLowerCase(Locale.ROOT) + ".png");
	}

	private File questFile()
	{
		return new File(dir, "quest.png");
	}
}

