package com.osrscopilot;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Minimal markdown-to-HTML converter for the subset LLMs emit, targeting
 * the HTML 3.2 subset Swing's JEditorPane renders. Dependency-free (the
 * Plugin Hub scrutinizes third-party libraries). Partial mid-stream
 * markdown renders as slightly unstyled text, never breaks.
 */
final class MarkdownHtml
{
	private static final Pattern HEADER = Pattern.compile("^(#{1,6})\\s+(.*)$");
	private static final Pattern BULLET = Pattern.compile("^\\s*[-*]\\s+(.*)$");
	private static final Pattern NUMBERED = Pattern.compile("^\\s*\\d+[.)]\\s+(.*)$");
	private static final Pattern TABLE_ROW = Pattern.compile("^\\s*\\|.*\\|\\s*$");
	private static final Pattern TABLE_SEPARATOR = Pattern.compile("^[\\s|:\\-]+$");
	private static final Pattern HRULE = Pattern.compile("^\\s*[-_*]{3,}\\s*$");

	private MarkdownHtml()
	{
	}

	static String toHtml(String markdown)
	{
		StringBuilder out = new StringBuilder();
		String openList = null;
		boolean inTable = false;
		boolean tableHeaderDone = false;

		for (String raw : markdown.split("\n", -1))
		{
			String line = SwingUtil.escapeHtml(raw);

			Matcher table = TABLE_ROW.matcher(line);
			if (table.matches())
			{
				if (TABLE_SEPARATOR.matcher(line).matches())
				{
					continue;
				}
				openList = closeList(out, openList);
				Theme theme = Theme.active();
				if (!inTable)
				{
					// cellspacing over a colored table bg draws a hairline grid,
					// the only bordering Swing's HTML 3.2 renderer honors.
					out.append("<table width='100%' cellpadding='4' cellspacing='1' bgcolor='")
						.append(theme.tableEdgeHex).append("'>");
					inTable = true;
					tableHeaderDone = false;
				}
				out.append("<tr>");
				String trimmed = line.trim();
				String inner = trimmed.substring(1, trimmed.length() - 1);
				for (String cell : inner.split("\\|", -1))
				{
					out.append("<td bgcolor='")
						.append(tableHeaderDone ? theme.tableCellHex : theme.tableHeaderHex)
						.append("'>")
						.append(tableHeaderDone ? inline(cell.trim()) : "<b>" + inline(cell.trim()) + "</b>")
						.append("</td>");
				}
				out.append("</tr>");
				tableHeaderDone = true;
				continue;
			}
			inTable = closeTable(out, inTable);

			Matcher header = HEADER.matcher(line);
			if (header.matches())
			{
				openList = closeList(out, openList);
				// Two visible header sizes: sections (#, ##) and
				// subsections (### and deeper).
				String size = header.group(1).length() <= 2 ? "4" : "3";
				out.append("<br><font size='").append(size).append("'><b>")
					.append(inline(header.group(2))).append("</b></font><br>");
				continue;
			}
			if (HRULE.matcher(line).matches())
			{
				openList = closeList(out, openList);
				out.append("<hr>");
				continue;
			}

			Matcher bullet = BULLET.matcher(line);
			Matcher numbered = NUMBERED.matcher(line);
			if (bullet.matches() || numbered.matches())
			{
				String tag = bullet.matches() ? "ul" : "ol";
				String item = bullet.matches() ? bullet.group(1) : numbered.group(1);
				if (!tag.equals(openList))
				{
					openList = closeList(out, openList);
					out.append('<').append(tag).append('>');
					openList = tag;
				}
				out.append("<li>").append(inline(item)).append("</li>");
				continue;
			}

			openList = closeList(out, openList);
			if (line.trim().isEmpty())
			{
				out.append("<br>");
			}
			else
			{
				out.append(inline(line)).append("<br>");
			}
		}
		closeList(out, openList);
		closeTable(out, inTable);
		return out.toString();
	}

	private static String closeList(StringBuilder out, String openList)
	{
		if (openList != null)
		{
			out.append("</").append(openList).append('>');
		}
		return null;
	}

	private static boolean closeTable(StringBuilder out, boolean inTable)
	{
		if (inTable)
		{
			out.append("</table>");
		}
		return false;
	}

	private static String inline(String s)
	{
		s = s.replaceAll("`([^`]+)`", "<code>$1</code>");
		s = s.replaceAll("\\*\\*([^*]+)\\*\\*", "<b>$1</b>");
		s = s.replaceAll("(?<![\\w*])\\*([^*]+)\\*(?![\\w*])", "<i>$1</i>");
		// Links render as underlined text; the game client is no place to browse.
		s = s.replaceAll("\\[([^\\]]+)\\]\\([^)]*\\)", "<u>$1</u>");
		return s;
	}
}

package com.osrscopilot;

/** Config-facing theme choice; each maps to a {@link Theme} palette. */
public enum PanelTheme
{
	GAME_NATIVE("game-native", "Game native"),
	MODERN("modern", "Modern"),
	PARCHMENT("parchment", "Parchment");

	final String key;
	private final String label;

	PanelTheme(String key, String label)
	{
		this.key = key;
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.osrscopilot;

import java.awt.BorderLayout;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import javax.swing.JButton;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import net.runelite.client.ui.ColorScheme;

/**
 * Moves the chat UI between the sidebar and a free-floating resizable
 * frame; RuneLite's sidebar width is a fixed constant.
 */
class PopOutManager
{
	private final JPanel host;
	private final JPanel content;
	private final JButton popOutButton;
	private final JTextField input;
	private final Theme theme;

	private JFrame frame;

	PopOutManager(JPanel host, JPanel content, JButton popOutButton, JTextField input, Theme theme)
	{
		this.host = host;
		this.content = content;
		this.popOutButton = popOutButton;
		this.input = input;
		this.theme = theme;
	}

	void toggle()
	{
		if (frame == null)
		{
			open();
		}
		else
		{
			frame.dispose();
		}
	}

	private void open()
	{
		host.remove(content);
		JLabel placeholder = new JLabel("Chat is open in its own window", JLabel.CENTER);
		placeholder.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		host.add(placeholder, BorderLayout.CENTER);
		host.revalidate();
		host.repaint();

		frame = new JFrame("OSRS Copilot");
		frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);
		frame.getContentPane().setBackground(theme.chromeBg);
		frame.add(content);
		frame.setSize(560, 720);
		frame.setLocationByPlatform(true);
		// Closing the window by any path docks the chat back into the sidebar.
		frame.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent e)
			{
				dockBack(placeholder);
			}
		});
		popOutButton.setText("Dock");
		popOutButton.setToolTipText("Return the chat to the sidebar");
		frame.setVisible(true);
		input.requestFocusInWindow();
	}

	private void dockBack(JLabel placeholder)
	{
		frame = null;
		host.remove(placeholder);
		host.add(content, BorderLayout.CENTER);
		popOutButton.setText("Pop out");
		popOutButton.setToolTipText("Open the chat in its own resizable window");
		host.revalidate();
		host.repaint();
	}

	/** Plugin shutdown: a floating chat window must not outlive the plugin. */
	void close()
	{
		if (frame != null)
		{
			frame.dispose();
		}
	}
}

package com.osrscopilot;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JButton;
import javax.swing.JEditorPane;
import javax.swing.JLabel;
import javax.swing.JScrollBar;
import javax.swing.event.HyperlinkListener;
import javax.swing.plaf.basic.BasicScrollBarUI;
import javax.swing.text.html.HTMLEditorKit;
import javax.swing.text.html.StyleSheet;

/** Shared Swing helpers for the copilot's custom-painted UI. */
final class SwingUtil
{
	private SwingUtil()
	{
	}

	/** The OS's font smoothing settings (subpixel AA on Windows). Custom
	 * painting starts from a bare Graphics2D with no text hints at all, so
	 * every text-drawing component here must opt in or small text renders
	 * with hard pixel stairsteps. */
	private static final Object DESKTOP_FONT_HINTS =
		java.awt.Toolkit.getDefaultToolkit().getDesktopProperty("awt.font.desktophints");

	static void smooth(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g;
		if (DESKTOP_FONT_HINTS instanceof java.util.Map)
		{
			g2.addRenderingHints((java.util.Map<?, ?>) DESKTOP_FONT_HINTS);
		}
		else
		{
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_LCD_HRGB);
		}
	}

	/** JLabel that honors the desktop's text antialiasing. */
	static JLabel smoothLabel(String text)
	{
		return new JLabel(text)
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				smooth(g);
				super.paintComponent(g);
			}
		};
	}

	/** HTML pane tuned for card bodies: transparent, non-editable, entity
	 * links colored but not underlined. */
	static JEditorPane newHtmlPane(HyperlinkListener links, int fontPx)
	{
		JEditorPane pane = new JEditorPane()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				smooth(g);
				super.paintComponent(g);
			}
		};
		HTMLEditorKit kit = new HTMLEditorKit();
		StyleSheet sheet = new StyleSheet();
		sheet.addStyleSheet(kit.getStyleSheet());
		sheet.addRule("a { text-decoration: none; }");
		kit.setStyleSheet(sheet);
		pane.setEditorKit(kit);
		pane.setEditable(false);
		pane.setOpaque(false);
		pane.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);
		pane.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, fontPx));
		pane.addHyperlinkListener(links);
		return pane;
	}

	static void styleScrollBar(JScrollBar bar, Theme theme)
	{
		bar.setPreferredSize(new Dimension(8, 0));
		bar.setUI(new BasicScrollBarUI()
		{
			@Override
			protected void configureScrollBarColors()
			{
				thumbColor = theme.scrollThumb;
				trackColor = theme.surface;
			}

			@Override
			protected JButton createDecreaseButton(int orientation)
			{
				return zeroButton();
			}

			@Override
			protected JButton createIncreaseButton(int orientation)
			{
				return zeroButton();
			}

			@Override
			protected void paintThumb(Graphics g, javax.swing.JComponent c, java.awt.Rectangle r)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
					RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(thumbColor);
				g2.fillRoundRect(r.x + 1, r.y, r.width - 2, r.height, 6, 6);
				g2.dispose();
			}

			private JButton zeroButton()
			{
				JButton b = new JButton();
				b.setPreferredSize(new Dimension(0, 0));
				return b;
			}
		});
	}

	static String escapeHtml(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Antialiased rounded fill with an optional light inner line (stone
	 * bevel) and an optional outer edge. */
	static void paintRounded(Graphics g, javax.swing.JComponent c, int arc,
		java.awt.Color fill, java.awt.Color edge, java.awt.Color innerBevel)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(fill);
		g2.fillRoundRect(0, 0, c.getWidth(), c.getHeight(), arc, arc);
		if (innerBevel != null)
		{
			g2.setColor(innerBevel);
			g2.drawRoundRect(1, 1, c.getWidth() - 3, c.getHeight() - 3, arc, arc);
		}
		if (edge != null)
		{
			g2.setColor(edge);
			g2.drawRoundRect(0, 0, c.getWidth() - 1, c.getHeight() - 1, arc, arc);
		}
		g2.dispose();
	}
}

package com.osrscopilot;

import java.awt.Color;
import java.awt.Font;
import net.runelite.client.ui.FontManager;

/**
 * One visual identity for the whole presentation stack: the chat panel, the
 * markdown renderer, and the entity decorator all read the active theme.
 */
final class Theme
{
	// -- Chrome -----------------------------------------------------------
	/** Font for wordmark, speaker labels, and buttons; null = default sans. */
	Font chromeFont;
	Font statusFont;
	Color accent;
	/** Transcript background (behind the cards). */
	Color surface;
	/** Chrome background (behind the header buttons and input row). */
	Color chromeBg;
	Color buttonBg;
	Color buttonHover;
	Color buttonFg;
	Color primaryBg;
	Color primaryHover;
	Color primaryFg;
	Color inputBg;
	Color inputEdge;
	Color inputFocusEdge;
	Color inputText;
	Color statusFg;
	Color scrollThumb;
	int arc;

	// -- Message cards ------------------------------------------------------
	/** Game-native mode: user questions render as chat lines, not cards. */
	boolean userAsChatLine;
	Color userCardBg;
	Color userCardEdge;
	Color botCardBg;
	Color botCardEdge;
	/** Inner highlight line for the stone-bevel look; null = flat hairline. */
	Color bevelLight;
	Color userLabelFg;
	Color botLabelFg;
	String userBodyHex;
	String botBodyHex;
	/** "You:" prefix color in chat-line mode. */
	String userPrefixHex;
	String noteHex;
	String metaHex;
	String caretHex;
	String welcomeTextHex;

	// -- Markdown (answer body) --------------------------------------------
	String tableEdgeHex;
	String tableHeaderHex;
	String tableCellHex;

	// -- Entity decorator ----------------------------------------------------
	String questDoneHex;
	String questProgressHex;
	String questNotStartedHex;
	String itemCarriedHex;
	String itemBankedHex;
	String itemUnownedHex;
	String plainLinkHex;

	private Theme()
	{
	}

	private static volatile Theme active = build(0);

	static Theme active()
	{
		return active;
	}

	static void setActive(Theme theme)
	{
		active = theme;
	}

	static Theme byName(String name)
	{
		switch (name)
		{
			case "modern":
				return build(1);
			case "parchment":
				return build(2);
			default:
				return build(0);
		}
	}

	static String hex(Color c)
	{
		return String.format("#%06x", c.getRGB() & 0xffffff);
	}

	/** All three palettes in one table, one field per row, so a new field
	 * can't silently miss a theme. Columns: [0] game-native, [1] modern,
	 * [2] parchment. */
	private static Theme build(int i)
	{
		Font bold = FontManager.getRunescapeBoldFont();
		Font small = FontManager.getRunescapeSmallFont();
		Theme t = new Theme();
		t.chromeFont = pick(i, bold, null, bold);
		t.statusFont = pick(i, small, null, small);
		t.accent = pick(i, c(0xff981f), c(0xe0e0e0), c(0xffd870));
		t.surface = pick(i, c(0x1e1b16), c(0x212121), c(0x2e2820));
		t.chromeBg = pick(i, c(0x26221b), c(0x282828), c(0x241f18));
		t.buttonBg = pick(i, c(0x3a3226), c(0x2a2a2a), c(0x4e4433));
		t.buttonHover = pick(i, c(0x4a4030), c(0x343434), c(0x5e5340));
		t.buttonFg = pick(i, c(0xff981f), c(0xbbbbbb), c(0xf0d9a0));
		t.primaryBg = pick(i, c(0xff981f), c(0xe8e8e8), c(0x6a5a3a));
		t.primaryHover = pick(i, c(0xffb04a), c(0xffffff), c(0x7a6a48));
		t.primaryFg = pick(i, c(0x211a10), c(0x1e1e1e), c(0xffd870));
		t.inputBg = pick(i, c(0x1e1b16), c(0x212121), c(0xded5b6));
		t.inputEdge = pick(i, c(0x4a3f2a), c(0x3a3a3a), c(0x5a4a33));
		t.inputFocusEdge = pick(i, c(0xb8781c), c(0x5a5a5a), c(0x8a6d2e));
		t.inputText = pick(i, c(0xe6d9b8), c(0xdddddd), c(0x3a2f1b));
		t.statusFg = pick(i, c(0xb8a888), c(0x9a9a9a), c(0xc8b681));
		t.scrollThumb = pick(i, c(0x4a4030), c(0x424242), c(0x5a4a33));
		t.arc = pick(i, 8, 12, 4);
		t.userAsChatLine = pick(i, true, false, false);
		t.userCardBg = pick(i, null, c(0x2f2f2f), c(0xd8cdad));
		t.userCardEdge = pick(i, null, c(0x3c3c3c), c(0x5a4a33));
		t.botCardBg = pick(i, c(0x262019), c(0x2a2a2a), c(0xe2d8ba));
		t.botCardEdge = pick(i, c(0x4a3b24), c(0x363636), c(0x5a4a33));
		t.bevelLight = pick(i, null, null, c(0xf4ecd4));
		t.userLabelFg = pick(i, c(0xffffff), c(0x9a9a9a), c(0x16388c));
		t.botLabelFg = pick(i, c(0xff981f), c(0x9a9a9a), c(0x7a1f1f));
		t.userBodyHex = pick(i, "#ff981f", "#dddddd", "#16388c");
		t.botBodyHex = pick(i, "#e8ddc4", "#dddddd", "#2e2415");
		t.userPrefixHex = pick(i, "#ffffff", "#ffffff", "#16388c");
		t.noteHex = pick(i, "#a89878", "#9a9a9a", "#6a5c40");
		t.metaHex = pick(i, "#8a7c60", "#828282", "#7a6c50");
		t.caretHex = pick(i, "#ff981f", "#cfcfcf", "#7a1f1f");
		t.welcomeTextHex = pick(i, "#a89878", "#828282", "#c8b681");
		t.tableEdgeHex = pick(i, "#4a3b24", "#3a3a3a", "#8a7a5c");
		t.tableHeaderHex = pick(i, "#332a1d", "#303030", "#c9bc96");
		t.tableCellHex = pick(i, "#241f17", "#252525", "#d8cdad");
		t.questDoneHex = pick(i, "#2ee62e", "#6cc24a", "#1e7d1e");
		t.questProgressHex = pick(i, "#f0e130", "#d4aa46", "#8a6d00");
		t.questNotStartedHex = pick(i, "#ff4040", "#cc5555", "#a02121");
		t.itemCarriedHex = pick(i, "#8ee88e", "#7ec850", "#2a7d2a");
		t.itemBankedHex = pick(i, "#4ed6d6", "#6fa8dc", "#1e5b8a");
		t.itemUnownedHex = pick(i, "#e05b5b", "#b07070", "#a04040");
		t.plainLinkHex = pick(i, "#c8b681", "#b0a6e8", "#6a4fa0");
		return t;
	}

	private static <T> T pick(int i, T gameNative, T modern, T parchment)
	{
		return i == 1 ? modern : i == 2 ? parchment : gameNative;
	}

	private static Color c(int rgb)
	{
		return new Color(rgb);
	}
}

package com.osrscopilot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The conversation transcript and its streaming state machine, free of any
 * Swing, so partial-answer and rollback behavior is unit-testable without
 * a display.
 */
class TranscriptModel
{
	/** One message in the transcript. */
	static final class Block
	{
		final String who;
		final StringBuilder text = new StringBuilder();
		/** Dim disclosure line under an answer: what the model was given. */
		String meta;
		/** Interim activity (tool-call preamble, "Looking up ..." lines),
		 * shown dim above the text; cleared when the final answer arrives. */
		final List<String> working = new ArrayList<>();
		/** Finished answers arrive pre-rendered and entity-decorated;
		 * streaming text renders live from markdown until then. */
		String decoratedHtml;

		Block(String who)
		{
			this.who = who;
		}

		boolean isUser()
		{
			return "You".equals(who);
		}
	}

	private final List<Block> blocks = new ArrayList<>();
	// The copilot block currently receiving streamed text, if any.
	private Block answerBlock;
	// On error the block list rolls back to this size and the question
	// returns to the input box, so failures never pollute the conversation.
	private int restoreCount;
	private String pendingQuestion;

	List<Block> blocks()
	{
		return Collections.unmodifiableList(blocks);
	}

	boolean isEmpty()
	{
		return blocks.isEmpty();
	}

	/** Whether this block is the one currently streaming. */
	boolean isStreaming(Block block)
	{
		return block == answerBlock;
	}

	Block answerBlock()
	{
		return answerBlock;
	}

	/** The player submitted a question: record the rollback point and add
	 * the user block. */
	void beginQuestion(String question)
	{
		restoreCount = blocks.size();
		pendingQuestion = question;
		Block block = new Block("You");
		block.text.append(question);
		blocks.add(block);
	}

	/** Replay one completed exchange (panel rebuilds on theme/font change). */
	void seedExchange(String question, String answer, String decoratedHtml, String meta)
	{
		Block q = new Block("You");
		q.text.append(question);
		blocks.add(q);
		Block a = new Block("Copilot");
		a.text.append(answer);
		a.decoratedHtml = decoratedHtml;
		a.meta = meta;
		blocks.add(a);
		restoreCount = blocks.size();
	}

	/** A fragment of the streamed answer arrived. Returns true when this
	 * created the answer block (a structural change; the view must rebuild). */
	boolean appendDelta(String text)
	{
		boolean created = ensureAnswerBlock();
		answerBlock.text.append(text);
		return created;
	}

	/** Streamed text turned out not to be the answer (tool-call preamble);
	 * it moves to a dim working note. Returns true if anything changed. */
	boolean discardPartial()
	{
		if (answerBlock == null)
		{
			return false;
		}
		String partial = answerBlock.text.toString().trim();
		if (!partial.isEmpty())
		{
			answerBlock.working.add(partial);
		}
		answerBlock.text.setLength(0);
		return true;
	}

	/** A pipeline progress note ("Looking up: ..."). Returns true when this
	 * created the answer block. */
	boolean addWorkingNote(String note)
	{
		boolean created = ensureAnswerBlock();
		answerBlock.working.add(note);
		return created;
	}

	/** Canonicalize the finished turn: the block becomes exactly the final
	 * answer, working notes are dropped. Returns the block to re-render. */
	Block completeAnswer(String answer, String decoratedHtml, String meta)
	{
		ensureAnswerBlock();
		Block block = answerBlock;
		answerBlock = null;
		block.working.clear();
		block.text.setLength(0);
		block.text.append(answer);
		block.decoratedHtml = decoratedHtml;
		block.meta = meta;
		return block;
	}

	/** Roll the conversation back to before the failed question. Returns
	 * the question text so the view can put it back in the input box. */
	String rollback()
	{
		while (blocks.size() > restoreCount)
		{
			blocks.remove(blocks.size() - 1);
		}
		answerBlock = null;
		return pendingQuestion;
	}

	void clear()
	{
		blocks.clear();
		answerBlock = null;
		restoreCount = 0;
		// A stale pending question would otherwise resurface in the input
		// box if the first post-clear question fails and rolls back.
		pendingQuestion = null;
	}

	/** Returns true when the answer block had to be created. */
	private boolean ensureAnswerBlock()
	{
		if (answerBlock != null)
		{
			return false;
		}
		answerBlock = new Block("Copilot");
		blocks.add(answerBlock);
		return true;
	}
}

package com.osrscopilot.area;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Names for map regions the vendored {@link GameArea} table lacks: content
 * released after the table's last update, and the Wilderness, which the
 * table never covered. Region IDs were derived from each wiki location
 * page's map coordinates by GameAreaScan; where several places share a
 * region, the settlement or best-known landmark won. Consulted only when
 * GameArea resolves nothing, so entries can never shadow the vendored data.
 */
final class AreaSupplement
{
	private AreaSupplement()
	{
	}

	/** Surface Wilderness bounds. Named POI regions inside them are in
	 * REGION_NAMES and match first. */
	private static final int WILDY_X_MIN = 2944;
	private static final int WILDY_X_MAX = 3391;
	private static final int WILDY_Y_MIN = 3520;
	private static final int WILDY_Y_MAX = 3970;

	static String name(WorldPoint point)
	{
		for (Rect r : RECTS)
		{
			if (point.getX() >= r.x1 && point.getX() <= r.x2
				&& point.getY() >= r.y1 && point.getY() <= r.y2)
			{
				return r.name;
			}
		}
		String named = REGION_NAMES.get(point.getRegionID());
		if (named != null)
		{
			return named;
		}
		if (point.getX() >= WILDY_X_MIN && point.getX() <= WILDY_X_MAX
			&& point.getY() >= WILDY_Y_MIN && point.getY() <= WILDY_Y_MAX)
		{
			int level = Math.min(56, (point.getY() - WILDY_Y_MIN) / 8 + 1);
			return "the Wilderness (level " + level + ")";
		}
		return null;
	}

	/** Places whose footprint is far smaller than a map region or which
	 * straddle a region boundary; a whole-region entry would misname the
	 * surrounding wilderness. Checked before REGION_NAMES. */
	private static final Rect[] RECTS = {
		new Rect(3113, 3616, 3157, 3648, "Ferox Enclave"),
		new Rect(3096, 3558, 3114, 3580, "South Wilderness mine"),
	};

	private static final class Rect
	{
		final int x1;
		final int y1;
		final int x2;
		final int y2;
		final String name;

		Rect(int x1, int y1, int x2, int y2, String name)
		{
			this.x1 = x1;
			this.y1 = y1;
			this.x2 = x2;
			this.y2 = y2;
			this.name = name;
		}
	}

	private static final Map<Integer, String> REGION_NAMES = new HashMap<>();

	private static void put(int region, String name)
	{
		REGION_NAMES.put(region, name);
	}

	static
	{
		put(4651, "Laguna Aurorae");
		put(4751, "Kurask Lair");
		put(4764, "Headless Beast's Lair");
		put(4911, "South-west Tlati Rainforest mine");
		put(4912, "Tal Teklan");
		put(4913, "Tal Teok");
		put(5012, "Dragon Nest");
		put(5165, "Darkmoon Ravine");
		put(5168, "Tlati Rainforest");
		put(5170, "Tempestus");
		put(5172, "Stalker Den");
		put(5173, "Custodia Mountains mine");
		put(5266, "Tonali Cavern");
		put(5267, "Crypt of Tonali");
		put(5268, "Ruins of Mokhaiotl");
		put(5420, "Mistrock");
		put(5421, "Aldarin");
		put(5423, "Kastori");
		put(5426, "Gloomthorn Trail");
		put(5427, "Auburn Valley");
		put(5677, "Villa Lucens");
		put(5683, "Great Auburn Redwood");
		put(5684, "Auburnvale");
		put(5786, "Giants' Den");
		put(5787, "Shayzien Prison");
		put(5938, "Quetzacalli Gorge");
		put(5939, "The Darkfrost");
		put(5949, "The White Cliffs of Lova");
