package com.osrscopilot.area;

import com.google.common.base.Preconditions;
import com.google.common.collect.Range;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.ToString;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

/**
 * An area of the game contained within a given region, which may encompass the entire region or be limited to a
 * specific {@link WorldArea}'s rectangle and/or planes within that region.
 *
 * <p>Vendored from runelite/runelite#14808 with {@code subRegionIntersects} removed (it needs a
 * {@code WorldArea} method that PR also adds); replace with net.runelite.client.game.RegionArea if that PR merges.
 */
@Getter
@ToString
public class RegionArea
{
	private final int region;
	@Nullable
	private final WorldArea area;
	@Nullable
	private final Range<Integer> planes;

	/**
	 * Create a {@link RegionArea} in a given region encompassing the entire region, e.g. a full-region area.
	 *
	 * @param region Region the area is within
	 */
	public RegionArea(final int region)
	{
		this(region, (WorldArea) null, null);
	}

	/**
	 * Create a {@link RegionArea} in a given region encompassing the 2-dimensional rectangle with the given southwest
	 * and northeast {@link WorldPoint WorldPoints} as corners, spanning all planes. (The
	 * {@link WorldPoint#getPlane() plane} of the given points will be ignored.)
	 *
	 * @param region   Region the area is within
	 * @param swCorner Southwest corner of the area
	 * @param neCorner Northeast corner of the area
	 */
	public RegionArea(final int region, final WorldPoint swCorner, final WorldPoint neCorner)
	{
		this(region, swCorner, neCorner, null);
	}

	/**
	 * Create a {@link RegionArea} in a given region encompassing the given area, spanning all planes. (The
	 * {@link WorldArea#getPlane() plane} of the given points will be ignored.)
	 *
	 * @param region Region the area is within
	 * @param area   The area within the region to be covered
	 */
	public RegionArea(final int region, @Nullable final WorldArea area)
	{
		this(region, area, null);
	}

	/**
	 * Create a {@link RegionArea} in a given region encompassing the entire region, spanning the given range of planes.
	 *
	 * @param region Region the area is within
	 * @param planes A {@link Range} of planes to be spanned. (This should be within the range 0-3, inclusive. See
	 *               {@link net.runelite.api.Constants#MAX_Z})
	 */
	public RegionArea(final int region, @Nullable final Range<Integer> planes)
	{
		this(region, null, planes);
	}

	/**
	 * Create a {@link RegionArea} in a given region encompassing the 2-dimensional rectangle with the given southwest
	 * and northeast {@link WorldPoint WorldPoints} as corners, spanning the given range of planes. (The
	 * {@link WorldPoint#getPlane() plane} of the given points will be ignored in favor of the given range of planes.)
	 *
	 * @param region   Region the area is within
	 * @param swCorner Southwest corner of the area
	 * @param neCorner Northeast corner of the area
	 * @param planes   A {@link Range} of planes to be spanned. (This should be within the range 0-3, inclusive. See
	 *                 {@link net.runelite.api.Constants#MAX_Z})
	 */
	public RegionArea(final int region, final WorldPoint swCorner, final WorldPoint neCorner, @Nullable final Range<Integer> planes)
	{
		this(region, new WorldArea(swCorner, neCorner.getX() - swCorner.getX() + 1, neCorner.getY() - swCorner.getY() + 1), planes);
	}

	/**
	 * Create a {@link RegionArea} in a given region encompassing the given area and spanning the given range of planes.
	 * (The {@link WorldArea#getPlane() plane} of the given area will be ignored in favor of the given range of planes.)
	 *
	 * @param region Region the area is within
	 * @param area   The area within the region to be covered
	 * @param planes A {@link Range} of planes to be spanned. (This should be within the range 0-3, inclusive. See
	 *               {@link net.runelite.api.Constants#MAX_Z})
	 */
	public RegionArea(final int region, @Nullable final WorldArea area, @Nullable final Range<Integer> planes)
	{
		if (area != null)
		{
			final WorldPoint swCorner = area.toWorldPoint();
			final WorldPoint neCorner = swCorner.dx(area.getWidth() - 1).dy(area.getHeight() - 1);
			Preconditions.checkArgument(swCorner.getRegionID() == region && neCorner.getRegionID() == region,
				"Area corners ({}, {}) must both be in the given region (id: {})", swCorner, neCorner, region);
		}

		this.region = region;
		this.area = area;
		this.planes = planes;
	}

	/**
	 * Tests if a given {@link WorldPoint} is inside the {@link RegionArea}.
	 *
	 * @param point The given {@link WorldPoint} to be tested
	 * @return {@code true} if the given {@link WorldPoint} is inside the {@link RegionArea}, {@code false} otherwise.
	 */
	public boolean contains(final WorldPoint point)
	{
		if (getPlanes() != null && !getPlanes().contains(point.getPlane()))
		{
			return false;
		}

		if (getArea() != null && !getArea().contains2D(point))
		{
			return false;
		}

		return getRegion() == point.getRegionID();
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/** Tool-calling loop: the model may call tools for a bounded number of turns,
 * then is forced to answer from what it has gathered. */
@Slf4j
class AgentLoop
{
	/** Cap on tool calls executed from one model message: the endpoint is
	 * untrusted and could fan out into hundreds of wiki requests. Excess
	 * calls get an error result (the protocol requires a response per
	 * call id). */
	private static final int MAX_TOOL_CALLS_PER_TURN = 8;

	interface Tool
	{
		Object call(JsonObject args) throws Exception;
	}

	static class Result
	{
		String answer = "";
		final List<String> toolLog = new ArrayList<>();
		int turns;
	}

	/** Runs on a prepared message list (system + any conversation history +
	 * the current user turn), mutating it as tool calls resolve. */
	static Result run(Llm llm, Gson gson, JsonArray messages,
		JsonArray toolSpecs, Map<String, Tool> tools, int maxTurns,
		StreamListener listener) throws IOException
	{
		Result result = new Result();

		for (int turn = 0; turn < maxTurns; turn++)
		{
			result.turns = turn + 1;
			// The warning must precede the final turn: a cutoff discovered
			// after the fact leaks tool markup instead of prose.
			if (turn == maxTurns - 1 && turn > 0)
			{
				messages.add(message("user", "Research budget nearly exhausted: any tool "
					+ "calls in your next message are the LAST that will be executed. "
					+ "Prefer answering now from what you have gathered."));
			}
			JsonObject msg = llm.chat(messages, toolSpecs, listener);
			JsonArray toolCalls = msg.has("tool_calls") && msg.get("tool_calls").isJsonArray()
				? msg.getAsJsonArray("tool_calls") : null;

			if (toolCalls == null || toolCalls.size() == 0)
			{
				result.answer = ensureAnswer(llm, messages, msg, listener, result);
				return result;
			}

			// Any text streamed this turn was preamble to tool calls, not
			// the answer -- take it back off the display.
			if (listener != null)
			{
				listener.onTurnDiscarded();
				listener.onStatus("Looking up: " + toolCallNames(toolCalls));
			}

			JsonObject assistant = message("assistant", contentOf(msg));
			assistant.add("tool_calls", toolCalls);
			messages.add(assistant);

			for (int i = 0; i < toolCalls.size(); i++)
			{
				JsonObject call = toolCalls.get(i).getAsJsonObject();
				JsonObject fn = call.getAsJsonObject("function");
				String name = fn.get("name").getAsString();
				JsonObject args;
				try
				{
					args = gson.fromJson(fn.get("arguments").getAsString(), JsonObject.class);
				}
				catch (Exception e)
				{
					args = new JsonObject();
				}
				if (args == null)
				{
					args = new JsonObject();
				}

				Object output;
				Tool tool = tools.get(name);
				if (i >= MAX_TOOL_CALLS_PER_TURN)
				{
					output = Map.of("error", "tool call budget for this turn exceeded; "
						+ "answer from what you have");
				}
				else
				{
					try
					{
						output = tool != null ? tool.call(args)
							: Map.of("error", "unknown tool: " + name);
					}
					catch (Exception e)
					{
						output = Map.of("error", e.getClass().getSimpleName() + ": " + e.getMessage());
					}
				}
				String outputJson = output instanceof String ? (String) output : gson.toJson(output);
				result.toolLog.add(name + "(" + gson.toJson(args) + ")");
				log.debug("tool {} -> {}B", name, outputJson.length());

				JsonObject toolMsg = message("tool", outputJson);
				toolMsg.addProperty("tool_call_id",
					call.has("id") ? call.get("id").getAsString() : String.valueOf(i));
				messages.add(toolMsg);
			}
		}

		// Turn budget exhausted: force a final answer without tools.
		messages.add(message("user",
			"Stop researching. Give your final answer now using the facts you have gathered."));
		result.answer = ensureAnswer(llm, messages,
			llm.chat(messages, null, listener), listener, result);
		return result;
	}

	/** Retries once when the "answer" is empty or tool markup: a
	 * length-truncated response (finish_reason=length) gets a brevity
	 * corrective, leaked tool syntax gets "tools are gone". A failed
	 * retry throws EmptyAnswerException with the tool trace. */
	private static String ensureAnswer(Llm llm, JsonArray messages, JsonObject msg,
		StreamListener listener, Result result) throws IOException
	{
		String answer = contentOf(msg);
		if (!looksLikeToolMarkup(answer))
		{
			return answer;
		}
		if (listener != null)
		{
			listener.onTurnDiscarded();
		}
		boolean truncated = truncatedByLength(msg);
		messages.add(message("user", truncated
			? "Your previous response hit the token limit before any answer text "
				+ "appeared. Answer now in plain prose. Be brief: a compact answer "
				+ "beats a complete one that gets cut off again."
			: "Tools are no longer available. Do NOT emit tool-call syntax. "
				+ "Write your final answer as plain prose now."));
		JsonObject retryMsg = llm.chat(messages, null, listener);
		String retry = contentOf(retryMsg);
		if (looksLikeToolMarkup(retry))
		{
			throw new EmptyAnswerException(result.turns, toolNames(result.toolLog),
				truncated || truncatedByLength(retryMsg));
		}
		return retry;
	}

	private static boolean truncatedByLength(JsonObject msg)
	{
		return msg.has("finish_reason") && !msg.get("finish_reason").isJsonNull()
			&& "length".equals(msg.get("finish_reason").getAsString());
	}

	/** Bare tool names from the log's "name({args})" entries. */
	private static String toolNames(List<String> toolLog)
	{
		List<String> names = new ArrayList<>();
		for (String entry : toolLog)
		{
			int paren = entry.indexOf('(');
			names.add(paren > 0 ? entry.substring(0, paren) : entry);
		}
		return String.join(", ", names);
	}

	private static String toolCallNames(JsonArray toolCalls)
	{
		List<String> names = new ArrayList<>();
		for (int i = 0; i < toolCalls.size(); i++)
		{
			names.add(toolCalls.get(i).getAsJsonObject()
				.getAsJsonObject("function").get("name").getAsString());
		}
		return String.join(", ", names);
	}

	static JsonObject message(String role, String content)
	{
		JsonObject msg = new JsonObject();
		msg.addProperty("role", role);
		msg.addProperty("content", content == null ? "" : content);
		return msg;
	}

	private static String contentOf(JsonObject msg)
	{
		return msg.has("content") && !msg.get("content").isJsonNull()
			? msg.get("content").getAsString() : "";
	}

	private static boolean looksLikeToolMarkup(String text)
	{
		String stripped = text == null ? "" : text.trim();
		return stripped.isEmpty() || stripped.contains("tool_calls")
			|| stripped.contains("invoke name=") || stripped.startsWith("<");
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;

/**
 * OSRS Copilot pipeline: resolve -> classify -> prefetch -> synthesize.
 * The only external dependencies are the OSRS Wiki/GE APIs and the user's
 * own LLM endpoint.
 */
@Slf4j
public class CopilotPipeline
{
	/** One completed question/answer pair from earlier in the session. */
	public static class Exchange
	{
		public final String question;
		public final String answer;
		/** What that turn resolved to; lets follow-ups keep the subject. */
		public final EntityResolver.Resolution entities;

		public Exchange(String question, String answer, EntityResolver.Resolution entities)
		{
			this.question = question;
			this.answer = answer;
			this.entities = entities;
		}
	}

	/** The deterministic routing decision for one question, made before
	 * the model runs. */
	public static class Route
	{
		public EntityResolver.Resolution entities;
		public List<String> needs;
		public List<String> facilityPages;
		/** Named diary tier (easy/medium/hard/elite) when a diary page
		 * resolved; routes the prefetch to that tier's section only. */
		public String diaryTier;
		/** complete | summarized | unknown */
		public String bankMode;
	}

	public static class Result
	{
		public String answer;
		public Route route;
		public int factBlocks;
		/** Heading of every fact block retrieved, for user-facing disclosure. */
		public List<String> factTitles = List.of();
		public int contextChars;
		public List<String> toolLog;
		public long millis;
		/** The full user message sent to the model, for sanity inspection. */
		public String prompt;
		/** Token usage summed across every LLM call for this question. */
		public Llm.Usage usage;
		/** Names the answer introduced that the wiki says aren't this
		 * game's ("Anachronia -> Fossil Island"). */
		public List<String> suspectNames = List.of();
		/** The turn's inheritable subject (see subjectOf). Store this in
		 * the Exchange, not route.entities, so follow-ups can point at
		 * things the answer brought up. */
		public EntityResolver.Resolution subject;
	}

	/** Everything the model gets, produced without any LLM call so
	 * retrieval can be inspected and regression-tested. */
	public static class Prepared
	{
		public Route route;
		public String prompt;
		public int factBlocks;
		public List<String> factTitles = List.of();
		private Map<String, long[]> ownedIndex;
		private Map<String, String> ownedNames;
		private boolean bankInlined;
		/** Whether search_owned_items is offered; decided in prepare(). */
		private boolean offerOwnedSearch;
	}

	private final Http http;
	private final Gson gson;
	private final WikiApi wiki;
	private final EntityResolver resolver;
	private final Hiscores hiscores;
	private final Router router;
	private final Prefetcher prefetcher;
	private final ToolRegistry toolRegistry;
	private final PromptBuilder promptBuilder;

	public CopilotPipeline(OkHttpClient httpClient, Gson gson, File cacheDir)
	{
		this.http = new Http(httpClient, gson);
		this.gson = gson;
		this.wiki = new WikiApi(http, gson, cacheDir);
		this.resolver = new EntityResolver(wiki);
		this.hiscores = new Hiscores(http);
		this.router = new Router(resolver);
		this.prefetcher = new Prefetcher(wiki, gson);
		this.toolRegistry = new ToolRegistry(wiki, gson);
		this.promptBuilder = new PromptBuilder(gson, hiscores);
	}

	/** Invalidates the hiscores cache; see {@link Hiscores}. */
	public void onLogin()
	{
		hiscores.invalidate();
	}

	/** Warm vocabulary caches (call off-thread, e.g. at plugin start). */
	public void warmCaches()
	{
		try
		{
		wiki.itemCatalog();
			wiki.monsterNames();
			wiki.englishWords();
		}
		catch (IOException e)
		{
			log.warn("cache warm failed (will retry on first question)", e);
		}
	}

	/** The deterministic front half; callable on its own for route
	 * regression testing. */
	public Route route(String question, GameCapture cap, EntityResolver.Resolution previous)
		throws IOException
	{
		return router.route(question, cap, previous);
	}

	/** The subject usually opens the answer; deeper text is supporting
	 * cast. */
	private static final int SUBJECT_SCAN_CHARS = 600;
	/** The scan stops at the first list/table row: enumerated names are
	 * supporting cast. */
	private static final Pattern SUBJECT_SCAN_STOP =
		Pattern.compile("(?m)^\\s*(?:[-*|]|\\d+\\.)\\s");
	/** Cap on answer-introduced names joining the subject, per kind. */
	private static final int SUBJECT_ADDITIONS = 3;

	/** The turn's inheritable subject: the question's entities plus the
	 * leading names the answer introduced ("make the bow" resolves the
	 * Tormented synapse, the answer talks about the Scorching bow, "this
	 * bow" then means the bow). Best-effort. */
	public EntityResolver.Resolution subjectOf(EntityResolver.Resolution question,
		String answer, GameCapture cap)
	{
		EntityResolver.Resolution subject = new EntityResolver.Resolution();
		subject.items.addAll(question.items);
		subject.monsters.addAll(question.monsters);
		subject.quests.addAll(question.quests);
		subject.skills.addAll(question.skills);
		subject.pages.addAll(question.pages);
		try
		{
			String opening = answer.length() > SUBJECT_SCAN_CHARS
				? answer.substring(0, SUBJECT_SCAN_CHARS) : answer;
			Matcher stop = SUBJECT_SCAN_STOP.matcher(opening);
			if (stop.find())
			{
				opening = opening.substring(0, stop.start());
			}
			EntityResolver.Resolution named = resolver.resolve(opening,
				cap.questStates != null ? cap.questStates.keySet() : Set.of(),
				EntityResolver.Source.ANSWER);
			appendCapped(named.items, subject.items);
			appendCapped(named.monsters, subject.monsters);
			appendCapped(named.quests, subject.quests);
			appendCapped(named.pages, subject.pages);
		}
		catch (Exception e)
		{
			log.debug("subject resolution from answer failed", e);
		}
		return subject;
	}

	private static void appendCapped(List<String> from, List<String> into)
	{
		int added = 0;
		for (String name : from)
		{
			if (added == SUBJECT_ADDITIONS)
			{
				return;
			}
			if (!into.contains(name))
			{
				into.add(name);
				added++;
			}
		}
	}

	/** The wiki page a fact title was retrieved from (null for game-state
	 * and non-page facts), for the answer footer's source links. */
	public static String factSourcePage(String factTitle)
	{
		return Prefetcher.sourcePage(factTitle);
	}

	/** A fact title's user-facing form: game-state headings drop the
	 * model-facing instructions they carry. */
	public static String factDisplayTitle(String factTitle)
	{
		return Prefetcher.displayTitle(factTitle);
	}

	/** The item catalogue, for UI entity linking. */
	public List<ItemDescriptor> knownItems() throws IOException
	{
		return wiki.itemCatalog();
	}

	/** Every plain monster name, for UI entity linking. Variant pages with
	 * parenthetical disambiguators are excluded: prose never writes "Black
	 * demon (The Grand Tree)". */
	public List<String> knownMonsterNames() throws IOException
	{
		List<String> out = new ArrayList<>();
		for (String name : wiki.monsterNames())
		{
			if (name.indexOf('(') < 0)
			{
				out.add(name);
			}
		}
		return out;
	}

	public Prepared prepare(String question, GameCapture cap, EntityResolver.Resolution previous)
		throws IOException
	{
		Prepared p = new Prepared();
		p.route = route(question, cap, previous);
		p.ownedIndex = Ownership.buildIndex(cap);
		p.ownedNames = Ownership.buildNames(cap);
		p.bankInlined = !"summarized".equals(p.route.bankMode);

		List<String> facts = prefetcher.prefetch(p.route, cap,
			p.ownedIndex, p.ownedNames, p.bankInlined);
		// Dedupe against pages the entity loop actually fetched: it skips
		// pages the facility rule claimed, so those must not count here.
		List<String> fetchedPages = new ArrayList<>();
		for (String pg : p.route.entities.pages)
		{
			if (p.route.facilityPages.stream().noneMatch(f -> f.equalsIgnoreCase(pg)))
			{
				fetchedPages.add(pg);
			}
		}
		prefetcher.prefetchFacilities(p.route.facilityPages, fetchedPages, facts);
		prefetcher.addFacilitiesFromFacts(question, p.route, facts);
		Map<String, String> questFacts = Prefetcher.relevantQuestStates(question, facts,
			p.route.entities, cap.questStates);
		if (questFacts != null)
		{
			facts.add("### Quest progress (authoritative, from the game client)\n"
				+ gson.toJson(questFacts));
		}
		boolean ownershipComplete = false;
		if (!p.bankInlined)
		{
			ownershipComplete = prefetcher.addOwnershipFromFacts(facts, p.ownedIndex, p.ownedNames);
		}
		// Withhold the search tool only when the facts carry a gear list
		// with a complete ownership slice; without a gear list, "complete"
		// covers only incidental page items.
		boolean equipmentListed = facts.stream()
			.anyMatch(f -> f.startsWith("### Recommended equipment: "));
		p.offerOwnedSearch = !p.bankInlined && !(ownershipComplete && equipmentListed);

		p.factBlocks = facts.size();
		p.factTitles = new ArrayList<>();
		for (String fact : facts)
		{
			int nl = fact.indexOf('\n');
			p.factTitles.add((nl > 0 ? fact.substring(0, nl) : fact)
				.replaceFirst("^#+\\s*", ""));
		}
		p.prompt = promptBuilder.buildUserMessage(question, cap, facts,
			p.bankInlined, ownershipComplete, p.offerOwnedSearch);
		return p;
	}

	/** One minimal completion so the setup form can verify an endpoint;
	 * throws with the provider's error on failure. */
	public void testEndpoint(Llm.Settings settings) throws IOException
	{
		Llm llm = new Llm(http, gson, settings);
		JsonObject m = new JsonObject();
		m.addProperty("role", "user");
		m.addProperty("content", "Reply with one word: OK");
		JsonArray messages = new JsonArray();
		messages.add(m);
		llm.chat(messages, null, text -> { });
	}

	public Result answer(String question, List<Exchange> history, GameCapture cap,
		Llm.Settings llmSettings, int maxTurns, boolean simpleMode,
		StreamListener listener) throws IOException
	{
		long t0 = System.currentTimeMillis();
		Llm llm = new Llm(http, gson, llmSettings);

		Exchange last = history != null && !history.isEmpty()
			? history.get(history.size() - 1) : null;
		Prepared prepared = prepare(question, cap, last != null ? last.entities : null);
		Route route = prepared.route;
		String userMessage = prepared.prompt;

		// Prior turns carry only question + answer; state and facts
		// accompany the latest turn only.
		JsonArray messages = new JsonArray();
		messages.add(AgentLoop.message("system", PromptBuilder.systemPrompt(simpleMode)));
		for (Exchange ex : PromptBuilder.boundedHistory(history))
		{
			messages.add(AgentLoop.message("user", ex.question));
			messages.add(AgentLoop.message("assistant", ex.answer));
		}
		messages.add(AgentLoop.message("user", userMessage));

		JsonArray toolSpecs = toolRegistry.buildToolSpecs(prepared.offerOwnedSearch);
		Map<String, AgentLoop.Tool> tools = toolRegistry.buildTools(cap, prepared.ownedIndex,
			prepared.ownedNames, prepared.offerOwnedSearch, !prepared.bankInlined);

		AgentLoop.Result agent = AgentLoop.run(llm, gson, messages,
			toolSpecs, tools, maxTurns, listener);

		// The simple-mode prompt alone doesn't hold on formatting-happy
		// models; strip before the answer enters history.
		String answer = simpleMode ? stripEmphasisMarkdown(agent.answer) : agent.answer;

		Result result = new Result();
		result.answer = answer;
		result.route = route;
		result.factBlocks = prepared.factBlocks;
		result.factTitles = prepared.factTitles;
		result.contextChars = userMessage.length();
		result.toolLog = agent.toolLog;
		result.prompt = userMessage;
		result.usage = llm.usage();
		result.suspectNames = suspectNames(answer, userMessage);
		result.subject = subjectOf(route.entities, answer, cap);
		result.millis = System.currentTimeMillis() - t0;
		return result;
	}

	/** Removes emphasis markup (bold, italics, headers, inline code).
	 * Lists and tables are left alone: they can't be flattened to prose
	 * mechanically, and the renderer handles them. */
	static String stripEmphasisMarkdown(String answer)
	{
		return answer
			.replaceAll("(?m)^#{1,6}\\s+", "")
			.replaceAll("\\*\\*([^*]+)\\*\\*", "$1")
			.replaceAll("(?<![\\w*])\\*([^*\\n]+)\\*(?![\\w*])", "$1")
			.replaceAll("`([^`]+)`", "$1");
	}

	/** Post-hoc grounding check: proper nouns the answer introduced that
	 * the wiki has no page for. A failure never costs the answer. */
	private List<String> suspectNames(String answer, String context)
	{
		try
		{
			List<GroundingCheck.Finding> suspect =
				GroundingCheck.suspect(GroundingCheck.check(answer, context, wiki));
			List<String> names = new ArrayList<>();
			for (GroundingCheck.Finding f : suspect)
			{
				names.add(f.toString());
			}
			if (!names.isEmpty())
			{
				log.info("answer contains names absent from the wiki: {}", names);
			}
			return names;
		}
		catch (Exception e)
		{
			log.debug("grounding check failed", e);
			return List.of();
		}
	}

}

package com.osrscopilot.pipeline;

import java.io.IOException;

/** The model finished without usable answer text even after a corrective
 * retry. Its own type so the UI can offer a resubmit; carries the tool
 * trace. */
public class EmptyAnswerException extends IOException
{
	public EmptyAnswerException(int turns, String toolNames, boolean truncatedByLength)
	{
		super("no answer text after " + turns + " tool turn" + (turns == 1 ? "" : "s")
			+ (toolNames.isEmpty() ? "" : " (" + toolNames + ")")
			+ (truncatedByLength
				? " -- the response hit the max-token limit before any answer text; "
					+ "raising Max tokens in the copilot settings gives the model room"
				: ""));
	}
}

package com.osrscopilot.pipeline;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * Deterministic entity resolution: n-gram lookup against local vocabularies
 * (longest match wins), then unresolved spans batched through the wiki
 * redirect API, which resolves community slang ("addy bars" -> Adamantite
 * bar, "kbd" -> King Black Dragon).
 */
@Slf4j
public class EntityResolver
{
	private static final List<String> SKILLS = Arrays.asList(
		"attack", "strength", "defence", "ranged", "prayer", "magic", "runecraft",
		"construction", "hitpoints", "agility", "herblore", "thieving", "crafting",
		"fletching", "slayer", "hunter", "mining", "smithing", "fishing", "cooking",
		"firemaking", "woodcutting", "farming", "sailing");

	private static final Map<String, String> SKILL_ALIASES = Map.of(
		"defense", "defence", "rc", "runecraft", "wc", "woodcutting", "fm", "firemaking",
		"hp", "hitpoints", "con", "construction", "range", "ranged", "ranging", "ranged",
		"mage", "magic");

	/** Question vocabulary that is never a subject ("whats", "worth",
	 * "gear"). Common English is rejected by the frequency band instead;
	 * two-letter words ("go", "up") must be listed here because the
	 * wordlist can't judge that length and both have wiki redirects. */
	private static final Set<String> STOPWORDS = new HashSet<>(Arrays.asList(
		("a an the i my me you your it its this that these those is are was be been "
		+ "do does did can could should would will whats what's what how where when why which who "
		+ "best good better fast fastest quick quickest way ways get got make making need needs "
		+ "build building built nearest closest go up "
		+ "worth for with without and or not no yes of in on at to from into vs versus about "
		+ "more less most many much have has had if while during active right now current level "
		+ "levels xp exp experience quest quests boss monster gear setup loadout strategy guide tips "
		+ "kill killing fight fighting drop drops dropped use using item items stuff thing things "
		+ "money gp gold profit hour hr afk safe easy hard next "
		+ "player players people normally usually give giving steps step finish finished "
		+ "complete completed start started solo group grouping").split(" ")));

	/** Function words only; judges span edges. STOPWORDS can't: it holds
	 * game words ("quest", "gear") that appear in page titles. */
	private static final Set<String> GRAMMAR = new HashSet<>(Arrays.asList(
		("a an the this that these those my your our their its his her "
		+ "i me you it we they "
		+ "is are was were be been am do does did can could should would will might must "
		+ "if while during until when where what whats what's how why which who whose "
		+ "and or nor but not no yes vs versus "
		+ "of in on at to from into onto with without for by about than then as "
		// Some contractions have wiki redirects ("Im" -> Ironman Mode).
		+ "im ive id ill youre ur hes shes theyre weve youve "
		+ "dont doesnt didnt isnt arent wasnt werent cant wont couldnt "
		+ "wouldnt shouldnt havent hasnt hadnt "
		+ "ah hm hmm eh oh ok okay um uh huh hey yo "
		// "Nearest bank" is a real wiki redirect; keeping the superlatives
		// here stops such spans at the edge check.
		+ "between above below over under across behind among upon after before near "
		+ "nearest closest there here also just really please any some").split(" ")));

	/** The register of the text; controls how eagerly the redirect pass
	 * guesses on single dictionary words. */
	public enum Source
	{
		/** Context-free player question: bare dictionary words are tried
		 * when nothing else resolved. */
		QUESTION,
		/** The conversation already has a subject: dictionary words are
		 * not tried. */
		FOLLOW_UP,
		/** Model answer prose: no single-token guesses; multi-word proper
		 * names still resolve. */
		ANSWER
	}

	public static class Resolution
	{
		public final List<String> items = new ArrayList<>();
		public final List<String> monsters = new ArrayList<>();
		public final List<String> quests = new ArrayList<>();
		public final List<String> skills = new ArrayList<>();
		public final List<String> pages = new ArrayList<>();

		public boolean anyEntity()
		{
			return !items.isEmpty() || !monsters.isEmpty() || !quests.isEmpty()
				|| !skills.isEmpty() || !pages.isEmpty();
		}

		private List<String> byKind(String kind)
		{
			switch (kind)
			{
				case "items": return items;
				case "monsters": return monsters;
				case "quests": return quests;
				case "skills": return skills;
				default: return pages;
			}
		}
	}

	private final WikiApi wiki;
	private Map<String, String> itemVocab;
	private Map<String, String> monsterVocab;

	public EntityResolver(WikiApi wiki)
	{
		this.wiki = wiki;
	}

	/** First call fetches/loads vocabularies (then cached in memory + disk). */
	private synchronized void ensureVocabs() throws IOException
	{
		if (itemVocab == null)
		{
			// Values are the canonical page: versioned names ("Fire cape
			// (l)") map to their shared page.
			Map<String, String> items = new HashMap<>();
			for (ItemDescriptor it : wiki.itemCatalog())
			{
				items.putIfAbsent(norm(it.name), it.page);
			}
			Map<String, String> monsters = new HashMap<>();
			for (String name : wiki.monsterNames())
			{
				monsters.put(norm(name), name);
			}
			itemVocab = items;
			monsterVocab = monsters;
		}
	}

	/** Resolve extra text (a name from game state, not from the player) and
	 * merge what it finds into an existing resolution. */
	public void resolveInto(String text, Collection<String> questNames, Resolution into)
		throws IOException
	{
		// Game-state names are trusted; resolve at full question register.
		Resolution extra = resolve(text, questNames, Source.QUESTION);
		for (String kind : new String[]{"items", "monsters", "quests", "skills", "pages"})
		{
			List<String> target = into.byKind(kind);
			for (String name : extra.byKind(kind))
			{
				if (!target.contains(name))
				{
					target.add(name);
				}
			}
		}
	}

	public Resolution resolve(String question, Collection<String> questNames, Source source)
		throws IOException
	{
		ensureVocabs();
		Map<String, String> questVocab = questVocab(questNames);

		String[] tokens = norm(question).split(" +");
		Resolution result = new Resolution();
		boolean[] used = new boolean[tokens.length];
		// {start, size} spans the vocabulary pass could not claim.
		List<int[]> unresolved = vocabularyPass(tokens, used, questVocab, result);
		redirectPass(tokens, used, unresolved, questVocab, result, source);
		dropShadowedPages(result);
		return result;
	}

	private static Map<String, String> questVocab(Collection<String> questNames)
	{
		Map<String, String> questVocab = new HashMap<>();
		for (String q : questNames)
		{
			questVocab.put(norm(q), q);
		}
		// Alias bare series names ("Dragon Slayer") to the numbered opener;
		// putIfAbsent keeps a real quest with that exact name first.
		for (String q : questNames)
		{
			String n = norm(q);
			if (n.endsWith(" i"))
			{
				questVocab.putIfAbsent(n.substring(0, n.length() - 2), q);
			}
		}
		return questVocab;
	}

	/** N-gram scan against the local vocabularies, longest span first.
	 * Marks claimed tokens in {@code used} and returns the spans left for
	 * the redirect pass. */
	private List<int[]> vocabularyPass(String[] tokens, boolean[] used,
		Map<String, String> questVocab, Resolution result)
	{
		List<int[]> unresolved = new ArrayList<>();
		for (int size = 4; size >= 1; size--)
		{
			for (int i = 0; i + size <= tokens.length; i++)
			{
				if (anyUsed(used, i, size))
				{
					continue;
				}
				String gram = String.join(" ", Arrays.copyOfRange(tokens, i, i + size));
				// Single letters are noise; two-letter slang ("hp", "cg")
				// is real.
				if (size == 1 && (STOPWORDS.contains(gram) || gram.length() < 2))
				{
					continue;
				}
				String[] hit = lookup(gram, questVocab);
				if (hit != null)
				{
					// A negated mention is consumed (no sub-span may retry
					// it) but resolves to nothing.
					if (!negated(tokens, i))
					{
						List<String> list = result.byKind(hit[0]);
						if (!list.contains(hit[1]))
						{
							list.add(hit[1]);
						}
					}
					Arrays.fill(used, i, i + size, true);
				}
				else if (size <= 3)
				{
					unresolved.add(new int[]{i, size});
				}
			}
		}
		return unresolved;
	}

	/** Wiki redirect pass over the spans the vocabularies left behind:
	 * candidate selection is register-aware (see isRedirectCandidate),
	 * acceptance longest-span-first as in the vocabulary pass. */
	private void redirectPass(String[] tokens, boolean[] used, List<int[]> unresolved,
		Map<String, String> questVocab, Resolution result, Source source) throws IOException
	{
		boolean vocabHit = !result.items.isEmpty() || !result.monsters.isEmpty()
			|| !result.quests.isEmpty() || !result.skills.isEmpty();

		// Shortest spans first: they are the likeliest slang.
		unresolved.sort((a, b) -> Integer.compare(a[1], b[1]));
		Map<String, int[]> chosen = new LinkedHashMap<>();
		Set<String> english = wiki.englishWords();
		Set<String> common = wiki.commonEnglishWords();
		for (int[] span : unresolved)
		{
			if (anyUsed(used, span[0], span[1]))
			{
				continue;
			}
			String[] gramTokens = Arrays.copyOfRange(tokens, span[0], span[0] + span[1]);
			if (spansFunctionWord(gramTokens) || negated(tokens, span[0]))
			{
				continue;
			}
			String gram = String.join(" ", gramTokens);
			if (!chosen.containsKey(gram)
				&& isRedirectCandidate(span[1], gramTokens, gram, english, common,
					vocabHit || source != Source.QUESTION, source))
			{
				chosen.put(gram, span);
			}
		}

		// Accept longest span first: "crystal armor" suppresses "armor".
		List<Map.Entry<String, String[]>> hits =
			new ArrayList<>(redirectBatch(new ArrayList<>(chosen.keySet()), questVocab).entrySet());
		hits.sort((a, b) -> Integer.compare(chosen.get(b.getKey())[1], chosen.get(a.getKey())[1]));
		for (Map.Entry<String, String[]> hit : hits)
		{
			int[] span = chosen.get(hit.getKey());
			if (anyUsed(used, span[0], span[1]))
			{
				continue;
			}
			// An English word must land on a typed entity ("fury" ->
			// Amulet of fury yes, "bow" -> the Bow page no). Two-letter
			// shorthand and facility nouns are exempt.
			String gram = hit.getKey();
			if (span[1] == 1 && gram.length() > 2 && english.contains(gram)
				&& !facilityNoun(gram) && "pages".equals(hit.getValue()[0]))
			{
				continue;
			}
			Arrays.fill(used, span[0], span[0] + span[1], true);
			List<String> list = result.byKind(hit.getValue()[0]);
			if (!list.contains(hit.getValue()[1]))
			{
				list.add(hit.getValue()[1]);
			}
		}
	}

	/** Drop generic page hits contained inside a stronger match
	 * ("Bar" vs "Adamantite bar", "King" vs "Dagannoth Kings"), and
	 * glossary pages when a real subject resolved. */
	private static void dropShadowedPages(Resolution result)
	{
		List<String> allNames = new ArrayList<>();
		for (String kind : new String[]{"items", "monsters", "quests", "pages"})
		{
			for (String n : result.byKind(kind))
			{
				allNames.add(n.toLowerCase(Locale.ROOT));
			}
		}
		result.pages.removeIf(p -> {
			String pl = p.toLowerCase(Locale.ROOT);
			return allNames.stream().anyMatch(other -> !pl.equals(other) && other.contains(pl));
		});
		// A glossary page ("kc" -> Kill count) is only the subject when
		// nothing else resolved.
		if (hasSubjectBesides(result, GLOSSARY_PAGES))
		{
			result.pages.removeIf(GLOSSARY_PAGES::contains);
		}
	}

	private static final Set<String> GLOSSARY_PAGES =
		new HashSet<>(Arrays.asList("Kill count", "Drop rate"));

	private static boolean hasSubjectBesides(Resolution result, Set<String> ignoredPages)
	{
		if (!result.items.isEmpty() || !result.monsters.isEmpty()
			|| !result.quests.isEmpty() || !result.skills.isEmpty())
		{
			return true;
		}
		return result.pages.stream().anyMatch(p -> !ignoredPages.contains(p));
	}

	/** Exclusion cues. "don't/haven't" are deliberately absent: "I don't
	 * have the armor" still needs the armor's facts. */
	private static final Set<String> NEGATIONS = new HashSet<>(Arrays.asList(
		"not", "without", "excluding", "except", "besides", "minus", "ignoring"));

	/** True when the word appears at least once outside a negation
	 * ("on task" yes; "not on task" no). */
	static boolean mentionsAffirmatively(String question, String word)
	{
		String[] tokens = norm(question).split(" +");
		for (int i = 0; i < tokens.length; i++)
		{
			if (tokens[i].equals(word) && !negated(tokens, i))
			{
				return true;
			}
		}
		return false;
	}

	/** True when the span sits under a negation cue with only function
	 * words between; a content word breaks the chain ("don't HAVE the
	 * armor" still resolves the armor). */
	private static boolean negated(String[] tokens, int start)
	{
		for (int back = 1; back <= 3 && start - back >= 0; back++)
		{
			String t = tokens[start - back];
			if (NEGATIONS.contains(t))
			{
				return true;
			}
			if (!GRAMMAR.contains(t))
			{
				return false;
			}
		}
		return false;
	}

	/** A mention never begins or ends on a function word: "blowpipe or"
	 * is a real redirect (the game names ornament kits "(or)"). */
	private static boolean spansFunctionWord(String[] gramTokens)
	{
		return GRAMMAR.contains(gramTokens[0]) || GRAMMAR.contains(gramTokens[gramTokens.length - 1]);
	}

	/** Common nouns whose game-facility sense dominates in a game question;
	 * exempt from the common-band block and the typed-entity requirement. */
	private static final Set<String> FACILITY_NOUNS =
		new HashSet<>(Arrays.asList("bank", "house"));

	private static boolean facilityNoun(String gram)
	{
		return FACILITY_NOUNS.contains(gram)
			|| (gram.endsWith("s") && FACILITY_NOUNS.contains(gram.substring(0, gram.length() - 1)));
	}

	/** Absence from English is evidence of slang, so the redirect is
	 * trusted ("kbd", "toa"); English words need proof. Common-band words
	 * never qualify, rare-band words only when nothing else resolved. */
	private static boolean isRedirectCandidate(int size, String[] gramTokens, String gram,
		Set<String> english, Set<String> common, boolean subjectKnown, Source source)
	{
		if (size == 1)
		{
			if (source == Source.ANSWER)
			{
				return false;
			}
			// A bare number is a level, not a subject ("99" redirects to
			// Skill mastery).
			if (gram.chars().allMatch(Character::isDigit))
			{
				return false;
			}
			// The wordlist can't judge two-letter words; GRAMMAR and
			// STOPWORDS have already filtered the junk ones.
			if (gram.length() == 2)
			{
				return true;
			}
			if (common.contains(gram) && !facilityNoun(gram))
			{
				return false;
			}
			if (!english.isEmpty() && english.contains(gram))
			{
				return !subjectKnown;
			}
			return true;
		}
		int content = 0;
		for (String t : gramTokens)
		{
			if (!STOPWORDS.contains(t) && t.length() >= 3)
			{
				content++;
			}
		}
		return content * 2 >= gramTokens.length;
	}

	/** Check one normalized n-gram against all vocabularies. Returns
	 * {kind, canonicalName} or null. */
	private String[] lookup(String gram, Map<String, String> questVocab)
	{
		for (String candidate : gram.endsWith("s")
			? new String[]{gram, gram.substring(0, gram.length() - 1)}
			: new String[]{gram})
		{
			if (questVocab.containsKey(candidate))
			{
				return new String[]{"quests", questVocab.get(candidate)};
			}
			if (monsterVocab.containsKey(candidate))
			{
				return new String[]{"monsters", monsterVocab.get(candidate)};
			}
			// Skills outrank items: the item index has interface
			// pseudo-items named exactly after skills.
			if (SKILL_ALIASES.containsKey(candidate))
			{
				return new String[]{"skills", capitalize(SKILL_ALIASES.get(candidate))};
			}
			if (SKILLS.contains(candidate))
			{
				return new String[]{"skills", capitalize(candidate)};
			}
			if (itemVocab.containsKey(candidate))
			{
				return new String[]{"items", itemVocab.get(candidate)};
			}
		}
		return null;
	}

	/** Resolve unmatched n-grams via wiki redirects in one batched call. */
	private Map<String, String[]> redirectBatch(List<String> grams, Map<String, String> questVocab)
	{
		Map<String, String[]> out = new LinkedHashMap<>();
		if (grams.isEmpty())
		{
			return out;
		}
		List<String> capped = grams.subList(0, Math.min(25, grams.size()));
		Map<String, String> resolved;
		try
		{
			resolved = wiki.resolveTitles(capped);
		}
		catch (Exception e)
		{
			log.debug("redirect batch failed", e);
			return out;
		}
		for (String gram : capped)
		{
			String target = resolved.get(gram);
			if (target == null)
			{
				continue;
			}
			int frag = target.indexOf('#');
			if (frag >= 0)
			{
				target = target.substring(0, frag);
			}
			if (target.endsWith("(disambiguation)"))
			{
				continue;
			}
			String[] known = lookup(norm(target), questVocab);
			out.put(gram, known != null ? known : new String[]{"pages", target});
		}
		return out;
	}

	private static boolean anyUsed(boolean[] used, int start, int size)
	{
		for (int i = start; i < start + size; i++)
		{
			if (used[i])
			{
				return true;
			}
		}
		return false;
	}

	static String norm(String s)
	{
		return s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9' ]", " ")
			.replaceAll(" +", " ").trim();
	}

	private static String capitalize(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

