package com.osrscopilot.pipeline;

import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Checks an answer's proper nouns against the OSRS wiki, after discarding
 * ones the supplied context grounds. The landing page classifies each name:
 * same or near-identical title is the thing itself, a different title means
 * another game's name, no page means unknown. One batched request, no LLM.
 */
class GroundingCheck
{
	enum Verdict
	{
		/** Real OSRS content the model recalled without being told. */
		OK,
		/** Resolves to a differently-named page: another game's name, or a rename. */
		OTHER_NAME,
		/** No page under any form of the name. */
		UNKNOWN
	}

	static class Finding
	{
		final String name;
		final String resolvedTitle;
		final Verdict verdict;

		Finding(String name, String resolvedTitle, Verdict verdict)
		{
			this.name = name;
			this.resolvedTitle = resolvedTitle;
			this.verdict = verdict;
		}

		@Override
		public String toString()
		{
			return verdict == Verdict.OTHER_NAME ? name + " -> " + resolvedTitle : name;
		}
	}

	private GroundingCheck()
	{
	}

	/** One finding per ungrounded proper noun in the answer. */
	static List<Finding> check(String answer, String context, WikiApi wiki) throws IOException
	{
		Set<String> english = wiki.englishWords();
		List<String> ungrounded = NameCheck.ungroundedNames(answer, context, english);
		ungrounded.removeIf(name -> !NameCheck.looksGameSpecific(name, english));
		if (ungrounded.isEmpty())
		{
			return List.of();
		}

		// Every form of every name resolves in a single batched request.
		Set<String> allVariants = new LinkedHashSet<>();
		for (String name : ungrounded)
		{
			allVariants.addAll(NameCheck.variants(name, english));
		}
		Map<String, String> resolved = wiki.resolveTitles(allVariants);

		List<Finding> findings = new ArrayList<>();
		for (String name : ungrounded)
		{
			findings.add(classify(name, english, resolved));
		}
		return findings;
	}

	/** Names flagged as not this game's -- the ones worth acting on. */
	static List<Finding> suspect(List<Finding> findings)
	{
		List<Finding> out = new ArrayList<>();
		for (Finding f : findings)
		{
			if (f.verdict != Verdict.OK)
			{
				out.add(f);
			}
		}
		return out;
	}

	private static Finding classify(String name, Set<String> english,
		Map<String, String> resolved)
	{
		String firstResolvedTitle = null;
		for (String variant : NameCheck.variants(name, english))
		{
			String title = resolved.get(variant);
			if (title == null)
			{
				continue;
			}
			// Any form that names its own page settles the matter.
			if (NameCheck.namesSameThing(variant, title))
			{
				return new Finding(name, title, Verdict.OK);
			}
			if (firstResolvedTitle == null)
			{
				firstResolvedTitle = title;
			}
		}
		return firstResolvedTitle == null
			? new Finding(name, null, Verdict.UNKNOWN)
			: new Finding(name, firstResolvedTitle, Verdict.OTHER_NAME);
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * Official OSRS hiscores: boss kill counts and activity scores, which are
 * invisible to the client. Cached for the whole login session: hiscores
 * only persist on logout/hop, so a mid-session refetch can't return
 * anything newer.
 */
@Slf4j
class Hiscores
{
	private static final String URL =
		"https://secure.runescape.com/m=hiscore_oldschool/index_lite.json?player=";

	private final Http http;
	private String cachedPlayer;
	private Map<String, Long> cachedScores;

	Hiscores(Http http)
	{
		this.http = http;
	}

	/** Ranked activities (boss -> kill count, minigame -> score), or null
	 * when the lookup fails or nothing is ranked. */
	synchronized Map<String, Long> rankedActivities(String player)
	{
		if (player == null || player.isEmpty())
		{
			return null;
		}
		// Client names may use non-breaking spaces.
		player = player.replace('\u00A0', ' ');
		if (player.equals(cachedPlayer))
		{
			return cachedScores;
		}
		try
		{
			JsonObject r = http.getJson(URL + Http.enc(player));
			Map<String, Long> found = new LinkedHashMap<>();
			for (JsonElement e : r.getAsJsonArray("activities"))
			{
				JsonObject a = e.getAsJsonObject();
				long score = a.get("score").getAsLong();
				if (score > 0)
				{
					found.put(a.get("name").getAsString(), score);
				}
			}
			cachedPlayer = player;
			cachedScores = found.isEmpty() ? null : found;
		}
		catch (Exception e)
		{
			// Failures are not cached; the next question retries.
			log.debug("hiscores lookup failed for {}", player, e);
			return null;
		}
		return cachedScores;
	}

	/** Called on login, the only moment the hiscores can have changed. */
	synchronized void invalidate()
	{
		cachedPlayer = null;
		cachedScores = null;
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/** Small JSON-over-HTTP helper shared by the wiki tools and the LLM client. */
class Http
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/** The wiki's APIs 400 anonymous User-Agents and require a contact
	 * channel (the repo URL). Sent on every request. */
	private static final String USER_AGENT =
		"osrs-copilot RuneLite plugin (https://github.com/zerofata/osrs-copilot)";

	private final OkHttpClient client;
	private final Gson gson;

	Http(OkHttpClient base, Gson gson)
	{
		// Reasoning models can take minutes per call.
		this.client = base.newBuilder()
			.readTimeout(180, TimeUnit.SECONDS)
			.addInterceptor(chain -> chain.proceed(chain.request().newBuilder()
				.header("User-Agent", USER_AGENT).build()))
			.build();
		this.gson = gson;
	}

	JsonObject getJson(String url) throws IOException
	{
		Request req = new Request.Builder().url(url).build();
		return execute(req);
	}

	/** POST returning the raw response for streaming consumption (SSE).
	 * Caller must close the response. Throws with the error body on non-2xx. */
	Response postStream(String url, JsonObject body, Map<String, String> headers) throws IOException
	{
		Request.Builder builder = new Request.Builder()
			.url(url)
			.post(RequestBody.create(JSON, gson.toJson(body)));
		headers.forEach(builder::header);
		Response resp = client.newCall(builder.build()).execute();
		if (!resp.isSuccessful())
		{
			String errBody = resp.body() != null ? resp.body().string() : "";
			resp.close();
			throw error(resp.code(), url, errBody);
		}
		return resp;
	}

	private JsonObject execute(Request req) throws IOException
	{
		try (Response resp = client.newCall(req).execute())
		{
			String body = resp.body() != null ? resp.body().string() : "";
			if (!resp.isSuccessful())
			{
				throw error(resp.code(), req.url().toString(), body);
			}
			return gson.fromJson(body, JsonObject.class);
		}
	}

	/** Builds an HttpException, extracting the server's error message from an
	 * OpenAI-style JSON error body when present. */
	private HttpException error(int code, String url, String body)
	{
		String serverMessage = "";
		try
		{
			JsonObject parsed = gson.fromJson(body, JsonObject.class);
			if (parsed != null && parsed.has("error") && parsed.get("error").isJsonObject())
			{
				JsonObject err = parsed.getAsJsonObject("error");
				if (err.has("message") && !err.get("message").isJsonNull())
				{
					serverMessage = err.get("message").getAsString();
				}
			}
		}
		catch (Exception ignored)
		{
			// Not JSON; fall through to the raw body.
		}
		if (serverMessage.isEmpty() && body != null && !body.isEmpty())
		{
			serverMessage = body.substring(0, Math.min(300, body.length()));
		}
		return new HttpException(code, url, serverMessage);
	}

	String getText(String url) throws IOException
	{
		return new String(getBytes(url), StandardCharsets.UTF_8);
	}

	byte[] getBytes(String url) throws IOException
	{
		Request req = new Request.Builder().url(url).build();
		try (Response resp = client.newCall(req).execute())
		{
			if (!resp.isSuccessful() || resp.body() == null)
			{
				throw new IOException("HTTP " + resp.code() + " from " + req.url());
			}
			return resp.body().bytes();
		}
	}

	static String enc(String s)
	{
		return URLEncoder.encode(s, StandardCharsets.UTF_8);
	}
}

package com.osrscopilot.pipeline;

import java.io.IOException;

/** Non-2xx HTTP response, with the status code and the server's error
 * message as fields. */
public class HttpException extends IOException
{
	public final int code;
	public final String serverMessage;

	HttpException(int code, String url, String serverMessage)
	{
		super("HTTP " + code + " from " + url
			+ (serverMessage.isEmpty() ? "" : (": " + serverMessage)));
		this.code = code;
		this.serverMessage = serverMessage;
	}
}

package com.osrscopilot.pipeline;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Collective terms guides use for item families whose real names the term
 * cannot substring-match ("god cape" for the per-god Mage Arena capes),
 * mapped to the variant words that do. Curated like the area supplement;
 * the weekly snapshot job fails when a variant no longer matches any
 * catalogued item.
 */
final class ItemCollectives
{
	private static final List<String> GOD_DHIDES = List.of(
		"saradomin d'hide", "zamorak d'hide", "guthix d'hide",
		"armadyl d'hide", "bandos d'hide", "ancient d'hide");

	private static final List<String> CANNON_PARTS = List.of(
		"cannon base", "cannon stand", "cannon barrels", "cannon furnace");

	private static final List<String> BARROWS_SETS = List.of(
		"dharok's", "ahrim's", "karil's", "torag's", "verac's", "guthan's");

	private static final List<String> SKILL_CAPES = List.of(
		"attack cape", "strength cape", "defence cape", "hitpoints cape",
		"ranging cape", "prayer cape", "magic cape", "cooking cape",
		"woodcutting cape", "fletching cape", "fishing cape", "firemaking cape",
		"crafting cape", "smithing cape", "mining cape", "herblore cape",
		"agility cape", "thieving cape", "slayer cape", "farming cape",
		"runecraft cape", "hunter cape", "construct. cape", "sailing cape");

	private static final Map<String, List<String>> COLLECTIVES = Map.ofEntries(
		Map.entry("god cape", List.of(
			"saradomin cape", "zamorak cape", "guthix cape",
			"saradomin max cape", "zamorak max cape", "guthix max cape")),
		// Prefix members cover both "Imbued X cape" and "Imbued X max cape".
		Map.entry("imbued cape", List.of(
			"imbued saradomin", "imbued zamorak", "imbued guthix")),
		Map.entry("god book", List.of(
			"holy book", "unholy book", "book of balance",
			"book of war", "book of law", "book of darkness")),
		Map.entry("god blessing", List.of(
			"holy blessing", "unholy blessing", "peaceful blessing",
			"honourable blessing", "war blessing", "ancient blessing")),
		Map.entry("blessed d'hide", GOD_DHIDES),
		Map.entry("blessed dragonhide", GOD_DHIDES),
		Map.entry("god d'hide", GOD_DHIDES),
		Map.entry("dwarf multicannon", CANNON_PARTS),
		Map.entry("dwarf cannon", CANNON_PARTS),
		Map.entry("zenyte jewellery", List.of(
			"amulet of torture", "necklace of anguish",
			"tormented bracelet", "ring of suffering")),
		Map.entry("barrows armour", BARROWS_SETS),
		Map.entry("barrows equipment", BARROWS_SETS),
		// The identity member keeps "Mystic air staff" matching.
		Map.entry("air staff", List.of(
			"air staff", "staff of air", "air battlestaff")),
		Map.entry("water staff", List.of(
			"water staff", "staff of water", "water battlestaff")),
		Map.entry("earth staff", List.of(
			"earth staff", "staff of earth", "earth battlestaff")),
		Map.entry("fire staff", List.of(
			"fire staff", "staff of fire", "fire battlestaff")),
		Map.entry("antivenom", List.of("anti-venom")),
		Map.entry("team cape", List.of("team-")),
		Map.entry("quest cape", List.of("quest point cape")),
		Map.entry("skill cape", SKILL_CAPES),
		Map.entry("cape of accomplishment", SKILL_CAPES));

	/** The lowercased query, or every variant of it when it contains a
	 * collective term. Expansion substitutes within the query, so
	 * qualifiers survive: "imbued god cape" becomes "imbued saradomin
	 * cape" and friends. */
	static List<String> expand(String lowerQuery)
	{
		for (Map.Entry<String, List<String>> e : COLLECTIVES.entrySet())
		{
			if (lowerQuery.contains(e.getKey()))
			{
				List<String> out = new ArrayList<>();
				for (String variant : e.getValue())
				{
					out.add(lowerQuery.replace(e.getKey(), variant));
				}
				return out;
			}
		}
		return List.of(lowerQuery);
	}

	/** Every variant term, for the snapshot job's staleness check. */
	static Collection<String> variantTerms()
	{
		List<String> out = new ArrayList<>();
		COLLECTIVES.values().forEach(out::addAll);
		return out;
	}

	private ItemCollectives()
	{
	}
}

