package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Map;
import java.util.TreeMap;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Response;
import okio.BufferedSource;

/** OpenAI-compatible chat-completions client. Endpoint, key, model, and
 * sampling all come from user settings -- nothing is hardcoded. */
@Slf4j
public class Llm
{
	/** User-configured connection + sampling settings, captured per request. */
	public static class Settings
	{
		public final String baseUrl;
		public final String apiKey;
		public final String model;
		public final double temperature;
		public final int maxTokens;

		public Settings(String baseUrl, String apiKey, String model, double temperature, int maxTokens)
		{
			// Tolerate trailing slashes and full /chat/completions URLs.
			String url = baseUrl == null ? "" : baseUrl.trim();
			while (url.endsWith("/"))
			{
				url = url.substring(0, url.length() - 1);
			}
			if (url.endsWith("/chat/completions"))
			{
				url = url.substring(0, url.length() - "/chat/completions".length());
			}
			this.baseUrl = url;
			this.apiKey = apiKey == null ? "" : apiKey.trim();
			this.model = model == null ? "" : model.trim();
			this.temperature = temperature;
			this.maxTokens = maxTokens;
		}

		public boolean isConfigured()
		{
			return !baseUrl.isEmpty() && !model.isEmpty();
		}
	}

	/** Token usage accumulated across every call this client instance makes
	 * (one instance per pipeline question, so totals are per-question). */
	public static class Usage
	{
		public int promptTokens;
		public int completionTokens;
		public int cachedPromptTokens;
		public int calls;
	}

	private final Http http;
	private final Gson gson;
	private final Settings settings;
	private final Usage usage = new Usage();

	Llm(Http http, Gson gson, Settings settings)
	{
		this.http = http;
		this.gson = gson;
		this.settings = settings;
	}

	Usage usage()
	{
		return usage;
	}

	private void recordUsage(JsonObject u)
	{
		if (u == null)
		{
			return;
		}
		usage.calls++;
		if (u.has("prompt_tokens") && !u.get("prompt_tokens").isJsonNull())
		{
			usage.promptTokens += u.get("prompt_tokens").getAsInt();
		}
		if (u.has("completion_tokens") && !u.get("completion_tokens").isJsonNull())
		{
			usage.completionTokens += u.get("completion_tokens").getAsInt();
		}
		// OpenAI-style cache reporting; absent on endpoints without it.
		if (u.has("prompt_tokens_details") && u.get("prompt_tokens_details").isJsonObject())
		{
			JsonObject d = u.getAsJsonObject("prompt_tokens_details");
			if (d.has("cached_tokens") && !d.get("cached_tokens").isJsonNull())
			{
				usage.cachedPromptTokens += d.get("cached_tokens").getAsInt();
			}
		}
	}

	/** One chat-completion call, always streamed (SSE); the returned
	 * message is the reassembled first choice. */
	JsonObject chat(JsonArray messages, JsonArray tools, StreamListener listener) throws IOException
	{
		JsonObject body = new JsonObject();
		body.addProperty("model", settings.model);
		body.add("messages", messages);
		body.addProperty("temperature", settings.temperature);
		body.addProperty("max_tokens", settings.maxTokens);
		if (tools != null && tools.size() > 0)
		{
			body.add("tools", tools);
			body.addProperty("tool_choice", "auto");
		}
		Map<String, String> headers = settings.apiKey.isEmpty()
			? Map.of()
			: Map.of("Authorization", "Bearer " + settings.apiKey);
		String url = settings.baseUrl + "/chat/completions";

		body.addProperty("stream", true);
		JsonObject streamOptions = new JsonObject();
		streamOptions.addProperty("include_usage", true);
		body.add("stream_options", streamOptions);
		try (Response resp = http.postStream(url, body, headers))
		{
			return readSseStream(resp.body().source(), listener);
		}
	}

	/** Reassembles SSE delta chunks into a complete assistant message.
	 * Package-private for tests. */
	JsonObject readSseStream(BufferedSource source, StreamListener listener) throws IOException
	{
		StringBuilder content = new StringBuilder();
		Map<Integer, JsonObject> toolCalls = new TreeMap<>();
		String finishReason = null;

		String line;
		while ((line = source.readUtf8Line()) != null)
		{
			if (!line.startsWith("data:"))
			{
				continue;
			}
			String data = line.substring(5).trim();
			if (data.equals("[DONE]"))
			{
				break;
			}
			JsonObject chunk = gson.fromJson(data, JsonObject.class);
			// A failure after streaming begins can't change the committed
			// 200 status; OpenRouter delivers it as a chunk with a
			// top-level error object and ends the stream.
			if (chunk.has("error") && chunk.get("error").isJsonObject())
			{
				throw midStreamError(chunk.getAsJsonObject("error"));
			}
			if (chunk.has("usage") && chunk.get("usage").isJsonObject())
			{
				recordUsage(chunk.getAsJsonObject("usage"));
			}
			JsonArray choices = chunk.getAsJsonArray("choices");
			if (choices == null || choices.size() == 0)
			{
				continue;
			}
			JsonObject choice = choices.get(0).getAsJsonObject();
			if (choice.has("finish_reason") && !choice.get("finish_reason").isJsonNull())
			{
				finishReason = choice.get("finish_reason").getAsString();
			}
			JsonObject delta = choice.getAsJsonObject("delta");
			if (delta == null)
			{
				continue;
			}
			// reasoning_content deltas are intentionally not surfaced.
			if (delta.has("content") && !delta.get("content").isJsonNull())
			{
				String d = delta.get("content").getAsString();
				if (!d.isEmpty())
				{
					content.append(d);
					listener.onDelta(d);
				}
			}
			if (delta.has("tool_calls") && delta.get("tool_calls").isJsonArray())
			{
				for (JsonElement e : delta.getAsJsonArray("tool_calls"))
				{
					accumulateToolCallDelta(toolCalls, e.getAsJsonObject());
				}
			}
		}

		JsonObject msg = new JsonObject();
		msg.addProperty("role", "assistant");
		msg.addProperty("content", content.toString());
		if (finishReason != null)
		{
			msg.addProperty("finish_reason", finishReason);
		}
		if (!toolCalls.isEmpty())
		{
			JsonArray arr = new JsonArray();
			toolCalls.values().forEach(arr::add);
			msg.add("tool_calls", arr);
		}
		log.debug("llm call: finish={} contentChars={} toolCalls={}",
			finishReason, content.length(), toolCalls.size());
		return msg;
	}

	/** The error's code field is the upstream HTTP status when the
	 * provider failed, but a string like "server_error" for internal
	 * failures; string codes map to 0. */
	private HttpException midStreamError(JsonObject err)
	{
		int code = 0;
		if (err.has("code") && err.get("code").isJsonPrimitive()
			&& err.getAsJsonPrimitive("code").isNumber())
		{
			code = err.get("code").getAsInt();
		}
		String message = err.has("message") && !err.get("message").isJsonNull()
			? err.get("message").getAsString()
			: "";
		return new HttpException(code, settings.baseUrl + "/chat/completions", message);
	}

	/** Tool calls stream as fragments keyed by index; id/name arrive once,
	 * arguments arrive as string pieces to concatenate. */
	private static void accumulateToolCallDelta(Map<Integer, JsonObject> toolCalls, JsonObject tc)
	{
		int idx = tc.has("index") ? tc.get("index").getAsInt() : 0;
		JsonObject acc = toolCalls.computeIfAbsent(idx, k -> {
			JsonObject o = new JsonObject();
			o.addProperty("type", "function");
			JsonObject f = new JsonObject();
			f.addProperty("name", "");
			f.addProperty("arguments", "");
			o.add("function", f);
			return o;
		});
		if (tc.has("id") && !tc.get("id").isJsonNull())
		{
			acc.addProperty("id", tc.get("id").getAsString());
		}
		JsonObject fn = tc.getAsJsonObject("function");
		if (fn != null)
		{
			JsonObject accFn = acc.getAsJsonObject("function");
			if (fn.has("name") && !fn.get("name").isJsonNull())
			{
				accFn.addProperty("name",
					accFn.get("name").getAsString() + fn.get("name").getAsString());
			}
			if (fn.has("arguments") && !fn.get("arguments").isJsonNull())
			{
				accFn.addProperty("arguments",
					accFn.get("arguments").getAsString() + fn.get("arguments").getAsString());
			}
		}
	}
}

package com.osrscopilot.pipeline;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Finds proper nouns in an answer that the supplied context does not
 * contain -- the channel through which other games' content leaks in
 * (RS3's "Anachronia" offered as an OSRS location).
 */
class NameCheck
{
	/** Markdown decoration to drop before scanning for capitalisation. */
	private static final Pattern CODE_SPAN = Pattern.compile("`[^`]*`");
	private static final Pattern MD_LINK = Pattern.compile("\\[([^\\]]*)\\]\\([^)]*\\)");
	private static final Pattern MD_MARKS = Pattern.compile("[*_#>\\\\]");
	/** Table cell walls end a phrase the way a full stop does. */
	private static final Pattern CELL_WALL = Pattern.compile("\\|");

	/** A capitalised token: "Varrock", "Zamorak's", "TzTok-Jad". */
	private static final Pattern CAP_TOKEN = Pattern.compile("[A-Z][A-Za-z'\\-]*");

	/** Lowercase words that continue a name ("Tower of Voices").
	 * Prepositions of place are excluded: "Blast Furnace in Keldagrim" is
	 * two names. */
	private static final Set<String> CONNECTORS = Set.of(
		"of", "the", "and", "de", "der", "van");

	/** Pronouns and articles that start sentences. */
	private static final Set<String> ALWAYS_IGNORE = Set.of(
		"i", "you", "your", "it", "its", "a", "an", "the", "this", "that", "these",
		"those", "they", "we", "he", "she", "there", "here");

	private NameCheck()
	{
	}

	/** Proper nouns with no variant present in the context
	 * (case-insensitive containment). */
	static List<String> ungroundedNames(String answer, String context, Set<String> englishWords)
	{
		String haystack = context == null ? "" : context.toLowerCase(Locale.ROOT);
		List<String> out = new ArrayList<>(new LinkedHashSet<>(names(answer, englishWords)));
		out.removeIf(name -> variants(name, englishWords).stream()
			.anyMatch(v -> haystack.contains(v.toLowerCase(Locale.ROOT))));
		return out;
	}

	/** Forms of a name worth trying, most specific first: trimmed sentence
	 * openers ("Requires The Giant Dwarf") and singulars ("Skeletal
	 * Wyverns" often has no page of its own). */
	static List<String> variants(String name, Set<String> englishWords)
	{
		Set<String> out = new LinkedHashSet<>();
		String candidate = name;
		while (true)
		{
			out.add(candidate);
			if (candidate.length() > 3 && candidate.endsWith("s"))
			{
				out.add(candidate.substring(0, candidate.length() - 1));
			}
			int space = candidate.indexOf(' ');
			if (space < 0 || !isGeneric(candidate.substring(0, space), englishWords))
			{
				break;
			}
			candidate = candidate.substring(space + 1);
		}
		return new ArrayList<>(out);
	}

	/** Every proper-noun phrase in the text, before any grounding check. */
	static List<String> names(String text, Set<String> englishWords)
	{
		String clean = CELL_WALL.matcher(MD_MARKS.matcher(
			MD_LINK.matcher(CODE_SPAN.matcher(text).replaceAll(" "))
				.replaceAll("$1")).replaceAll(" ")).replaceAll("\n");
		// Sentence boundaries end a name: a following capital starts a new one.
		List<String> found = new ArrayList<>();
		for (String sentence : clean.split("(?<=[.!?:;\\n])"))
		{
			collectFromSentence(sentence, found, englishWords);
		}
		return found;
	}

	private static void collectFromSentence(String sentence, List<String> found,
		Set<String> englishWords)
	{
		String[] words = sentence.trim().split("\\s+");
		int i = 0;
		while (i < words.length)
		{
			String word = strip(words[i]);
			if (!isCapitalised(word))
			{
				i++;
				continue;
			}

		// Phrases are built maximally ("Mining Guild" keeps its head);
		// any separator ends the phrase ("Edgeville, Falador" is two).
			StringBuilder phrase = new StringBuilder(word);
			int j = i + 1;
			while (j < words.length && !endsPhrase(words[j - 1]))
			{
				String next = strip(words[j]);
				if (isCapitalised(next))
				{
					phrase.append(' ').append(next);
					j++;
				}
				else if (CONNECTORS.contains(next.toLowerCase(Locale.ROOT))
					&& !endsPhrase(words[j]) && j + 1 < words.length
					&& isCapitalised(strip(words[j + 1])))
				{
					phrase.append(' ').append(next).append(' ').append(strip(words[j + 1]));
					j += 2;
				}
				else
				{
					break;
				}
			}

			// A lone capitalised English word asserts nothing worth checking.
			String candidate = phrase.toString();
			if (candidate.indexOf(' ') >= 0 || !isGeneric(candidate, englishWords))
			{
				found.add(candidate);
			}
			i = j;
		}
	}

	/** Whether a name is game vocabulary rather than title-case English
	 * ("Gear Setup" makes no claim; "Anachronia" does). A fabricated name
	 * built purely from dictionary words is missed. */
	static boolean looksGameSpecific(String name, Set<String> englishWords)
	{
		for (String word : name.split("[\\s\\-]+"))
		{
			if (word.isEmpty() || CONNECTORS.contains(word.toLowerCase(Locale.ROOT)))
			{
				continue;
			}
			if (isGeneric(word, englishWords))
			{
				return false;
			}
		}
		return true;
	}

	/** Whether a name and the page it resolved to are the same thing:
	 * plural/casing/qualifier differences are ("Aviansies" -> "Aviansie");
	 * an unrelated title is not ("Anachronia" -> "Fossil Island"). */
	static boolean namesSameThing(String name, String resolvedTitle)
	{
		String a = fold(name);
		String b = fold(resolvedTitle);
		return a.contains(b) || b.contains(a) || a.equals(initials(resolvedTitle));
	}

	/** Initials of a title's significant words, so player abbreviations count
	 * as the thing they abbreviate ("KBD" -> "King Black Dragon"). */
	private static String initials(String title)
	{
		StringBuilder sb = new StringBuilder();
		for (String word : title.split("[\\s\\-]+"))
		{
			if (!word.isEmpty() && !CONNECTORS.contains(word.toLowerCase(Locale.ROOT)))
			{
				sb.append(Character.toLowerCase(word.charAt(0)));
			}
		}
		return fold(sb.toString());
	}

	/** A word ordinary English uses, so capitalisation alone doesn't make it
	 * a name. */
	private static boolean isGeneric(String word, Set<String> englishWords)
	{
		if (isGenericExact(fold(word), englishWords))
		{
			return true;
		}
		// Possessives keep their apostrophe, as page titles do
		// ("Gertrude's Cat"); only the check strips it.
		int tick = word.indexOf('\'');
		return tick > 0 && isGenericExact(fold(word.substring(0, tick)), englishWords);
	}

	private static boolean isGenericExact(String folded, Set<String> englishWords)
	{
		return ALWAYS_IGNORE.contains(folded)
			|| (englishWords != null && englishWords.contains(folded));
	}

	/** Lowercase, drop non-alphanumerics and any plural ending. */
	private static String fold(String s)
	{
		String folded = s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
		return folded.endsWith("s") ? folded.substring(0, folded.length() - 1) : folded;
	}

	/** Whether the raw token carries trailing punctuation that separates it
	 * from whatever follows. */
	private static boolean endsPhrase(String rawWord)
	{
		for (int i = rawWord.length() - 1; i >= 0; i--)
		{
			char c = rawWord.charAt(i);
			if (Character.isLetterOrDigit(c) || c == '\'')
			{
				return false;
			}
			if (",;:)]}\"/&".indexOf(c) >= 0)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isCapitalised(String word)
	{
		if (word.length() < 2)
		{
			return false;
		}
		Matcher m = CAP_TOKEN.matcher(word);
		return m.matches();
	}

	/** Trims surrounding punctuation while keeping internal apostrophes. */
	private static String strip(String word)
	{
		int start = 0;
		int end = word.length();
		while (start < end && !Character.isLetterOrDigit(word.charAt(start)))
		{
			start++;
		}
		while (end > start && !Character.isLetterOrDigit(word.charAt(end - 1))
			&& word.charAt(end - 1) != '\'')
		{
			end--;
		}
		return word.substring(start, end);
	}
}

package com.osrscopilot.pipeline;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The player's ownership index: bank + inventory + equipment flattened into
 * case-folded name -> per-location quantities. Pure functions of a
 * GameCapture, shared by the prefetcher, the tool registry, and the answer
 * decorator so prompted and displayed ownership can't drift apart.
 */
public final class Ownership
{
	/** Slots of the per-name quantity array. */
	static final int CARRIED = 0;
	static final int EQUIPPED = 1;
	static final int BANKED = 2;
	private static final String[] SLOT_NAMES = {"carried", "equipped", "banked"};

	private static final Pattern TRAILING_QUALIFIER = Pattern.compile("\\s*\\([^)]*\\)$");

	private Ownership()
	{
	}

	/** Display name with any trailing "(4)"/"(i)" qualifier removed;
	 * qualifiers never appear in prose. */
	public static String baseName(String name)
	{
		return TRAILING_QUALIFIER.matcher(name).replaceAll("").trim();
	}

	/** name -> {carried, equipped, banked} quantities. */
	static Map<String, long[]> buildIndex(GameCapture cap)
	{
		Map<String, long[]> owned = new LinkedHashMap<>();
		eachOwnedItem(cap, (name, item, slot) -> {
			long qty = item.get("quantity") instanceof Number
				? ((Number) item.get("quantity")).longValue() : 1;
			owned.computeIfAbsent(name.toLowerCase(Locale.ROOT),
				k -> new long[3])[slot] += qty;
		});
		return owned;
	}

	static Map<String, String> buildNames(GameCapture cap)
	{
		Map<String, String> names = new LinkedHashMap<>();
		eachOwnedItem(cap, (name, item, slot) ->
			names.putIfAbsent(name.toLowerCase(Locale.ROOT), name));
		return names;
	}

	static long total(long[] counts)
	{
		return counts[CARRIED] + counts[EQUIPPED] + counts[BANKED];
	}

	/** The location phrase for a count array: "banked" when everything is
	 * in one place (the caller already carries the quantity), counted
	 * parts like "3 carried, 5 banked" when the copies are split. */
	static String whereLabel(long[] counts)
	{
		int locations = 0;
		for (long c : counts)
		{
			if (c > 0)
			{
				locations++;
			}
		}
		StringBuilder sb = new StringBuilder();
		for (int slot = 0; slot < counts.length; slot++)
		{
			if (counts[slot] == 0)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			if (locations > 1)
			{
				sb.append(counts[slot]).append(' ');
			}
			sb.append(SLOT_NAMES[slot]);
		}
		return sb.toString();
	}

	private interface OwnedItemVisitor
	{
		void accept(String name, Map<String, Object> item, int slot);
	}

	/** The one walk over everything the player holds; absent containers
	 * are skipped. Iteration order (bank first) fixes which container
	 * names the display variant in buildNames. */
	private static void eachOwnedItem(GameCapture cap, OwnedItemVisitor fn)
	{
		int[] slots = {BANKED, CARRIED, EQUIPPED};
		List<List<Map<String, Object>>> containers =
			Arrays.asList(cap.bank, cap.inventory, cap.equipment);
		for (int i = 0; i < containers.size(); i++)
		{
			List<Map<String, Object>> container = containers.get(i);
			if (container == null)
			{
				continue;
			}
			for (Map<String, Object> item : container)
			{
				fn.accept(String.valueOf(item.get("name")), item, slots[i]);
			}
		}
	}

	static Object check(Map<String, long[]> owned, Map<String, String> names, String itemName)
	{
		String key = itemName.toLowerCase(Locale.ROOT);
		if (owned.containsKey(key))
		{
			return Map.of("item", names.get(key), "owned", total(owned.get(key)));
		}
		List<Map<String, Object>> partial = new ArrayList<>();
		for (Map.Entry<String, long[]> e : owned.entrySet())
		{
			if ((e.getKey().contains(key) || key.contains(e.getKey())) && partial.size() < 5)
			{
				Map<String, Object> hit = new LinkedHashMap<>();
				hit.put("item", names.get(e.getKey()));
				hit.put("owned", total(e.getValue()));
				partial.add(hit);
			}
		}
		if (!partial.isEmpty())
		{
			Map<String, Object> out = new LinkedHashMap<>();
			out.put("item", itemName);
			out.put("exact_match", false);
			out.put("similar_owned", partial);
			return out;
		}
		return Map.of("item", itemName, "owned", 0);
	}

	/** Both ownership lists for every catalogued item a text mentions:
	 * OWNED with quantities, NOT OWNED by name (the system prompt forbids
	 * inferring from absence). */
	static final class Slice
	{
		final String text;
		/** True when nothing was cut for length. */
		final boolean complete;

		private Slice(String text, boolean complete)
		{
			this.text = text;
			this.complete = complete;
		}
	}

	/** Cap on the owned list; past this the block is noise. */
	private static final int OWNED_LIMIT = 120;
	/** Cap on the not-owned enumeration, sized above the ~150 items a
	 * three-style equipment page mentions: a truncated list forfeits the
	 * completeness claim. */
	private static final int LACKED_LIMIT = 200;

	/**
	 * @param haystackLower lowercased text to scan for item mentions
	 * @return the rendered lists, or null when the text mentions nothing
	 *         catalogued or owned
	 */
	static Slice slice(String haystackLower, Map<String, long[]> owned,
		Map<String, String> names, List<ItemDescriptor> vocabulary)
	{
		Map<String, long[]> ownedMentioned = new LinkedHashMap<>();
		List<String> ownedBases = new ArrayList<>();
		for (Map.Entry<String, long[]> e : owned.entrySet())
		{
			String base = baseName(e.getKey());
			ownedBases.add(base);
			if (base.length() < 3 || !mentionsItem(haystackLower, base))
			{
				continue;
			}
			String display = baseName(names.get(e.getKey()));
			long[] sum = ownedMentioned.computeIfAbsent(display, k -> new long[3]);
			for (int slot = 0; slot < sum.length; slot++)
			{
				sum[slot] += e.getValue()[slot];
			}
		}

		Set<String> lacked = lackedMentioned(haystackLower, ownedBases, vocabulary);
		if (ownedMentioned.isEmpty() && lacked.isEmpty())
		{
			return null;
		}

		StringBuilder sb = new StringBuilder("OWNED: ");
		int n = 0;
		boolean truncated = false;
		for (Map.Entry<String, long[]> e : ownedMentioned.entrySet())
		{
			if (n >= OWNED_LIMIT)
			{
				sb.append(", ...");
				truncated = true;
				break;
			}
			sb.append(n++ > 0 ? ", " : "").append(e.getKey());
			long qty = total(e.getValue());
			if (qty > 1)
			{
				sb.append(" x").append(qty);
			}
			sb.append(" (").append(whereLabel(e.getValue())).append(')');
		}
		if (n == 0)
		{
			sb.append("none of them");
		}
		sb.append("\nNOT OWNED (verified absent at capture): ");
		n = 0;
		for (String name : lacked)
		{
			if (n >= LACKED_LIMIT)
			{
				sb.append(", ...");
				truncated = true;
				break;
			}
			sb.append(n++ > 0 ? ", " : "").append(name);
		}
		if (n == 0)
		{
			sb.append("nothing relevant");
		}
		return new Slice(sb.toString(), !truncated);
	}

	/**
	 * Every catalogued item the text mentions that the player does NOT
	 * own, by name. Owned variants count as owned: a text saying "Slayer
	 * helmet (i)" is covered by the player's "Black slayer helmet (i)".
	 */
	private static Set<String> lackedMentioned(String haystackLower,
		List<String> ownedBases, List<ItemDescriptor> vocabulary)
	{
		Set<String> lacked = new LinkedHashSet<>();
		Set<String> seen = new HashSet<>();
		for (ItemDescriptor it : vocabulary)
		{
			String base = baseName(it.name);
			String lower = base.toLowerCase(Locale.ROOT);
			if (lower.length() < 4 || !seen.add(lower)
				|| !mentionsWord(haystackLower, lower))
			{
				continue;
			}
			boolean ownedVariant = false;
			for (String ownedBase : ownedBases)
			{
				if (covers(ownedBase, lower))
				{
					ownedVariant = true;
					break;
				}
			}
			if (!ownedVariant)
			{
				lacked.add(base);
			}
		}
		return lacked;
	}

	/** True when the text mentions the item's name directly or under a
	 * shorter form: pages name canonical gear ("Slayer helmet (i)") while
	 * the player's copy may be decorated ("Black slayer helmet (i)").
	 * Only multi-word remainders count; "helmet" alone is prose. */
	private static boolean mentionsItem(String haystackLower, String base)
	{
		String candidate = base;
		while (true)
		{
			if (mentionsWord(haystackLower, candidate))
			{
				return true;
			}
			int space = candidate.indexOf(' ');
			if (space < 0 || candidate.indexOf(' ', space + 1) < 0)
			{
				return false;
			}
			candidate = candidate.substring(space + 1);
		}
	}

	/** True when an owned item's base name covers a canonical base name:
	 * equal, or the canonical appears whole-word inside the owned name.
	 * Pages and answers name canonical gear ("Slayer helmet") while the
	 * player's copy may be decorated ("Black slayer helmet"). Both
	 * arguments lowercased. */
	public static boolean covers(String ownedBase, String canonicalBase)
	{
		return ownedBase.equals(canonicalBase) || mentionsWord(ownedBase, canonicalBase);
	}

	/** Case-folded whole-word containment. */
	public static boolean mentionsWord(String haystack, String needle)
	{
		int from = 0;
		int i;
		while ((i = haystack.indexOf(needle, from)) >= 0)
		{
			if (wordMatchEnd(haystack, i, needle.length()) >= 0)
			{
				return true;
			}
			from = i + 1;
		}
		return false;
	}

	/** End index of a whole-word match at [start, start+length), extended
	 * over a plural "s"; -1 when the span is not word-bounded. Plain
	 * substring containment would let "bow" claim "blowpipe". */
	public static int wordMatchEnd(String s, int start, int length)
	{
		int end = start + length;
		if (end < s.length() && s.charAt(end) == 's')
		{
			end++;
		}
		boolean startOk = start == 0 || !Character.isLetterOrDigit(s.charAt(start - 1));
		boolean endOk = end >= s.length() || !Character.isLetterOrDigit(s.charAt(end));
		return startOk && endOk ? end : -1;
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Deterministic prefetch: every resolved entity gets a core fact bundle;
 * needs add extras (drop tables, prices, strategy pages).
 */
@Slf4j
class Prefetcher
{
	/** Char budget per secondary page fact; truncation happens once, at
	 * the content source. */
	private static final int FACT_PAGE_BUDGET = 4500;
	/** Facility listing tables need room for the player's region to make
	 * the excerpt. */
	private static final int FACILITY_CHAR_LIMIT = 9000;
	/** Fits one gear table per combat style; a three-style tabber runs
	 * ~11k chars. */
	private static final int EQUIPMENT_CHAR_LIMIT = 12000;

	/** Travel-section headings on location and boss pages. */
	private static final Pattern TRANSPORT_HEADING =
		Pattern.compile("(?i)transport|getting there|travel|access");

	private static final Pattern LOCATIONS_HEADING =
		Pattern.compile("(?i)^locations?$|list of|where to find");

	/** First page link of a location table row's destination, e.g.
	 * "|location = [[Asgarnian Ice Dungeon]] ({{Fairycode|AIQ}})". */
	private static final Pattern LOCATION_ROW_DEST =
		Pattern.compile("(?m)^\\|\\s*location\\s*=\\s*\\[\\[([^\\]|]+)");

	/** Strategy pages keep recommended gear in an equipment/setup section. */
	private static final Pattern EQUIPMENT_HEADING =
		Pattern.compile("(?i)\\b(equipment|gear|setups?|loadout)\\b");

	/** Reading rule for gear sections: pages carry both per-slot tier
	 * tables and worked-example setups, and models otherwise follow the
	 * concrete example over the player's best owned tier. */
	private static final String EQUIPMENT_NOTE =
		"[Where gear is tiered, recommend each slot's highest tier the player "
		+ "owns; example setups are illustrations, not the player's best option.]";

	private final WikiApi wiki;
	private final Gson gson;

	Prefetcher(WikiApi wiki, Gson gson)
	{
		this.wiki = wiki;
		this.gson = gson;
	}

	List<String> prefetch(CopilotPipeline.Route route, GameCapture cap,
		Map<String, long[]> owned, Map<String, String> ownedNames, boolean bankInlined)
	{
		EntityResolver.Resolution ents = route.entities;
		List<String> facts = new ArrayList<>();
		Set<String> needs = new TreeSet<>(route.needs);

		monsterFacts(facts, needs, ents.monsters);
		itemFacts(facts, needs, ents.items, owned, ownedNames, bankInlined);
		questFacts(facts, ents.quests);
		pageFacts(facts, needs, route);
		skillFacts(facts, needs, ents, cap);
		houseFact(facts, needs, cap);
		return facts;
	}

	/** The player's POH facilities, so travel and prep answers can weigh
	 * a house teleport. Captured on house visits; absent until one. */
	private void houseFact(List<String> facts, Set<String> needs, GameCapture cap)
	{
		if (cap.house != null && !cap.house.isEmpty()
			&& (needs.contains(Router.NEED_TRANSPORT) || needs.contains(Router.NEED_STRATEGY)))
		{
			addFact(facts, "User's player owned house (POH) facilities",
				String.join("; ", cap.house));
		}
	}

	/** Core bundle: monster info always; extras per needs. */
	private void monsterFacts(List<String> facts, Set<String> needs, List<String> monsters)
	{
		for (String monster : limit(monsters, 3))
		{
			boolean strategyNeeded = needs.contains(Router.NEED_STRATEGY)
				|| needs.contains(Router.NEED_MECHANICS);
			boolean taskNeeded = needs.contains(Router.NEED_SLAYER_TASK);
			String taskGuide = slayerTaskPage(monster);
			Map<String, Object> info = wiki.monsterInfo(monster);
			// Advertise an unfetched guide subpage so the model can
			// wiki_page it.
			if (!strategyNeeded && info != null && !info.containsKey("error")
				&& Boolean.TRUE.equals(hasStrategiesPage(monster)))
			{
				info.put("strategy_guide_page", monster + "/Strategies");
			}
			if (!taskNeeded && taskGuide != null && info != null && !info.containsKey("error"))
			{
				info.put("slayer_task_guide_page", taskGuide);
			}
			addFact(facts, "Monster info: " + monster, info);
			if (taskNeeded && taskGuide != null)
			{
				// The label carries the page's category tail ("Greater
				// demons") so sourcePage can rebuild the fetched title.
				addFact(facts, "Slayer task guide: "
					+ taskGuide.substring("Slayer task/".length()), wiki.page(taskGuide));
			}
			if (needs.contains(Router.NEED_DROP_TABLE) || needs.contains(Router.NEED_PRICES))
			{
				addFact(facts, "Drop table: " + monster, wiki.monsterDrops(monster));
			}
			if (strategyNeeded)
			{
				String strategyPage = monster + "/Strategies";
				// The index skips guaranteed-404 strategy fetches; when it
				// is unavailable (null), fall back to the blind fetch.
				String text = Boolean.FALSE.equals(hasStrategiesPage(monster))
					? null : wiki.page(strategyPage);
				String label = "Strategy: " + monster;
				if (text == null)
				{
					strategyPage = monster;
					text = wiki.page(monster, FACT_PAGE_BUDGET);
					label = "Page: " + monster;
				}
				addFact(facts, label, text);
				addFact(facts, "Recommended equipment: " + monster,
					equipmentSection(strategyPage));
			}
			if (needs.contains(Router.NEED_TRANSPORT))
			{
				addTravelFact(facts, monster);
			}
		}
	}

	/** Core bundle: item page always (recipes/requirements live there).
	 * Ownership fact only when the bank couldn't be inlined into the state. */
	private void itemFacts(List<String> facts, Set<String> needs, List<String> items,
		Map<String, long[]> owned, Map<String, String> ownedNames, boolean bankInlined)
	{
		for (String item : limit(items, 4))
		{
			addFact(facts, "Item page: " + item, wiki.page(item, FACT_PAGE_BUDGET));
			// Combat bonuses live in the infobox, which no text fetch ever
			// carries. Non-equipment returns a not-found that addFact skips.
			addFact(facts, "Equipment stats: " + item, wiki.itemStats(item));
			if (!bankInlined)
			{
				// An exact hit puts the location in the heading ("Ownership:
				// Ring of wealth (banked)"); the payload stays quantity-only.
				long[] counts = owned.get(item.toLowerCase(Locale.ROOT));
				String where = counts != null && Ownership.total(counts) > 0
					? " (" + Ownership.whereLabel(counts) + ")" : "";
				addFact(facts, "Ownership: " + item + where,
					Ownership.check(owned, ownedNames, item));
			}
			if (needs.contains(Router.NEED_ITEM_SOURCES) || needs.contains(Router.NEED_DROP_TABLE))
			{
				addFact(facts, "How to obtain: " + item, wiki.itemSources(item));
			}
			if (needs.contains(Router.NEED_PRICES))
			{
				addFact(facts, "GE price: " + item, wiki.gePrice(item));
			}
		}
	}

	/** Core bundle: quest page always. */
	private void questFacts(List<String> facts, List<String> quests)
	{
		for (String quest : limit(quests, 2))
		{
			addFact(facts, "Quest page: " + quest, wiki.page(quest, FACT_PAGE_BUDGET));
			// Requirements live in the {{Quest details}} template, which no
			// text fetch carries.
			addFact(facts, "Quest requirements: " + quest, wiki.questInfo(quest));
		}
	}

	/** Other resolved pages (locations, guides, diaries...). Three:
	 * comparison questions name up to three subjects. */
	private void pageFacts(List<String> facts, Set<String> needs, CopilotPipeline.Route route)
	{
		for (String page : limit(route.entities.pages, 3))
		{
			// When a facility rule claims the same page, its targeted
			// Locations fetch wins over the generic article.
			if (route.facilityPages.stream().anyMatch(p -> p.equalsIgnoreCase(page)))
			{
				continue;
			}
			// A named diary tier replaces the whole-page fetch.
			if (route.diaryTier != null && Router.isDiaryPage(page))
			{
				String tierHeading = "^" + route.diaryTier + "$";
				String section = wiki.sectionByHeading(page,
					Pattern.compile(tierHeading, Pattern.CASE_INSENSITIVE), FACILITY_CHAR_LIMIT);
				if (section != null)
				{
					addFact(facts, "Diary tasks (" + route.diaryTier + "): " + page, section);
					continue;
				}
			}
			// Raids and minigames resolve as pages but can have /Strategies
			// guides. Pages are never blind-fetched: positive index hit only.
			boolean guideExists = Boolean.TRUE.equals(hasStrategiesPage(page));
			boolean pageStrategy = (needs.contains(Router.NEED_STRATEGY)
				|| needs.contains(Router.NEED_MECHANICS)) && guideExists;
			String pageText = wiki.page(page);
			if (pageText != null && !pageStrategy && guideExists)
			{
				// Advertise the guide so the model can wiki_page it.
				pageText = "[Strategy guide page: " + page + "/Strategies]\n" + pageText;
			}
			addFact(facts, "Page: " + page, pageText);
			if (pageStrategy)
			{
				String strategyPage = page + "/Strategies";
				addFact(facts, "Strategy: " + page, wiki.page(strategyPage));
				addFact(facts, "Recommended equipment: " + page,
					equipmentSection(strategyPage));
			}
			// Untradeable equipment (Arclight, Emberlight, barrows gloves...)
			// resolves as a page, not an item -- it still has an infobox.
			addFact(facts, "Equipment stats: " + page, wiki.itemStats(page));
			if (needs.contains(Router.NEED_TRANSPORT))
			{
				addTravelFact(facts, page);
			}
		}
	}

	/** The skill's own page, only when skills are the question's whole
	 * subject (levels already sit in PLAYER STATE). Training guides and
	 * XP math ride along per needs. */
	private void skillFacts(List<String> facts, Set<String> needs,
		EntityResolver.Resolution ents, GameCapture cap)
	{
		if (!ents.skills.isEmpty() && ents.items.isEmpty() && ents.monsters.isEmpty()
			&& ents.quests.isEmpty() && ents.pages.isEmpty())
		{
			for (String skill : limit(ents.skills, 2))
			{
				addFact(facts, "Skill: " + skill, wiki.page(skill, FACT_PAGE_BUDGET));
			}
		}

		// The label carries the page title: the footer links it for
		// attribution and the model sees which audience the guide targets.
		if (needs.contains(Router.NEED_TRAINING))
		{
			for (String skill : limit(ents.skills, 2))
			{
				String guide = trainingGuide(skill, cap.accountTypeName());
				addFact(facts, "Training guide: " + guide, wiki.page(guide));
			}
		}

		if (needs.contains(Router.NEED_XP_MATH) && cap.skillXp != null)
		{
			for (String skill : limit(ents.skills, 2))
			{
				Integer xp = cap.skillXp.get(skill);
				if (xp != null)
				{
					int[] next = XpTable.toNextLevel(xp);
					Map<String, Object> math = new LinkedHashMap<>();
					math.put("current_xp", xp);
					math.put("current_level", next[0]);
					math.put("next_level", next[1]);
					math.put("xp_needed_for_next_level", next[2]);
					addFact(facts, "XP math: " + skill, math);
				}
			}
		}
	}

	/** The training guide page for the player's account type. "<Skill>
	 * training" is a wiki convention (page or redirect for every skill);
	 * the ironman guide families have a chapter per skill, with Attack
	 * and Strength consolidated under Melee. */
	static String trainingGuide(String skill, String accountType)
	{
		if ("NORMAL".equals(accountType))
		{
			return skill + " training";
		}
		String chapter = "Attack".equals(skill) || "Strength".equals(skill) ? "Melee" : skill;
		return ("ULTIMATE_IRONMAN".equals(accountType)
			? "Ultimate Ironman Guide/" : "Ironman Guide/") + chapter;
	}

	/** Whether {monster}/Strategies exists per the snapshot index; null
	 * when the index is unavailable. Callers must treat null as unknown,
	 * never as absent. */
	private Boolean hasStrategiesPage(String monster)
	{
		try
		{
			return wiki.strategiesPages().contains(monster + "/Strategies");
		}
		catch (Exception e)
		{
			log.debug("strategies index unavailable; keeping blind-fetch behavior", e);
			return null;
		}
	}

	/** The "Slayer task/..." guide page for a creature, or null when none
	 * exists or the index is unavailable. Task pages are named by plural
	 * category ("Slayer task/Greater demons"); a plural probe bridges the
	 * gap from singular monster names. */
	private String slayerTaskPage(String monster)
	{
		try
		{
			return matchTaskPage(monster, wiki.slayerTaskPages());
		}
		catch (Exception e)
		{
			log.debug("slayer task index unavailable; skipping task guide", e);
			return null;
		}
	}

	static String matchTaskPage(String monster, Set<String> index)
	{
		String n = EntityResolver.norm(monster);
		for (String title : index)
		{
			String tail = EntityResolver.norm(title.substring("Slayer task/".length()));
			if (tail.equals(n) || tail.equals(n + "s") || tail.equals(n + "es")
				|| (n.endsWith("s") && tail.equals(n.substring(0, n.length() - 1))))
			{
				return title;
			}
		}
		return null;
	}

	/** Gear-section wikitext with the tier-preference note prepended, or
	 * null when the page has no such section. Fetched as wikitext because
	 * plaintext extracts strip equipment tables without tripping the husk
	 * detector. */
	private String equipmentSection(String strategyPage)
	{
		String section = wiki.sectionByHeading(
			strategyPage, EQUIPMENT_HEADING, EQUIPMENT_CHAR_LIMIT);
		return section == null ? null : EQUIPMENT_NOTE + "\n" + section;
	}

	/** Bosses, dungeons, and cities carry a dedicated travel section;
	 * ordinary monster pages only have a Locations heading. Try the
	 * travel section first, then fall back. */
	private void addTravelFact(List<String> facts, String page)
	{
		String section = wiki.sectionByHeading(page, TRANSPORT_HEADING, FACT_PAGE_BUDGET);
		if (section != null)
		{
			addFact(facts, "Getting there: " + page, section);
			return;
		}
		String locations = wiki.sectionByHeading(page, LOCATIONS_HEADING, FACT_PAGE_BUDGET);
		addFact(facts, "Locations: " + page, locations);
		// With exactly one destination, fetch its travel section too; with
		// several, the model picks from the table and wiki_pages its choice.
		String destination = soleDestination(locations);
		if (destination != null && !destination.equalsIgnoreCase(page))
		{
			addFact(facts, "Getting there: " + destination,
				wiki.sectionByHeading(destination, TRANSPORT_HEADING, FACT_PAGE_BUDGET));
		}
	}

	/** The single destination a locations table points at, or null when it
	 * has none or several. */
	static String soleDestination(String locationsWikitext)
	{
		if (locationsWikitext == null)
		{
			return null;
		}
		Set<String> destinations = new LinkedHashSet<>();
		Matcher m = LOCATION_ROW_DEST.matcher(locationsWikitext);
		while (m.find())
		{
			destinations.add(m.group(1).trim());
		}
		return destinations.size() == 1 ? destinations.iterator().next() : null;
	}

	/** Grounds facilities the facts lean on but the question never names:
	 * "quickest way to get planks" retrieves the Plank page, which says
	 * "sawmill" throughout but never where one is. */
	void addFacilitiesFromFacts(String question, CopilotPipeline.Route route, List<String> facts)
	{
		// Skip when a facility rule already matched: its table is in the
		// facts, and facility tables mention every other amenity.
		if (!route.facilityPages.isEmpty())
		{
			return;
		}
		String ql = question.toLowerCase(Locale.ROOT);
		if (!route.needs.contains(Router.NEED_ITEM_SOURCES) && !Router.LOCATIONAL.matcher(ql).find())
		{
			return;
		}
		String hay = String.join("\n", facts).toLowerCase(Locale.ROOT);
		List<String> pages = new ArrayList<>();
		for (Object[] rule : Router.FACILITY_RULES)
		{
			String page = (String) rule[1];
			// Banks are mentioned incidentally on half the wiki; only a
			// question naming banks fetches that page.
			if ("Bank".equals(page) || pages.size() >= 2)
			{
				continue;
			}
			Matcher m = ((Pattern) rule[0]).matcher(hay);
			int hits = 0;
			while (hits < 3 && m.find())
			{
				hits++;
			}
			if (hits >= 3)
			{
				pages.add(page);
			}
		}
		List<String> alreadyFetched = new ArrayList<>(route.entities.pages);
		alreadyFetched.addAll(route.facilityPages);
		prefetchFacilities(pages, alreadyFetched, facts);
	}

	/** For facility questions, attach the wiki's canonical listing page
	 * (its Locations section when present, else the page wikitext). */
	void prefetchFacilities(List<String> facilityPages, List<String> alreadyFetched,
		List<String> facts)
	{
		for (String page : facilityPages)
		{
			// The resolver often resolved the same page; don't fetch twice.
			if (alreadyFetched.stream().anyMatch(p -> p.equalsIgnoreCase(page)))
			{
				continue;
			}
			String text = wiki.sectionByHeading(page, LOCATIONS_HEADING, FACILITY_CHAR_LIMIT);
			if (text == null)
			{
				text = wiki.wikitext(page, FACILITY_CHAR_LIMIT);
			}
			addFact(facts, "Facility locations: " + page, text);
		}
	}

	/** Ownership slice for a summarized bank: for every item the facts
	 * mention, state positively whether the player owns or lacks it (the
	 * system prompt forbids inferring from absence). Matches names
	 * against fact text, so a wiki reformat can't break it. */
	boolean addOwnershipFromFacts(List<String> facts, Map<String, long[]> owned,
		Map<String, String> names) throws IOException
	{
		Ownership.Slice slice = Ownership.slice(
			String.join("\n", facts).toLowerCase(Locale.ROOT),
			owned, names, wiki.itemCatalog());
		if (slice == null)
		{
			return false;
		}
		addFact(facts, slice.complete
			? "Ownership of every item these facts mention"
			: "Ownership (lists cut for length; for items in neither list, decide "
				+ "what actually matters to the answer and verify just those in ONE "
				+ "batched search_owned_items call)",
			slice.text);
		return slice.complete;
	}

	/** The player's progress for every quest the question or facts
	 * mention. */
	static Map<String, String> relevantQuestStates(String question, List<String> facts,
		EntityResolver.Resolution ents, Map<String, String> questStates)
	{
		if (questStates == null || questStates.isEmpty())
		{
			return null;
		}
		String hay = (question + " " + String.join(" ", facts)).toLowerCase(Locale.ROOT);
		Map<String, String> rel = new LinkedHashMap<>();
		for (String q : ents.quests)
		{
			if (questStates.containsKey(q))
			{
				rel.put(q, questStates.get(q));
			}
		}
		for (Map.Entry<String, String> e : questStates.entrySet())
		{
			if (rel.size() >= 15)
			{
				break;
			}
			if (!rel.containsKey(e.getKey()) && e.getKey().length() >= 6
				&& hay.contains(e.getKey().toLowerCase(Locale.ROOT)))
			{
				rel.put(e.getKey(), e.getValue());
			}
		}
		return rel.isEmpty() ? null : rel;
	}

	/** The wiki page a fact was retrieved from (null for game-state
	 * facts); the answer footer links it for CC BY-NC-SA attribution.
	 * Unknown labels return null: unlinked beats mislinked. */
	static String sourcePage(String factTitle)
	{
		int sep = factTitle.indexOf(": ");
		if (sep < 0)
		{
			return null;
		}
		String label = factTitle.substring(0, sep);
		String name = factTitle.substring(sep + 2);
		if (label.startsWith("Diary tasks"))
		{
			return name;
		}
		switch (label)
		{
			case "Monster info":
			case "Drop table":
			case "Page":
			case "Item page":
			case "Equipment stats":
			case "How to obtain":
			case "Quest page":
			case "Quest requirements":
			case "Skill":
			case "Getting there":
			case "Locations":
			case "Facility locations":
			// Fetched from /Strategies when it exists, else the main page;
			// both are already their own fact, so the page stays linked.
			case "Recommended equipment":
			// The label already names the guide page.
			case "Training guide":
				return name;
			case "Strategy":
				return name + "/Strategies";
			case "Slayer task guide":
				return "Slayer task/" + name;
			default:
				return null;
		}
	}

	/** Strips the model-facing usage instructions that game-state fact
	 * titles carry before display in the footer. */
	static String displayTitle(String factTitle)
	{
		if (factTitle.startsWith("Quest progress"))
		{
			return "Quest progress";
		}
		if (factTitle.startsWith("Ownership") && !factTitle.startsWith("Ownership: "))
		{
			return "Ownership";
		}
		return factTitle;
	}

	/** Skips failed lookups: content methods return null, structured
	 * lookups return error maps; neither is a fact. */
	private void addFact(List<String> facts, String label, Object payload)
	{
		if (payload == null || (payload instanceof Map && ((Map<?, ?>) payload).containsKey("error")))
		{
			log.debug("prefetch: {} -> nothing found, skipped", label);
			return;
		}
		String text = payload instanceof String ? (String) payload : gson.toJson(payload);
		facts.add("### " + label + "\n" + text);
		log.debug("prefetch: {} ({}B)", label, text.length());
	}

	private static <T> List<T> limit(List<T> list, int n)
	{
		return list.subList(0, Math.min(n, list.size()));
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.osrscopilot.area.Areas;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Assembles everything the model reads: the system prompt, the user message
 * (player state + retrieved facts), and the bounded conversation history.
 * The one place where game state is rendered into text.
 */
class PromptBuilder
{
	private static final int HISTORY_MAX_EXCHANGES = 6;
	private static final int HISTORY_MAX_CHARS = 8000;

	/** The system prompt; only the closing style rule varies by mode.
	 * Exactly two byte-stable variants exist, so provider prompt caching
	 * gets an identical prefix per mode. */
	static String systemPrompt(boolean simple)
	{
		return SYNTH_SYSTEM + (simple
			? "- Verify with tools as thoroughly as ever -- every rule above still "
			+ "applies. Only the final answer changes: write it as short plain "
			+ "conversational sentences, like a chat message. No markdown syntax "
			+ "may appear in it: no *, **, #, |, backticks, bullet points, or "
			+ "numbered lists -- state emphasis and structure in words instead. "
			+ "Give the recommendation and the verified facts that justify it, "
			+ "without alternatives or caveats unless asked."
			: "- Be concrete and concise; recommend rather than exhaustively enumerate, "
			+ "but use steps or lists when the question calls for them.");
	}

	private static final String SYNTH_SYSTEM =
		"You are an OSRS copilot running inside RuneLite. Answer the player's question "
		+ "using their live game state and the retrieved facts provided. Principles:\n"
		+ "- PLAYER STATE is what the client observes. A field marked "
		+ "\"complete\" is exhaustive (absence there means not owned -- never search or "
		+ "guess for what it already rules out). Everything else not shown is UNKNOWN, "
		+ "not absent: never infer missing items, progress, or experience from absence -- say "
		+ "what you can't see and give conditional advice ('if you have X, otherwise Y') where "
		+ "it matters.\n"
		+ "- Respect the player's account type (an IRONMAN cannot use the Grand Exchange).\n"
		+ "- Retrieved facts were fetched from the OSRS Wiki just now and are authoritative. "
		+ "Prefer them over memory, and don't assert game facts from memory that they don't "
		+ "support. Use tools if something essential is missing.\n"
		+ "- Personalize: check requirements against the player's actual levels, quest progress, "
		+ "kill counts (boss_kc_and_activity_scores; a missing boss means few kills, not "
		+ "exactly zero), and owned items.\n"
		+ "- PRICES: never state a coin price, price range, or cost claim ('nearly free', "
		+ "'expensive') from memory -- prices move constantly and your training-time prices are "
		+ "often wrong by 10-100x. Every price you mention must come from a GE price fact or a "
		+ "ge_price call in this conversation (batch all candidates into ONE call). If an item "
		+ "isn't priced by then, name it without a number.\n"
		+ "- Gear and upgrade recommendations must come from the retrieved equipment tables and "
		+ "facts, which include items released after your training data; your remembered meta is "
		+ "incomplete. Recommend the alternatives the tables list at the player's budget and "
		+ "stats, and check ownership of those alternatives before declaring a purchase needed. "
		+ "If you add an option from memory, say that's what it is.\n"
		+ "- slayer_task is the player's current Slayer assignment. On-task-only effects "
		+ "(Slayer helmet/black mask bonuses, task-only areas) apply ONLY against that exact "
		+ "creature; the player is off-task for everything else.\n"
		+ "- Quest progress shown in the facts is authoritative. For any quest not shown, verify "
		+ "with the quest_status tool before advising quest-gated content.\n"
		+ "- If the question is ambiguous, state the interpretation you chose in one short sentence.\n"
		+ "- If the facts don't answer the question, say so honestly rather than guessing.\n"
		+ "- When comparing or ranking options, ground the verdict in retrieved numbers "
		+ "(defensive stats, requirements, mechanics) or a retrieved recommendation. If nothing "
		+ "retrieved settles it, present the trade-offs and say the data doesn't settle it -- "
		+ "never manufacture a confident winner.\n"
		+ "- In an ongoing conversation, PLAYER STATE and RETRIEVED FACTS accompany the latest "
		+ "question and reflect the current moment; earlier answers may describe older state.\n";

	private final Gson gson;
	private final Hiscores hiscores;

	PromptBuilder(Gson gson, Hiscores hiscores)
	{
		this.gson = gson;
		this.hiscores = hiscores;
	}

	String buildUserMessage(String question, GameCapture cap, List<String> facts,
		boolean bankInlined, boolean ownershipComplete, boolean offerOwnedSearch)
	{
		Map<String, Object> state = playerState(cap, bankInlined,
			ownershipComplete, offerOwnedSearch);

		StringBuilder sb = new StringBuilder();
		sb.append("QUESTION: ").append(question).append("\n\n");
		sb.append("PLAYER STATE:\n").append(gson.toJson(state));
		if (cap.recentEvents != null && !cap.recentEvents.isEmpty())
		{
			sb.append("\n\nRECENT SESSION EVENTS (newest last):\n")
				.append(gson.toJson(cap.recentEvents));
		}
		if (!facts.isEmpty())
		{
			sb.append("\n\nRETRIEVED FACTS (fetched from OSRS Wiki / GE just now):\n\n")
				.append(String.join("\n", facts));
		}
		return sb.toString();
	}

	/** The PLAYER STATE block. */
	private Map<String, Object> playerState(GameCapture cap, boolean bankInlined,
		boolean ownershipComplete, boolean offerOwnedSearch)
	{
		Map<String, Object> state = new LinkedHashMap<>();
		// Without today's date the model assumes its training-time year.
		// Lives here so the system prompt stays byte-identical for caching.
		state.put("date", java.time.LocalDate.now().toString());
		state.put("player", cap.playerName);
		state.put("account_type", cap.accountTypeName());
		state.put("combat_level", cap.combatLevel);
		state.put("location", groundedLocation(cap));
		state.put("skills", cap.skills);
		// Kill counts are server-side state the client can't see; without
		// them the model assumes a beginner.
		Map<String, Long> scores = hiscores.rankedActivities(cap.playerName);
		if (scores != null)
		{
			state.put("boss_kc_and_activity_scores", scores);
		}
		if (cap.boostsOrDrains != null && !cap.boostsOrDrains.isEmpty())
		{
			state.put("boosts_or_drains", cap.boostsOrDrains);
		}
		if (cap.questStates != null)
		{
			long finished = cap.questStates.values().stream()
				.filter("FINISHED"::equals).count();
			state.put("quests_finished", finished);
			List<String> inProgress = new ArrayList<>();
			cap.questStates.forEach((q, s) -> {
				if ("IN_PROGRESS".equals(s))
				{
					inProgress.add(q);
				}
			});
			state.put("quests_in_progress", inProgress);
		}
		if (cap.slayerTask != null)
		{
			state.put("slayer_task", cap.slayerTask);
		}
		if (cap.unlocks != null)
		{
			state.put("unlocks", cap.unlocks);
		}
		state.put("inventory", itemStrings(cap.inventory));
		state.put("equipment", itemNamesOnly(cap.equipment));
		state.put("bank", bankState(cap, bankInlined, ownershipComplete, offerOwnedSearch));
		addDiaryState(state, cap);
		return state;
	}

	/** Data plus status, no embedded instructions; the system prompt
	 * defines the semantics of "complete"/"unknown" once. */
	private Map<String, Object> bankState(GameCapture cap, boolean bankInlined,
		boolean ownershipComplete, boolean offerOwnedSearch)
	{
		Map<String, Object> bank = new LinkedHashMap<>();
		if (cap.bank == null)
		{
			bank.put("status", "unknown");
		}
		else
		{
			bank.put("status", bankInlined ? "complete" : "summarized");
			if (bankInlined)
			{
				bank.put("items", itemStrings(cap.bank));
			}
			else
			{
				bank.put("item_count", cap.bank.size());
			// The access note must match the tools actually offered;
			// referencing a withheld tool sends the model chasing it.
				String factsAreDefinitive =
					"the Ownership fact in RETRIEVED FACTS is the definitive bank "
						+ "answer for every item the facts mention, and each tool "
						+ "result carries the same ownership note for the items IT "
						+ "mentions -- state ownership plainly from these, never "
						+ "conditionally ('if you have one')";
				bank.put("access", !offerOwnedSearch
					? factsAreDefinitive
					: ownershipComplete
						? factsAreDefinitive + "; for items the facts do NOT "
							+ "mention, use ONE search_owned_items call with all "
							+ "queries batched"
						: "ownership of items the facts mention is in RETRIEVED FACTS, "
							+ "and each tool result carries an ownership note for the "
							+ "items IT mentions; for anything still uncovered use ONE "
							+ "search_owned_items call with all queries batched");
			}
		}
		return bank;
	}

	private static void addDiaryState(Map<String, Object> state, GameCapture cap)
	{
		if (cap.diaries != null && !cap.diaries.isEmpty())
		{
			// Only areas with completed tiers are listed; the note
			// carries the semantics for the rest.
			Map<String, Object> completed = new LinkedHashMap<>();
			for (Map.Entry<String, Object> e : cap.diaries.entrySet())
			{
				if (e.getValue() instanceof List && !((List<?>) e.getValue()).isEmpty())
				{
					completed.put(e.getKey(), e.getValue());
				}
			}
			Map<String, Object> diaries = new LinkedHashMap<>();
			diaries.put("status", "authoritative, from the game client");
			diaries.put("completed_tiers", completed);
			diaries.put("note", "any area or tier not listed here is NOT complete. "
				+ "Per-task progress inside an incomplete tier is not visible: present its "
				+ "tasks as a checklist, never claim which individual tasks are done");
			state.put("achievement_diaries", diaries);
		}
	}

	/** Resolve raw coordinates to the named game area containing them; the
	 * coordinates stay in as supplementary data. */
	private static Map<String, Object> groundedLocation(GameCapture cap)
	{
		if (cap.location == null)
		{
			return null;
		}
		// JSON round-trips turn ints into doubles ("y":3220.0); tidy them.
		Map<String, Object> out = new LinkedHashMap<>();
		cap.location.forEach((k, v) ->
			out.put(k, v instanceof Number ? ((Number) v).longValue() : v));
		Object xo = cap.location.get("x");
		Object yo = cap.location.get("y");
		if (xo instanceof Number && yo instanceof Number)
		{
			Object po = cap.location.get("plane");
			WorldPoint point = new WorldPoint(((Number) xo).intValue(),
				((Number) yo).intValue(),
				po instanceof Number ? ((Number) po).intValue() : 0);
			String place = Areas.resolve(point);
			if (place != null)
			{
				out.put("place", place);
			}
			else if (point.getX() >= 6400)
			{
				// Instanced content is translated to template coordinates
				// before this check, so an untranslated far-x point is the
				// sailing ocean.
				out.put("place", "sailing at sea on a boat");
			}
			else if (point.getY() >= 6400)
			{
				// Above y=6400 with normal x is dungeons.
				out.put("place", "underground area");
			}
			// Unmapped surface spot: say nothing rather than guess.
		}
		return out;
	}

	/** Newest-first budget: keep the most recent exchanges within both the
	 * exchange and character caps, preserving chronological order. */
	static List<CopilotPipeline.Exchange> boundedHistory(List<CopilotPipeline.Exchange> history)
	{
		List<CopilotPipeline.Exchange> kept = new ArrayList<>();
		if (history == null)
		{
			return kept;
		}
		int chars = 0;
		for (int i = history.size() - 1; i >= 0 && kept.size() < HISTORY_MAX_EXCHANGES; i--)
		{
			CopilotPipeline.Exchange ex = history.get(i);
			chars += ex.question.length() + ex.answer.length();
			if (chars > HISTORY_MAX_CHARS && !kept.isEmpty())
			{
				break;
			}
			kept.add(0, ex);
		}
		return kept;
	}

	private static List<String> itemStrings(List<Map<String, Object>> items)
	{
		List<String> out = new ArrayList<>();
		if (items != null)
		{
			for (Map<String, Object> item : items)
			{
				long qty = item.get("quantity") instanceof Number
					? ((Number) item.get("quantity")).longValue() : 1;
				out.add(item.get("name") + (qty > 1 ? " x" + qty : ""));
			}
		}
		return out;
	}

	private static List<String> itemNamesOnly(List<Map<String, Object>> items)
	{
		List<String> out = new ArrayList<>();
		if (items != null)
		{
			for (Map<String, Object> item : items)
			{
				out.add(String.valueOf(item.get("name")));
			}
		}
		return out;
	}
}

package com.osrscopilot.pipeline;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * The deterministic front half of the pipeline: entity resolution, needs
 * classification, facility intents, diary tiers, bank mode. No LLM, so
 * routing is regression-testable without a model.
 */
@Slf4j
class Router
{
	/** Bank size at or below which the full bank inlines into the prompt;
	 * larger banks are summarized. */
	static final int BANK_INLINE_LIMIT = 200;

	/** Locational phrasing gate for the facility rules. */
	static final Pattern LOCATIONAL =
		Pattern.compile("\\b(where|nearest|closest|closer|nearby|near me|how far)\\b");

	/** Words that point back at the conversation; their presence carries
	 * the previous turn's entities into this turn's retrieval. */
	private static final Pattern ANAPHORIC = Pattern.compile(
		"\\b(it|its|that|those|them|these|this|ones?|same|again|instead|"
		+ "i meant?|what about|how about|and if|what if)\\b"
		// Locative "there" points back ("is a tbow good there");
		// existential "there" ("is there a way...") is excluded by its
		// surrounding frames.
		+ "|(?<!\\b(?:is|are|was|were|will|would|can|could|should|do|does|did) )"
		+ "\\bthere\\b(?!'s)(?! (?:is|are|was|were|be|a|an|any\\w*|no)\\b)");

	/** Only applied when a resolved page is a diary; "hard" elsewhere is
	 * inert. */
	private static final Pattern DIARY_TIER =
		Pattern.compile("\\b(easy|medium|hard|elite)\\b", Pattern.CASE_INSENSITIVE);

	/** "herb run"/"tree route" names an activity the resolver can't find;
	 * routes to the wiki's Farming runs guide. */
	private static final Pattern FARMING_RUN = Pattern.compile(
		"\\b(farm(ing)?|herb|tree|fruit tree|allotment|flower) (runs?|routes?)\\b");

	static final Object[][] FACILITY_RULES = {
		{Pattern.compile("\\b(pray(er)?|altar)\\b"), "Altar"},
		{Pattern.compile("\\bbank\\b"), "Bank"},
		{Pattern.compile("\\b(furnace|smelt)\\b"), "Furnace"},
		{Pattern.compile("\\b(anvil|smith)\\b"), "Anvil"},
		{Pattern.compile("\\b(cook|range|stove)\\b"), "Cooking range"},
		{Pattern.compile("\\bfairy ring\\b"), "Fairy ring"},
		{Pattern.compile("\\bspirit tree\\b"), "Spirit tree"},
		{Pattern.compile("\\b(farm(ing)? patch|allotment)\\b"), "Farming patch"},
		{Pattern.compile("\\bwater(fill| source)?\\b"), "Water source"},
		{Pattern.compile("\\bsaw ?mill\\b"), "Sawmill"},
	};

	// Need names shared with the prefetcher; a misspelled need silently
	// no-ops.
	static final String NEED_PRICES = "prices";
	static final String NEED_DROP_TABLE = "drop_table";
	static final String NEED_STRATEGY = "strategy";
	static final String NEED_MECHANICS = "mechanics";
	static final String NEED_ITEM_SOURCES = "item_sources";
	static final String NEED_XP_MATH = "xp_math";
	static final String NEED_TRAINING = "training";
	static final String NEED_TRANSPORT = "transport";
	static final String NEED_RECENT_EVENTS = "recent_events";
	static final String NEED_SLAYER_TASK = "slayer_task";

	private static final Pattern SLAYER_MENTION = Pattern.compile("\\bslayer\\b");

	/** References to something that just happened ("what did that drop");
	 * gates the recent-events need. */
	private static final Pattern EVENT_REFERENCE =
		Pattern.compile("\\b(this|that|just|my)\\b.*\\b(drop|loot|kill|got)\\b");

	// Shared phrasing frames; a pronoun variant added here fixes every rule.
	/** "how to / how do i / how can you / how should we ..." */
	static final String HOW = "how (to|do (i|you|we)|can (i|you|we)|should (i|we)|would (i|you|we))";
	/** "where" including the contraction-less "wheres". */
	static final String WHERE = "where('?s)?";
	/** Fight verbs, inflection-tolerant (kills, killed, fighting, fought...). */
	static final String FIGHT_VERB = "(kill|beat|fight|fought|defeat|solo)(s|t?ed|ing)?";
	/** Obtain verbs, inflection-tolerant (gets, getting, made, crafting...). */
	static final String OBTAIN_VERB = "(get(s|ting)?|got|buy(s|ing)?|bought|find(s|ing)?|found"
		+ "|mak(e|es|ing)|made|craft(s|ed|ing)?|obtain(s|ed|ing|able)?|farm(s|ed|ing|able)?)";

	/** Applied only when a monster resolved: a monster plus a fight verb is
	 * fight intent, no frame required. */
	private static final Pattern FIGHT_VERB_ANYWHERE =
		Pattern.compile("\\b" + FIGHT_VERB + "\\b");

	/** Applied only when an item resolved. */
	private static final Pattern OBTAIN_VERB_ANYWHERE =
		Pattern.compile("\\b" + OBTAIN_VERB + "\\b");

	/** Needs are EXTRAS on top of each entity's core bundle, never the only
	 * path to essential facts. */
	private static final Object[][] NEED_RULES = {
		{Pattern.compile("\\b(price|cost|how much|value|alch|sell)\\b"), new String[]{NEED_PRICES}},
		{Pattern.compile("\\bworth (doing|it|killing|farming)\\b"), new String[]{NEED_DROP_TABLE, NEED_PRICES, NEED_STRATEGY}},
		{Pattern.compile("\\b(" + WHERE + "|" + HOW + ")\\b.*\\b" + OBTAIN_VERB + "\\b"),
			new String[]{NEED_ITEM_SOURCES}},
		{Pattern.compile("\\b(quickest|fastest|easiest|best) (way|place|method)\\b.*\\b" + OBTAIN_VERB + "\\b"),
			new String[]{NEED_ITEM_SOURCES}},
		{Pattern.compile("\\b(gear|setup|equipment|loadout|what.*(wear|bring|take|pack))\\b"), new String[]{NEED_STRATEGY}},
		// Safe on non-combat subjects: strategy extras only fetch when a
		// /Strategies page exists.
		{Pattern.compile("\\b(prep|prepping|prepare|preparing) for\\b"), new String[]{NEED_STRATEGY}},
		{Pattern.compile("\\b(strategy|safespot|(" + HOW + "|best way to) " + FIGHT_VERB + ")\\b"),
			new String[]{NEED_STRATEGY, NEED_MECHANICS}},
		{Pattern.compile("\\b(afk|aggro|mechanic|spawn|attack style|weakness)\\b"), new String[]{NEED_MECHANICS}},
		{Pattern.compile("\\b(level|xp|experience)\\b"), new String[]{NEED_XP_MATH}},
		// Bare "level" belongs to XP math ("what level do i need"); only
		// verb frames make it a training question.
		{Pattern.compile("\\btrain(ing)?\\b|\\blevel(l?ing| up)\\b|\\b("
			+ HOW + "|(quickest|fastest|easiest|best) (way|method) to) level\\b"),
			new String[]{NEED_TRAINING}},
		{Pattern.compile("\\b(drop|dropped|loot)\\b"), new String[]{NEED_DROP_TABLE}},
		{Pattern.compile("\\b(fastest|quickest|best) way\\b|\\b" + HOW + " (get|travel) to\\b|\\broute to\\b"),
			new String[]{NEED_TRANSPORT}},
	};

	private final EntityResolver resolver;

	Router(EntityResolver resolver)
	{
		this.resolver = resolver;
	}

	CopilotPipeline.Route route(String question, GameCapture cap,
		EntityResolver.Resolution previous) throws IOException
	{
		CopilotPipeline.Route r = new CopilotPipeline.Route();
		Set<String> questNames = cap.questStates != null ? cap.questStates.keySet() : Set.of();
		r.entities = resolver.resolve(question, questNames,
			previous != null && previous.anyEntity()
				? EntityResolver.Source.FOLLOW_UP : EntityResolver.Source.QUESTION);
		// "my task" names an entity the player never types; resolve the
		// task creature from game state.
		boolean taskReferenced = cap.slayerTask != null && cap.slayerTask.get("creature") != null
			&& referencesSlayerTask(question, r.entities);
		if (taskReferenced)
		{
			resolver.resolveInto(String.valueOf(cap.slayerTask.get("creature")),
				questNames, r.entities);
		}
		if (FARMING_RUN.matcher(question.toLowerCase(Locale.ROOT)).find()
			&& !r.entities.pages.contains("Farming runs"))
		{
			r.entities.pages.add("Farming runs");
		}
		// Inherit the previous subject only when the question points back
		// at it (anaphor, or nothing newly resolved). Inherited entities
		// merge after the question's own.
		if (previous != null && (!r.entities.anyEntity()
			|| ANAPHORIC.matcher(question.toLowerCase(Locale.ROOT)).find()))
		{
			mergeMissing(previous.items, r.entities.items);
			mergeMissing(previous.monsters, r.entities.monsters);
			mergeMissing(previous.quests, r.entities.quests);
			mergeMissing(previous.pages, r.entities.pages);
		}
		r.needs = classifyNeeds(question,
			!r.entities.monsters.isEmpty(), !r.entities.items.isEmpty());
		String ql = question.toLowerCase(Locale.ROOT);
		if (cap.recentEvents != null && !cap.recentEvents.isEmpty()
			&& (EVENT_REFERENCE.matcher(ql).find()
				|| ql.contains("whats this") || ql.contains("what's this")))
		{
			r.needs.add(NEED_RECENT_EVENTS);
		}
		// Not in classifyNeeds: the task-reference half needs game state.
		if (!r.entities.monsters.isEmpty() && (taskReferenced
			|| SLAYER_MENTION.matcher(question.toLowerCase(Locale.ROOT)).find()))
		{
			r.needs.add(NEED_SLAYER_TASK);
		}
		// Transport is meaningless without a resolved destination ("best
		// way to train smithing" must not route as travel).
		if (r.entities.pages.isEmpty() && r.entities.monsters.isEmpty())
		{
			r.needs.remove(NEED_TRANSPORT);
		}
		r.facilityPages = facilityPages(question);
		// A whole diary page blows the fact budget; a named tier routes to
		// just that tier's section.
		if (r.entities.pages.stream().anyMatch(Router::isDiaryPage))
		{
			Matcher tier = DIARY_TIER.matcher(question);
			if (tier.find())
			{
				r.diaryTier = tier.group(1).toLowerCase(Locale.ROOT);
				// Otherwise the tier word also resolves as a junk page
				// ("Medium").
				r.entities.pages.removeIf(p -> p.equalsIgnoreCase(r.diaryTier));
			}
		}
		r.bankMode = cap.bank == null ? "unknown"
			: cap.bank.size() <= BANK_INLINE_LIMIT ? "complete" : "summarized";
		log.debug("route: items={} monsters={} quests={} pages={} needs={} facilities={} bank={}",
			r.entities.items, r.entities.monsters, r.entities.quests, r.entities.pages,
			r.needs, r.facilityPages, r.bankMode);
		return r;
	}

	/** Append entries from previous that the current list doesn't already
	 * have, preserving current-question-first order. */
	private static void mergeMissing(List<String> previous, List<String> into)
	{
		for (String name : previous)
		{
			addMissing(into, name);
		}
	}

	/** Pure needs classification: no network, no game state beyond the
	 * flags. Table-tested by RouterPhrasingTest. */
	static List<String> classifyNeeds(String question,
		boolean monsterResolved, boolean itemResolved)
	{
		String ql = question.toLowerCase(Locale.ROOT);
		List<String> needs = new ArrayList<>();
		for (Object[] rule : NEED_RULES)
		{
			if (((Pattern) rule[0]).matcher(ql).find())
			{
				for (String n : (String[]) rule[1])
				{
					addMissing(needs, n);
				}
			}
		}
		// A resolved entity makes intent near-certain without a question
		// frame ("can i kill vorkath without a shield").
		if (monsterResolved && FIGHT_VERB_ANYWHERE.matcher(ql).find())
		{
			addMissing(needs, NEED_STRATEGY);
			addMissing(needs, NEED_MECHANICS);
		}
		if (itemResolved && OBTAIN_VERB_ANYWHERE.matcher(ql).find())
		{
			addMissing(needs, NEED_ITEM_SOURCES);
		}
		return needs;
	}

	private static void addMissing(List<String> needs, String need)
	{
		if (!needs.contains(need))
		{
			needs.add(need);
		}
	}

	/** Facility intents matched in the question (routing only, no fetching). */
	private static List<String> facilityPages(String question)
	{
		List<String> pages = new ArrayList<>();
		String ql = question.toLowerCase(Locale.ROOT);
		if (!LOCATIONAL.matcher(ql).find())
		{
			return pages;
		}
		for (Object[] rule : FACILITY_RULES)
		{
			if (((Pattern) rule[0]).matcher(ql).find())
			{
				pages.add((String) rule[1]);
			}
		}
		return pages;
	}

	/** Every achievement diary page ends in " Diary" ("Varrock Diary",
	 * "Lumbridge & Draynor Diary"); tier names redirect to these. */
	static boolean isDiaryPage(String page)
	{
		return page.endsWith(" Diary");
	}

	/** True when the player refers to their Slayer task without naming the
	 * creature and the client knows the task. A resolved monster wins; a
	 * denied task ("off task") must not fire. */
	private static boolean referencesSlayerTask(String question, EntityResolver.Resolution entities)
	{
		if (!entities.monsters.isEmpty())
		{
			return false;
		}
		String q = question.toLowerCase(Locale.ROOT);
		if (q.matches(".*\\boff[ -](task|assignment)\\b.*"))
		{
			return false;
		}
		return EntityResolver.mentionsAffirmatively(question, "task")
			|| EntityResolver.mentionsAffirmatively(question, "assignment");
	}
}

package com.osrscopilot.pipeline;

/**
 * Receives incremental output while the pipeline runs, so the UI can render
 * the answer as it generates. Called from the pipeline thread -- implementors
 * must hop to their own thread (e.g. the Swing EDT) as needed.
 */
public interface StreamListener
{
	/** A fragment of visible answer text arrived. */
	void onDelta(String text);

	/** The text streamed so far was not the final answer; discard it from
	 * the display. */
	default void onTurnDiscarded()
	{
	}

	/** Short progress note ("Checking wiki_page...") for a status line. */
	default void onStatus(String status)
	{
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The tools offered to the synth model: OpenAI function-calling specs and
 * implementations side by side so they cannot drift apart.
 */
class ToolRegistry
{
	/** Budget for a single-section fetch (wikitext, tables intact). One
	 * deliberately chosen section of one page may run long. */
	private static final int SECTION_CHAR_LIMIT = 12000;

	private final WikiApi wiki;
	private final Gson gson;

	ToolRegistry(WikiApi wiki, Gson gson)
	{
		this.wiki = wiki;
		this.gson = gson;
	}

	JsonArray buildToolSpecs(boolean offerOwnedSearch)
	{
		JsonArray specs = new JsonArray();
		specs.add(toolSpec("wiki_search",
			"Search the OSRS Wiki for pages. Returns page titles and short snippets ONLY, "
				+ "not page content -- follow up with wiki_page to read a page.",
			"query"));
		// Section fetches return wikitext so tables (loot, rewards) survive.
		JsonObject pageSpec = toolSpec("wiki_page",
			"Get the text of an OSRS Wiki page (item, monster, quest, guide). Long pages are "
				+ "truncated and full-page text OMITS tables; the [Sections: ...] line lists "
				+ "every section that exists. Pass one as \"section\" to fetch just that "
				+ "section with its tables intact.",
			"title");
		pageSpec.getAsJsonObject("function").getAsJsonObject("parameters")
			.getAsJsonObject("properties").add("section", singleType("string"));
		specs.add(pageSpec);
		specs.add(toolSpec("item_sources",
			"How to obtain an item: monster drops and activity/reward-chest sources with drop "
				+ "rates, creation recipes (materials, skill levels, facility), shops that stock "
				+ "it, and whether it trades on the GE. Quest rewards are not covered; use "
				+ "wiki_page for those.",
			"item_name"));
		specs.add(toolSpec("monster_drops",
			"Full drop table of a monster with quantities and drop rarities.", "name"));
		specs.add(toolSpec("monster_info",
			"Get a monster's full combat profile: levels, defensive bonuses per style, "
				+ "attributes, attack style/speed, and immunities.", "name"));
		specs.add(toolSpec("item_stats",
			"Get a wearable item's combat bonuses: attack and defence by style, "
				+ "strength, ranged strength, magic damage, and prayer.", "item_name"));
		specs.add(toolSpec("quest_info",
			"Get a quest's requirements (skill levels and prerequisite quests), "
				+ "items required, and start point.", "quest_name"));
		// Batched: pricing a shortlist costs one round trip, not one each.
		specs.add(toolSpec("ge_price",
			"Current Grand Exchange price, buy limit, and high-alch value. Takes a LIST "
				+ "of item names and returns the price of each -- price all candidate "
				+ "items in one call, never one call per item.",
			"item_names", arrayOf("string")));
		specs.add(toolSpec("quest_status",
			"Check whether the player has finished, started, or not started a specific quest.",
			"quest_name"));
		JsonObject xpSpec = toolSpec("xp_to_level",
			"Gives the total xp required to reach requested level in skill. Use it for every "
				+ "xp-to-a-level figure rather than estimating; the XP math fact only "
				+ "precomputes the next level.",
			"skill");
		JsonObject xpParams = xpSpec.getAsJsonObject("function").getAsJsonObject("parameters");
		xpParams.getAsJsonObject("properties").add("target_level", singleType("integer"));
		xpParams.getAsJsonArray("required").add("target_level");
		specs.add(xpSpec);
		// Withheld when ownership is already fully in context: a tool over
		// visible data invites redundant lookups.
		if (offerOwnedSearch)
		{
			specs.add(toolSpec("search_owned_items",
				"Search the player's bank, inventory, and equipment. Takes a LIST of item-name "
					+ "queries and returns the matches for each -- check all candidate items "
					+ "in one call, never one call per item.",
				"queries", arrayOf("string")));
		}
		return specs;
	}

	private static JsonObject toolSpec(String name, String description, String param)
	{
		return toolSpec(name, description, param, singleType("string"));
	}

	private static JsonObject toolSpec(String name, String description, String param,
		JsonObject paramSchema)
	{
		JsonObject prop = new JsonObject();
		prop.add(param, paramSchema);
		JsonObject params = new JsonObject();
		params.addProperty("type", "object");
		params.add("properties", prop);
		JsonArray required = new JsonArray();
		required.add(param);
		params.add("required", required);
		JsonObject fn = new JsonObject();
		fn.addProperty("name", name);
		fn.addProperty("description", description);
		fn.add("parameters", params);
		JsonObject spec = new JsonObject();
		spec.addProperty("type", "function");
		spec.add("function", fn);
		return spec;
	}

	private static JsonObject arrayOf(String type)
	{
		JsonObject o = new JsonObject();
		o.addProperty("type", "array");
		o.add("items", singleType(type));
		return o;
	}

	private static JsonObject singleType(String type)
	{
		JsonObject o = new JsonObject();
		o.addProperty("type", type);
		return o;
	}

	Map<String, AgentLoop.Tool> buildTools(GameCapture cap, Map<String, long[]> owned,
		Map<String, String> ownedNames, boolean offerOwnedSearch,
		boolean annotateOwnership)
	{
		Map<String, AgentLoop.Tool> tools = new LinkedHashMap<>();
		// Content-returning tools surface item names the prompt-time
		// ownership fact never saw; each result carries its own slice.
		tools.put("wiki_search", annotated(owned, ownedNames, annotateOwnership,
			args -> wiki.search(str(args, "query"))));
		tools.put("wiki_page", annotated(owned, ownedNames, annotateOwnership, args -> {
			String title = str(args, "title");
			String section = str(args, "section");
			if (!section.isEmpty())
			{
				String text = wiki.sectionByHeading(title, Pattern.compile(
					Pattern.quote(section), Pattern.CASE_INSENSITIVE), SECTION_CHAR_LIMIT);
				if (text != null)
				{
					return text;
				}
				List<String> available = wiki.topSections(title);
				return Map.of("error", "No section '" + section + "' on '" + title + "'"
					+ (available.isEmpty() ? "."
						: ". Sections: " + String.join("; ", available)));
			}
			String text = wiki.page(title);
			return text != null ? text
				: Map.of("error", "No page found for '" + title + "'. Try wiki_search first.");
		}));
		tools.put("item_sources", annotated(owned, ownedNames, annotateOwnership,
			args -> wiki.itemSources(str(args, "item_name"))));
		tools.put("monster_drops", annotated(owned, ownedNames, annotateOwnership,
			args -> wiki.monsterDrops(str(args, "name"))));
		tools.put("monster_info", annotated(owned, ownedNames, annotateOwnership,
			args -> wiki.monsterInfo(str(args, "name"))));
		tools.put("item_stats", annotated(owned, ownedNames, annotateOwnership,
			args -> wiki.itemStats(str(args, "item_name"))));
		tools.put("quest_info", annotated(owned, ownedNames, annotateOwnership,
			args -> wiki.questInfo(str(args, "quest_name"))));
		tools.put("ge_price", annotated(owned, ownedNames, annotateOwnership, args -> {
			List<String> names = strList(args, "item_names", "item_name");
			if (names.isEmpty())
			{
				return Map.of("error", "provide 'item_names': a list of items to price");
			}
			Map<String, Object> result = new LinkedHashMap<>();
			for (String name : names)
			{
				result.put(name, wiki.gePrice(name));
			}
			return result;
		}));
		tools.put("quest_status", args -> {
			if (cap.questStates == null || cap.questStates.isEmpty())
			{
				return Map.of("error", "quest states not available this session");
			}
			String ql = str(args, "quest_name").toLowerCase(Locale.ROOT);
			for (Map.Entry<String, String> e : cap.questStates.entrySet())
			{
				if (e.getKey().toLowerCase(Locale.ROOT).equals(ql))
				{
					return Map.of("quest", e.getKey(), "status", e.getValue());
				}
			}
			Map<String, String> partial = new LinkedHashMap<>();
			for (Map.Entry<String, String> e : cap.questStates.entrySet())
			{
				if (e.getKey().toLowerCase(Locale.ROOT).contains(ql))
				{
					partial.put(e.getKey(), e.getValue());
				}
			}
			return partial.isEmpty()
				? Map.of("error", "no quest matching '" + str(args, "quest_name") + "'")
				: partial;
		});
		tools.put("xp_to_level", args -> {
			if (cap.skillXp == null || cap.skillXp.isEmpty())
			{
				return Map.of("error", "skill XP not available this session");
			}
			String skill = str(args, "skill");
			String sl = skill.toLowerCase(Locale.ROOT);
			Map.Entry<String, Integer> match = null;
			for (Map.Entry<String, Integer> e : cap.skillXp.entrySet())
			{
				if (e.getKey().toLowerCase(Locale.ROOT).equals(sl))
				{
					match = e;
					break;
				}
			}
			if (match == null)
			{
				return Map.of("error", "no skill named '" + skill + "'");
			}
			int target;
			try
			{
				target = args.get("target_level").getAsInt();
			}
			catch (Exception e)
			{
				return Map.of("error", "provide 'target_level': the level to reach (2-99)");
			}
			if (target < 2 || target > 99)
			{
				return Map.of("error", "target_level must be 2-99");
			}
			int xp = match.getValue();
			Map<String, Object> out = new LinkedHashMap<>();
			out.put("skill", match.getKey());
			out.put("current_xp", xp);
			out.put("current_level", XpTable.toNextLevel(xp)[0]);
			out.put("target_level", target);
			int needed = XpTable.xpForLevel(target) - xp;
			out.put("xp_needed", Math.max(0, needed));
			if (needed <= 0)
			{
				out.put("note", "target level already reached");
			}
			return out;
		});
		if (offerOwnedSearch)
		{
			// The annotated wrap adds the ownership slice footer, whose
			// entries carry the carried/equipped/banked locations for the
			// items the hits name; the hits themselves stay totals.
			tools.put("search_owned_items", annotated(owned, ownedNames, annotateOwnership,
				args -> {
				List<String> queries = strList(args, "queries", "query");
				if (queries.isEmpty())
				{
					return Map.of("error", "provide 'queries': a list of item names to look for");
				}
				Map<String, Object> result = new LinkedHashMap<>();
				Set<String> known = validItemNames();
				for (String query : queries)
				{
					String ql = query.toLowerCase(Locale.ROOT);
					List<String> needles = ItemCollectives.expand(ql);
					List<Map<String, Object>> hits = new ArrayList<>();
					for (String needle : needles)
					{
						for (Map.Entry<String, long[]> e : owned.entrySet())
						{
							if (e.getKey().contains(needle) && hits.size() < 20)
							{
								Map<String, Object> hit = new LinkedHashMap<>();
								hit.put("item", ownedNames.get(e.getKey()));
								hit.put("quantity", Ownership.total(e.getValue()));
								hits.add(hit);
							}
						}
					}
					if (!hits.isEmpty())
					{
						result.put(query, hits);
						continue;
					}
					// An expanded query searched every variant: a true zero.
					// Otherwise a miss on an invented name must not read as
					// one ("Dwarf multicannon" is a page, not an item).
					result.put(query, needles.size() > 1 || known.contains(ql)
						? "no match in bank/inventory/equipment"
						: "not a valid OSRS item name -- search queries must use "
							+ "exact in-game item names");
				}
				return result;
			}));
		}
		return tools;
	}

	/** Lowercased catalogue names plus their bases ("saradomin brew" for
	 * "Saradomin brew(4)", since prose and queries drop the qualifier). */
	private Set<String> validItemNames() throws IOException
	{
		Set<String> names = new HashSet<>();
		for (ItemDescriptor it : wiki.itemCatalog())
		{
			String lower = it.name.toLowerCase(Locale.ROOT);
			names.add(lower);
			names.add(Ownership.baseName(lower));
		}
		return names;
	}

	/** Appends the ownership slice for every catalogued item a tool result
	 * mentions. Disabled when the bank is inlined; error results pass
	 * through untouched. */
	private AgentLoop.Tool annotated(Map<String, long[]> owned,
		Map<String, String> ownedNames, boolean enabled, AgentLoop.Tool inner)
	{
		if (!enabled)
		{
			return inner;
		}
		return args -> {
			Object out = inner.call(args);
			if (out instanceof Map && ((Map<?, ?>) out).containsKey("error"))
			{
				return out;
			}
			String text = out instanceof String ? (String) out : gson.toJson(out);
			Ownership.Slice slice = Ownership.slice(text.toLowerCase(Locale.ROOT),
				owned, ownedNames, wiki.itemCatalog());
			if (slice == null)
			{
				return out;
			}
			return text + "\n\n[Player ownership of items this result mentions"
				+ (slice.complete ? "" : " (lists cut for length)")
				+ "]\n" + slice.text;
		};
	}

	private static String str(JsonObject args, String key)
	{
		return args.has(key) && !args.get(key).isJsonNull() ? args.get(key).getAsString() : "";
	}

	/** List argument for a batched tool; tolerates a bare string under
	 * the list key or its singular cousin. */
	private static List<String> strList(JsonObject args, String listKey, String singleKey)
	{
		List<String> values = new ArrayList<>();
		if (args.has(listKey) && args.get(listKey).isJsonArray())
		{
			for (JsonElement v : args.getAsJsonArray(listKey))
			{
				values.add(v.getAsString());
			}
		}
		else
		{
			String single = args.has(singleKey) ? str(args, singleKey) : str(args, listKey);
			if (!single.isEmpty())
			{
				values.add(single);
			}
		}
		return values;
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * Bulk vocabularies served from published snapshots: a weekly CI job
 * (VocabSnapshotTool) runs the wiki's bulk queries once; clients download
 * the gzipped result with a 7-day disk cache and stale-beats-broken
 * fallback.
 */
@Slf4j
class VocabSnapshots
{
	/** Deliberately no fallback to building from the wiki: a broken
	 * snapshot pipeline must not shift bulk-query load onto the wiki. */
	private static final String SNAPSHOT_BASE =
		"https://raw.githubusercontent.com/zerofata/osrs-copilot/vocab-data/";

	/** Matches the weekly publish cadence. */
	private static final long CACHE_TTL_MS = 7L * 24 * 60 * 60 * 1000;

	private final Http http;
	private final Gson gson;
	private final File cacheDir;

	private Set<String> monsterNames;
	private Set<String> englishWords;
	private Set<String> commonEnglishWords;
	private List<ItemDescriptor> itemCatalog;
	private Set<String> strategiesPages;
	private Set<String> slayerTaskPages;

	VocabSnapshots(Http http, Gson gson, File cacheDir)
	{
		this.http = http;
		this.gson = gson;
		this.cacheDir = cacheDir;
	}

	synchronized Set<String> monsterNames() throws IOException
	{
		if (monsterNames == null)
		{
			monsterNames = gson.fromJson(snapshot("monsters_v2.json"),
				new TypeToken<Set<String>>() { }.getType());
		}
		return monsterNames;
	}

	/** Exact titles of every {Monster}/Strategies subpage. Callers must
	 * treat IOException as "index unknown" and keep blind-fetch behavior,
	 * never as "page absent". */
	synchronized Set<String> strategiesPages() throws IOException
	{
		if (strategiesPages == null)
		{
			strategiesPages = gson.fromJson(snapshot("strategies.json"),
				new TypeToken<Set<String>>() { }.getType());
		}
		return strategiesPages;
	}

	/** Exact titles of every "Slayer task/..." guide subpage, redirect
	 * aliases included. IOException means "index unknown", never "page
	 * absent". */
	synchronized Set<String> slayerTaskPages() throws IOException
	{
		if (slayerTaskPages == null)
		{
			slayerTaskPages = gson.fromJson(snapshot("slayer_tasks.json"),
				new TypeToken<Set<String>>() { }.getType());
		}
		return slayerTaskPages;
	}

	/** The one item catalogue the resolver, ownership pass, and UI
	 * decorator share. The snapshot job canonicalizes it: removed content,
	 * fake pages, and bare dictionary-word untradeables are already gone,
	 * duplicate display names resolved, game IDs attached where known. */
	synchronized List<ItemDescriptor> itemCatalog() throws IOException
	{
		if (itemCatalog == null)
		{
			itemCatalog = gson.fromJson(snapshot("items_v2.json"),
				new TypeToken<List<ItemDescriptor>>() { }.getType());
		}
		return itemCatalog;
	}

	/** 10k most common English words, frequency-ordered. Empty on fetch
	 * failure. */
	synchronized Set<String> englishWords()
	{
		loadWordlist();
		return englishWords;
	}

	/** The high-frequency band of the wordlist; hostile redirects come
	 * from here ("up", "want"), genuine game words sit below it. */
	synchronized Set<String> commonEnglishWords()
	{
		loadWordlist();
		return commonEnglishWords;
	}

	private void loadWordlist()
	{
		if (englishWords != null)
		{
			return;
		}
		englishWords = new HashSet<>();
		commonEnglishWords = new HashSet<>();
		try
		{
			for (String w : snapshot("english_10k.txt").split("\n"))
			{
				if (!w.trim().isEmpty())
				{
					englishWords.add(w.trim());
					if (englishWords.size() <= COMMON_ENGLISH_BAND)
					{
						commonEnglishWords.add(w.trim());
					}
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Wordlist unavailable", e);
		}
	}

	/** Hostile redirect words top out near rank 305; "staff" (511), the
	 * one game word inside the band, resolves through the vocabulary
	 * pass instead. */
	private static final int COMMON_ENGLISH_BAND = 1000;

	/** Fresh disk copy, else download, else stale disk copy (stale beats
	 * broken). */
	private String snapshot(String filename) throws IOException
	{
		File f = new File(cacheDir, filename);
		boolean fresh = f.exists()
			&& System.currentTimeMillis() - f.lastModified() < CACHE_TTL_MS;
		if (fresh)
		{
			return new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
		}
		try
		{
			String content = gunzip(http.getBytes(SNAPSHOT_BASE + filename + ".gz"));
			cacheDir.mkdirs();
			Files.write(f.toPath(), content.getBytes(StandardCharsets.UTF_8));
			return content;
		}
		catch (IOException e)
		{
			// Refresh failed but a stale copy exists: stale beats broken.
			if (f.exists())
			{
				log.warn("snapshot refresh failed for {}, using stale copy", filename, e);
				return new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
			}
			throw e;
		}
	}

	private static String gunzip(byte[] compressed) throws IOException
	{
		try (java.util.zip.GZIPInputStream in = new java.util.zip.GZIPInputStream(
			new java.io.ByteArrayInputStream(compressed)))
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
