package com.osrscopilot.pipeline;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Live wiki content: search, title resolution, page text (plaintext extract
 * with wikitext fallback), sections by heading, and render-time query
 * templates. Owns the short-TTL LRU over wiki GETs, which all live queries
 * flow through.
 */
@Slf4j
class WikiContent
{
	private static final String WIKI_API = "https://oldschool.runescape.wiki/api.php";

	/** Extract-to-page-size ratio below which the plaintext extract has lost
	 * the page's substance to table stripping; see isHusk. */
	private static final double HUSK_RATIO = 0.3;

	private static final int PAGE_CHAR_LIMIT = 7000;
	private static final int WIKITEXT_CHAR_LIMIT = 12000;

	/** TTL for the wiki-GET cache. Not applied to the prices API (prices
	 * move) or snapshots (own 7-day disk cache). */
	private static final long CONTENT_CACHE_TTL_MS = 24 * 60 * 60 * 1000;
	private static final int CONTENT_CACHE_MAX_ENTRIES = 256;

	/** Standard wiki appendix sections; excluded from the TOC line and
	 * dropped first when over budget. */
	private static final Set<String> NOISE_SECTIONS = Set.of(
		"changes", "references", "trivia", "gallery", "see also", "external links",
		"official worlds", "music", "developers");

	private final Http http;

	/** URL -> {fetchedAtMs, response}, LRU-evicted. Guarded by itself. */
	private final Map<String, Object[]> contentCache =
		new LinkedHashMap<String, Object[]>(64, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, Object[]> eldest)
			{
				return size() > CONTENT_CACHE_MAX_ENTRIES;
			}
		};

	WikiContent(Http http)
	{
		this.http = http;
	}

	/** All wiki GETs go through here; see CONTENT_CACHE_TTL_MS. Responses
	 * are treated as read-only by every caller, so sharing them is safe. */
	private JsonObject cachedGet(String url) throws IOException
	{
		synchronized (contentCache)
		{
			Object[] hit = contentCache.get(url);
			if (hit != null && System.currentTimeMillis() - (long) hit[0] < CONTENT_CACHE_TTL_MS)
			{
				return (JsonObject) hit[1];
			}
		}
		JsonObject fresh = http.getJson(url);
		synchronized (contentCache)
		{
			contentCache.put(url, new Object[]{System.currentTimeMillis(), fresh});
		}
		return fresh;
	}

	/** Runs a bucket query. API-level errors throw rather than reading as
	 * empty: empty means the subject doesn't exist, and conflating the
	 * two hides upstream schema drift. */
	JsonObject bucket(String query) throws IOException
	{
		JsonObject r = cachedGet(WIKI_API + "?action=bucket&format=json&query=" + Http.enc(query));
		if (r != null && r.has("error"))
		{
			String message = r.get("error").isJsonPrimitive()
				? r.get("error").getAsString() : r.get("error").toString();
			log.warn("bucket query rejected: {} (query: {})", message, query);
			throw new IOException("bucket query rejected: " + message);
		}
		return r;
	}

	private JsonObject wikiQuery(String params) throws IOException
	{
		return cachedGet(WIKI_API + "?action=query&format=json&" + params);
	}

	/** Search the wiki: [{title, snippet, headings}]. Headings let the
	 * follow-up be a targeted section fetch. */
	List<Map<String, Object>> search(String query)
	{
		try
		{
			JsonObject r = wikiQuery("list=search&srlimit=5&srsearch=" + Http.enc(query));
			List<Map<String, Object>> out = new ArrayList<>();
			for (JsonElement hit : r.getAsJsonObject("query").getAsJsonArray("search"))
			{
				JsonObject h = hit.getAsJsonObject();
				Map<String, Object> entry = new LinkedHashMap<>();
				String title = h.get("title").getAsString();
				entry.put("title", title);
				entry.put("snippet", h.get("snippet").getAsString()
					.replace("<span class=\"searchmatch\">", "").replace("</span>", ""));
				if (out.size() < 3)
				{
					List<String> headings = topSections(title);
					if (!headings.isEmpty())
					{
						entry.put("headings", headings);
					}
				}
				out.add(entry);
			}
			return out;
		}
		catch (Exception e)
		{
			return List.of(Map.of("error", "search failed: " + e.getMessage()));
		}
	}

	/** Top-level headings, appendix noise excluded. Empty on failure:
	 * headings only decorate. */
	List<String> topSections(String title)
	{
		try
		{
			List<String> out = new ArrayList<>();
			for (JsonElement e : pageSections(title))
			{
				JsonObject s = e.getAsJsonObject();
				String line = s.get("line").getAsString();
				if (s.get("toclevel").getAsInt() != 1
					|| NOISE_SECTIONS.contains(line.toLowerCase(Locale.ROOT)))
				{
					continue;
				}
				out.add(line);
				if (out.size() >= 12)
				{
					break;
				}
			}
			return out;
		}
		catch (Exception e)
		{
			log.debug("sections fetch failed for {}", title, e);
			return List.of();
		}
	}

	/** Resolves each name to the wiki page it lands on, or null when no
	 * such page exists. Batched 50 per request (API limit). */
	Map<String, String> resolveTitles(Collection<String> names) throws IOException
	{
		Map<String, String> resolved = new LinkedHashMap<>();
		List<String> batch = new ArrayList<>(new LinkedHashSet<>(names));
		for (int i = 0; i < batch.size(); i += 50)
		{
			List<String> slice = batch.subList(i, Math.min(i + 50, batch.size()));
			JsonObject query = wikiQuery("redirects=1&titles="
				+ Http.enc(String.join("|", slice))).getAsJsonObject("query");
			if (query == null)
			{
				continue;
			}
			Map<String, String> hops = new LinkedHashMap<>();
			hops.putAll(fromToMap(query, "normalized"));
			hops.putAll(fromToMap(query, "redirects"));
			Set<String> missing = new LinkedHashSet<>();
			if (query.has("pages"))
			{
				for (Map.Entry<String, JsonElement> e : query.getAsJsonObject("pages").entrySet())
				{
					JsonObject page = e.getValue().getAsJsonObject();
					if (page.has("missing") || page.has("invalid"))
					{
						missing.add(page.get("title").getAsString());
					}
				}
			}
			for (String name : slice)
			{
				String title = name;
				// Normalization and redirects are reported as hops; follow the
				// chain, guarding against redirect loops.
				for (int hop = 0; hop < 5 && hops.containsKey(title); hop++)
				{
					title = hops.get(title);
				}
				resolved.put(name, missing.contains(title) ? null : title);
			}
		}
		return resolved;
	}

	/** Parses a MediaWiki "normalized"/"redirects" hop array into a
	 * from -> to map. */
	private static Map<String, String> fromToMap(JsonObject q, String key)
	{
		Map<String, String> map = new HashMap<>();
		if (q.has(key))
		{
			for (JsonElement e : q.getAsJsonArray(key))
			{
				JsonObject o = e.getAsJsonObject();
				map.put(o.get("from").getAsString(), o.get("to").getAsString());
			}
		}
		return map;
	}

	/** Page content, truncated: plaintext extract, falling back to raw
	 * wikitext when the extract lost the page's substance. Null when the
	 * page doesn't exist. */
	String page(String title)
	{
		return page(title, 0);
	}

	/** Same, with a caller-chosen char budget (0 = defaults). */
	String page(String title, int charLimit)
	{
		try
		{
		// prop=info returns the wikitext size, so the extract can be
		// measured against its source in one request.
			JsonObject r = wikiQuery("prop=extracts%7Cinfo&explaintext=1&redirects=1"
				+ "&titles=" + Http.enc(title));
			JsonObject pages = r.getAsJsonObject("query").getAsJsonObject("pages");
			for (Map.Entry<String, JsonElement> entry : pages.entrySet())
			{
				JsonObject p = entry.getValue().getAsJsonObject();
				if (!p.has("extract"))
				{
					continue;
				}
				String text = p.get("extract").getAsString();
				int pageBytes = p.has("length") ? p.get("length").getAsInt() : 0;
				if (text.isEmpty() && pageBytes == 0)
				{
					continue;
				}
				// An empty extract from a non-empty page is the extreme husk:
				// table-only pages plaintext-extract to nothing.
				if (text.isEmpty() || isHusk(text, pageBytes))
				{
					log.debug("husk extract for {} ({}B of {}B page), using wikitext",
						title, text.length(), pageBytes);
					return wikitext(title, WIKITEXT_CHAR_LIMIT);
				}
				return withQuerySections(title, text,
					charLimit > 0 ? charLimit : PAGE_CHAR_LIMIT);
			}
		}
		catch (Exception e)
		{
			log.debug("page fetch failed for {}", title, e);
		}
		return null;
	}

	/** Whether a plaintext extract lost the page's substance to table
	 * stripping. Table-gutted pages measure below the 0.3 threshold;
	 * prose pages sit at 0.39+. */
	private static boolean isHusk(String extract, int pageBytes)
	{
		return pageBytes > 0 && (double) extract.length() / pageBytes < HUSK_RATIO;
	}

	/** The wiki's own document structure for a page
	 * (action=parse&prop=sections), shared by the TOC and section fetches. */
	private JsonArray pageSections(String title) throws IOException
	{
		JsonObject r = cachedGet(WIKI_API + "?action=parse&prop=sections&format=json"
			+ "&redirects=1&page=" + Http.enc(title));
		return r.getAsJsonObject("parse").getAsJsonArray("sections");
	}

	/** Fetch one section of a page by heading; null when no section
	 * matches. */
	String sectionByHeading(String title, Pattern headingPattern, int charLimit)
	{
		try
		{
			for (JsonElement e : pageSections(title))
			{
				JsonObject s = e.getAsJsonObject();
				if (!headingPattern.matcher(s.get("line").getAsString()).find())
				{
					continue;
				}
				JsonObject sec = cachedGet(WIKI_API + "?action=parse&prop=wikitext&format=json"
					+ "&redirects=1&page=" + Http.enc(title) + "&section=" + s.get("index").getAsString());
				String text = sec.getAsJsonObject("parse").getAsJsonObject("wikitext")
					.get("*").getAsString();
				return truncate(scrubWikitext(text), charLimit);
			}
		}
		catch (Exception e)
		{
			log.debug("section fetch failed for {}", title, e);
		}
		return null;
	}

	/** Large tables often live on transcluded subpages ({{/Locations}});
	 * the raw wikitext only has the stub, so follow one level down. */
	private static final Pattern SUBPAGE_TRANSCLUSION =
		Pattern.compile("\\{\\{/([^}|{]+)(\\|[^}]*)?\\}\\}");

	/** Raw wikitext (preserves tables and templates), with directly
	 * transcluded subpages inlined. Null when the page doesn't exist. */
	String wikitext(String title, int charLimit)
	{
		try
		{
			String text = rawWikitext(title);
			text = inlineSubpages(title, text, charLimit);
			return withQuerySections(title, scrubWikitext(text), charLimit);
		}
		catch (Exception e)
		{
			log.debug("wikitext fetch failed for {}", title, e);
			return null;
		}
	}

	// ------------------------------------------------------------------
	// Render-time query sections
	// ------------------------------------------------------------------

	/** Sections whose whole body is a render-time query template are
	 * invisible to both extraction paths. "Used in recommended equipment"
	 * exists nowhere else, so it is rendered explicitly. */
	private static final String USED_IN_REC_EQUIP = "Used in recommended equipment";
	private static final Pattern REC_EQUIP_HUSK = Pattern.compile(
		"(\\{\\{Used in recommended equipment[^}]*\\}\\}|==+ *Used in recommended equipment *==+)");
	private static final int RENDERED_SECTION_CHAR_LIMIT = 2500;

	/** Top-level headings ("== X ==") in extract or wikitext form. */
	private static final Pattern TOP_HEADING =
		Pattern.compile("(?m)^== *([^=\\n]+?) *== *$");

	// ------------------------------------------------------------------
	// Wikitext scrubbing and section-aware budgeting
	// ------------------------------------------------------------------

	private static final Pattern GALLERY_BLOCK =
		Pattern.compile("(?is)<gallery[^>]*>.*?</gallery>");
	/** Cell prefix attributes that carry no content ("data-sort-value=..."). */
	private static final Pattern SORT_VALUE_ATTR =
		Pattern.compile("data-sort-value=\"[^\"\\n]*\" *\\| *");

	/** Removes wikitext with no semantic content: image/file links,
	 * gallery blocks, citation templates, sort-value cell attributes. */
	static String scrubWikitext(String text)
	{
		text = GALLERY_BLOCK.matcher(text).replaceAll("");
		text = stripBalanced(text, "[[file:", "[[", "]]");
		text = stripBalanced(text, "[[image:", "[[", "]]");
		text = stripBalanced(text, "{{cite", "{{", "}}");
		text = SORT_VALUE_ATTR.matcher(text).replaceAll("");
		return text;
	}

	/**
	 * Removes every occurrence of a balanced construct that starts with
	 * startToken (matched case-insensitively), tracking nesting: captions
	 * contain [[links]] and citations nest templates. An unclosed
	 * construct is left untouched.
	 */
	private static String stripBalanced(String text, String startToken, String open, String close)
	{
		String lower = text.toLowerCase(Locale.ROOT);
		StringBuilder out = new StringBuilder(text.length());
		int pos = 0;
		while (true)
		{
			int start = lower.indexOf(startToken, pos);
			if (start < 0)
			{
				out.append(text, pos, text.length());
				return out.toString();
			}
			int depth = 1;
			int i = start + open.length();
			while (i < text.length() && depth > 0)
			{
				if (lower.startsWith(open, i))
				{
					depth++;
					i += open.length();
				}
				else if (lower.startsWith(close, i))
				{
					depth--;
					i += close.length();
				}
				else
				{
					i++;
				}
			}
			out.append(text, pos, start);
			pos = depth == 0 ? i : start + open.length();
			if (depth != 0)
			{
				out.append(text, start, pos);
			}
		}
	}

	/** Spends an over-budget page's char limit on whole sections: the lead
	 * always ships, noise sections drop first, the rest are admitted whole
	 * in page order, and a section bigger than half the budget is weighed
	 * last. Pages with no usable sections fall back to a position cut. */
	static String budgetBySections(String text, int limit)
	{
		if (text.length() <= limit)
		{
			return text;
		}
		List<Integer> starts = new ArrayList<>();
		List<String> headings = new ArrayList<>();
		Matcher m = TOP_HEADING.matcher(text);
		while (m.find())
		{
			starts.add(m.start());
			headings.add(m.group(1).trim().toLowerCase(Locale.ROOT));
		}
		if (starts.isEmpty())
		{
			return truncate(text, limit);
		}
		String lead = text.substring(0, starts.get(0));
		if (lead.length() >= limit)
		{
			return truncate(text, limit);
		}
		List<String> ordered = new ArrayList<>();
		List<String> deferred = new ArrayList<>();
		for (int i = 0; i < starts.size(); i++)
		{
			if (NOISE_SECTIONS.contains(headings.get(i)))
			{
				continue;
			}
			int end = i + 1 < starts.size() ? starts.get(i + 1) : text.length();
			String section = text.substring(starts.get(i), end);
			// Admitted only into whatever budget the rest left over.
			(section.length() > limit / 2 ? deferred : ordered).add(section);
		}
		ordered.addAll(deferred);
		StringBuilder out = new StringBuilder(lead);
		int admitted = 0;
		for (String section : ordered)
		{
			if (out.length() + section.length() <= limit)
			{
				out.append(section);
				admitted++;
			}
		}
		// No section fit: the substance is one giant section, and a
		// position cut beats a bare lead.
		return admitted == 0 && !ordered.isEmpty() ? truncate(text, limit) : out.toString();
	}

	/** The page's TOC from the full pre-truncation text, so a reader of a
	 * truncated page still sees every section that exists. */
	static String tocLine(String text)
	{
		List<String> toc = new ArrayList<>();
		Matcher m = TOP_HEADING.matcher(text);
		while (m.find() && toc.size() < 15)
		{
			String heading = m.group(1).trim();
			if (!NOISE_SECTIONS.contains(heading.toLowerCase(Locale.ROOT))
				&& !toc.contains(heading))
			{
				toc.add(heading);
			}
		}
		return toc.size() >= 2 ? "[Sections: " + String.join("; ", toc) + "]\n\n" : "";
	}

	/** Truncate, then append any render-time query section rendered for
	 * real: the section sits at the tail of long pages where the budget
	 * would drop it. The in-place husk is removed. */
	private String withQuerySections(String title, String text, int charLimit)
	{
		boolean present = text.contains(USED_IN_REC_EQUIP);
		String out = tocLine(text) + budgetBySections(text, charLimit);
		if (!present)
		{
			return out;
		}
		String rendered = renderTemplate("{{" + USED_IN_REC_EQUIP + "|" + title + "}}");
		if (rendered == null || rendered.length() < 20)
		{
			return out;
		}
		out = REC_EQUIP_HUSK.matcher(out).replaceAll("");
		return out + "\n\n== " + USED_IN_REC_EQUIP + " ==\n"
			+ "(rank 1 = listed best-in-slot on that strategy page)\n"
			+ truncate(rendered, RENDERED_SECTION_CHAR_LIMIT);
	}

	/** Render one template invocation by itself and flatten the HTML. */
	private String renderTemplate(String wikitextCall)
	{
		try
		{
			JsonObject r = cachedGet(WIKI_API + "?action=parse&format=json&prop=text"
				+ "&contentmodel=wikitext&text=" + Http.enc(wikitextCall));
			return htmlToText(r.getAsJsonObject("parse").getAsJsonObject("text")
				.get("*").getAsString());
		}
		catch (Exception e)
		{
			log.debug("template render failed for {}", wikitextCall, e);
			return null;
		}
	}

	/** Row-preserving HTML flattening: block closers become line breaks,
	 * tags go, the entities that appear in game names are unescaped. */
	private static String htmlToText(String html)
	{
		String text = html
			.replaceAll("(?i)</(tr|li|p|h[1-6]|caption)>", "\n")
			.replaceAll("<[^>]+>", " ")
			.replace("&amp;", "&").replace("&#39;", "'").replace("&quot;", "\"")
			.replace("&lt;", "<").replace("&gt;", ">").replace("&nbsp;", " ");
		StringBuilder out = new StringBuilder();
		for (String line : text.split("\n"))
		{
			String collapsed = line.replaceAll("\\s+", " ").trim();
			if (!collapsed.isEmpty())
			{
				out.append(collapsed).append('\n');
			}
		}
		return out.toString().trim();
	}

	private String rawWikitext(String title) throws IOException
	{
		JsonObject r = cachedGet(WIKI_API + "?action=parse&prop=wikitext&format=json"
			+ "&redirects=1&page=" + Http.enc(title));
		return r.getAsJsonObject("parse").getAsJsonObject("wikitext")
			.get("*").getAsString();
	}

	private String inlineSubpages(String title, String text, int charLimit)
	{
		Matcher m = SUBPAGE_TRANSCLUSION.matcher(text);
		StringBuffer sb = new StringBuffer();
		while (m.find() && sb.length() < charLimit)
		{
			String replacement;
			try
			{
				replacement = rawWikitext(title + "/" + m.group(1).trim());
			}
			catch (Exception e)
			{
				replacement = m.group(0);
			}
			m.appendReplacement(sb, Matcher.quoteReplacement(replacement));
		}
		m.appendTail(sb);
		return sb.toString();
	}

	private static String truncate(String s, int limit)
	{
		return s.length() > limit ? s.substring(0, limit) : s;
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Predicate;
import lombok.extern.slf4j.Slf4j;

/**
 * Structured game-data lookups over the wiki's buckets and the prices API.
 * Returns error maps rather than nulls because the LLM tool boundary wants
 * the message.
 */
@Slf4j
class WikiLookups
{
	private static final String PRICES_API = "https://prices.runescape.wiki/api";

	private final Http http;
	private final Gson gson;
	private final WikiContent content;
	private final VocabSnapshots vocab;

	WikiLookups(Http http, Gson gson, WikiContent content, VocabSnapshots vocab)
	{
		this.http = http;
		this.gson = gson;
		this.content = content;
		this.vocab = vocab;
	}

	/** Best-effort canonical item name via tradeable catalogue names, else
	 * wiki search. */
	String resolveItemName(String name)
	{
		try
		{
			String exact = mappingMatch(name);
			if (exact != null)
			{
				return exact;
			}
		// Try the wiki's curated redirects before substring matching. GE
		// names carry charge qualifiers players never type ("Toxic
		// blowpipe (empty)"), so a redirect target also matches its
		// qualified variant.
			String target = content.resolveTitles(List.of(name)).get(name);
			if (target != null)
			{
				String viaRedirect = mappingMatch(target);
				if (viaRedirect != null)
				{
					return viaRedirect;
				}
				String qualified = qualifiedVariant(target);
				return qualified != null ? qualified : target;
			}
			String lower = name.toLowerCase(Locale.ROOT);
			String shortestPartial =
				scanTradeables(c -> c.toLowerCase(Locale.ROOT).contains(lower));
			if (shortestPartial != null)
			{
				return shortestPartial;
			}
			List<Map<String, Object>> hits = content.search(name);
			if (!hits.isEmpty() && hits.get(0).containsKey("title"))
			{
				return (String) hits.get(0).get("title");
			}
		}
		catch (Exception e)
		{
			log.debug("resolveItemName failed for {}", name, e);
		}
		return name;
	}

	/** Case-insensitive exact match against tradeable names, or null. */
	private String mappingMatch(String name) throws IOException
	{
		return scanTradeables(c -> c.equalsIgnoreCase(name));
	}

	/** Shortest "Name (qualifier)" tradeable name, or null. */
	private String qualifiedVariant(String name) throws IOException
	{
		String prefix = name.toLowerCase(Locale.ROOT) + " (";
		return scanTradeables(c -> c.toLowerCase(Locale.ROOT).startsWith(prefix));
	}

	/** Shortest tradeable catalogue name satisfying the predicate, or null;
	 * shortest is the least-decorated variant. */
	private String scanTradeables(Predicate<String> match) throws IOException
	{
		String best = null;
		for (ItemDescriptor it : vocab.itemCatalog())
		{
			if (it.tradeable && match.test(it.name)
				&& (best == null || it.name.length() < best.length()))
			{
				best = it.name;
			}
		}
		return best;
	}

	/** Every acquisition route with structured data: drops, recipes, shop
	 * stock, GE tradeability. Routes with no data are omitted. Quest and
	 * minigame rewards have no bucket and stay page-prose. */
	Map<String, Object> itemSources(String itemName)
	{
		Map<String, Object> result = new LinkedHashMap<>();
		try
		{
		// Buckets key on the PAGE name, which can differ from the GE
		// canonical ("Bow of Faerdhinen (inactive)" trades; its bucket
		// rows are "Bow of Faerdhinen"). Resolve the page first.
			String page = content.resolveTitles(List.of(itemName)).get(itemName);
			String canonical = page != null ? page : resolveItemName(itemName);
			result.put("item", canonical);
			if (!canonical.equalsIgnoreCase(itemName))
			{
				result.put("resolved", "'" + itemName + "' resolved to '" + canonical + "'");
			}
			List<Map<String, Object>> drops = dropSources(canonical);
			if (!drops.isEmpty())
			{
				result.put("drops", drops);
			}
			List<Map<String, Object>> creation = recipes(canonical);
			if (!creation.isEmpty())
			{
				result.put("creation", creation);
			}
			List<Map<String, Object>> shops = shopStock(canonical);
			if (!shops.isEmpty())
			{
				result.put("shops", shops);
			}
			String geName = mappingMatch(canonical) != null
				? canonical : qualifiedVariant(canonical);
			result.put("tradeable_on_ge", geName != null);
			if (geName != null && !geName.equals(canonical))
			{
				result.put("ge_item", geName);
			}
			if (drops.isEmpty() && creation.isEmpty() && shops.isEmpty())
			{
				result.put("note", "No drop, creation, or shop sources found for '" + canonical
					+ "'. Quest and minigame rewards are not covered here; check wiki_page.");
			}
		}
		catch (Exception e)
		{
			result.put("error", "lookup failed: " + e.getMessage());
		}
		return result;
	}

	/** Dropsline rows for an item: monster and reward-chest sources. */
	private List<Map<String, Object>> dropSources(String canonical) throws IOException
	{
		JsonObject r = content.bucket("bucket('dropsline').select('page_name','drop_json')"
			+ ".where('item_name','" + esc(canonical) + "').limit(50).run()");
		List<Map<String, Object>> out = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (JsonElement row : r.getAsJsonArray("bucket"))
		{
			Map<String, Object> entry = dropRow(row.getAsJsonObject(), "source", seen);
			if (entry != null)
			{
				out.add(entry);
				if (out.size() >= 30)
				{
					break;
				}
			}
		}
		return out;
	}

	/** One dropsline row as {identity, quantity, rarity}, or null when the
	 * row lacks drop_json or repeats an entry. "source" reads the dropping
	 * monster; anything else reads the item_name. */
	private Map<String, Object> dropRow(JsonObject o, String idKey, Set<String> seen)
	{
		if (!o.has("drop_json"))
		{
			return null;
		}
		JsonObject dj = gson.fromJson(o.get("drop_json").getAsString(), JsonObject.class);
		String id = "source".equals(idKey)
			? (dj.has("Dropped from") ? dj.get("Dropped from").getAsString()
				: jstr(o, "page_name", "?"))
			: jstr(o, "item_name", "?");
		String qty = dj.has("Drop Quantity") ? dj.get("Drop Quantity").getAsString() : "?";
		String rarity = dj.has("Rarity") ? dj.get("Rarity").getAsString() : "?";
		if (!seen.add(id + "|" + qty + "|" + rarity))
		{
			return null;
		}
		Map<String, Object> entry = new LinkedHashMap<>();
		entry.put(idKey, id);
		entry.put("quantity", qty);
		entry.put("rarity", rarity);
		return entry;
	}

	/** Recipe rows rendered as compact strings ("100 x Crystal shard",
	 * "82 Smithing (boostable)"). */
	private List<Map<String, Object>> recipes(String canonical) throws IOException
	{
		JsonObject r = content.bucket("bucket('recipe').select('production_json')"
			+ ".where('page_name','" + esc(canonical) + "').limit(5).run()");
		List<Map<String, Object>> out = new ArrayList<>();
		JsonArray rows = r.getAsJsonArray("bucket");
		if (rows == null)
		{
			return out;
		}
		for (JsonElement row : rows)
		{
			JsonObject o = row.getAsJsonObject();
			if (!o.has("production_json"))
			{
				continue;
			}
			JsonObject pj = gson.fromJson(o.get("production_json").getAsString(), JsonObject.class);
			Map<String, Object> rec = new LinkedHashMap<>();
			List<String> materials = new ArrayList<>();
			if (pj.has("materials") && pj.get("materials").isJsonArray())
			{
				for (JsonElement m : pj.getAsJsonArray("materials"))
				{
					JsonObject mo = m.getAsJsonObject();
					materials.add(jstr(mo, "quantity", "?") + " x " + jstr(mo, "name", "?"));
				}
			}
			List<String> skills = new ArrayList<>();
			if (pj.has("skills") && pj.get("skills").isJsonArray())
			{
				for (JsonElement s : pj.getAsJsonArray("skills"))
				{
					JsonObject so = s.getAsJsonObject();
					String skill = jstr(so, "level", "?") + " " + jstr(so, "name", "?");
					if ("Yes".equalsIgnoreCase(jstr(so, "boostable", "")))
					{
						skill += " (boostable)";
					}
					skills.add(skill);
				}
			}
			if (!materials.isEmpty())
			{
				rec.put("materials", materials);
			}
			if (!skills.isEmpty())
			{
				rec.put("skills", skills);
			}
			String facility = jstr(pj, "facilities", "");
			if (!facility.isEmpty())
			{
				rec.put("facility", facility);
			}
			if (!rec.isEmpty())
			{
				out.add(rec);
			}
		}
		return out;
	}

	/** Storeline-bucket rows: shops stocking the item, with price and stock. */
	private List<Map<String, Object>> shopStock(String canonical) throws IOException
	{
		JsonObject r = content.bucket("bucket('storeline')"
			+ ".select('sold_by','store_buy_price','store_currency','store_stock')"
			+ ".where('sold_item','" + esc(canonical) + "').limit(10).run()");
		List<Map<String, Object>> out = new ArrayList<>();
		JsonArray rows = r.getAsJsonArray("bucket");
		if (rows == null)
		{
			return out;
		}
		for (JsonElement row : rows)
		{
			JsonObject o = row.getAsJsonObject();
			Map<String, Object> entry = new LinkedHashMap<>();
			entry.put("shop", jstr(o, "sold_by", "?"));
			String price = jstr(o, "store_buy_price", "");
			String currency = jstr(o, "store_currency", "");
			if (!price.isEmpty())
			{
				entry.put("price", (price + " " + currency).trim());
			}
			String stock = jstr(o, "store_stock", "");
			if (!stock.isEmpty())
			{
				entry.put("stock", stock);
			}
			out.add(entry);
		}
		return out;
	}

	private static String jstr(JsonObject o, String key, String fallback)
	{
		return o.has(key) && !o.get(key).isJsonNull() && o.get(key).isJsonPrimitive()
			? o.get(key).getAsString() : fallback;
	}

	/** First row of a bucket result with null fields dropped, or null when
	 * nothing matched. */
	private Map<String, Object> firstRow(JsonObject r)
	{
		JsonArray rows = r.getAsJsonArray("bucket");
		if (rows == null || rows.size() == 0)
		{
			return null;
		}
		Map<String, Object> info = gson.fromJson(rows.get(0),
			new TypeToken<Map<String, Object>>() { }.getType());
		info.values().removeIf(Objects::isNull);
		return info;
	}

	/** Bucket query values sit in single quotes; escape accordingly. */
	private static String esc(String s)
	{
		return s.replace("'", "\\'");
	}

	/** Full drop table of a monster. */
	Map<String, Object> monsterDrops(String name)
	{
		try
		{
			JsonObject r = content.bucket("bucket('dropsline').select('item_name','drop_json')"
				+ ".where('page_name','" + esc(name) + "').limit(80).run()");
			JsonArray rows = r.getAsJsonArray("bucket");
			if (rows == null || rows.size() == 0)
			{
				// Monster page names are exact; try to resolve via search once.
				List<Map<String, Object>> hits = content.search(name);
				if (!hits.isEmpty() && hits.get(0).containsKey("title")
					&& !name.equals(hits.get(0).get("title")))
				{
					return monsterDrops((String) hits.get(0).get("title"));
				}
				return Map.of("error", "No drop data found for '" + name + "'.");
			}
			List<Map<String, Object>> out = new ArrayList<>();
			Set<String> seen = new HashSet<>();
			for (JsonElement row : rows)
			{
				Map<String, Object> entry = dropRow(row.getAsJsonObject(), "item", seen);
				if (entry != null)
				{
					out.add(entry);
				}
			}
			Map<String, Object> result = new LinkedHashMap<>();
			result.put("monster", name);
			result.put("drops", out);
			return result;
		}
		catch (Exception e)
		{
			return Map.of("error", "lookup failed: " + e.getMessage());
		}
	}

	/** Combat profile of a monster: defensive stats, attributes, and
	 * immunities. Deliberately complete -- omissions invite the model to
	 * fill gaps from stale priors. */
	Map<String, Object> monsterInfo(String name)
	{
		return firstRowLookup("bucket('infobox_monster')"
			+ ".select('name','combat_level','hitpoints','max_hit',"
			+ "'slayer_level','slayer_category','attribute',"
			+ "'attack_level','strength_level','defence_level','ranged_level','magic_level',"
			+ "'stab_defence_bonus','slash_defence_bonus','crush_defence_bonus',"
			+ "'magic_defence_bonus','light_range_defence_bonus',"
			+ "'standard_range_defence_bonus','heavy_range_defence_bonus',"
			+ "'attack_style','attack_speed','size',"
			+ "'poison_resistance','venom_resistance','cannon_immune','burn_immune',"
			+ "'freeze_resistance','elemental_weakness','elemental_weakness_percent')"
			+ ".where('name','" + esc(name) + "').limit(3).run()",
			"No monster named '" + name + "' found. Check spelling via wiki_search.",
			info ->
			{
				// The bucket carries "ERR" where the wiki's own template
				// data is broken; junk, not a value.
				info.values().removeIf("ERR"::equals);
				info.replaceAll((k, v) -> stripMarkup(v));
			});
	}

	/** Equipment combat bonuses; infoboxes never survive plaintext
	 * extracts, so this bucket is the only numeric source. No attack-speed
	 * or slot fields -- those live in page prose. */
	Map<String, Object> itemStats(String name)
	{
		return firstRowLookup("bucket('infobox_bonuses')"
			+ ".select('page_name',"
			+ "'stab_attack_bonus','slash_attack_bonus','crush_attack_bonus',"
			+ "'magic_attack_bonus','range_attack_bonus',"
			+ "'stab_defence_bonus','slash_defence_bonus','crush_defence_bonus',"
			+ "'magic_defence_bonus','range_defence_bonus',"
			+ "'strength_bonus','ranged_strength_bonus','magic_damage_bonus','prayer_bonus')"
			+ ".where('page_name','" + esc(name) + "').limit(3).run()",
			"No equipment stats for '" + name
				+ "'. It may not be wearable, or the name may differ; check via wiki_search.",
			info -> info.replaceAll((k, v) -> stripMarkup(v)));
	}

	/** Quest requirements from the quest bucket; the {{Quest details}}
	 * template never survives plaintext extracts, so this is the only
	 * source of skill levels and the prerequisite tree. */
	Map<String, Object> questInfo(String name)
	{
		return firstRowLookup("bucket('quest')"
			+ ".select('page_name','requirements','items_required','start_point')"
			+ ".where('page_name','" + esc(name) + "').limit(2).run()",
			"No quest named '" + name + "' found. Check spelling via wiki_search.",
			info -> info.replaceAll((k, v) ->
				v instanceof String ? flattenWikitext((String) v) : v));
	}

	/** One-row bucket lookup: the first match, cleaned in place, or an
	 * error map when nothing matched or the query failed. */
	private Map<String, Object> firstRowLookup(String query, String notFound,
		Consumer<Map<String, Object>> clean)
	{
		try
		{
			Map<String, Object> info = firstRow(content.bucket(query));
			if (info == null)
			{
				return Map.of("error", notFound);
			}
			clean.accept(info);
			return info;
		}
		catch (Exception e)
		{
			return Map.of("error", "lookup failed: " + e.getMessage());
		}
	}

	/** Line-preserving cleanup for wikitext bucket fields: drops icon file
	 * links, unwraps [[page|label]] links, and strips HTML, but keeps the
	 * "*"/"**" bullet nesting that encodes the prerequisite tree. */
	private static String flattenWikitext(String wikitext)
	{
		StringBuilder sb = new StringBuilder();
		for (String line : wikitext.split("\n"))
		{
			String s = line
				.replaceAll("\\[\\[File:[^\\]]*\\]\\]", "")
				.replaceAll("\\[\\[[^|\\]]*\\|([^\\]]*)\\]\\]", "$1")
				.replaceAll("\\[\\[([^\\]]*)\\]\\]", "$1")
				.replaceAll("<[^>]+>", "")
				.replaceAll("[ \t]+", " ")
				.trim();
			if (!s.isEmpty() && !s.matches("\\**"))
			{
				sb.append(s).append('\n');
			}
		}
		return sb.toString().trim();
	}

	/** Bucket TEXT fields can carry raw HTML ("<div class=..>*31 (auto)");
	 * flatten to plain text so stat blocks stay readable. */
	@SuppressWarnings("unchecked")
	private static Object stripMarkup(Object value)
	{
		if (value instanceof String)
		{
			return ((String) value).replaceAll("<[^>]+>", " ")
				.replaceAll("[\\s*]+", " ").trim();
		}
		if (value instanceof List)
		{
			List<Object> out = new ArrayList<>();
			for (Object v : (List<Object>) value)
			{
				out.add(stripMarkup(v));
			}
			return out;
		}
		return value;
	}

	/** Current GE price, buy limit, and high-alch value. */
	Map<String, Object> gePrice(String itemName)
	{
		try
		{
			String canonical = resolveItemName(itemName);
			for (ItemDescriptor it : vocab.itemCatalog())
			{
				if (!it.tradeable || !canonical.equals(it.name))
				{
					continue;
				}
				JsonObject r = http.getJson(PRICES_API + "/v2/osrs/latest?id=" + it.id);
				JsonObject data = r.getAsJsonObject("data").getAsJsonObject(String.valueOf(it.id));
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("item", canonical);
				out.put("high", data != null && data.has("high") && !data.get("high").isJsonNull()
					? data.get("high").getAsLong() : null);
				out.put("low", data != null && data.has("low") && !data.get("low").isJsonNull()
					? data.get("low").getAsLong() : null);
				out.put("buy_limit", it.limit);
				out.put("high_alch", it.highAlch);
				return out;
			}
			return Map.of("error", "'" + itemName + "' is not a tradeable item.");
		}
		catch (Exception e)
		{
			return Map.of("error", "lookup failed: " + e.getMessage());
		}
	}
}

package com.osrscopilot.pipeline;

/** Official OSRS experience table math. */
final class XpTable
{
	private XpTable()
	{
	}

	static int xpForLevel(int level)
	{
		double points = 0;
		for (int lvl = 1; lvl < level; lvl++)
		{
			points += Math.floor(lvl + 300 * Math.pow(2, lvl / 7.0));
		}
		return (int) Math.floor(points / 4);
	}

	/** Returns {currentLevel, nextLevel (or -1 at 99), xpNeeded}. */
	static int[] toNextLevel(int currentXp)
	{
		int level = 1;
		for (int lvl = 2; lvl < 100; lvl++)
		{
			if (currentXp >= xpForLevel(lvl))
			{
				level = lvl;
			}
		}
		if (level >= 99)
		{
			return new int[]{99, -1, 0};
		}
		return new int[]{level, level + 1, xpForLevel(level + 1) - currentXp};
	}
}

package com.osrscopilot;

import com.osrscopilot.pipeline.EntityResolver;
import com.osrscopilot.pipeline.GameCapture;
import com.osrscopilot.pipeline.ItemDescriptor;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AnswerDecoratorTest
{
	private static AnswerDecorator bankDecorator()
	{
		EntityResolver.Resolution entities = new EntityResolver.Resolution();
		entities.pages.add("Bank");
		return AnswerDecorator.build(new GameCapture(), entities, List.of(), List.of(), null);
	}

	@Test
	public void fragmentOfLargerProperNounIsNotDecorated()
	{
		String html = bankDecorator().decorate(
			"Your closest bank is the Bank of Gielinor in Yanille.");
		// The standalone lowercase mention still links...
		assertTrue(html.contains("closest <a"));
		// ...but "Bank" inside the invented proper noun must stay bare.
		assertTrue(html.contains("Bank of Gielinor"));
		assertFalse(html.contains(">Bank</font>"));
	}

	@Test
	public void fragmentGuardStopsAtPhraseEnd()
	{
		// "Bank" followed by lowercase prose is a whole name, not a fragment.
		String html = bankDecorator().decorate("The Bank is north of the anvil.");
		assertTrue(html.contains(">Bank</font>"));
	}

	@Test
	public void connectorWithoutCapitalDoesNotSuppress()
	{
		String html = bankDecorator().decorate("Use the bank of the city centre.");
		assertTrue(html.contains(">bank</font>"));
	}

	private static AnswerDecorator demonDecorator(boolean withMonsterVocab)
	{
		EntityResolver.Resolution entities = new EntityResolver.Resolution();
		entities.pages.add("Demon");
		List<String> monsters = withMonsterVocab ? List.of("Greater demon") : List.of();
		return AnswerDecorator.build(new GameCapture(), entities, monsters, List.of(), null);
	}

	@Test
	public void tailOfLargerProperNounIsNotDecorated()
	{
		// "demons" is the tail of "Greater demons"; the Demon page would
		// mislabel it, and no rule knows the longer name.
		String html = demonDecorator(false)
			.decorate("Kill the Greater demons in the Catacombs.");
		assertFalse(html.contains("<a"));
	}

	@Test
	public void sentenceOpeningCapitalDoesNotSuppress()
	{
		// "The" is capitalized only because it opens the sentence.
		String html = demonDecorator(false).decorate("The demons there are aggressive.");
		assertTrue(html.contains(">demons</font>"));
	}

	@Test
	public void monsterVocabularyClaimsWholePhrase()
	{
		// The vocabulary knows "Greater demon" even though the route never
		// resolved it; longest-first beats the "Demon" page fragment.
		String html = demonDecorator(true).decorate("Kill the Greater demons there.");
		assertTrue(html.contains(">Greater demons</font>"));
	}

	@Test
	public void bareUntradeableYieldsToALongerNameInTheSameAnswer()
	{
		// "the totem" beside "Dark totem pieces" means the dark totem; the
		// Legends' Quest "Totem" item must not claim it.
		List<ItemDescriptor> items = List.of(
			new ItemDescriptor("Totem", "Totem", 1857, false, null, null),
