		String html = AnswerDecorator.build(new GameCapture(),
			new EntityResolver.Resolution(), List.of(), items, null)
			.decorate("Bring your Fire cape (l) along.");
		assertTrue(html.contains("/w/Fire_cape'"));
		assertTrue(html.contains(">Fire cape (l)</font>"));
	}
}

package com.osrscopilot;

import com.google.gson.Gson;
import com.osrscopilot.pipeline.CopilotPipeline;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The answer footer is the plugin's disclosure and attribution line: every
 * wiki page the answer drew on -- prefetched fact or tool fetch -- must link
 * its edit history (the contributors hold the copyright), game-state blocks
 * must display their short names without their model-facing instructions,
 * and nothing may leak unescaped HTML.
 */
public class AnswerMetaTest
{
	private static final Gson GSON = new Gson();

	private static String answerMeta(CopilotPipeline.Result result)
	{
		return CopilotPlugin.answerMeta(result, GSON);
	}

	private static CopilotPipeline.Result result(List<String> factTitles, List<String> toolLog)
	{
		CopilotPipeline.Result r = new CopilotPipeline.Result();
		r.factTitles = factTitles;
		r.toolLog = toolLog;
		return r;
	}

	@Test
	public void wikiFactsLinkTheirSourcePageHistory()
	{
		String meta = answerMeta(result(List.of("Monster info: Vorkath"), List.of()));
		assertTrue(meta.contains(
			"<a href='https://oldschool.runescape.wiki/w/Vorkath?action=history'>"));
		assertTrue("links must be visibly underlined", meta.contains("<u>Monster info: Vorkath</u>"));
	}

	@Test
	public void gameStateFactsDisplayShortAndUnlinked()
	{
		String meta = answerMeta(result(
			List.of("Quest progress (authoritative, from the game client)"), List.of()));
		assertTrue(meta.contains("Quest progress"));
		assertFalse(meta.contains("authoritative"));
		assertFalse(meta.contains("<a "));
	}

	@Test
	public void pageBackedToolCallsLinkAndSimplify()
	{
		String meta = answerMeta(result(List.of(),
			List.of("wiki_page({\"title\":\"Castaway\"})")));
		assertTrue(meta.contains(
			"<a href='https://oldschool.runescape.wiki/w/Castaway?action=history'>"));
		assertTrue(meta.contains("<u>wiki_page(Castaway)</u>"));
	}

	@Test
	public void searchCallsSimplifyWithoutLinking()
	{
		String meta = answerMeta(result(List.of(),
			List.of("wiki_search({\"query\":\"dog pet update 2025\"})")));
		assertTrue(meta.contains("wiki_search(dog pet update 2025)"));
		assertFalse(meta.contains("<a "));
		assertFalse("json syntax should not reach the display", meta.contains("&quot;query&quot;"));
	}

	@Test
	public void multiArgumentToolCallsFallBackToTheRawEntry()
	{
		String entry = "search_owned_items({\"queries\":[\"slayer helmet\",\"dragon boots\"]})";
		String meta = answerMeta(result(List.of(), List.of(entry)));
		assertTrue(meta.contains("search_owned_items"));
		assertTrue(meta.contains("slayer helmet"));
		assertFalse(meta.contains("<a "));
	}

	@Test
	public void emptyResultSaysSo()
	{
		assertEquals("no facts retrieved", answerMeta(result(List.of(), List.of())));
	}
}

package com.osrscopilot;

import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The out-of-band bank trackers must be conservative: only credit what the
 * arithmetic proves was deposited or collected, and clear rather than guess
 * on any ambiguous path. A missed credit self-heals at the next bank open;
 * an invented one is a wrong ownership answer until then.
 */
public class BankMutationsTest
{
	// --- deposit box container diffs ---

	@Test
	public void decreasesDetectDepositsOnly()
	{
		Map<Integer, Integer> before = Map.of(385, 5, 560, 200, 4151, 1);
		Map<Integer, Integer> after = Map.of(385, 2, 560, 250, 4151, 1);
		// Sharks went down (deposit), death runes went UP (withdrawal has no
		// deposit-box path, but an increase must never become a credit),
		// the whip is unchanged.
		assertEquals(Map.of(385, 3), BankMutations.decreases(before, after));
	}

	@Test
	public void itemFullyDepositedIsItsWholeStack()
	{
		Map<Integer, Integer> before = Map.of(11212, 4663);
		Map<Integer, Integer> after = Map.of();
		assertEquals(Map.of(11212, 4663), BankMutations.decreases(before, after));
	}

	@Test
	public void itemAppearingFromNowhereIsNotADeposit()
	{
		Map<Integer, Integer> before = Map.of();
		Map<Integer, Integer> after = Map.of(385, 5);
		assertTrue(BankMutations.decreases(before, after).isEmpty());
	}

	// --- GE slot bookkeeping ---

	@Test
	public void buyFillsAccrueAsUncollected()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(0, GrandExchangeOfferState.BUYING, 560, 100, 1000);
		slots.offerChanged(0, GrandExchangeOfferState.BUYING, 560, 350, 1000);
		slots.offerChanged(0, GrandExchangeOfferState.BOUGHT, 560, 1000, 1000);

		List<int[]> credits = slots.drain();
		assertEquals(1, credits.size());
		assertEquals(560, credits.get(0)[0]);
		assertEquals(1000, credits.get(0)[1]);
	}

	@Test
	public void drainClearsWhatItReturned()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(2, GrandExchangeOfferState.BUYING, 560, 100, 1000);
		slots.drain();
		assertTrue("second drain must not double-credit", slots.drain().isEmpty());
	}

	@Test
	public void newOfferReusingASlotStartsFresh()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(0, GrandExchangeOfferState.BOUGHT, 560, 500, 500);
		slots.offerChanged(0, GrandExchangeOfferState.EMPTY, 0, 0, 0);
		slots.offerChanged(0, GrandExchangeOfferState.BUYING, 385, 10, 100);

		List<int[]> credits = slots.drain();
		assertEquals(1, credits.size());
		assertEquals(385, credits.get(0)[0]);
		assertEquals(10, credits.get(0)[1]);
	}

	@Test
	public void sameItemNewOfferDetectedByQuantityResetDropsStaleAccrual()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(0, GrandExchangeOfferState.BOUGHT, 560, 500, 500);
		// No EMPTY seen between offers: the first offer's items were
		// collected while untracked, so its accrual is stale.
		// The new offer's lower quantitySold is the tell; only its own
		// fills may credit.
		slots.offerChanged(0, GrandExchangeOfferState.BUYING, 560, 20, 300);

		List<int[]> credits = slots.drain();
		assertEquals(1, credits.size());
		assertEquals(20, credits.get(0)[1]);
	}

	@Test
	public void cancelledSellRemainderCollectsAsItems()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(1, GrandExchangeOfferState.SELLING, 4151, 3, 10);
		slots.offerChanged(1, GrandExchangeOfferState.CANCELLED_SELL, 4151, 3, 10);

		List<int[]> credits = slots.drain();
		assertEquals(1, credits.size());
		assertEquals(4151, credits.get(0)[0]);
		assertEquals(7, credits.get(0)[1]);
	}

	@Test
	public void sellProceedsAreCoinsNotItems()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(1, GrandExchangeOfferState.SELLING, 4151, 3, 10);
		slots.offerChanged(1, GrandExchangeOfferState.SOLD, 4151, 10, 10);
		assertTrue(slots.drain().isEmpty());
	}

	@Test
	public void clearDropsUncollectedWithoutCrediting()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(0, GrandExchangeOfferState.BOUGHT, 560, 500, 500);
		slots.clear();
		assertTrue(slots.drain().isEmpty());
	}

	@Test
	public void outOfRangeSlotIsIgnored()
	{
		BankMutations.GeSlots slots = new BankMutations.GeSlots();
		slots.offerChanged(-1, GrandExchangeOfferState.BOUGHT, 560, 5, 5);
		slots.offerChanged(8, GrandExchangeOfferState.BOUGHT, 560, 5, 5);
		assertTrue(slots.drain().isEmpty());
	}

	// --- drift audit ---

	@Test
	public void matchingPredictionReportsNoDrift()
	{
		List<Map<String, Object>> bank = List.of(
			Map.of("id", 11212.0, "name", "Dragon arrow", "quantity", 4663.0));
		assertNull(BankMutations.drift(bank, bank));
	}

	@Test
	public void nothingPredictedReportsNoDrift()
	{
		assertNull(BankMutations.drift(null,
			List.of(Map.of("id", 385, "name", "Shark", "quantity", 5))));
	}

	@Test
	public void driftNamesTheStacksThatAreOff()
	{
		List<Map<String, Object>> predicted = List.of(
			Map.of("id", 11212, "name", "Dragon arrow", "quantity", 4663),
			Map.of("id", 560, "name", "Death rune", "quantity", 200));
		List<Map<String, Object>> actual = List.of(
			Map.of("id", 11212, "name", "Dragon arrow", "quantity", 4700),
			Map.of("id", 385, "name", "Shark", "quantity", 5));

		String drift = BankMutations.drift(predicted, actual);
		assertTrue(drift.contains("item 11212 +37"));
		assertTrue("unpredicted stack must show", drift.contains("item 385 +5"));
		assertTrue("vanished stack must show", drift.contains("item 560 -200"));
		assertTrue(drift.startsWith("3 stacks off prediction"));
	}
}

package com.osrscopilot;

import com.google.gson.Gson;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class BankStoreTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private final Gson gson = new Gson();

	private static final List<Map<String, Object>> ITEMS = List.of(
		Map.of("id", 11212.0, "name", "Dragon arrow", "quantity", 4663.0));

	@Test
	public void persistedBankSurvivesRestart()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.sync(42L);
		store.update(ITEMS);

		BankStore reopened = new BankStore(tmp.getRoot(), gson, Runnable::run);
		reopened.sync(42L);
		assertEquals(1, reopened.contents().size());
		assertEquals("Dragon arrow", reopened.contents().get(0).get("name"));
	}

	@Test
	public void accountSwitchNeverInheritsAnotherAccountsBank()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.sync(42L);
		store.update(ITEMS);

		store.sync(99L);
		assertNull("fresh account must start with no bank", store.contents());

		// Switching back restores the first account's persisted bank.
		store.sync(42L);
		assertEquals(1, store.contents().size());
	}

	@Test
	public void noAccountSeenMeansNothingPersisted()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.update(ITEMS);
		// No account hash yet: nothing may be written to disk.
		assertEquals(0, tmp.getRoot().listFiles((d, n) -> n.startsWith("bank-")).length);
	}

	@Test
	public void creditMergesIntoTheExistingStack()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.sync(42L);
		store.update(ITEMS);

		store.credit(11212, "Dragon arrow", 150);

		assertEquals(1, store.contents().size());
		assertEquals(4813L,
			((Number) store.contents().get(0).get("quantity")).longValue());
	}

	@Test
	public void creditAppendsAnItemNotYetBanked()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.sync(42L);
		store.update(ITEMS);

		store.credit(560, "Death rune", 200);

		assertEquals(2, store.contents().size());
		Map<String, Object> added = store.contents().get(1);
		assertEquals("Death rune", added.get("name"));
		assertEquals(200L, ((Number) added.get("quantity")).longValue());
	}

	@Test
	public void creditPersistsAcrossRestart()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.sync(42L);
		store.update(ITEMS);
		store.credit(11212, "Dragon arrow", 37);

		BankStore reopened = new BankStore(tmp.getRoot(), gson, Runnable::run);
		reopened.sync(42L);
		assertEquals(4700L,
			((Number) reopened.contents().get(0).get("quantity")).longValue());
	}

	@Test
	public void creditWithoutASnapshotIsRefused()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.sync(42L);
		// No capture ever seen: there is nothing sound to patch.
		store.credit(11212, "Dragon arrow", 5);
		assertNull(store.contents());
		assertEquals(0, tmp.getRoot().listFiles((d, n) -> n.startsWith("bank-")).length);
	}

	@Test
	public void creditDoesNotMutateTheCapturedList()
	{
		BankStore store = new BankStore(tmp.getRoot(), gson, Runnable::run);
		store.sync(42L);
		store.update(ITEMS);
		List<Map<String, Object>> captured = store.contents();

		// A pipeline run may be reading the captured list off-thread;
		// credits must swap the reference, never mutate in place.
		store.credit(560, "Death rune", 200);

		assertEquals(1, captured.size());
		assertEquals(4663L,
			((Number) captured.get(0).get("quantity")).longValue());
	}
}

