package com.osrscopilot;

import com.osrscopilot.pipeline.EntityResolver;
import com.osrscopilot.pipeline.GameCapture;
import com.osrscopilot.pipeline.ItemDescriptor;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.List;
import java.util.Map;
import javax.imageio.ImageIO;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The store renders from the live client, which tests cannot host; what is
 * testable is the contract around it: ID-keyed disk serving, fail-soft
 * misses, and the decorator resolving icons by item ID instead of guessed
 * filename.
 */
public class IconStoreTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private static final int WHIP = 4151;

	private IconStore storeWith(String... pngNames) throws Exception
	{
		File dir = tmp.newFolder();
		for (String name : pngNames)
		{
			ImageIO.write(new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB),
				"png", new File(dir, name));
		}
		// Null managers: outside the client only disk content is served.
		return new IconStore(dir, null, null, null);
	}

	@Test
	public void servesDiskIconsByIdAndFailsSoftWithoutClient() throws Exception
	{
		IconStore store = storeWith("item-" + WHIP + ".png", "skill-attack.png", "quest.png");
		assertTrue(store.itemIconUrl(WHIP).endsWith("item-" + WHIP + ".png"));
		assertTrue(store.skillIconUrl("Attack").endsWith("skill-attack.png"));
		assertTrue(store.questIconUrl().endsWith("quest.png"));
		// Unrendered sprite, no client to render it: null, never an error.
		assertNull(store.itemIconUrl(9999));
		assertNull(store.skillIconUrl("Sailing"));
	}

	@Test
	public void decoratorResolvesOwnedItemIconsByCapturedId() throws Exception
	{
		IconStore store = storeWith("item-" + WHIP + ".png");
		GameCapture cap = new GameCapture();
		cap.equipment = List.of(Map.of("id", WHIP, "name", "Abyssal whip", "quantity", 1));

		String html = AnswerDecorator
			.build(cap, new EntityResolver.Resolution(), List.of(),
				List.of(new ItemDescriptor("Abyssal whip", "Abyssal whip", null, true, null, null)), store)
			.decorate("Bring your Abyssal whip.");
		assertTrue("owned item icon must come from its captured ID",
			html.contains("item-" + WHIP + ".png"));
	}

	@Test
	public void decoratorResolvesUnownedItemIconsFromTheCatalogue() throws Exception
	{
		IconStore store = storeWith("item-" + WHIP + ".png");
		String html = AnswerDecorator
			.build(new GameCapture(), new EntityResolver.Resolution(), List.of(),
				List.of(new ItemDescriptor("Abyssal whip", "Abyssal whip", WHIP, true, null, null)), store)
			.decorate("Save up for an Abyssal whip.");
		assertTrue("unowned item icon must come from the catalogue ID",
			html.contains("item-" + WHIP + ".png"));

		String noId = AnswerDecorator
			.build(new GameCapture(), new EntityResolver.Resolution(), List.of(),
				List.of(new ItemDescriptor("Abyssal whip", "Abyssal whip", null, true, null, null)), store)
			.decorate("Save up for an Abyssal whip.");
		assertFalse("no ID means no icon, never a guess", noId.contains("<img"));
	}

	@Test
	public void capturedIdBeatsTheCatalogueId() throws Exception
	{
		// The player's copy may be a variant; its captured ID wins over
		// the catalogue's canonical one.
		IconStore store = storeWith("item-" + WHIP + ".png", "item-9999.png");
		GameCapture cap = new GameCapture();
		cap.equipment = List.of(Map.of("id", WHIP, "name", "Abyssal whip", "quantity", 1));
		String html = AnswerDecorator
			.build(cap, new EntityResolver.Resolution(), List.of(),
				List.of(new ItemDescriptor("Abyssal whip", "Abyssal whip", 9999, true, null, null)), store)
			.decorate("Bring your Abyssal whip.");
		assertTrue(html.contains("item-" + WHIP + ".png"));
		assertFalse(html.contains("item-9999.png"));
	}

	@Test
	public void untradeableIconComesFromItsCatalogueId() throws Exception
	{
		// Crowbar is not on the GE; only the infobox catalogue carries its ID.
		IconStore store = storeWith("item-31807.png");
		String html = AnswerDecorator
			.build(new GameCapture(), new EntityResolver.Resolution(), List.of(),
				List.of(new ItemDescriptor("Crowbar", "Crowbar", 31807, false, null, null)), store)
			.decorate("The quest rewards a Crowbar.");
		assertTrue(html.contains("item-31807.png"));
	}
}

package com.osrscopilot;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class MarkdownHtmlTest
{
	@Test
	public void inlineStyles()
	{
		String html = MarkdownHtml.toHtml("Use **Protect from Melee** with *Piety* and `::probe`.");
		assertTrue(html.contains("<b>Protect from Melee</b>"));
		assertTrue(html.contains("<i>Piety</i>"));
		assertTrue(html.contains("<code>::probe</code>"));
	}

	@Test
	public void headersAndLists()
	{
		String html = MarkdownHtml.toHtml("### Gear Setup\n- Abyssal whip\n- Anti-dragon shield\n\n1. First\n2. Second");
		assertTrue(html.contains("<b>Gear Setup</b>"));
		assertTrue(html.contains("<ul><li>Abyssal whip</li><li>Anti-dragon shield</li></ul>"));
		assertTrue(html.contains("<ol><li>First</li><li>Second</li></ol>"));
	}

	@Test
	public void tablesRenderWithHeaderRow()
	{
		String html = MarkdownHtml.toHtml("| Slot | Item |\n|---|---|\n| Weapon | Whip |");
		assertTrue(html.contains("<table"));
		// Header cells are bold on a distinct background; body cells plain.
		assertTrue(html.contains("<b>Slot</b></td>"));
		assertTrue(html.contains(">Whip</td>"));
		assertFalse(html.contains("---"));
	}

	@Test
	public void bulletAsteriskDoesNotItalicize()
	{
		String html = MarkdownHtml.toHtml("* one\n* two");
		assertTrue(html.contains("<ul><li>one</li><li>two</li></ul>"));
		assertFalse(html.contains("<i>"));
	}

	@Test
	public void htmlIsEscaped()
	{
		String html = MarkdownHtml.toHtml("damage <10 & \"safe\"");
		assertTrue(html.contains("&lt;10 &amp;"));
	}

	@Test
	public void partialMarkdownNeverBreaks()
	{
		// Mid-stream fragments: unclosed bold, dangling table pipe.
		assertEquals(false, MarkdownHtml.toHtml("**unclosed bold").isEmpty());
		assertEquals(false, MarkdownHtml.toHtml("| half | a row").isEmpty());
	}
}

package com.osrscopilot;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import com.osrscopilot.pipeline.CopilotPipeline;
import com.osrscopilot.pipeline.EntityResolver;
import com.osrscopilot.pipeline.GameCapture;
import com.osrscopilot.pipeline.Llm;
import com.osrscopilot.pipeline.StreamListener;
import java.io.File;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import okhttp3.OkHttpClient;

/**
 * Offline eval harness: runs the in-plugin pipeline against a recorded
 * snapshot without launching the game.
 *
 * Usage:
 *   --env FILE        KEY=VALUE file with PARASAIL_BASE_URL / PARASAIL_API_KEY
 *   --snapshot FILE   snapshot JSON (::probe dump)
 *   --question TEXT   the question to ask
 *   --battery FILE    run every question in a file instead (one per line;
 *                     "&gt; " prefix = follow-up in the same conversation;
 *                     "EVENT {json}" attaches a recent game event to the next
 *                     question; "ASSERT {json}" checks the previous question's
 *                     route; "ANSWER text" seeds the previous question's
 *                     answer ("\n" becomes a newline) so routeOnly/promptOnly
 *                     runs exercise answer-derived subject inheritance (full
 *                     runs use the model's real answer and ignore the seed);
 *                     # comments and blank lines skipped)
 *   --routeOnly true  run only the deterministic router + assertions -- no
 *                     LLM calls, free, fast route regression check
 *   --simple true     answer with the simple-mode system prompt (short
 *                     plain text, no markdown)
 *   --model NAME      model name (default deepseek-ai/DeepSeek-V4-Flash)
 *   --maxTokens N     per-response completion cap (default 4096; lower it to
 *                     reproduce reasoning-burn truncation deterministically)
 *
 * ASSERT keys: items/monsters/quests/pages/skills/needs/facilities require
 * those entries in the route (case-insensitive); a "not_" prefix requires
 * their absence. Example: ASSERT {"needs":["transport"],"not_facilities":["Bank"]}
 * The "facts" key asserts prefetched fact headings ("Monster info: Bloodveld")
 * and requires a promptOnly or full run, since routeOnly builds no facts.
 *
 * Battery runs write a JSONL artifact to eval/runs/ so runs diff mechanically.
 * Exits nonzero when any assertion fails.
 */
public class PipelineEvalRunner
{
	public static void main(String[] args) throws Exception
	{
		PrintStream out = new PrintStream(System.out, true, "UTF-8");
		Map<String, String> opts = parseArgs(args);
		Gson gson = new Gson();

		Map<String, String> env = new HashMap<>(System.getenv());
		if (opts.containsKey("env"))
		{
			for (String line : Files.readAllLines(new File(opts.get("env")).toPath(), StandardCharsets.UTF_8))
			{
				int eq = line.indexOf('=');
				if (eq > 0 && !line.trim().startsWith("#"))
				{
					env.put(line.substring(0, eq).trim(), line.substring(eq + 1).trim());
				}
			}
		}

		String baseUrl = env.getOrDefault("PARASAIL_BASE_URL", env.getOrDefault("OPENAI_BASE_URL", ""));
		String apiKey = env.getOrDefault("PARASAIL_API_KEY", env.getOrDefault("OPENAI_API_KEY", ""));
		String model = opts.getOrDefault("model", "deepseek-ai/DeepSeek-V4-Flash");
		int maxTokens = Integer.parseInt(opts.getOrDefault("maxTokens", "4096"));
		Llm.Settings settings = new Llm.Settings(baseUrl, apiKey, model, 0.2, maxTokens);
		if (!settings.isConfigured())
		{
			out.println("No endpoint configured: set PARASAIL_BASE_URL/PARASAIL_API_KEY or pass --env FILE");
			System.exit(1);
		}

		GameCapture cap = loadSnapshot(new File(opts.get("snapshot")), gson);
		out.printf("snapshot: %s (%s, cb %d, bank %s)%n", opts.get("snapshot"),
			cap.accountTypeName(), cap.combatLevel,
			cap.bank == null ? "none" : cap.bank.size() + " items");

		File cacheDir = new File(new File(System.getProperty("user.home"), ".runelite"),
			"osrs-copilot/cache");
		CopilotPipeline pipeline = new CopilotPipeline(new OkHttpClient(), gson, cacheDir);

		// Streaming listener mirrors what the plugin panel does, so this run
		// verifies the SSE path end-to-end.
		StreamListener listener = new StreamListener()
		{
			@Override
			public void onDelta(String text)
			{
				out.print(text);
				out.flush();
			}

			@Override
			public void onTurnDiscarded()
			{
				out.println("\n[partial turn discarded]");
			}

			@Override
			public void onStatus(String status)
			{
				out.println("[" + status + "]");
			}
		};

		// Battery file, or --question with optional --question2 follow-up.
		List<BatteryItem> items = new java.util.ArrayList<>();
		if (opts.containsKey("battery"))
		{
			items = parseBattery(new File(opts.get("battery")), gson);
		}
		else
		{
			items.add(new BatteryItem(opts.get("question"), false, null));
			if (opts.get("question2") != null)
			{
				items.add(new BatteryItem(opts.get("question2"), true, null));
			}
		}

		boolean routeOnly = "true".equals(opts.get("routeOnly"));
		boolean promptOnly = "true".equals(opts.get("promptOnly"));
		boolean simpleMode = "true".equals(opts.get("simple"));
		Map<String, String> promptDump = new LinkedHashMap<>();
		List<String> summary = new java.util.ArrayList<>();
		List<String> failures = new java.util.ArrayList<>();
		List<String> suspects = new java.util.ArrayList<>();
		List<String> errors = new java.util.ArrayList<>();
		List<CopilotPipeline.Exchange> history = new java.util.ArrayList<>();
		List<Map<String, Object>> baseEvents = cap.recentEvents;

		// Records are appended as they complete: a battery is minutes of API
		// calls, and a flaky endpoint must not cost the whole run's evidence.
		java.io.PrintWriter artifact = null;
		File artifactFile = null;
		if (opts.containsKey("battery"))
		{
			File runsDir = new File(new File(opts.get("battery")).getAbsoluteFile()
				.getParentFile(), "runs");
			runsDir.mkdirs();
			String stamp = new java.text.SimpleDateFormat("yyyyMMdd-HHmmss").format(new java.util.Date());
			artifactFile = new File(runsDir, "run-" + stamp
				+ (routeOnly ? "-routes" : promptOnly ? "-prompts" : "") + ".jsonl");
			artifact = new java.io.PrintWriter(artifactFile, "UTF-8");
		}

		for (BatteryItem item : items)
		{
			if (!item.followUp)
			{
				history.clear();
			}
			cap.recentEvents = item.events != null ? item.events : baseEvents;

			out.println("\n########################################################");
			out.println("question: " + (item.followUp ? "(follow-up) " : "") + item.question
				+ (item.events != null ? "   [with simulated event]" : ""));

			// Follow-ups inherit the previous turn's entities, as in-game.
			EntityResolver.Resolution prev = history.isEmpty() ? null
				: history.get(history.size() - 1).entities;

			CopilotPipeline.Route route;
			CopilotPipeline.Result result = null;
			try
			{
				if (routeOnly)
				{
					route = pipeline.route(item.question, cap, prev);
					history.add(new CopilotPipeline.Exchange(item.question,
						item.answer != null ? item.answer : "",
						seededSubject(pipeline, route, item, cap)));
				}
				else if (promptOnly)
				{
					// Retrieval without synthesis: shows exactly what the model
					// would be given, at zero LLM cost.
					CopilotPipeline.Prepared prepared = pipeline.prepare(item.question, cap, prev);
					route = prepared.route;
					history.add(new CopilotPipeline.Exchange(item.question,
						item.answer != null ? item.answer : "",
						seededSubject(pipeline, route, item, cap)));
					out.println("\n=== BUILT PROMPT ===\n" + prepared.prompt + "\n=== END PROMPT ===");
					promptDump.put(item.question, prepared.prompt);
				}
				else
				{
					out.println("\n=== ANSWER (streaming) ===");
					// Matches CopilotConfig.maxToolTurns() so evals exercise
					// the same budget the plugin ships with.
					result = pipeline.answer(item.question, history, cap, settings, 4,
						simpleMode, listener);
					route = result.route;
					history.add(new CopilotPipeline.Exchange(item.question, result.answer,
						result.subject));
					out.println();
				}
			}
			catch (Exception e)
			{
				out.println("\nERROR: " + e);
				errors.add(trim(item.question, 40) + " :: " + e);
				JsonObject failed = new JsonObject();
				failed.addProperty("question", item.question);
				failed.addProperty("error", String.valueOf(e));
				writeRecord(artifact, gson, failed);
				continue;
			}

			out.printf("%nroute: items=%s monsters=%s quests=%s pages=%s skills=%s needs=%s facilities=%s diaryTier=%s bank=%s%n",
				route.entities.items, route.entities.monsters, route.entities.quests,
				route.entities.pages, route.entities.skills, route.needs,
				route.facilityPages, route.diaryTier, route.bankMode);

			String builtPrompt = promptDump.containsKey(item.question)
				? promptDump.get(item.question)
				: result != null ? result.prompt : null;
			List<String> assertFailures = checkAssertions(item.asserts, route, builtPrompt);
			for (String f : assertFailures)
			{
				out.println("ASSERT FAIL: " + f);
				failures.add(trim(item.question, 40) + " :: " + f);
			}
			if (item.asserts != null && assertFailures.isEmpty())
			{
				out.println("asserts: PASS");
			}

			JsonObject rec = new JsonObject();
			rec.addProperty("question", item.question);
			rec.addProperty("followUp", item.followUp);
			rec.add("route", gson.toJsonTree(route));
			rec.addProperty("assertFailures", String.join("; ", assertFailures));
			if (promptDump.containsKey(item.question))
			{
				rec.addProperty("prompt", promptDump.get(item.question));
			}
			if (result != null)
			{
				Llm.Usage u = result.usage;
				out.printf("facts=%d contextChars=%d toolCalls=%s time=%.1fs%n",
					result.factBlocks, result.contextChars, result.toolLog, result.millis / 1000.0);
				out.printf("tokens: in=%d out=%d cached=%d llmCalls=%d%n",
					u.promptTokens, u.completionTokens, u.cachedPromptTokens, u.calls);
				if ("true".equals(opts.get("showPrompt")))
				{
					out.println("\n=== BUILT PROMPT ===\n" + result.prompt + "\n=== END PROMPT ===");
				}
				if (!result.suspectNames.isEmpty())
				{
					out.println("UNGROUNDED NAMES: " + result.suspectNames);
					suspects.add(trim(item.question, 40) + " :: " + result.suspectNames);
				}
				rec.addProperty("answer", result.answer);
				rec.add("suspectNames", gson.toJsonTree(result.suspectNames));
				rec.add("toolCalls", gson.toJsonTree(result.toolLog));
				rec.addProperty("seconds", result.millis / 1000.0);
				rec.addProperty("tokensIn", u.promptTokens);
				rec.addProperty("tokensOut", u.completionTokens);
				rec.addProperty("tokensCached", u.cachedPromptTokens);
				summary.add(String.format("%-52s %6.1fs  in=%-6d out=%-5d cached=%-6d calls=%d tools=%d",
					trim(item.question, 50), result.millis / 1000.0, u.promptTokens,
					u.completionTokens, u.cachedPromptTokens, u.calls, result.toolLog.size()));
			}
			writeRecord(artifact, gson, rec);
		}

		if (artifact != null)
		{
			artifact.close();
			out.println("\nrun artifact: " + artifactFile);
		}

		if (!summary.isEmpty())
		{
			out.println("\n=== SUMMARY ===");
			summary.forEach(out::println);
		}
		out.println("\n=== UNGROUNDED NAMES: " + (suspects.isEmpty() ? "NONE ==="
			: suspects.size() + " ANSWERS ==="));
		suspects.forEach(out::println);
		if (!errors.isEmpty())
		{
			out.println("\n=== ERRORS: " + errors.size() + " ===");
			errors.forEach(out::println);
		}
		out.println("\n=== ASSERTIONS: " + (failures.isEmpty() ? "ALL PASS ==="
			: failures.size() + " FAILED ==="));
		failures.forEach(out::println);
		// OkHttp keeps non-daemon pool threads alive; don't let them hang the JVM.
		System.exit(failures.isEmpty() ? 0 : 1);
	}

	/** LLM-free modes have no real answer; an ANSWER-seeded one stands in so
	 * the follow-up inheritance path (question + answer subject) still runs. */
	private static EntityResolver.Resolution seededSubject(CopilotPipeline pipeline,
		CopilotPipeline.Route route, BatteryItem item, GameCapture cap)
	{
		return item.answer != null
			? pipeline.subjectOf(route.entities, item.answer, cap) : route.entities;
	}

	private static void writeRecord(java.io.PrintWriter artifact, Gson gson, JsonObject rec)
	{
		if (artifact != null)
		{
			artifact.println(gson.toJson(rec));
			artifact.flush();
		}
	}

	/** Checks route expectations: each key lists entries that must be present
	 * in the corresponding route list ("not_" prefix: must be absent).
	 * "facts" checks prefetched fact headings against the built prompt,
	 * null in routeOnly runs. */
	private static List<String> checkAssertions(JsonObject asserts, CopilotPipeline.Route route,
		String prompt)
	{
		List<String> failures = new java.util.ArrayList<>();
		if (asserts == null)
		{
			return failures;
		}
		Map<String, List<String>> routeLists = new HashMap<>();
		if (prompt != null)
		{
			List<String> factLabels = new java.util.ArrayList<>();
			for (String line : prompt.split("\n"))
			{
				if (line.startsWith("### "))
				{
					factLabels.add(line.substring(4).trim());
				}
			}
			routeLists.put("facts", factLabels);
		}
		routeLists.put("items", route.entities.items);
		routeLists.put("monsters", route.entities.monsters);
		routeLists.put("quests", route.entities.quests);
		routeLists.put("pages", route.entities.pages);
		routeLists.put("skills", route.entities.skills);
		routeLists.put("needs", route.needs);
		routeLists.put("facilities", route.facilityPages);
		routeLists.put("diary_tier",
			route.diaryTier == null ? List.of() : List.of(route.diaryTier));
		routeLists.put("bank",
			route.bankMode == null ? List.of() : List.of(route.bankMode));

		for (String key : asserts.keySet())
		{
			boolean negated = key.startsWith("not_");
			String listName = negated ? key.substring(4) : key;
			List<String> actual = routeLists.get(listName);
			if (actual == null)
			{
				failures.add("facts".equals(listName)
					? "facts assertion requires a promptOnly or full run"
					: "unknown assert key: " + key);
				continue;
			}
			for (JsonElement e : asserts.getAsJsonArray(key))
			{
				String expected = e.getAsString();
				boolean present = actual.stream().anyMatch(a -> a.equalsIgnoreCase(expected));
				if (present == negated)
				{
					failures.add(listName + (negated ? " must not contain '" : " must contain '")
						+ expected + "' (actual: " + actual + ")");
				}
			}
		}
		return failures;
	}

	private static class BatteryItem
	{
		final String question;
		final boolean followUp;
		final List<Map<String, Object>> events;
		JsonObject asserts;
		String answer;

		BatteryItem(String question, boolean followUp, List<Map<String, Object>> events)
		{
			this.question = question;
			this.followUp = followUp;
			this.events = events;
		}
	}

	private static List<BatteryItem> parseBattery(File file, Gson gson) throws Exception
	{
		List<BatteryItem> items = new java.util.ArrayList<>();
		List<Map<String, Object>> pendingEvents = null;
		for (String raw : Files.readAllLines(file.toPath(), StandardCharsets.UTF_8))
		{
			String line = raw.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			if (line.startsWith("EVENT "))
			{
				Map<String, Object> event = gson.fromJson(line.substring(6),
					new TypeToken<Map<String, Object>>() { }.getType());
				pendingEvents = List.of(event);
				continue;
			}
			if (line.startsWith("ASSERT "))
			{
				if (items.isEmpty())
				{
					throw new IllegalArgumentException("ASSERT before any question");
				}
				items.get(items.size() - 1).asserts = gson.fromJson(line.substring(7), JsonObject.class);
				continue;
			}
			if (line.startsWith("ANSWER "))
			{
				if (items.isEmpty())
				{
					throw new IllegalArgumentException("ANSWER before any question");
				}
				items.get(items.size() - 1).answer = line.substring(7).replace("\\n", "\n");
				continue;
			}
			boolean followUp = line.startsWith("> ");
			items.add(new BatteryItem(followUp ? line.substring(2) : line, followUp, pendingEvents));
			pendingEvents = null;
		}
		return items;
	}

	private static String trim(String s, int max)
	{
		return s.length() <= max ? s : s.substring(0, max - 3) + "...";
	}

	private static Map<String, String> parseArgs(String[] args)
	{
		Map<String, String> opts = new HashMap<>();
		for (int i = 0; i + 1 < args.length; i += 2)
		{
			opts.put(args[i].replaceFirst("^--", ""), args[i + 1]);
		}
		if (!opts.containsKey("snapshot") || (!opts.containsKey("question") && !opts.containsKey("battery")))
		{
			throw new IllegalArgumentException("--snapshot and (--question or --battery) are required");
		}
		return opts;
	}

	/** Loads a GameCapture dump as written by ::probe. */
	static GameCapture loadSnapshot(File file, Gson gson) throws Exception
	{
		String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
		return gson.fromJson(json, GameCapture.class);
	}
}

package com.osrscopilot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TranscriptModelTest
{
	@Test
	public void streamingCreatesOneAnswerBlockAndAppends()
	{
		TranscriptModel model = new TranscriptModel();
		model.beginQuestion("what is a whip");

		assertTrue("first delta creates the block", model.appendDelta("The abyssal "));
		assertFalse("later deltas reuse it", model.appendDelta("whip is..."));
		assertEquals(2, model.blocks().size());
		assertEquals("The abyssal whip is...", model.answerBlock().text.toString());
		assertTrue(model.isStreaming(model.answerBlock()));
	}

	@Test
	public void discardedPartialBecomesWorkingNoteAndTextClears()
	{
		TranscriptModel model = new TranscriptModel();
		model.beginQuestion("q");
		model.appendDelta("Let me look that up");
		assertTrue(model.discardPartial());

		TranscriptModel.Block block = model.answerBlock();
		assertEquals(0, block.text.length());
		assertEquals(java.util.List.of("Let me look that up"), block.working);
	}

	@Test
	public void completingTheAnswerCanonicalizesTheBlock()
	{
		TranscriptModel model = new TranscriptModel();
		model.beginQuestion("q");
		model.appendDelta("preamble");
		model.discardPartial();
		model.appendDelta("The ans");

		TranscriptModel.Block done = model.completeAnswer("The answer.", "<b>The answer.</b>", "tokens 5");
		assertNull("streaming is over", model.answerBlock());
		assertFalse(model.isStreaming(done));
		assertEquals("The answer.", done.text.toString());
		assertEquals("<b>The answer.</b>", done.decoratedHtml);
		assertEquals("tokens 5", done.meta);
		assertTrue("working notes served their purpose", done.working.isEmpty());
	}

	@Test
	public void errorRollsBackToBeforeTheQuestionAndReturnsIt()
	{
		TranscriptModel model = new TranscriptModel();
		model.seedExchange("old q", "old a", null, null);
		model.beginQuestion("new question");
		model.appendDelta("partial answer that failed");

		String question = model.rollback();
		assertEquals("new question", question);
		assertEquals("failures never pollute the conversation", 2, model.blocks().size());
		assertNull(model.answerBlock());
	}

	@Test
	public void seededExchangesAreNotRolledBack()
	{
		TranscriptModel model = new TranscriptModel();
		model.seedExchange("q1", "a1", "<b>a1</b>", "meta");
		model.rollback();
		assertEquals(2, model.blocks().size());
		assertEquals("a1", model.blocks().get(1).text.toString());
	}
}

package com.osrscopilot;

import com.osrscopilot.pipeline.EntityResolver;
import com.osrscopilot.pipeline.GameCapture;
import com.osrscopilot.pipeline.ItemDescriptor;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.lang.reflect.Field;
import java.util.List;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.JButton;
import javax.swing.JFrame;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;

/**
 * Renders the chat panel offscreen with a seeded conversation and saves
 * PNGs at sidebar and pop-out sizes, so UI changes can be reviewed without
 * launching the game client. Dev tool only.
 */
public final class UiPreview
{
	private UiPreview()
	{
	}

	public static void main(String[] args) throws Exception
	{
		SwingUtilities.invokeAndWait(() -> {
			try
			{
				for (String name : new String[]{"game-native", "modern", "parchment"})
				{
					Theme.setActive(Theme.byName(name));
					render(name, 242, 620, true);
					render(name, 560, 720, true);
					render(name + "-welcome", 242, 620, false);
					render(name + "-welcome-custom", 242, 620, false);
				}
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		System.exit(0);
	}

	private static void render(String tag, int width, int height, boolean seedConversation)
		throws Exception
	{
		CopilotPanel panel = new CopilotPanel(13);
		panel.setAskHandler(q -> {
		});
		if (seedConversation)
		{
			seed(panel);
			// The welcome render keeps Simple off, so both states appear
			// across the preview set.
			panel.setSimpleMode(true);
		}
		else if (tag.endsWith("-custom"))
		{
			// The setup form expanded, in its second state: Custom endpoint
			// with the base URL row revealed.
			panel.setSetupState(new CopilotPanel.SetupValues(LlmProvider.CUSTOM, "",
				"llama3", "http://localhost:8000/v1", 0.2, 8192, 4));
			panel.setSetupOpen(true);
		}
		// Streamed content renders on a coalescing timer that can't fire
		// while this thread owns the EDT; flush the pending render directly.
		java.lang.reflect.Method render = CopilotPanel.class.getDeclaredMethod("render");
		render.setAccessible(true);
		render.invoke(panel);

		JFrame frame = new JFrame();
		frame.setUndecorated(true);
		frame.add(panel);
		frame.setSize(width, height);
		frame.addNotify();
		frame.validate();

		BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		panel.setSize(width, height);
		panel.validate();
		panel.printAll(g);
		g.dispose();
		frame.dispose();

		File out = new File("eval/ui-" + tag + "-" + width + "x" + height + ".png");
		ImageIO.write(img, "png", out);
		System.out.println("wrote " + out.getAbsolutePath());
	}

	private static void seed(CopilotPanel panel) throws Exception
	{
		GameCapture cap = new GameCapture();
		cap.questStates = Map.of(
			"While Guthix Sleeps", "FINISHED",
			"A Kingdom Divided", "NOT_STARTED");
		cap.inventory = List.of(Map.of("name", "Prayer potion(4)", "quantity", 3));
		cap.equipment = List.of();
		cap.bank = List.of(
			Map.of("name", "Emberlight", "quantity", 1),
			Map.of("name", "Bandos chestplate", "quantity", 1),
			Map.of("name", "Neitiznot faceguard", "quantity", 1));
		EntityResolver.Resolution ents = new EntityResolver.Resolution();
		ents.monsters.add("Tormented Demon");
		// Includes the owned items: only catalogued names decorate.
		List<ItemDescriptor> catalogue = List.of(
			new ItemDescriptor("Bow of Faerdhinen", "Bow of Faerdhinen", null, true, null, null),
			new ItemDescriptor("Dragon dart", "Dragon dart", null, true, null, null),
			new ItemDescriptor("Prayer potion(4)", "Prayer potion", null, true, null, null),
			new ItemDescriptor("Emberlight", "Emberlight", null, false, null, null),
			new ItemDescriptor("Bandos chestplate", "Bandos chestplate", null, true, null, null),
			new ItemDescriptor("Neitiznot faceguard", "Neitiznot faceguard", null, false, null, null));

		ask(panel, "what should i bring for tormented demons");
		String answer = "You have **While Guthix Sleeps** done, so you can fight them. "
			+ "A Kingdom Divided is not started, so demonbane spells are out.\n\n"
			+ "### Melee (primary)\n"
			+ "| Slot | Item |\n|---|---|\n"
			+ "| Weapon | Emberlight |\n"
			+ "| Body | Bandos chestplate |\n"
			+ "| Head | Neitiznot faceguard |\n\n"
			+ "- Bring prayer potions and a ranged switch\n"
			+ "- Bow of Faerdhinen only helps with the crystal set\n"
			+ "- At 93 Ranged your accuracy is fine either way\n";
		// No client here, so no sprite rendering: the store serves whatever
		// a previous dev-client session left on disk, else no icons.
		IconStore icons = new IconStore(new java.io.File("eval/icon-cache"),
			null, null, null);
		String decorated = AnswerDecorator.build(cap, ents, List.of(), catalogue, icons)
			.decorate(MarkdownHtml.toHtml(answer));
		panel.showAnswerDone(answer, decorated, 12.4, true,
			"facts: Monster info: Tormented Demon; Strategy: Tormented Demon; "
				+ "Recommended equipment: Tormented Demon | tokens 16719 in / 2999 out");

		ask(panel, "what about dragon darts in the blowpipe");
		panel.appendDelta("Let me check the numbers on that");
		panel.discardPartial();
		panel.showWorking("Looking up: search_owned_items, ge_price");
		panel.appendDelta("Dragon darts push the blowpipe's DPS up during the "
			+ "shield-down phase, and");
	}

	private static void ask(CopilotPanel panel, String question) throws Exception
	{
		Field inputField = CopilotPanel.class.getDeclaredField("input");
		inputField.setAccessible(true);
		((JTextField) inputField.get(panel)).setText(question);
		Field sendField = CopilotPanel.class.getDeclaredField("send");
		sendField.setAccessible(true);
		((JButton) sendField.get(panel)).doClick();
	}
}

package com.osrscopilot.area;

import java.util.HashMap;
import java.util.Map;
import java.util.StringJoiner;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Pins the vendored area table's behavior at known world points. The
 * coordinates are hand-verified against the wiki's maps; a future re-sync
 * of the table that breaks any of these is a data regression, not drift.
 */
public class GameAreaTest
{
	private static GameArea at(int x, int y, int plane)
	{
		return GameArea.fromPoint(new WorldPoint(x, y, plane));
	}

	@Test
	public void surfaceCities()
	{
		assertEquals(GameArea.LUMBRIDGE, at(3222, 3218, 0));
		assertEquals(GameArea.VARROCK, at(3212, 3428, 0));
		assertEquals(GameArea.FALADOR, at(2965, 3380, 0));
		assertEquals(GameArea.GRAND_EXCHANGE, at(3164, 3487, 0));
		// Varlamore (2024+): newest expansion present in the table.
		assertEquals(GameArea.CIVITAS_ILLA_FORTIS, at(1750, 3100, 0));
	}

	@Test
	public void undergroundAreas()
	{
		assertEquals(GameArea.TAVERLEY_DUNGEON, at(2885, 9798, 0));
		assertEquals(GameArea.LUMBRIDGE_SWAMP_CAVES, at(3170, 9560, 0));
		assertEquals(GameArea.VARROCK_SEWERS, at(3237, 9858, 0));
	}

	/** Boss rooms are sub-region rectangles overlaid on the dungeon's
	 * full regions; fromPoint must prefer the rectangle. */
	@Test
	public void subRegionBeatsFullRegion()
	{
		// General Graardor's room is a rectangle inside GWD region 11347.
		assertEquals(GameArea.GENERAL_GRAARDOR, at(2870, 5360, 0));
		// Same region, outside the rectangle: the surrounding dungeon.
		assertEquals(GameArea.GOD_WARS_DUNGEON, at(2820, 5330, 0));
	}

	/** The Warriors' Guild building is carved out of Burthorpe's region
	 * with different footprints per plane. */
	@Test
	public void planeDependentFootprints()
	{
		assertEquals(GameArea.WARRIORS_GUILD, at(2850, 3545, 0));
		assertEquals(GameArea.BURTHORPE, at(2850, 3533, 0));
		// Upstairs footprint extends further south than the ground floor.
		assertEquals(GameArea.WARRIORS_GUILD, at(2850, 3533, 1));
	}

	/** The three MTA rooms share one region, split by plane. */
	@Test
	public void planeSplitRooms()
	{
		assertEquals(GameArea.MTA_ENCHANTING_CHAMBER, at(3350, 9630, 0));
		assertEquals(GameArea.MTA_CREATURE_GRAVEYARD, at(3350, 9630, 1));
		assertEquals(GameArea.MTA_ALCHEMISTS_PLAYGROUND, at(3350, 9630, 2));
		// NMZ shares its region with plane 0 content; only planes >= 1 match.
		assertEquals(GameArea.NIGHTMARE_ZONE, at(2270, 4680, 1));
	}

	@Test
	public void rectangleBoundariesAreInclusive()
	{
		// Graardor room corners: (2863, 5351) to (2876, 5369).
		assertEquals(GameArea.GENERAL_GRAARDOR, at(2863, 5351, 0));
		assertEquals(GameArea.GENERAL_GRAARDOR, at(2876, 5369, 0));
		assertEquals(GameArea.GOD_WARS_DUNGEON, at(2862, 5351, 0));
		assertEquals(GameArea.GOD_WARS_DUNGEON, at(2876, 5370, 0));
	}

	@Test
	public void unmappedPointResolvesToNull()
	{
		assertNull(at(1000, 1000, 0));
	}

	/** The supplement covers content the vendored table lacks; it must
	 * only ever fill gaps, never shadow the table. */
	@Test
	public void supplementFillsGaps()
	{
		// Post-table content: Varlamore part 2 (2024) and Sailing (2025).
		assertEquals("Aldarin", Areas.resolve(new WorldPoint(1391, 2935, 0)));
		assertEquals("Port Roberts", Areas.resolve(new WorldPoint(1888, 3298, 0)));
		// Never in the table: Ferox Enclave and the surface Wilderness.
		assertEquals("Ferox Enclave", Areas.resolve(new WorldPoint(3137, 3623, 0)));
		assertEquals("the Wilderness (level 34)", Areas.resolve(new WorldPoint(3100, 3788, 0)));
		// Named wilderness POIs beat the generic wilderness rule.
		assertEquals("Resource Area", Areas.resolve(new WorldPoint(3185, 3934, 0)));
		// The vendored table still wins where it has data.
		assertEquals("Lumbridge", Areas.resolve(new WorldPoint(3222, 3218, 0)));
		assertEquals("Kraken (boss area)", Areas.resolve(new WorldPoint(2280, 10022, 0)));
		assertNull(Areas.resolve(new WorldPoint(1000, 1000, 0)));
	}

	/** Ferox Enclave straddles a region boundary and the South Wilderness
	 * mine is far smaller than its region; both are rectangle entries so
	 * the surrounding wilderness keeps its level readout. */
	@Test
	public void rectangleBoundedPois()
	{
		// The enclave's western third lies in region 12344.
		assertEquals("Ferox Enclave", Areas.resolve(new WorldPoint(3123, 3629, 0)));
		assertEquals("Ferox Enclave", Areas.resolve(new WorldPoint(3144, 3630, 0)));
		// Region 12600 south of the enclave walls is open wilderness.
		assertEquals("the Wilderness (level 11)", Areas.resolve(new WorldPoint(3160, 3600, 0)));
		// The mine itself, then the ditch crossing in the same region column.
		assertEquals("South Wilderness mine", Areas.resolve(new WorldPoint(3105, 3569, 0)));
		assertEquals("the Wilderness (level 1)", Areas.resolve(new WorldPoint(3100, 3525, 0)));
	}

	/** Two areas claiming the same full region would make fromPoint's
	 * answer depend on enum declaration order. Sub-region overlays on a
	 * full region are fine; duplicate full-region claims are data bugs. */
	@Test
	public void noDuplicateFullRegionClaims()
	{
		Map<Integer, GameArea> claimed = new HashMap<>();
		StringJoiner dupes = new StringJoiner("; ");
		for (GameArea area : GameArea.values())
		{
			for (int region : area.getFullRegions())
			{
				GameArea prior = claimed.put(region, area);
				if (prior != null)
				{
					dupes.add("region " + region + ": " + prior + " and " + area);
				}
			}
		}
		assertTrue("duplicate full-region claims: " + dupes, dupes.length() == 0);
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrscopilot.area.Areas;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;
import okhttp3.OkHttpClient;

/**
 * Audits area resolution against the wiki. Every page with a location
 * infobox is fetched and its {{Map}} coordinates extracted from the
 * wikitext; each point is then resolved through {@link Areas}, the same
 * path the prompt uses. Reports places that resolve to nothing (gaps --
 * typically content newer than the vendored table, listed newest release
 * first) and places that resolve to a name sharing no word with the page
 * title (possible misattributions; most are benign, e.g. a shop resolving
 * to its city).
 *
 * Run: gradlew areaScan
 */
public final class GameAreaScan
{
	private static final String WIKI_API = "https://oldschool.runescape.wiki/api.php";
	private static final Pattern RELEASE = Pattern.compile("\\|\\s*release\\s*=([^\\n]*)");
	private static final Pattern YEAR = Pattern.compile("\\b(19|20)\\d{2}\\b");
	private static final Pattern NUM_PAIR = Pattern.compile("^(\\d{3,5})\\s*,\\s*(\\d{3,5})$");

	private final Http http;
	private final Gson gson;

	private GameAreaScan(Http http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	private static final class Place
	{
		final String title;
		final int x;
		final int y;
		final int plane;
		final int releaseYear;

		Place(String title, int x, int y, int plane, int releaseYear)
		{
			this.title = title;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.releaseYear = releaseYear;
		}
	}

	public static void main(String[] args) throws Exception
	{
		Gson gson = new Gson();
		GameAreaScan scan = new GameAreaScan(new Http(new OkHttpClient(), gson), gson);

		List<String> titles = scan.locationPages();
		System.out.println("location-infobox pages: " + titles.size());

		List<Place> places = new ArrayList<>();
		int noCoords = 0;
		for (int i = 0; i < titles.size(); i += 50)
		{
			List<String> batch = titles.subList(i, Math.min(i + 50, titles.size()));
			for (String[] page : scan.wikitexts(batch))
			{
				Place p = parsePlace(page[0], page[1]);
				if (p != null)
				{
					places.add(p);
				}
				else
				{
					noCoords++;
				}
			}
			Thread.sleep(1000);
		}
		System.out.println("with map coordinates:   " + places.size()
			+ "   (no coordinates in wikitext: " + noCoords + ")");

		List<Place> unresolved = new ArrayList<>();
		List<String> mismatches = new ArrayList<>();
		for (Place p : places)
		{
			String name = Areas.resolve(new WorldPoint(p.x, p.y, p.plane));
			if (name == null)
			{
				unresolved.add(p);
			}
			else if (!sharesWord(p.title, name))
			{
				mismatches.add(String.format("%-42s (%d,%d,%d) -> %s",
					p.title, p.x, p.y, p.plane, name));
			}
		}

		System.out.printf("%nresolved: %d / %d (%.0f%%)%n",
			places.size() - unresolved.size(), places.size(),
			100.0 * (places.size() - unresolved.size()) / places.size());

		System.out.println("\n== UNRESOLVED (newest release first) "
			+ "-- gaps in the area table ==");
		unresolved.sort(Comparator.comparingInt((Place p) -> -p.releaseYear)
			.thenComparing(p -> p.title));
		for (Place p : unresolved)
		{
			System.out.printf("%s  %-42s (%d,%d,%d)%n",
				p.releaseYear > 0 ? String.valueOf(p.releaseYear) : "????",
				p.title, p.x, p.y, p.plane);
		}

		System.out.println("\n== NAME MISMATCHES -- resolved, but to an "
			+ "unrelated-sounding area (review manually) ==");
		mismatches.forEach(System.out::println);
	}

	/** All page titles carrying a location infobox, via the wiki's bucket API. */
	private List<String> locationPages() throws IOException
	{
		Set<String> titles = new TreeSet<>();
		for (int offset = 0; offset < 100_000; offset += 5000)
		{
			JsonObject r = http.getJson(WIKI_API + "?action=bucket&format=json&query="
				+ Http.enc("bucket('infobox_location').select('page_name')"
				+ ".limit(5000).offset(" + offset + ").run()"));
			JsonArray rows = r.getAsJsonArray("bucket");
			if (rows == null || rows.size() == 0)
			{
				break;
			}
			for (JsonElement row : rows)
			{
				JsonElement name = row.getAsJsonObject().get("page_name");
				if (name != null && !name.isJsonNull())
				{
					titles.add(name.getAsString());
				}
			}
			if (rows.size() < 5000)
			{
				break;
			}
		}
		return new ArrayList<>(titles);
	}

	/** Fetches raw wikitext for up to 50 titles; returns {title, wikitext}. */
	private List<String[]> wikitexts(List<String> titles) throws IOException
	{
		JsonObject r = http.getJson(WIKI_API + "?action=query&prop=revisions"
			+ "&rvprop=content&rvslots=main&format=json&titles="
			+ Http.enc(String.join("|", titles)));
		List<String[]> out = new ArrayList<>();
		JsonObject pages = r.getAsJsonObject("query").getAsJsonObject("pages");
		for (String pageId : pages.keySet())
		{
			JsonObject p = pages.getAsJsonObject(pageId);
			if (p.has("revisions"))
			{
				String text = p.getAsJsonArray("revisions").get(0).getAsJsonObject()
					.getAsJsonObject("slots").getAsJsonObject("main").get("*").getAsString();
				out.add(new String[]{p.get("title").getAsString(), text});
			}
		}
		return out;
	}

	/** Extracts a representative world point from the page's first usable
	 * {{Map}} call: named x=/y= if present, else the centroid of positional
	 * "x,y" pairs (polygon and pin lists). */
	private static Place parsePlace(String title, String text)
	{
		int year = 0;
		Matcher rel = RELEASE.matcher(text);
		if (rel.find())
		{
			Matcher y = YEAR.matcher(rel.group(1));
			if (y.find())
			{
				year = Integer.parseInt(y.group());
			}
		}

		int from = 0;
		while (true)
		{
			int start = text.indexOf("{{Map", from);
			if (start < 0)
			{
				return null;
			}
			String body = balancedBody(text, start);
			from = start + 5;
			if (body == null)
			{
				continue;
			}
			Integer x = null;
			Integer y = null;
			int plane = 0;
			List<int[]> pairs = new ArrayList<>();
			for (String part : splitTopLevel(body))
			{
				String arg = part.trim();
				int eq = arg.indexOf('=');
				if (eq >= 0)
				{
					String key = arg.substring(0, eq).trim().toLowerCase(Locale.ROOT);
					String val = arg.substring(eq + 1).trim();
					try
					{
						if (key.equals("x"))
						{
							x = (int) Double.parseDouble(val);
						}
						else if (key.equals("y"))
						{
							y = (int) Double.parseDouble(val);
						}
						else if (key.equals("plane"))
						{
							plane = (int) Double.parseDouble(val);
						}
					}
					catch (NumberFormatException ignored)
					{
					}
				}
				else
				{
					Matcher m = NUM_PAIR.matcher(arg);
					if (m.matches())
					{
						pairs.add(new int[]{Integer.parseInt(m.group(1)),
							Integer.parseInt(m.group(2))});
					}
				}
			}
			if (x == null && !pairs.isEmpty())
			{
				long sx = 0;
				long sy = 0;
				for (int[] pr : pairs)
				{
					sx += pr[0];
					sy += pr[1];
				}
				x = (int) (sx / pairs.size());
				y = (int) (sy / pairs.size());
			}
			if (x != null && y != null)
			{
				return new Place(title, x, y, plane, year);
			}
		}
	}

	/** Template body between "{{Map" at start and its matching "}}", or
	 * null if braces never balance. */
	private static String balancedBody(String text, int start)
	{
		int depth = 0;
		for (int i = start; i < text.length() - 1; i++)
		{
			if (text.charAt(i) == '{' && text.charAt(i + 1) == '{')
			{
				depth++;
				i++;
			}
			else if (text.charAt(i) == '}' && text.charAt(i + 1) == '}')
			{
				depth--;
				i++;
				if (depth == 0)
				{
					return text.substring(start + 5, i - 1);
				}
			}
		}
		return null;
	}

	/** Splits template arguments on '|' at brace depth zero. */
	private static List<String> splitTopLevel(String body)
	{
		List<String> parts = new ArrayList<>();
		int depth = 0;
		int last = 0;
		for (int i = 0; i < body.length(); i++)
		{
			char c = body.charAt(i);
			if (c == '{' || c == '[')
			{
				depth++;
			}
			else if (c == '}' || c == ']')
			{
				depth--;
			}
			else if (c == '|' && depth == 0)
			{
				parts.add(body.substring(last, i));
				last = i + 1;
			}
		}
		parts.add(body.substring(last));
		return parts;
	}

	/** True if any normalized word appears in both names. */
	private static boolean sharesWord(String a, String b)
	{
		Set<String> wa = words(a);
		wa.retainAll(words(b));
		return !wa.isEmpty();
	}

	private static Set<String> words(String s)
	{
		Set<String> out = new HashSet<>();
		for (String w : s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9 ]", " ").split("\\s+"))
		{
			if (w.length() > 2 && !w.equals("the") && !w.equals("and"))
			{
				out.add(w);
			}
		}
		return out;
	}
}

