package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import okio.Buffer;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Pins the SSE stream parser against provider behaviors we rely on,
 * OpenRouter's in particular: keep-alive comment lines, usage in the
 * final chunk, fragmented tool calls, and mid-stream error chunks
 * delivered under an already-committed 200 status.
 */
public class LlmStreamTest
{
	private static class Recorder implements StreamListener
	{
		final StringBuilder deltas = new StringBuilder();

		@Override
		public void onDelta(String text)
		{
			deltas.append(text);
		}

		@Override
		public void onTurnDiscarded()
		{
		}

		@Override
		public void onStatus(String status)
		{
		}
	}

	private final Recorder listener = new Recorder();
	private final Llm llm = new Llm(null, new Gson(),
		new Llm.Settings("https://openrouter.ai/api/v1", "k", "m", 0.7, 512));

	private JsonObject parse(String... sseLines) throws IOException
	{
		Buffer source = new Buffer();
		for (String line : sseLines)
		{
			source.writeUtf8(line).writeUtf8("\n");
		}
		return llm.readSseStream(source, listener);
	}

	@Test
	public void reassemblesContentDeltas() throws IOException
	{
		JsonObject msg = parse(
			"data: {\"choices\":[{\"delta\":{\"content\":\"Hel\"}}]}",
			"data: {\"choices\":[{\"delta\":{\"content\":\"lo\"},\"finish_reason\":\"stop\"}]}",
			"data: [DONE]");
		assertEquals("Hello", msg.get("content").getAsString());
		assertEquals("stop", msg.get("finish_reason").getAsString());
		assertEquals("Hello", listener.deltas.toString());
	}

	/** OpenRouter interleaves ": OPENROUTER PROCESSING" keep-alive
	 * comments; per the SSE spec they must be ignored, not parsed. */
	@Test
	public void ignoresSseCommentsAndBlankLines() throws IOException
	{
		JsonObject msg = parse(
			": OPENROUTER PROCESSING",
			"",
			"data: {\"choices\":[{\"delta\":{\"content\":\"ok\"}}]}",
			": OPENROUTER PROCESSING",
			"data: [DONE]");
		assertEquals("ok", msg.get("content").getAsString());
	}

	/** Usage arrives in the final chunk, which may have no choices. */
	@Test
	public void recordsUsageFromFinalChunk() throws IOException
	{
		parse(
			"data: {\"choices\":[{\"delta\":{\"content\":\"x\"}}]}",
			"data: {\"choices\":[],\"usage\":{\"prompt_tokens\":100,\"completion_tokens\":7,"
				+ "\"prompt_tokens_details\":{\"cached_tokens\":60}}}",
			"data: [DONE]");
		assertEquals(100, llm.usage().promptTokens);
		assertEquals(7, llm.usage().completionTokens);
		assertEquals(60, llm.usage().cachedPromptTokens);
	}

	@Test
	public void reassemblesFragmentedToolCall() throws IOException
	{
		JsonObject msg = parse(
			"data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"id\":\"c1\","
				+ "\"function\":{\"name\":\"wiki_page\",\"arguments\":\"{\\\"title\\\":\"}}]}}]}",
			"data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,"
				+ "\"function\":{\"arguments\":\"\\\"Zulrah\\\"}\"}}]}}]}",
			"data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"tool_calls\"}]}",
			"data: [DONE]");
		JsonObject call = msg.getAsJsonArray("tool_calls").get(0).getAsJsonObject();
		assertEquals("c1", call.get("id").getAsString());
		JsonObject fn = call.getAsJsonObject("function");
		assertEquals("wiki_page", fn.get("name").getAsString());
		assertEquals("{\"title\":\"Zulrah\"}", fn.get("arguments").getAsString());
	}

	/** A mid-stream failure arrives as a chunk with a top-level error
	 * object under HTTP 200. It must surface as an exception carrying the
	 * server's message, not as a truncated or empty answer. */
	@Test
	public void midStreamErrorThrowsWithServerMessage()
	{
		try
		{
			parse(
				"data: {\"choices\":[{\"delta\":{\"content\":\"partial\"}}]}",
				"data: {\"error\":{\"code\":429,\"message\":\"Rate limit exceeded\","
					+ "\"metadata\":{\"error_type\":\"rate_limit_exceeded\"}},"
					+ "\"choices\":[{\"index\":0,\"delta\":{\"content\":\"\"},"
					+ "\"finish_reason\":\"error\"}]}");
			fail("expected HttpException");
		}
		catch (HttpException e)
		{
			assertEquals(429, e.code);
			assertEquals("Rate limit exceeded", e.serverMessage);
		}
		catch (IOException e)
		{
			fail("expected HttpException, got " + e);
		}
	}

	/** Internal failures carry a string code ("server_error") instead of
	 * an HTTP status; those map to code 0. */
	@Test
	public void midStreamErrorWithStringCode()
	{
		try
		{
			parse("data: {\"error\":{\"code\":\"server_error\","
				+ "\"message\":\"Provider disconnected unexpectedly\"},"
				+ "\"choices\":[{\"index\":0,\"delta\":{\"content\":\"\"},"
				+ "\"finish_reason\":\"error\"}]}");
			fail("expected HttpException");
		}
		catch (HttpException e)
		{
			assertEquals(0, e.code);
			assertEquals("Provider disconnected unexpectedly", e.serverMessage);
		}
		catch (IOException e)
		{
			fail("expected HttpException, got " + e);
		}
	}

	/** Endpoints that end the stream without [DONE] (connection close)
	 * still yield whatever content arrived. */
	@Test
	public void streamWithoutDoneMarkerStillYieldsContent() throws IOException
	{
		JsonObject msg = parse(
			"data: {\"choices\":[{\"delta\":{\"content\":\"abrupt\"}}]}");
		assertEquals("abrupt", msg.get("content").getAsString());
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import java.io.File;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import okhttp3.OkHttpClient;

/**
 * Measures the grounding check's noise level against real answers.
 *
 * Usage: --answer FILE [--context FILE]
 */
public class NameCheckScan
{
	public static void main(String[] args) throws Exception
	{
		PrintStream out = new PrintStream(System.out, true, "UTF-8");
		String answerFile = null;
		String contextFile = null;
		for (int i = 0; i < args.length - 1; i++)
		{
			if ("--answer".equals(args[i]))
			{
				answerFile = args[i + 1];
			}
			if ("--context".equals(args[i]))
			{
				contextFile = args[i + 1];
			}
		}

		String answer = read(answerFile);
		String context = contextFile == null ? "" : read(contextFile);

		File cacheDir = new File(new File(System.getProperty("user.home"), ".runelite"),
			"osrs-copilot/cache");
		Gson gson = new Gson();
		WikiApi wiki = new WikiApi(new Http(new OkHttpClient(), gson), gson, cacheDir);

		List<String> all = NameCheck.names(answer, wiki.englishWords());
		List<GroundingCheck.Finding> findings = GroundingCheck.check(answer, context, wiki);
		out.printf("names in answer: %d   ungrounded: %d%n", all.size(), findings.size());

		for (GroundingCheck.Verdict v : GroundingCheck.Verdict.values())
		{
			out.println("\n--- " + v + " ---");
			findings.stream().filter(f -> f.verdict == v).forEach(f -> out.println("  " + f));
		}
		out.printf("%nsuspect %d of %d ungrounded%n",
			GroundingCheck.suspect(findings).size(), findings.size());
		System.exit(0);
	}

	private static String read(String path) throws Exception
	{
		return new String(Files.readAllBytes(new File(path).toPath()), StandardCharsets.UTF_8);
	}
}

package com.osrscopilot.pipeline;

import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class OwnershipTest
{
	private static GameCapture capture()
	{
		GameCapture cap = new GameCapture();
		cap.bank = List.of(
			Map.of("name", "Dragon arrow", "quantity", 4663),
			Map.of("name", "Rune platebody", "quantity", 1));
		cap.inventory = List.of(
			Map.of("name", "Dragon arrow", "quantity", 100));
		cap.equipment = List.of(
			Map.of("name", "Scorching bow", "quantity", 1));
		return cap;
	}

	@Test
	public void indexTracksQuantitiesPerLocation()
	{
		Map<String, long[]> owned = Ownership.buildIndex(capture());
		assertArrayEquals(new long[]{100, 0, 4663}, owned.get("dragon arrow"));
		assertArrayEquals(new long[]{0, 1, 0}, owned.get("scorching bow"));
		assertArrayEquals(new long[]{0, 0, 1}, owned.get("rune platebody"));
		assertEquals(4763, Ownership.total(owned.get("dragon arrow")));
	}

	@Test
	public void whereLabelCountsOnlyWhenLocationsMix()
	{
		assertEquals("banked", Ownership.whereLabel(new long[]{0, 0, 4663}));
		assertEquals("carried", Ownership.whereLabel(new long[]{3, 0, 0}));
		assertEquals("equipped", Ownership.whereLabel(new long[]{0, 1, 0}));
		assertEquals("100 carried, 4663 banked",
			Ownership.whereLabel(new long[]{100, 0, 4663}));
		assertEquals("2 carried, 1 equipped, 5 banked",
			Ownership.whereLabel(new long[]{2, 1, 5}));
	}

	@Test
	public void sliceLabelsEachOwnedEntryWithItsLocation()
	{
		GameCapture cap = capture();
		Ownership.Slice slice = Ownership.slice(
			"bring dragon arrows and a scorching bow; a twisted bow also works",
			Ownership.buildIndex(cap), Ownership.buildNames(cap),
			List.of(new ItemDescriptor("Dragon arrow", "Dragon arrow", null, false, null, null),
				new ItemDescriptor("Scorching bow", "Scorching bow", null, false, null, null),
				new ItemDescriptor("Twisted bow", "Twisted bow", null, false, null, null)));
		assertTrue(slice.text.contains("Dragon arrow x4763 (100 carried, 4663 banked)"));
		assertTrue(slice.text.contains("Scorching bow (equipped)"));
		assertTrue("locations never leak into the not-owned list",
			slice.text.contains("NOT OWNED (verified absent at capture): Twisted bow"));
	}

	@Test
	public void checkFindsExactAndPartialMatches()
	{
		GameCapture cap = capture();
		Map<String, long[]> owned = Ownership.buildIndex(cap);
		Map<String, String> names = Ownership.buildNames(cap);

		Object exact = Ownership.check(owned, names, "Scorching bow");
		assertEquals(Map.of("item", "Scorching bow", "owned", 1L), exact);

		Object partial = Ownership.check(owned, names, "arrow");
		assertTrue(partial instanceof Map);
		assertEquals(false, ((Map<?, ?>) partial).get("exact_match"));

		Object absent = Ownership.check(owned, names, "Twisted bow");
		assertEquals(Map.of("item", "Twisted bow", "owned", 0), absent);
	}

	@Test
	public void mentionsWordMatchesWholeWordsOnly()
	{
		assertTrue(Ownership.mentionsWord("bring a dragon arrow to the fight", "dragon arrow"));
		assertTrue(Ownership.mentionsWord("dragon arrows are best", "dragon arrow"));
		assertFalse(Ownership.mentionsWord("use the blowpipe here", "bow"));
	}

	@Test
	public void baseNameStripsTrailingQualifiers()
	{
		assertEquals("Prayer potion", Ownership.baseName("Prayer potion(4)"));
		assertEquals("Slayer helmet", Ownership.baseName("Slayer helmet (i)"));
		assertEquals("Rune platebody", Ownership.baseName("Rune platebody"));
	}

	@Test
	public void wordMatchEndExtendsPluralsAndRejectsMidWordSpans()
	{
		assertEquals(13, Ownership.wordMatchEnd("dragon arrows", 7, 5));
		assertEquals(3, Ownership.wordMatchEnd("bow", 0, 3));
		assertEquals(-1, Ownership.wordMatchEnd("longbows here", 4, 3));
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import java.io.File;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The ownership fact block states, positively, which fact-mentioned items
 * the player owns and which they lack. The model answers gear questions
 * from it instead of re-verifying through the search tool, so these tests
 * pin the matching that makes its completeness claim true.
 */
public class PrefetcherTest
{
	@Test
	public void taskPageMatchingBridgesCategoryPlurals()
	{
		java.util.Set<String> index = new java.util.TreeSet<>(List.of(
			"Slayer task/Greater demons", "Slayer task/Ankou",
			"Slayer task/Aberrant spectres", "Slayer task/TzHaar"));
		// Singular monster to plural category, unchanged names, and the
		// capture's own plural creature string all resolve.
		assertEquals("Slayer task/Greater demons",
			Prefetcher.matchTaskPage("Greater demon", index));
		assertEquals("Slayer task/Ankou", Prefetcher.matchTaskPage("Ankou", index));
		assertEquals("Slayer task/TzHaar", Prefetcher.matchTaskPage("TzHaar", index));
		assertEquals("Slayer task/Aberrant spectres",
			Prefetcher.matchTaskPage("Aberrant spectres", index));
		assertEquals(null, Prefetcher.matchTaskPage("Zulrah", index));
	}

	/** WikiApi whose item vocabulary is a fixed list; nothing fetches. */
	private static WikiApi vocabOf(String... names)
	{
		return new WikiApi(null, new Gson(), new File("build/tmp"))
		{
			@Override
			public List<ItemDescriptor> itemCatalog()
			{
				List<ItemDescriptor> out = new ArrayList<>();
				for (String n : names)
				{
					out.add(new ItemDescriptor(n, n, null, false, null, null));
				}
				return out;
			}
		};
	}

	private static List<String> ownershipFacts(WikiApi wiki, List<String> pageFacts,
		Map<String, Long> ownedItems) throws Exception
	{
		Map<String, long[]> owned = new LinkedHashMap<>();
		Map<String, String> names = new LinkedHashMap<>();
		for (Map.Entry<String, Long> e : ownedItems.entrySet())
		{
			// Fixture quantities sit in the bank, the common case for the
			// summarized-bank mode these facts exist in.
			owned.put(e.getKey().toLowerCase(java.util.Locale.ROOT),
				new long[]{0, 0, e.getValue()});
			names.put(e.getKey().toLowerCase(java.util.Locale.ROOT), e.getKey());
		}
		List<String> facts = new ArrayList<>(pageFacts);
		new Prefetcher(wiki, new Gson()).addOwnershipFromFacts(facts, owned, names);
		return facts.subList(pageFacts.size(), facts.size());
	}

	@Test
	public void ownershipFactHeadingCarriesTheLocation() throws Exception
	{
		// The wiki stub yields no page/stats facts, so the ownership fact
		// is the only one the item produces; its heading must place the
		// item, the payload staying quantity-only.
		WikiApi wiki = new WikiApi(null, new Gson(), new File("build/tmp"))
		{
			@Override
			String page(String title, int charLimit)
			{
				return null;
			}

			@Override
			Map<String, Object> itemStats(String name)
			{
				return null;
			}
		};
		CopilotPipeline.Route route = new CopilotPipeline.Route();
		route.entities = new EntityResolver.Resolution();
		route.entities.items.add("Rune platebody");
		route.needs = List.of();
		route.facilityPages = List.of();
		Map<String, long[]> owned = new LinkedHashMap<>();
		owned.put("rune platebody", new long[]{0, 0, 1});
		List<String> facts = new Prefetcher(wiki, new Gson()).prefetch(route,
			new GameCapture(), owned, Map.of("rune platebody", "Rune platebody"), false);
		assertEquals(1, facts.size());
		assertTrue(facts.get(0).startsWith("### Ownership: Rune platebody (banked)\n"));
		assertTrue(facts.get(0).contains("\"owned\":1"));
	}

	@Test
	public void ownedAndLackedAreBothStatedPositively() throws Exception
	{
		List<String> added = ownershipFacts(
			vocabOf("Abyssal whip", "Twisted bow", "Dragon dagger"),
			List.of("### Recommended equipment\nWeapon: Abyssal whip or Twisted bow"),
			Map.of("Abyssal whip", 1L));
		assertEquals(1, added.size());
		String block = added.get(0);
		assertTrue("owned entries carry their location",
			block.contains("OWNED: Abyssal whip (banked)"));
		assertTrue("fact-mentioned unowned items must be named, not implied",
			block.contains("NOT OWNED") && block.contains("Twisted bow"));
		assertFalse("unmentioned items stay out of both lists",
			block.contains("Dragon dagger"));
		assertTrue("untruncated block states its full universe",
			block.contains("Ownership of every item these facts mention"));
	}

	@Test
	public void variantNamedGearMatchesTheCanonicalWikiName() throws Exception
	{
		// The wiki says "Slayer helmet (i)"; the player owns the black
		// variant. It must land in OWNED, not NOT OWNED -- a false
		// non-ownership claim is worse than no claim.
		List<String> added = ownershipFacts(
			vocabOf("Slayer helmet (i)"),
			List.of("### Recommended equipment\nHead: Slayer helmet (i)"),
			Map.of("Black slayer helmet (i)", 1L));
		assertEquals(1, added.size());
		assertTrue(added.get(0).contains("OWNED: Black slayer helmet"));
		assertFalse("an owned variant may never be declared not-owned",
			added.get(0).contains("NOT OWNED (verified absent at capture): Slayer helmet"));
	}

	@Test
	public void singleSharedWordIsNotAMention() throws Exception
	{
		// "helmet" alone appearing in prose must not drag in every owned
		// helmet: only multi-word remainders count as an item reference.
		List<String> added = ownershipFacts(
			vocabOf(),
			List.of("### Strategy\nAny helmet with decent defence works here."),
			Map.of("Black slayer helmet (i)", 1L));
		assertTrue(added.isEmpty());
	}

	@Test
	public void truncatedLackedListDropsTheCompletenessClaim() throws Exception
	{
		StringBuilder page = new StringBuilder("### Drop table\n");
		List<String> vocab = new ArrayList<>();
		for (int i = 0; i < 250; i++)
		{
			String name = "Ancient relic " + (char) ('a' + i / 26) + (char) ('a' + i % 26);
			page.append(name).append("\n");
			vocab.add(name);
		}
		List<String> added = ownershipFacts(
			vocabOf(vocab.toArray(new String[0])),
			List.of(page.toString()), Map.of("Abyssal whip", 1L));
		assertEquals(1, added.size());
		assertFalse("a cut list may not claim the full universe",
			added.get(0).contains("every item these facts mention"));
	}

	@Test
	public void singleDestinationLocationTableYieldsItsPage()
	{
