		{"levelling herblore cheap", false, false, need(Router.NEED_TRAINING)},
		{"leveling agility fast", false, false, need(Router.NEED_TRAINING)},
		{"whats the best way to level sailing forme", false, false, need(Router.NEED_TRAINING)},
		{"how do i level herblore", false, false, need(Router.NEED_TRAINING)},
		{"how to level fishing without banking", false, false, need(Router.NEED_TRAINING)},
		{"fastest way to level up mining", false, false, need(Router.NEED_TRAINING)},

		// --- Drop table ---
		{"what does vorkath drop", false, false, need(Router.NEED_DROP_TABLE)},
		{"zulrah loot table", false, false, need(Router.NEED_DROP_TABLE)},
		{"is the visage dropped by anything else", false, false, need(Router.NEED_DROP_TABLE)},
		{"is vorkath worth killing", false, false,
			need(Router.NEED_DROP_TABLE, Router.NEED_PRICES, Router.NEED_STRATEGY)},

		// --- Mechanics keywords ---
		{"is vorkath afkable, whats his weakness", false, false, need(Router.NEED_MECHANICS)},
		{"what attack style does kraken use", false, false, need(Router.NEED_MECHANICS)},
		{"where does the hellhound spawn", false, false, need(Router.NEED_MECHANICS)},
	};

	/** question / monsterResolved / itemResolved / need that must NOT appear. */
	private static final Object[][] NEGATIVE = {
		// No entity resolved: a bare fight verb must not fire the
		// entity-conditioned rule ("killing time", "beat the sepulchre").
		{"im just killing time before the update", false, false, Router.NEED_STRATEGY},
		{"can i beat the clock in the sepulchre", false, false, Router.NEED_STRATEGY},
		// No item resolved: bare obtain verbs stay inert.
		{"i got 99 strength yesterday", false, false, Router.NEED_ITEM_SOURCES},
		{"what should i do to have fun", false, false, Router.NEED_ITEM_SOURCES},
		// Monster resolved but no fight verb: asking about the creature is
		// not fight prep.
		{"where does vorkath live", true, false, Router.NEED_STRATEGY},
		{"on average how many kc needed for corrupted gauntlet", true, false, Router.NEED_STRATEGY},
		// Item resolved but no obtain verb.
		{"what does a bowfa look like", false, true, Router.NEED_ITEM_SOURCES},
		// "level" as a noun is XP math, not a training question.
		{"what level do i need for barrows gloves", false, false, Router.NEED_TRAINING},
		{"what level is my attack", false, false, Router.NEED_TRAINING},
	};

	@Test
	public void phrasingCorpusClassifies()
	{
		StringBuilder misses = new StringBuilder();
		for (Object[] row : POSITIVE)
		{
			List<String> got = Router.classifyNeeds((String) row[0],
				(Boolean) row[1], (Boolean) row[2]);
			for (String want : (String[]) row[3])
			{
				if (!got.contains(want))
				{
					misses.append(String.format("MISS  %-55s wanted %s, got %s%n",
						"\"" + row[0] + "\"", want, got));
				}
			}
		}
		assertTrue(misses.toString(), misses.length() == 0);
	}

	@Test
	public void phrasingCorpusRejects()
	{
		StringBuilder hits = new StringBuilder();
		for (Object[] row : NEGATIVE)
		{
			List<String> got = Router.classifyNeeds((String) row[0],
				(Boolean) row[1], (Boolean) row[2]);
			if (got.contains((String) row[3]))
			{
				hits.append(String.format("FALSE POSITIVE  %-55s must not have %s, got %s%n",
					"\"" + row[0] + "\"", row[3], got));
			}
		}
		assertFalse(hits.toString(), hits.length() > 0);
	}

	private static String[] need(String... needs)
	{
		return needs;
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ToolRegistryTest
{
	private final ToolRegistry registry = new ToolRegistry(null, new Gson());

	private static List<String> names(JsonArray specs)
	{
		List<String> names = new ArrayList<>();
		for (JsonElement e : specs)
		{
			names.add(e.getAsJsonObject().getAsJsonObject("function").get("name").getAsString());
		}
		return names;
	}

	@Test
	public void everySpecIsAWellFormedFunctionDeclaration()
	{
		for (JsonElement e : registry.buildToolSpecs(true))
		{
			JsonObject spec = e.getAsJsonObject();
			assertEquals("function", spec.get("type").getAsString());
			JsonObject fn = spec.getAsJsonObject("function");
			assertTrue(fn.has("name") && fn.has("description"));
			JsonObject params = fn.getAsJsonObject("parameters");
			assertEquals("object", params.get("type").getAsString());
			// Every declared parameter is required, and vice versa.
			String required = params.getAsJsonArray("required").get(0).getAsString();
			assertTrue(params.getAsJsonObject("properties").has(required));
		}
	}

	@Test
	public void ownedItemSearchOnlyOfferedWhenOwnershipIsNotAlreadyInContext()
	{
		// Offered only when neither the inlined bank nor a complete
		// ownership fact already answers it: a tool over visible data
		// invites redundant lookups.
		assertTrue(names(registry.buildToolSpecs(true)).contains("search_owned_items"));
		assertFalse(names(registry.buildToolSpecs(false)).contains("search_owned_items"));
	}

	@Test
	public void specsAndImplementationsStayInLockstep()
	{
		GameCapture cap = new GameCapture();
		for (boolean offerOwnedSearch : new boolean[]{true, false})
		{
			List<String> specNames = names(registry.buildToolSpecs(offerOwnedSearch));
			assertEquals(specNames.size(),
				registry.buildTools(cap, Map.of(), Map.of(), offerOwnedSearch, true).size());
			assertTrue(registry.buildTools(cap, Map.of(), Map.of(), offerOwnedSearch, true)
				.keySet().containsAll(specNames));
		}
	}

	// ---- xp_to_level -----------------------------------------------------

	private static Object xpCall(Map<String, Integer> skillXp, String skill, Object target)
		throws Exception
	{
		GameCapture cap = new GameCapture();
		cap.skillXp = skillXp;
		JsonObject args = new JsonObject();
		args.addProperty("skill", skill);
		if (target instanceof Number)
		{
			args.addProperty("target_level", (Number) target);
		}
		return new ToolRegistry(null, new Gson())
			.buildTools(cap, Map.of(), Map.of(), false, false)
			.get("xp_to_level").call(args);
	}

	@Test
	@SuppressWarnings("unchecked")
	public void xpToLevelComputesTheExactGapFromTheOfficialTable() throws Exception
	{
		// The real failure this guards: at 787,792 Herblore XP (level 70)
		// asking for 72, the model doubled the next-level gap and said ~54k.
		// The official table says level 72 = 899,257 total.
		Map<String, Object> out = (Map<String, Object>)
			xpCall(Map.of("Herblore", 787_792), "herblore", 72);
		assertEquals("Herblore", out.get("skill"));
		assertEquals(70, out.get("current_level"));
		assertEquals(111_465, out.get("xp_needed"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void xpToLevelReportsAnAlreadyReachedTargetInsteadOfANegativeGap() throws Exception
	{
		Map<String, Object> out = (Map<String, Object>)
			xpCall(Map.of("Herblore", 787_792), "Herblore", 60);
		assertEquals(0, out.get("xp_needed"));
		assertTrue(out.containsKey("note"));
	}

	@Test
	public void xpToLevelRejectsUnknownSkillsMissingTargetsAndAbsentCaptureData()
		throws Exception
	{
		assertTrue(((Map<?, ?>) xpCall(Map.of("Herblore", 1), "Herblaw", 72))
			.containsKey("error"));
		assertTrue(((Map<?, ?>) xpCall(Map.of("Herblore", 1), "Herblore", null))
			.containsKey("error"));
		assertTrue(((Map<?, ?>) xpCall(Map.of("Herblore", 1), "Herblore", 100))
			.containsKey("error"));
		assertTrue(((Map<?, ?>) xpCall(null, "Herblore", 72)).containsKey("error"));
	}

	// ---- owned-item search ----------------------------------------------

	private static Object searchOwned(WikiApi wiki, Map<String, Long> ownedItems,
		String... queries) throws Exception
	{
		Map<String, long[]> owned = new java.util.LinkedHashMap<>();
		Map<String, String> names = new java.util.LinkedHashMap<>();
		for (Map.Entry<String, Long> e : ownedItems.entrySet())
		{
			owned.put(e.getKey().toLowerCase(java.util.Locale.ROOT),
				new long[]{0, 0, e.getValue()});
			names.put(e.getKey().toLowerCase(java.util.Locale.ROOT), e.getKey());
		}
		JsonArray list = new JsonArray();
		for (String q : queries)
		{
			list.add(q);
		}
		JsonObject args = new JsonObject();
		args.add("queries", list);
		return new ToolRegistry(wiki, new Gson())
			.buildTools(new GameCapture(), owned, names, true, false)
			.get("search_owned_items").call(args);
	}

	@Test
	public void inventedNameIsFlaggedInsteadOfReadingAsNotOwned() throws Exception
	{
		WikiApi wiki = stubWiki("", Map.of(), "Cannon base", "Cannon stand");
		Map<?, ?> result = (Map<?, ?>) searchOwned(wiki,
			Map.of("Cannon base", 1L), "Reinforced cannon frame");
		assertTrue(String.valueOf(result.get("Reinforced cannon frame"))
			.contains("not a valid OSRS item name"));
	}

	@Test
	public void validNameWithNoCopiesStaysAVerifiedZero() throws Exception
	{
		WikiApi wiki = stubWiki("", Map.of(), "Cannon base", "Saradomin brew(4)");
		Map<?, ?> result = (Map<?, ?>) searchOwned(wiki, Map.of(),
			"Cannon base", "Saradomin brew");
		assertEquals("no match in bank/inventory/equipment", result.get("Cannon base"));
		// Base names of versioned items are how prose refers to them.
		assertEquals("no match in bank/inventory/equipment", result.get("Saradomin brew"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void collectiveTermFindsOwnedVariants() throws Exception
	{
		WikiApi wiki = stubWiki("", Map.of(), "Imbued Zamorak cape", "Cannon base");
		Map<?, ?> result = (Map<?, ?>) searchOwned(wiki,
			Map.of("Imbued Zamorak cape", 1L, "Cannon base", 1L),
			"Imbued god cape", "Dwarf multicannon");
		List<Map<String, Object>> capes =
			(List<Map<String, Object>>) result.get("Imbued god cape");
		assertEquals("Imbued Zamorak cape", capes.get(0).get("item"));
		List<Map<String, Object>> cannon =
			(List<Map<String, Object>>) result.get("Dwarf multicannon");
		assertEquals("Cannon base", cannon.get(0).get("item"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void collectiveTermReachesMaxCapeVariants() throws Exception
	{
		// "zamorak cape" is not a substring of "zamorak max cape": the max
		// variants need their own members or an owner gets a false zero.
		WikiApi wiki = stubWiki("", Map.of(), "Imbued Zamorak max cape");
		Map<?, ?> result = (Map<?, ?>) searchOwned(wiki,
			Map.of("Imbued Zamorak max cape", 1L), "Imbued god cape");
		List<Map<String, Object>> hits =
			(List<Map<String, Object>>) result.get("Imbued god cape");
		assertEquals("Imbued Zamorak max cape", hits.get(0).get("item"));
	}

	@Test
	public void unownedCollectiveIsAVerifiedZeroNotAnInvalidName() throws Exception
	{
		// Every variant was searched, so the miss is real -- unlike an
		// invented name, which stays flagged.
		WikiApi wiki = stubWiki("", Map.of(), "Cannon base");
		Map<?, ?> result = (Map<?, ?>) searchOwned(wiki, Map.of(), "God cape");
		assertEquals("no match in bank/inventory/equipment", result.get("God cape"));
	}

	@Test
	public void substringHitsBypassValidation() throws Exception
	{
		WikiApi wiki = stubWiki("", Map.of(), "Cannon base");
		Map<?, ?> result = (Map<?, ?>) searchOwned(wiki,
			Map.of("Cannon base", 1L, "Cannon stand", 1L), "cannon");
		assertTrue(result.get("cannon") instanceof List);
		assertEquals(2, ((List<?>) result.get("cannon")).size());
	}

	@Test
	public void searchResultsCarryLocationsThroughTheSliceFooter() throws Exception
	{
		// The hits state totals; where the copies sit rides the ownership
		// slice footer, same as every other annotated tool result.
		WikiApi wiki = stubWiki("", Map.of(), "Cannon base");
		Map<String, long[]> owned = new java.util.LinkedHashMap<>();
		owned.put("cannon base", new long[]{0, 0, 1});
		Map<String, String> names = Map.of("cannon base", "Cannon base");
		JsonArray list = new JsonArray();
		list.add("Cannon base");
		JsonObject args = new JsonObject();
		args.add("queries", list);
		Object out = new ToolRegistry(wiki, new Gson())
			.buildTools(new GameCapture(), owned, names, true, true)
			.get("search_owned_items").call(args);
		String text = (String) out;
		assertTrue("hit payload survives the wrap",
			text.contains("Cannon base") && text.contains("\"quantity\":1"));
		assertTrue("footer locates the found item",
			text.contains("OWNED: Cannon base (banked)"));
	}

	// ---- ownership annotation on tool results ---------------------------

	/** WikiApi serving fixed content and a fixed item vocabulary. */
	private static WikiApi stubWiki(String pageText, Map<String, Object> drops,
		String... vocabulary)
	{
		return new WikiApi(null, new Gson(), new File("build/tmp"))
		{
			@Override
			String page(String title)
			{
				return pageText;
			}

			@Override
			Map<String, Object> monsterDrops(String name)
			{
				return drops;
			}

			@Override
			public List<ItemDescriptor> itemCatalog()
			{
				List<ItemDescriptor> out = new ArrayList<>();
				for (String n : vocabulary)
				{
					out.add(new ItemDescriptor(n, n, null, false, null, null));
				}
				return out;
			}
		};
	}

	private static Object call(WikiApi wiki, String tool, String argKey, String argValue,
		Map<String, Long> ownedItems, boolean annotate) throws Exception
	{
		Map<String, long[]> owned = new java.util.LinkedHashMap<>();
		Map<String, String> names = new java.util.LinkedHashMap<>();
		for (Map.Entry<String, Long> e : ownedItems.entrySet())
		{
			owned.put(e.getKey().toLowerCase(java.util.Locale.ROOT),
				new long[]{0, 0, e.getValue()});
			names.put(e.getKey().toLowerCase(java.util.Locale.ROOT), e.getKey());
		}
		JsonObject args = new JsonObject();
		args.addProperty(argKey, argValue);
		return new ToolRegistry(wiki, new Gson())
			.buildTools(new GameCapture(), owned, names, false, annotate)
			.get(tool).call(args);
	}

	@Test
	public void toolResultsCarryTheOwnershipSliceForItemsTheyMention() throws Exception
	{
		// A page fetched mid-loop names items the prefetched facts never
		// mentioned. The result itself must state ownership, or the model
		// can only hedge ("if you have one...").
		WikiApi wiki = stubWiki(
			"The fastest route is the Giantsoul amulet teleport. "
				+ "Alternatively use a Twisted bow for the boss.",
			null, "Giantsoul amulet", "Twisted bow");
		Object out = call(wiki, "wiki_page", "title", "Asgarnian Ice Dungeon",
			Map.of("Giantsoul amulet", 1L), true);
		String text = (String) out;
		assertTrue("original content is preserved",
			text.startsWith("The fastest route"));
		assertTrue(text.contains("OWNED: Giantsoul amulet"));
		assertTrue("mentioned unowned items are named, not implied",
			text.contains("NOT OWNED") && text.contains("Twisted bow"));
		assertTrue("untruncated footer carries no cut note",
			text.contains("[Player ownership of items this result mentions]"));
	}

	@Test
	public void jsonToolResultsAreAnnotatedThroughTheirSerializedForm() throws Exception
	{
		WikiApi wiki = stubWiki(null,
			Map.of("drops", List.of("Draconic visage", "Skeletal visage")),
			"Draconic visage", "Skeletal visage");
		Object out = call(wiki, "monster_drops", "name", "Vorkath",
			Map.of("Draconic visage", 1L), true);
		String text = (String) out;
		assertTrue("the JSON payload survives for the model to read",
			text.contains("\"drops\""));
		assertTrue(text.contains("OWNED: Draconic visage"));
		assertTrue(text.contains("NOT OWNED") && text.contains("Skeletal visage"));
	}

	@Test
	public void inlinedBankDisablesTheAnnotation() throws Exception
	{
		// With the bank inlined in the prompt the model already sees
		// everything; annotating would only repeat it.
		WikiApi wiki = stubWiki("Bring a Giantsoul amulet.", null, "Giantsoul amulet");
		Object out = call(wiki, "wiki_page", "title", "Anything",
			Map.of("Giantsoul amulet", 1L), false);
		assertEquals("Bring a Giantsoul amulet.", out);
	}

	@Test
	public void errorResultsAndItemFreeResultsPassThroughUntouched() throws Exception
	{
		WikiApi wiki = stubWiki(null, null, "Giantsoul amulet");
		Object error = call(wiki, "wiki_page", "title", "No such page",
			Map.of("Giantsoul amulet", 1L), true);
		assertTrue("a lookup failure stays a structured error", error instanceof Map);

		WikiApi prose = stubWiki("The quest begins in Lumbridge.", null, "Giantsoul amulet");
		Object plain = call(prose, "wiki_page", "title", "Some quest",
			Map.of("Giantsoul amulet", 1L), true);
		assertEquals("The quest begins in Lumbridge.", plain);
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.zip.GZIPOutputStream;
import okhttp3.OkHttpClient;

/**
 * Compiles the bulk vocabularies the plugin needs and writes them as
 * gzipped snapshots for publishing to the vocab-data branch. The only code
 * that runs the wiki's expensive bulk queries; it runs weekly in CI, never
 * on a user's machine. Every dataset has a minimum-size threshold: a wiki
 * API change that guts a dataset fails the job and leaves the previous
 * snapshot published.
 */
public final class VocabSnapshotTool
{
	private static final String WIKI_API = "https://oldschool.runescape.wiki/api.php";
	private static final String PRICES_API = "https://prices.runescape.wiki/api";
	private static final String WORDLIST_URL =
		"https://raw.githubusercontent.com/first20hours/google-10000-english/master/google-10000-english.txt";

	private final Http http;
	private final Gson gson;
	/** Milliseconds slept before each wiki request. Zero for local test
	 * runs; CI passes ~20s so the weekly gather spreads over ~15-20
	 * minutes instead of bursting fifty requests at the wiki. */
	private final long paceMs;

	private VocabSnapshotTool(Http http, Gson gson, long paceMs)
	{
		this.http = http;
		this.gson = gson;
		this.paceMs = paceMs;
	}

	public static void main(String[] args) throws Exception
	{
		File outDir = new File(args.length > 0 ? args[0] : "build/vocab");
		outDir.mkdirs();
		long paceMs = (args.length > 1 ? Long.parseLong(args[1]) : 0) * 1000;
		Gson gson = new Gson();
		VocabSnapshotTool tool = new VocabSnapshotTool(new Http(new OkHttpClient(), gson), gson, paceMs);
		if (paceMs > 0)
		{
			System.out.println("pacing: " + (paceMs / 1000) + "s before each request");
		}

		// ~85% of the live counts measured 2026-08. These datasets only
		// grow with game updates; a dip below means the query broke.
		Map<String, JsonObject> geMapping = tool.geMapping();
		Set<String> monsters = tool.monsterNameSet();
		tool.write(outDir, "monsters_v2.json",
			new Sized(gson.toJson(monsters), monsters.size()), 1400, "monster names");
		tool.write(outDir, "strategies.json", tool.strategiesIndex(monsters), 105, "strategy subpages");
		// 178 live titles measured 2026-08-21, redirect aliases included.
		tool.write(outDir, "slayer_tasks.json", tool.slayerTaskIndex(), 150, "slayer task subpages");
		Sized wordlist = tool.wordlist();
		tool.write(outDir, "english_10k.txt", wordlist, 9000, "wordlist lines");
		// ~85% of the 11,006 canonical rows measured 2026-08-28.
		tool.write(outDir, "items_v2.json",
			tool.itemIndex(wordSet(wordlist.content), geMapping),
			9300, "item descriptors");

		// For humans inspecting the branch; clients never read this.
		java.nio.file.Files.write(new File(outDir, "stamp.txt").toPath(),
			(java.time.Instant.now() + "\n").getBytes(StandardCharsets.UTF_8));
		System.out.println("snapshots written to " + outDir.getAbsolutePath());
	}

	/** Gzips content to outDir after checking the record-count threshold. */
	private void write(File outDir, String filename, Sized data, int minCount, String what)
		throws IOException
	{
		if (data.count < minCount)
		{
			throw new IllegalStateException("SANITY FAIL: " + filename + " has " + data.count
				+ " " + what + ", expected >= " + minCount + " -- refusing to publish");
		}
		File f = new File(outDir, filename + ".gz");
		try (GZIPOutputStream out = new GZIPOutputStream(new FileOutputStream(f)))
		{
			out.write(data.content.getBytes(StandardCharsets.UTF_8));
		}
		System.out.printf("%-22s %6d %-20s %8d bytes gz%n", filename, data.count, what, f.length());
	}

	private static final class Sized
	{
		final String content;
		final int count;

		Sized(String content, int count)
		{
			this.content = content;
			this.count = count;
		}
	}

	/** GE catalogue entries by lowercased name. Not published on its own:
	 * its fields (tradeability, buy limit, high alch, ID backfill) ride on
	 * the item descriptors. */
	private Map<String, JsonObject> geMapping() throws IOException
	{
		String json = getText(PRICES_API + "/v2/osrs/mapping");
		Map<String, JsonObject> byName = new HashMap<>();
		for (JsonElement e : gson.fromJson(json, JsonArray.class))
		{
			JsonObject entry = e.getAsJsonObject();
			JsonElement name = entry.get("name");
			if (name != null && !name.isJsonNull())
			{
				byName.putIfAbsent(name.getAsString().toLowerCase(Locale.ROOT), entry);
			}
		}
		if (byName.size() < 4000)
		{
			throw new IllegalStateException("SANITY FAIL: GE mapping has " + byName.size()
				+ " entries, expected >= 4000 -- refusing to publish");
		}
		return byName;
	}

	private Sized wordlist() throws IOException
	{
		String text = getText(WORDLIST_URL);
		return new Sized(text, text.split("\n").length);
	}

	/** page_name is the exact wiki title, so downstream queries match
	 * without casing surprises. Paginated defensively: versioned monsters
	 * multiply rows and nothing warns when a dataset outgrows one page. */
	private Set<String> monsterNameSet() throws IOException
	{
		Set<String> names = new TreeSet<>();
		for (int offset = 0; offset < 100_000; offset += 5000)
		{
			JsonObject r = bucket("bucket('infobox_monster').select('name','page_name')"
				+ ".limit(5000).offset(" + offset + ").run()");
			JsonArray rows = r.getAsJsonArray("bucket");
			if (rows == null || rows.size() == 0)
			{
				break;
			}
			for (JsonElement row : rows)
			{
				JsonObject o = row.getAsJsonObject();
				JsonElement page = o.get("page_name");
				JsonElement name = o.get("name");
				if (page != null && !page.isJsonNull())
				{
					names.add(page.getAsString());
				}
				else if (name != null && !name.isJsonNull())
				{
					names.add(name.getAsString());
				}
			}
			if (rows.size() < 5000)
			{
				break;
			}
		}
		return names;
	}

	/** Every /Strategies guide subpage that exists. A title search finds
	 * every real page with the suffix but skips redirect titles (which
	 * still fetch fine), so monster-derived titles are additionally batch
	 * existence-checked, 50 per request. */
	private Sized strategiesIndex(Set<String> monsterNames) throws IOException
	{
		Set<String> exists = new TreeSet<>();
		Integer offset = 0;
		while (offset != null)
		{
			JsonObject r = getJson(WIKI_API + "?action=query&list=search&format=json"
				+ "&srlimit=50&sroffset=" + offset
				+ "&srsearch=" + Http.enc("intitle:\"Strategies\""));
			for (JsonElement e : r.getAsJsonObject("query").getAsJsonArray("search"))
			{
				String title = e.getAsJsonObject().get("title").getAsString();
				if (title.endsWith("/Strategies"))
				{
					exists.add(title);
				}
			}
			offset = r.has("continue")
				? r.getAsJsonObject("continue").get("sroffset").getAsInt() : null;
		}
		List<String> batch = new ArrayList<>(50);
		for (String name : monsterNames)
		{
			batch.add(name + "/Strategies");
			if (batch.size() == 50)
			{
				addExisting(batch, exists);
				batch.clear();
			}
		}
		if (!batch.isEmpty())
		{
			addExisting(batch, exists);
		}
		return new Sized(gson.toJson(exists), exists.size());
	}

	/** Every "Slayer task/..." guide subpage, redirect aliases included:
	 * the aliases are matching surface for mapping a creature name to its
	 * task guide. */
	private Sized slayerTaskIndex() throws IOException
	{
		Set<String> titles = new TreeSet<>();
		String cont = null;
		do
		{
			JsonObject r = getJson(WIKI_API + "?action=query&list=allpages&format=json"
				+ "&apprefix=" + Http.enc("Slayer task/") + "&aplimit=500"
				+ (cont != null ? "&apcontinue=" + Http.enc(cont) : ""));
			for (JsonElement e : r.getAsJsonObject("query").getAsJsonArray("allpages"))
			{
				String title = e.getAsJsonObject().get("title").getAsString();
				// The bare "Slayer task/" root is in the listing too.
				if (title.length() > "Slayer task/".length())
				{
					titles.add(title);
				}
			}
			cont = r.has("continue")
				? r.getAsJsonObject("continue").get("apcontinue").getAsString() : null;
		} while (cont != null);
		return new Sized(gson.toJson(titles), titles.size());
	}

	/** Adds the titles in the batch that exist on the wiki to out. */
	private void addExisting(List<String> titles, Set<String> out) throws IOException
	{
		JsonObject r = getJson(WIKI_API + "?action=query&format=json&titles="
			+ Http.enc(String.join("|", titles)));
		JsonObject pages = r.getAsJsonObject("query").getAsJsonObject("pages");
		for (String pageId : pages.keySet())
		{
			JsonObject p = pages.getAsJsonObject(pageId);
			if (!p.has("missing"))
			{
				out.add(p.get("title").getAsString());
			}
		}
	}

	/** ~85% of the 10,872 id-bearing rows measured 2026-08-28. Guards the
	 * wiki dropping or reshaping item_id, like the Module:Map incident. */
	private static final int MIN_ITEM_IDS = 9200;

	/** Every item as a canonical {@link ItemDescriptor} from the item
	 * infoboxes, fully canonicalized here so clients just parse. */
	private Sized itemIndex(Set<String> englishWords, Map<String, JsonObject> geByName)
		throws IOException
	{
		List<JsonObject> rows = new ArrayList<>();
		for (int offset = 0; offset < 100_000; offset += 5000)
		{
			JsonObject page = bucket("bucket('infobox_item')"
				+ ".select('page_name','item_name','item_id','removal_date')"
				+ ".limit(5000).offset(" + offset + ").run()");
			JsonArray batch = page.getAsJsonArray("bucket");
			if (batch == null || batch.size() == 0)
			{
				break;
			}
			for (JsonElement e : batch)
			{
				rows.add(e.getAsJsonObject());
			}
			if (batch.size() < 5000)
			{
				break;
			}
		}
		List<ItemDescriptor> items = canonicalItems(rows, englishWords, geByName);
		long withId = items.stream().filter(it -> it.id != null).count();
		if (withId < MIN_ITEM_IDS)
		{
			throw new IllegalStateException("SANITY FAIL: items_v2.json has " + withId
				+ " id-bearing descriptors, expected >= " + MIN_ITEM_IDS
				+ " -- refusing to publish");
		}
		Set<String> lowerNames = new HashSet<>();
		for (ItemDescriptor it : items)
		{
			lowerNames.add(it.name.toLowerCase(Locale.ROOT));
		}
		for (String variant : ItemCollectives.variantTerms())
		{
			if (lowerNames.stream().noneMatch(n -> n.contains(variant)))
			{
				throw new IllegalStateException("SANITY FAIL: collective variant '"
					+ variant + "' matches no catalogued item -- table is stale");
			}
		}
		return new Sized(gson.toJson(items), items.size());
	}

	/** Canonicalization: drop removed content, fake pages, and bare
	 * dictionary-word names (kept when tradeable: prose "bread" means the
	 * item); resolve duplicate display names to their real page; take the
	 * first decimal game ID, else the GE one (new tradeables get GE IDs
	 * before wiki infobox IDs); attach GE buy limit and high alch.
	 * Deterministic for identical input rows. Package-private for tests. */
	static List<ItemDescriptor> canonicalItems(List<JsonObject> rows,
		Set<String> englishWords, Map<String, JsonObject> geByName)
	{
		Map<String, List<JsonObject>> byName = new HashMap<>();
		for (JsonObject row : rows)
		{
			JsonElement name = row.get("item_name");
			JsonElement removed = row.get("removal_date");
			if (name == null || name.isJsonNull()
				|| (removed != null && !removed.isJsonNull()))
			{
				continue;
			}
			if (fakeItemPage(pageOf(row)))
			{
				continue;
			}
			String lower = name.getAsString().toLowerCase(Locale.ROOT);
			if (name.getAsString().indexOf(' ') < 0 && englishWords.contains(lower)
				&& !geByName.containsKey(lower))
			{
				continue;
			}
			byName.computeIfAbsent(lower, k -> new ArrayList<>()).add(row);
		}
		List<ItemDescriptor> out = new ArrayList<>(byName.size());
		for (Map.Entry<String, List<JsonObject>> group : byName.entrySet())
		{
			JsonObject row = group.getValue().stream()
				.min(Comparator.comparingInt(VocabSnapshotTool::pageRank)
					.thenComparing(VocabSnapshotTool::pageOf)
					.thenComparing(r -> r.get("item_name").getAsString()))
				.get();
			String name = row.get("item_name").getAsString();
			JsonObject ge = geByName.get(group.getKey());
			Integer id = gameId(row);
			if (id == null && ge != null)
			{
				id = intField(ge, "id");
			}
			out.add(new ItemDescriptor(name, pageOf(row), id, ge != null,
				ge != null ? intField(ge, "limit") : null,
				ge != null ? intField(ge, "highalch") : null));
		}
		out.sort(Comparator.comparing(it -> it.name, String.CASE_INSENSITIVE_ORDER));
		return out;
	}

	private static Integer intField(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber()
			? e.getAsInt() : null;
	}

	/** Prefer the page named exactly like the item, then any real article
	 * over disambiguated ones ("Fire cape" over "Fire cape (Last Man
	 * Standing)"). */
	private static int pageRank(JsonObject row)
	{
		String page = pageOf(row);
		return page.equals(row.get("item_name").getAsString()) ? 0
			: page.indexOf('(') < 0 ? 1 : 2;
	}

	private static String pageOf(JsonObject row)
	{
		JsonElement pg = row.get("page_name");
		return pg != null && !pg.isJsonNull()
			? pg.getAsString() : row.get("item_name").getAsString();
	}

	/** First decimal ID in the row's item_id array; the bucket also holds
	 * prefixed non-game IDs ("beta...") that never render as sprites. */
	private static Integer gameId(JsonObject row)
	{
		JsonElement ids = row.get("item_id");
		if (ids == null || !ids.isJsonArray())
		{
			return null;
		}
		for (JsonElement e : ids.getAsJsonArray())
		{
			try
			{
				return Integer.parseInt(e.getAsString());
			}
			catch (NumberFormatException ignored)
			{
			}
		}
		return null;
	}

	/** Non-obtainable infobox variants that share a real item's name. */
	private static boolean fakeItemPage(String page)
	{
		return page.contains("(unobtainable item")
			|| page.contains("(interface item")
			|| page.contains("(animation item")
			|| page.contains("(RuneScape 2 Beta");
	}

	private static Set<String> wordSet(String text)
	{
		Set<String> words = new HashSet<>();
		for (String line : text.split("\n"))
		{
			if (!line.trim().isEmpty())
			{
				words.add(line.trim());
			}
		}
		return words;
	}

	private JsonObject bucket(String query) throws IOException
	{
		return getJson(WIKI_API + "?action=bucket&format=json&query=" + Http.enc(query));
	}

	private JsonObject getJson(String url) throws IOException
	{
		pace();
		return http.getJson(url);
	}

	private String getText(String url) throws IOException
	{
		pace();
		return http.getText(url);
	}

	private void pace() throws IOException
	{
		if (paceMs <= 0)
		{
			return;
		}
		try
		{
			Thread.sleep(paceMs);
		}
		catch (InterruptedException e)
		{
			throw new IOException("interrupted while pacing", e);
		}
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The canonicalization pass the weekly snapshot job runs over raw
 * infobox_item rows. */
public class VocabSnapshotToolTest
{
	private static final Set<String> ENGLISH = Set.of("key", "bread", "cake");
	private static final Map<String, JsonObject> GE = Map.of(
		"bread", geEntry(9999, 6000, 12),
		"fire cape", geEntry(6570, null, null));

	private static JsonObject geEntry(int id, Integer limit, Integer highalch)
	{
		JsonObject o = new JsonObject();
		o.addProperty("id", id);
		if (limit != null)
		{
			o.addProperty("limit", limit);
		}
		if (highalch != null)
		{
			o.addProperty("highalch", highalch);
		}
		return o;
	}

	private static JsonObject row(String name, String page, String... ids)
	{
		JsonObject o = new JsonObject();
		o.addProperty("item_name", name);
		o.addProperty("page_name", page);
		if (ids.length > 0)
		{
			JsonArray arr = new JsonArray();
			for (String id : ids)
			{
				arr.add(id);
			}
			o.add("item_id", arr);
		}
		return o;
	}

	private static ItemDescriptor only(String name, List<ItemDescriptor> items)
	{
		ItemDescriptor found = null;
		for (ItemDescriptor it : items)
		{
			if (it.name.equals(name))
			{
				assertNull("duplicate descriptor for " + name, found);
				found = it;
			}
		}
		return found;
	}

	@Test
	public void parsesDecimalGameIds()
	{
		List<ItemDescriptor> items = VocabSnapshotTool.canonicalItems(
			List.of(row("Crowbar", "Crowbar", "31807")), ENGLISH, GE);
		assertEquals(Integer.valueOf(31807), only("Crowbar", items).id);
	}

	@Test
	public void skipsNonGameIdsAndMissingIds()
	{
		List<ItemDescriptor> items = VocabSnapshotTool.canonicalItems(List.of(
			row("Ancient staff", "Ancient staff", "beta4675", "4675"),
			row("Quest scroll", "Quest scroll")), ENGLISH, GE);
		assertEquals(Integer.valueOf(4675), only("Ancient staff", items).id);
		assertNull(only("Quest scroll", items).id);
	}

	@Test
	public void duplicateNamesResolveToTheRealPage()
	{
		// The animation variant is a fake page; the LMS variant loses to
		// the exact-name page. One descriptor each, deterministically.
		List<ItemDescriptor> items = VocabSnapshotTool.canonicalItems(List.of(
			row("Fire cape", "Fire cape (animation item)", "10566"),
			row("Fire cape", "Fire cape", "6570"),
			row("Saradomin brew(4)", "Saradomin brew (Last Man Standing)", "23575"),
			row("Saradomin brew(4)", "Saradomin brew", "6685")), ENGLISH, GE);
		assertEquals(2, items.size());
		assertEquals(Integer.valueOf(6570), only("Fire cape", items).id);
		ItemDescriptor brew = only("Saradomin brew(4)", items);
		assertEquals("Saradomin brew", brew.page);
		assertEquals(Integer.valueOf(6685), brew.id);
	}

	@Test
	public void removedContentIsExcluded()
	{
		JsonObject removed = row("Half full wine jug", "Half full wine jug", "1989");
		removed.addProperty("removal_date", "2004-01-29");
		assertNull(only("Half full wine jug",
			VocabSnapshotTool.canonicalItems(List.of(removed), ENGLISH, GE)));
	}

	@Test
	public void bareDictionaryWordsStayOnlyWhenTradeable()
	{
		List<ItemDescriptor> items = VocabSnapshotTool.canonicalItems(List.of(
			row("Key", "Key (item)", "409"),
			row("Bread", "Bread", "2309")), ENGLISH, GE);
		assertNull("untradeable dictionary word must not claim prose", only("Key", items));
		assertEquals(Integer.valueOf(2309), only("Bread", items).id);
	}

	@Test
	public void geFieldsRideOnTradeableDescriptors()
	{
		List<ItemDescriptor> items = VocabSnapshotTool.canonicalItems(List.of(
			row("Bread", "Bread", "2309"),
			row("Crowbar", "Crowbar", "31807")), ENGLISH, GE);
		ItemDescriptor bread = only("Bread", items);
		assertTrue(bread.tradeable);
		assertEquals("wiki id beats the GE id", Integer.valueOf(2309), bread.id);
		assertEquals(Integer.valueOf(6000), bread.limit);
		assertEquals(Integer.valueOf(12), bread.highAlch);
		ItemDescriptor crowbar = only("Crowbar", items);
		assertFalse(crowbar.tradeable);
		assertNull(crowbar.limit);
		assertNull(crowbar.highAlch);
	}

	@Test
	public void geIdBackfillsARowTheWikiHasNotAssignedYet()
	{
		List<ItemDescriptor> items = VocabSnapshotTool.canonicalItems(
			List.of(row("Fire cape", "Fire cape")), ENGLISH, GE);
		ItemDescriptor cape = only("Fire cape", items);
		assertEquals(Integer.valueOf(6570), cape.id);
		assertNull("absent GE fields stay null", cape.limit);
	}

	@Test
	public void outputIsDeterministicRegardlessOfInputOrder()
	{
		List<JsonObject> rows = new ArrayList<>(List.of(
			row("Fire cape", "Fire cape (animation item)", "10566"),
			row("Fire cape", "Fire cape", "6570"),
			row("Crowbar", "Crowbar", "31807"),
			row("Abyssal whip", "Abyssal whip", "4151")));
		List<ItemDescriptor> a = VocabSnapshotTool.canonicalItems(rows, ENGLISH, GE);
		Collections.reverse(rows);
		List<ItemDescriptor> b = VocabSnapshotTool.canonicalItems(rows, ENGLISH, GE);
		assertEquals(a.size(), b.size());
		for (int i = 0; i < a.size(); i++)
		{
			assertEquals(a.get(i).name, b.get(i).name);
			assertEquals(a.get(i).page, b.get(i).page);
			assertEquals(a.get(i).id, b.get(i).id);
		}
	}
}

package com.osrscopilot.pipeline;

import com.google.gson.Gson;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import okhttp3.OkHttpClient;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class VocabSnapshotsTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	/** The client reads back exactly what the snapshot job serializes; a
	 * fresh disk copy means no network is touched. */
	@Test
	public void itemCatalogRoundTripsThroughTheSnapshotFormat() throws Exception
	{
		Gson gson = new Gson();
		File dir = tmp.newFolder();
		String json = gson.toJson(List.of(
			new ItemDescriptor("Shark", "Shark", 385, true, 20000, 102),
			new ItemDescriptor("Fire cape (l)", "Fire cape", null, false, null, null)));
		Files.write(new File(dir, "items_v2.json").toPath(),
			json.getBytes(StandardCharsets.UTF_8));

		VocabSnapshots vocab = new VocabSnapshots(
			new Http(new OkHttpClient(), gson), gson, dir);
		List<ItemDescriptor> items = vocab.itemCatalog();
		assertEquals(2, items.size());
		assertEquals("Shark", items.get(0).name);
		assertEquals(Integer.valueOf(385), items.get(0).id);
		assertEquals(Integer.valueOf(20000), items.get(0).limit);
		assertEquals(Integer.valueOf(102), items.get(0).highAlch);
		assertEquals("Fire cape", items.get(1).page);
		assertNull(items.get(1).id);
		assertNull(items.get(1).limit);
	}
}

package com.osrscopilot.pipeline;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WikiContentTest
{
	@Test
	public void tocListsTopLevelSectionsInOrder()
	{
		String page = "Lead prose.\n"
			+ "== Basic overview ==\nprose\n"
			+ "=== Starting items ===\nsub-section prose\n"
			+ "== Loot table ==\nrows\n"
			+ "== Combat Achievements ==\ntasks\n";
		assertEquals("[Sections: Basic overview; Loot table; Combat Achievements]\n\n",
			WikiContent.tocLine(page));
	}

	@Test
	public void tocExcludesAppendixNoise()
	{
		String page = "Lead.\n"
			+ "== Strategy ==\nprose\n"
			+ "== Rewards ==\nrows\n"
			+ "== Changes ==\nchangelog\n"
			+ "== References ==\ncitations\n"
			+ "== Trivia ==\nfacts\n";
		assertEquals("[Sections: Strategy; Rewards]\n\n", WikiContent.tocLine(page));
	}

	@Test
	public void singleSectionPagesGetNoToc()
	{
		assertEquals("", WikiContent.tocLine("Lead.\n== Only section ==\nprose\n"));
		assertEquals("", WikiContent.tocLine("Short item page with no sections at all."));
	}

	@Test
	public void wikitextHeadingsWithoutSpacesAlsoMatch()
	{
		String page = "Lead.\n==Loot table==\nrows\n==Money making==\nprose\n";
		assertTrue(WikiContent.tocLine(page).contains("Loot table; Money making"));
		assertFalse(WikiContent.tocLine(page).contains("=="));
	}

	// --- scrubWikitext: markup with zero semantic content ---

	@Test
	public void fileLinksWithNestedCaptionLinksAreRemovedWhole()
	{
		String text = "Before. [[File:Tombs of Amascut.png|thumb|350px|The "
			+ "[[invocation]] interface where [[Raid level|levels]] show.]] After.";
		assertEquals("Before.  After.", WikiContent.scrubWikitext(text));
	}

	@Test
	public void galleryBlocksAndCitationTemplatesAreRemoved()
	{
		String text = "Intro.\n<gallery mode=\"packed\" heights=\"180\">\n"
			+ "File:Fighting Akkha.png|[[Akkha]], Guardian of Het.\n</gallery>\n"
			+ "Levels are random.{{CiteTwitter|author=Mod Ash|url=https://x.com/1|"
			+ "quote=Looks random {{sic}} to me.}} More prose.";
		String scrubbed = WikiContent.scrubWikitext(text);
		assertEquals("Intro.\n\nLevels are random. More prose.", scrubbed);
	}

	@Test
	public void sortValueAttributesGoContentStays()
	{
		String row = "| data-sort-value=\"Try Again\" | Try Again\n|+5\n";
		assertEquals("| Try Again\n|+5\n", WikiContent.scrubWikitext(row));
	}

	@Test
	public void unclosedConstructsAreLeftUntouched()
	{
		String broken = "Prose [[File:cut off mid page";
		assertEquals(broken, WikiContent.scrubWikitext(broken));
	}

	@Test
	public void ordinaryLinksAndTemplatesSurviveScrubbing()
	{
		String text = "The [[Bandos chestplate]] needs {{SCP|Defence|65}} and "
			+ "[[Bow of Faerdhinen|bowfa]] works too.";
		assertEquals(text, WikiContent.scrubWikitext(text));
	}

	// --- budgetBySections: whole sections, never a mid-table cut ---

	private static String repeat(String s, int n)
	{
		StringBuilder b = new StringBuilder();
		for (int i = 0; i < n; i++)
		{
			b.append(s);
		}
		return b.toString();
	}

	@Test
	public void underBudgetPagesPassThroughUntouched()
	{
		String page = "Lead.\n== A ==\nshort\n== Trivia ==\nkept when under budget\n";
		assertEquals(page, WikiContent.budgetBySections(page, 10_000));
	}

	@Test
	public void overBudgetDropsWholeSectionsNeverCutsMidSection()
	{
		String page = "Lead.\n"
			+ "== Requirements ==\n" + repeat("req ", 100)
			+ "\n== Rewards ==\n" + repeat("gp ", 100)
			+ "\n== Lore ==\n" + repeat("myth ", 200);
		String out = WikiContent.budgetBySections(page, 950);
		assertTrue(out.startsWith("Lead."));
		assertTrue(out.contains("== Requirements =="));
		assertTrue("a section that fits after a skipped one is still admitted",
			out.contains("== Rewards =="));
		assertFalse(out.contains("== Lore =="));
		assertFalse("no partial section content may leak", out.contains("myth"));
	}

	@Test
	public void noiseSectionsAreDroppedFirstWhenOverBudget()
	{
		String page = "Lead.\n"
			+ "== Official worlds ==\n" + repeat("world ", 50)
			+ "\n== Rewards ==\n" + repeat("gp ", 50);
		String out = WikiContent.budgetBySections(page, page.length() - 10);
		assertFalse(out.contains("Official worlds"));
		assertTrue(out.contains("== Rewards =="));
	}

	@Test
	public void giantSectionIsWeighedLastSoTheRestOfThePageSurvives()
	{
		// The ToA shape: a huge early table (invocations) followed by the
		// sections the question needs. Position-cut truncation shipped the
		// table and starved the tail; section budgeting must do the reverse.
		String page = "Lead.\n"
			+ "== Invocations ==\n" + repeat("invocation row ", 500)
			+ "\n== Money making ==\n" + repeat("profit ", 60)
			+ "\n== Rewards ==\n" + repeat("unique ", 60);
		String out = WikiContent.budgetBySections(page, 2000);
		assertTrue(out.contains("== Money making =="));
		assertTrue(out.contains("== Rewards =="));
		assertFalse(out.contains("== Invocations =="));
	}

	@Test
	public void giantSectionStillAdmittedWhenRoomRemains()
	{
		String page = "Lead.\n"
			+ "== Strategy ==\n" + repeat("step ", 400)
			+ "\n== Trivia ==\nnoise stuff\n"
			+ "== Notes ==\nshort\n";
		// Dropping the noise section frees enough budget that the deferred
		// giant is admitted after the small section.
		String out = WikiContent.budgetBySections(page, page.length() - 10);
		assertTrue(out.contains("== Notes =="));
		assertTrue(out.contains("== Strategy =="));
		assertFalse(out.contains("== Trivia =="));
	}

	@Test
	public void headinglessAndGiantOnlyPagesFallBackToPositionCut()
	{
		String headingless = repeat("one long table row ", 400);
		assertEquals(1000, WikiContent.budgetBySections(headingless, 1000).length());
		// A page whose whole substance is one giant section: packing whole
		// sections would ship a bare lead, so position-cut wins.
		String giantOnly = "Tiny lead.\n== Locations ==\n" + repeat("row ", 2000);
		String out = WikiContent.budgetBySections(giantOnly, 1000);
		assertEquals(1000, out.length());
		assertTrue(out.contains("== Locations =="));
	}
}
